class SocialWorkerUnavailableError(ValueError):
    """Raised when queue mode is enabled but no healthy social worker is active."""

    def __init__(self, message: str, *, worker_health: dict[str, Any]):
        super().__init__(message)
        self.worker_health = worker_health


# ---------------------------------------------------------------------------
# General helpers
# ---------------------------------------------------------------------------


def _now_utc() -> datetime:
    return datetime.now(tz=UTC)


def _env_truthy(name: str, *, default: bool = False) -> bool:
    raw = (os.getenv(name) or "").strip().lower()
    if not raw:
        return default
    return raw in {"1", "true", "yes", "on"}


def is_queue_enabled() -> bool:
    return _env_truthy("SOCIAL_QUEUE_ENABLED", default=False)


def _resolve_positive_int_env(name: str, default: int, *, minimum: int = 1) -> int:
    raw = (os.getenv(name) or "").strip()
    if not raw:
        return max(minimum, default)
    try:
        return max(minimum, int(raw))
    except ValueError:
        return max(minimum, default)


def _resolve_int_env_with_bounds(name: str, default: int, *, minimum: int, maximum: int) -> int:
    value = _resolve_positive_int_env(name, default, minimum=minimum)
    return max(minimum, min(maximum, value))


def _resolve_non_negative_float_env(name: str, default: float) -> float:
    raw = (os.getenv(name) or "").strip()
    if not raw:
        return max(0.0, float(default))
    try:
        return max(0.0, float(raw))
    except ValueError:
        return max(0.0, float(default))


def _normalize_worker_stage(stage: str | None) -> str:
    value = (stage or "").strip().lower()
    if not value:
        return "any"
    if value in {
        "posts",
        "comments",
        INSTAGRAM_MEDIA_MIRROR_STAGE,
        COMMENT_MEDIA_MIRROR_STAGE,
        SHARED_ACCOUNT_POSTS_STAGE,
        POST_CLASSIFY_STAGE,
        SEASON_MATERIALIZE_STAGE,
        ANALYTICS_REFRESH_STAGE,
        "any",
    }:
        return value
    return "any"


def _normalize_worker_status(status: str | None) -> str:
    value = (status or "").strip().lower()
    if value in {"starting", "idle", "working", "stopped"}:
        return value
    return "idle"


def _configured_execution_metadata() -> dict[str, Any]:
    return dict(execution_metadata())


def _modal_social_dispatcher_worker_id() -> str:
    return "modal:social-dispatcher"


def _modal_dispatch_retry_delay_seconds() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_MODAL_DISPATCH_RETRY_DELAY_SECONDS",
        SOCIAL_MODAL_DISPATCH_RETRY_DELAY_SECONDS_DEFAULT,
        minimum=15,
    )


def _modal_dispatch_stage_global_cap(stage: str | None) -> int:
    normalized_stage = _normalize_social_job_stage_for_stale(stage) or "unknown"
    env_map = {
        "posts": ("SOCIAL_WORKER_POOL_POSTS", 8),
        "comments": ("SOCIAL_WORKER_POOL_COMMENTS", 8),
        SHARED_ACCOUNT_POSTS_STAGE: ("SOCIAL_WORKER_POOL_SHARED_ACCOUNT_POSTS", 6),
        POST_CLASSIFY_STAGE: ("SOCIAL_WORKER_POOL_POST_CLASSIFY", 10),
        SEASON_MATERIALIZE_STAGE: ("SOCIAL_WORKER_POOL_SEASON_MATERIALIZE", 10),
        ANALYTICS_REFRESH_STAGE: ("SOCIAL_WORKER_POOL_ANALYTICS_REFRESH", 4),
        INSTAGRAM_MEDIA_MIRROR_STAGE: ("SOCIAL_WORKER_POOL_MEDIA_MIRROR", 6),
        COMMENT_MEDIA_MIRROR_STAGE: ("SOCIAL_WORKER_POOL_COMMENT_MEDIA_MIRROR", 6),
    }
    env_name, default = env_map.get(normalized_stage, ("SOCIAL_WORKER_POOL_POSTS", 8))
    return _resolve_positive_int_env(env_name, default, minimum=1)


def _modal_dispatch_platform_cap(stage: str | None, platform: str | None) -> int | None:
    normalized_stage = _normalize_social_job_stage_for_stale(stage)
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform not in SUPPORTED_PLATFORMS:
        return None
    if normalized_stage in {"posts", "comments"}:
        defaults = {
            "instagram": 2,
            "tiktok": 2,
            "twitter": 2,
            "youtube": 2,
            "facebook": 1,
            "threads": 1,
        }
        env_name = f"SOCIAL_POSTS_COMMENTS_PLATFORM_CAP_{normalized_platform.upper()}"
        return _resolve_positive_int_env(env_name, defaults.get(normalized_platform, 1), minimum=1)
    if normalized_stage in {INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE}:
        return _resolve_positive_int_env("SOCIAL_MIRROR_PLATFORM_CAP", 2, minimum=1)
    return None


def _modal_dispatch_limit() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_DISPATCH_LIMIT",
        SOCIAL_MODAL_DISPATCH_LIMIT_DEFAULT,
        minimum=1,
        maximum=SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX,
    )


def _modal_social_dispatch_ready() -> tuple[bool, str | None]:
    return modal_dispatch_ready(function_name=modal_social_job_function_name())


def _touch_modal_social_dispatcher_heartbeat(
    *,
    status: str = "idle",
    metadata_updates: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    metadata = {
        "dispatcher_name": "social",
        "dispatch_enabled": modal_dispatch_enabled(),
        "execution_backend_canonical": "modal",
        "execution_mode_canonical": "remote",
        **dict(metadata_updates or {}),
    }
    return update_worker_heartbeat(
        _modal_social_dispatcher_worker_id(),
        stage="any",
        status=status,
        metadata=metadata,
        supported_platforms=list(SUPPORTED_PLATFORMS),
    )


def _resolve_stale_seconds_for_job(
    *,
    platform: Any = None,
    stage: Any = None,
    has_queue_fields: bool = True,  # noqa: ARG001
) -> int:
    return _resolve_social_job_stale_seconds(platform=platform, stage=stage)


def _oldest_queued_age_seconds() -> int | None:
    row = (
        pg.fetch_one(
            """
        select extract(epoch from now() - min(created_at))::int as oldest_seconds
        from social.scrape_jobs
        where status in ('queued', 'pending', 'retrying')
        """,
        )
        or {}
    )
    value = row.get("oldest_seconds")
    if value is None:
        return None
    return max(0, int(value))


def _stale_running_count() -> int:
    row = (
        pg.fetch_one(
            """
        select count(*)::int as total
        from social.scrape_jobs j
        where j.status = 'running'
          and coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)
            < now() - (
              case
                when lower(coalesce(j.platform, '')) = 'youtube'
                  and lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) = 'posts'
                  then make_interval(secs => %s)
                when lower(coalesce(j.platform, '')) = 'youtube'
                  and lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) = 'comments'
                  then make_interval(secs => %s)
                else make_interval(secs => %s)
              end
            )
        """,
            [
                _resolve_social_job_stale_seconds(platform="youtube", stage="posts"),
                _resolve_social_job_stale_seconds(platform="youtube", stage="comments"),
                _resolve_social_job_stale_seconds(),
            ],
        )
        or {}
    )
    return max(0, int(row.get("total") or 0))


def _build_modal_executor_health_payload(*, reason: str | None = None) -> dict[str, Any]:
    workers_payload = _query_worker_health()
    dispatcher_id = _modal_social_dispatcher_worker_id()
    dispatcher_row = next(
        (
            worker
            for worker in (workers_payload.get("workers") or [])
            if str(worker.get("worker_id") or "") == dispatcher_id
        ),
        None,
    )
    dispatcher_metadata = _metadata_dict((dispatcher_row or {}).get("metadata"))
    oldest_queued_age_seconds = _oldest_queued_age_seconds()
    stale_running_count = _stale_running_count()
    dispatch_enabled = bool(dispatcher_metadata.get("dispatch_enabled")) if dispatcher_row else modal_dispatch_enabled()
    workers_payload.update(
        {
            "healthy": True,
            "healthy_workers": max(1, int(workers_payload.get("healthy_workers") or 0)),
            "reason": reason,
            "executor_backend": "modal",
            "dispatch_enabled": dispatch_enabled,
            "dispatcher_heartbeat_fresh": bool(dispatcher_row.get("is_fresh")) if dispatcher_row else False,
            "active_invocations": max(
                0,
                int(dispatcher_metadata.get("active_invocations") or workers_payload.get("active_workers") or 0),
            ),
            "oldest_queued_age_seconds": oldest_queued_age_seconds,
            "stale_running_count": stale_running_count,
            "last_dispatch_success_at": str(dispatcher_metadata.get("last_dispatch_success_at") or "").strip() or None,
            "last_dispatch_error": str(dispatcher_metadata.get("last_dispatch_error") or "").strip() or None,
        }
    )
    return workers_payload


_schema_ready_cache: tuple[float, bool] | None = None
_worker_health_cache: tuple[float, int | None, dict[str, Any]] | None = None
_worker_health_cache_lock = Lock()
_queue_status_cache: tuple[float, int, int, bool, bool, int, bool, dict[str, Any]] | None = None
_queue_status_cache_lock = Lock()
_queue_status_last_good_cache: tuple[float, dict[str, Any]] | None = None
_instagram_cookie_refresh_lock = Lock()
_instagram_cookie_validation_cache: tuple[float, str, bool, str | None] | None = None
_instagram_cookie_runtime_override: dict[str, str] | None = None
_tiktok_cookie_refresh_lock = Lock()
_tiktok_cookie_validation_cache: tuple[float, str, bool, str | None] | None = None
_tiktok_cookie_runtime_override: dict[str, str] | None = None
_twitter_cookie_refresh_lock = Lock()
_twitter_cookie_validation_cache: tuple[float, str, bool, str | None] | None = None
_twitter_cookie_runtime_override: dict[str, str] | None = None
_facebook_cookie_refresh_lock = Lock()
_facebook_cookie_validation_cache: tuple[float, str, bool, str | None] | None = None
_facebook_cookie_runtime_override: dict[str, str] | None = None
_threads_cookie_refresh_lock = Lock()
_threads_cookie_validation_cache: tuple[float, str, bool, str | None] | None = None
_threads_cookie_runtime_override: dict[str, str] | None = None


def _worker_heartbeat_schema_ready() -> bool:
    global _schema_ready_cache
    now = time_module.monotonic()
    if _schema_ready_cache and (now - _schema_ready_cache[0]) < 60:
        return _schema_ready_cache[1]
    result = _relation_exists("social.scrape_workers")
    _schema_ready_cache = (now, result)
    return result


def get_worker_auth_capabilities() -> dict[str, bool]:
    """Describe platform auth capabilities for the current worker environment."""
    instagram_cookies = _load_instagram_cookies()
    tiktok_cookies = _load_tiktok_cookies()
    twitter_cookies, twitter_bearer = _load_twitter_auth()
    twikit_creds = _load_twikit_credentials(twitter_cookies)
    facebook_cookies = _load_facebook_cookies()
    threads_cookies = _load_threads_cookies()
    return {
        "instagram_authenticated": bool(instagram_cookies.get("sessionid")),
        "tiktok_authenticated": bool(tiktok_cookies.get("sessionid") or tiktok_cookies.get("sid_tt")),
        "twitter_authenticated": bool(
            (twitter_cookies.get("auth_token") and twitter_cookies.get("ct0")) or twitter_bearer or twikit_creds
        ),
        "facebook_authenticated": bool(facebook_cookies.get("c_user") and facebook_cookies.get("xs")),
        "threads_authenticated": bool(threads_cookies.get("sessionid") and threads_cookies.get("csrftoken")),
    }


def update_worker_heartbeat(
    worker_id: str,
    *,
    stage: str | None,
    status: str,
    run_id: str | None = None,
    current_job_id: str | None = None,
    metadata: dict[str, Any] | None = None,
    supported_platforms: list[str] | None = None,
) -> dict[str, Any] | None:
    global _worker_health_cache, _queue_status_cache
    if not _worker_heartbeat_schema_ready():
        return None

    _cleaned = sorted({p.strip().lower() for p in (supported_platforms or []) if p.strip()})
    normalized_platforms = _cleaned if _cleaned else None

    row = pg.fetch_one(
        """
        insert into social.scrape_workers (
          worker_id,
          stage,
          status,
          run_id,
          current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms
        )
        values (
          %s,
          %s,
          %s,
          %s,
          %s,
          %s::jsonb,
          now(),
          now(),
          now(),
          %s
        )
        on conflict (worker_id)
        do update set
          stage = excluded.stage,
          status = excluded.status,
          run_id = excluded.run_id,
          current_job_id = excluded.current_job_id,
          metadata = excluded.metadata,
          last_seen_at = now(),
          updated_at = now(),
          supported_platforms = CASE
            WHEN excluded.supported_platforms IS NOT NULL THEN excluded.supported_platforms
            ELSE social.scrape_workers.supported_platforms
          END
        returning
          worker_id,
          stage,
          status,
          run_id::text as run_id,
          current_job_id::text as current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms
        """,
        [
            worker_id,
            _normalize_worker_stage(stage),
            _normalize_worker_status(status),
            run_id,
            current_job_id,
            json.dumps(metadata or {}),
            normalized_platforms,
        ],
    )
    with _worker_health_cache_lock:
        _worker_health_cache = None
    with _queue_status_cache_lock:
        _queue_status_cache = None
    return row


def mark_worker_stopped(
    worker_id: str,
    *,
    stage: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    return update_worker_heartbeat(
        worker_id,
        stage=stage,
        status="stopped",
        run_id=None,
        current_job_id=None,
        metadata=metadata,
        supported_platforms=None,
    )


def _query_worker_health(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    payload: dict[str, Any] = {
        "healthy": False,
        "healthy_workers": 0,
        "fresh_workers": 0,
        "stale_workers": 0,
        "stale_hidden_count": 0,
        "active_workers": 0,
        "total_workers": 0,
        "stale_after_seconds": stale_seconds,
        "by_stage": {},
        "by_platform": {},
        "workers": [],
        "reason": None,
    }

    if not _worker_heartbeat_schema_ready():
        payload["reason"] = "worker_heartbeat_schema_missing"
        return payload

    summary_row: dict[str, Any] = {}
    workers: list[dict[str, Any]] = []
    try:
        with pg.db_connection() as conn:
            with pg.db_cursor(conn=conn) as cur:
                cur.execute("set local statement_timeout = '5000'")
                summary_row = (
                    pg.fetch_one_with_cursor(
                        cur,
                        """
                        select
                          count(*)::int as total_workers,
                          count(*) filter (where status != 'stopped')::int as active_workers,
                          count(*) filter (
                            where status in ('starting', 'idle', 'working')
                              and last_seen_at >= now() - (%s * interval '1 second')
                          )::int as healthy_workers,
                          count(*) filter (
                            where last_seen_at >= now() - (%s * interval '1 second')
                          )::int as fresh_workers
                        from social.scrape_workers
                        """,
                        [stale_seconds, stale_seconds],
                    )
                    or {}
                )
                workers = pg.fetch_all_with_cursor(
                    cur,
                    """
                    select
                      worker_id,
                      stage,
                      status,
                      run_id::text as run_id,
                      current_job_id::text as current_job_id,
                      metadata,
                      started_at,
                      last_seen_at,
                      updated_at,
                      supported_platforms,
                      (
                        last_seen_at >= now() - (%s * interval '1 second')
                      ) as is_fresh,
                      (
                        status in ('starting', 'idle', 'working')
                        and last_seen_at >= now() - (%s * interval '1 second')
                      ) as is_healthy
                    from social.scrape_workers
                    order by last_seen_at desc
                    limit 120
                    """,
                    [stale_seconds, stale_seconds],
                )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Worker health query timed out or failed: %s", exc)
        payload["reason"] = "health_query_failed"
        return payload
    healthy_workers = int(summary_row.get("healthy_workers") or 0)
    fresh_workers = int(summary_row.get("fresh_workers") or 0)
    total_workers = int(summary_row.get("total_workers") or 0)
    active_workers = int(summary_row.get("active_workers") or 0)
    stale_workers = max(0, total_workers - fresh_workers)
    visible_stale_workers = sum(1 for worker in workers if not bool(worker.get("is_fresh")))
    stale_hidden_count = max(0, stale_workers - visible_stale_workers)
    by_stage: dict[str, dict[str, int]] = {}
    by_platform: dict[str, dict[str, int]] = {}
    for worker in workers:
        stage = str(worker.get("stage") or "any").strip().lower() or "any"
        stage_bucket = by_stage.setdefault(stage, {"total": 0, "healthy": 0, "fresh": 0})
        stage_bucket["total"] += 1
        if bool(worker.get("is_healthy")):
            stage_bucket["healthy"] += 1
        if bool(worker.get("is_fresh")):
            stage_bucket["fresh"] += 1
        for platform in worker.get("supported_platforms") or []:
            normalized_platform = _normalize_platform_name(platform) or "unknown"
            platform_bucket = by_platform.setdefault(normalized_platform, {"total": 0, "healthy": 0, "fresh": 0})
            platform_bucket["total"] += 1
            if bool(worker.get("is_healthy")):
                platform_bucket["healthy"] += 1
            if bool(worker.get("is_fresh")):
                platform_bucket["fresh"] += 1
    reason: str | None = None
    if total_workers <= 0:
        reason = "no_workers"
    elif healthy_workers <= 0:
        reason = "no_healthy_workers"
    payload.update(
        {
            "healthy": healthy_workers > 0,
            "healthy_workers": healthy_workers,
            "fresh_workers": fresh_workers,
            "stale_workers": stale_workers,
            "stale_hidden_count": stale_hidden_count,
            "active_workers": active_workers,
            "total_workers": total_workers,
            "by_stage": by_stage,
            "by_platform": by_platform,
            "workers": workers,
            "reason": reason,
        }
    )
    return payload


def get_worker_health(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    global _worker_health_cache
    modal_executor_reason: str | None = None
    modal_executor_enabled = is_queue_enabled() and is_modal_remote_executor_enabled()
    if modal_executor_enabled:
        ready, reason = _modal_social_dispatch_ready()
        modal_executor_reason = None if ready else reason
        if ready:
            _touch_modal_social_dispatcher_heartbeat(
                metadata_updates={
                    "dispatch_enabled": True,
                    "last_dispatch_success_at": _iso(_now_utc()),
                }
            )
        else:
            _touch_modal_social_dispatcher_heartbeat(
                metadata_updates={
                    "dispatch_enabled": False,
                    "last_dispatch_error": reason,
                    "last_dispatch_error_at": _iso(_now_utc()),
                }
            )
    cache_ttl_seconds = _resolve_positive_int_env(
        "SOCIAL_WORKER_HEALTH_CACHE_TTL_SECONDS",
        SOCIAL_WORKER_HEALTH_CACHE_TTL_SECONDS_DEFAULT,
        minimum=0,
    )
    if cache_ttl_seconds <= 0:
        payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
        if modal_executor_enabled:
            return _build_modal_executor_health_payload(reason=modal_executor_reason)
        return payload

    now = time_module.monotonic()
    with _worker_health_cache_lock:
        if _worker_health_cache is not None:
            cached_at, cached_stale_after, cached_payload = _worker_health_cache
            if cached_stale_after == stale_after_seconds and (now - cached_at) < cache_ttl_seconds:
                return copy.deepcopy(cached_payload)

    payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
    if modal_executor_enabled:
        payload = _build_modal_executor_health_payload(reason=modal_executor_reason)
    with _worker_health_cache_lock:
        _worker_health_cache = (time_module.monotonic(), stale_after_seconds, payload)
    return copy.deepcopy(payload)


def _metadata_dict(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _compute_currently_scraping(*, worker: dict[str, Any], job: dict[str, Any] | None) -> str | None:
    if not job:
        stage = str(worker.get("stage") or "").strip()
        return stage or None
    metadata = _metadata_dict(job.get("metadata"))
    activity = _metadata_dict(metadata.get("activity"))
    phase = str(activity.get("phase") or "").strip()
    if phase:
        return phase
    stage = str(job.get("stage") or "").strip()
    platform = str(job.get("platform") or "").strip()
    account_handle = str(job.get("account_handle") or "").strip().lstrip("@")
    parts = [part for part in [platform, stage, account_handle] if part]
    return " · ".join(parts) if parts else None


def _compute_progress_made(*, job: dict[str, Any] | None) -> dict[str, Any]:
    if not job:
        return {
            "items_found": 0,
            "posts_upserted": 0,
            "comments_upserted": 0,
            "stage_counters": {},
            "phase": None,
        }
    metadata = _metadata_dict(job.get("metadata"))
    persist_counters = _metadata_dict(metadata.get("persist_counters"))
    stage_counters = _metadata_dict(metadata.get("stage_counters"))
    activity = _metadata_dict(metadata.get("activity"))
    return {
        "items_found": _normalize_non_negative_int(job.get("items_found")),
        "posts_upserted": _normalize_non_negative_int(persist_counters.get("posts_upserted")),
        "comments_upserted": _normalize_non_negative_int(persist_counters.get("comments_upserted")),
        "stage_counters": stage_counters,
        "phase": str(activity.get("phase") or "").strip() or None,
    }


def get_worker_detail(worker_id: str, *, stale_after_seconds: int | None = None) -> dict[str, Any]:
    normalized_worker_id = str(worker_id or "").strip()
    if not normalized_worker_id:
        raise ValueError("worker_not_found")
    if not _worker_heartbeat_schema_ready():
        raise ValueError("worker_heartbeat_schema_missing")

    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    worker_row = pg.fetch_one(
        """
        select
          worker_id,
          stage,
          status,
          run_id::text as run_id,
          current_job_id::text as current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms,
          (
            status in ('starting', 'idle', 'working')
            and last_seen_at >= now() - (%s * interval '1 second')
          ) as is_healthy
        from social.scrape_workers
        where worker_id = %s
        limit 1
        """,
        [stale_seconds, normalized_worker_id],
    )
    if not worker_row:
        raise ValueError("worker_not_found")

    features = _scrape_jobs_features()
    has_run_id = bool(features.get("has_run_id"))
    has_queue_fields = bool(features.get("has_queue_fields"))
    current_job_id = str(worker_row.get("current_job_id") or "").strip()
    job_row: dict[str, Any] | None = None
    if current_job_id and _relation_exists("social.scrape_jobs"):
        select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
        select_attempt_count = "j.attempt_count" if has_queue_fields else "0::int as attempt_count"
        select_max_attempts = "j.max_attempts" if has_queue_fields else "0::int as max_attempts"
        select_heartbeat_at = "j.heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
        select_last_error_code = "j.last_error_code" if has_queue_fields else "null::text as last_error_code"
        job_row = pg.fetch_one(
            f"""
            select
              j.id::text as id,
              {select_run_id},
              j.platform,
              j.job_type,
              j.status,
              coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) as stage,
              j.config,
              j.metadata,
              j.items_found,
              {select_attempt_count},
              {select_max_attempts},
              j.started_at,
              {select_heartbeat_at},
              j.error_message,
              {select_last_error_code}
            from social.scrape_jobs j
            where j.id = %s::uuid
            limit 1
            """,
            [current_job_id],
        )

    run_id = str((job_row or {}).get("run_id") or worker_row.get("run_id") or "").strip() or None
    run_row: dict[str, Any] | None = None
    if run_id and _relation_exists("social.scrape_runs"):
        run_row = pg.fetch_one(
            """
            select
              id::text as run_id,
              status,
              source_scope,
              config,
              created_at,
              started_at,
              completed_at,
              summary
            from social.scrape_runs
            where id = %s::uuid
            limit 1
            """,
            [run_id],
        )

    job_payload: dict[str, Any] | None = None
    if isinstance(job_row, dict):
        job_config = _metadata_dict(job_row.get("config"))
        account_handle = (
            str(job_config.get("account") or "").strip()
            or str(job_config.get("username") or "").strip()
            or str(job_config.get("source_account") or "").strip()
            or None
        )
        job_payload = {
            "id": str(job_row.get("id") or ""),
            "run_id": str(job_row.get("run_id") or "").strip() or None,
            "platform": str(job_row.get("platform") or ""),
            "job_type": str(job_row.get("job_type") or ""),
            "status": str(job_row.get("status") or ""),
            "stage": str(job_row.get("stage") or ""),
            "account_handle": account_handle,
            "items_found": _normalize_non_negative_int(job_row.get("items_found")),
            "attempt_count": _normalize_non_negative_int(job_row.get("attempt_count")),
            "max_attempts": _normalize_non_negative_int(job_row.get("max_attempts")),
            "started_at": _iso(_coerce_dt(job_row.get("started_at"))),
            "heartbeat_at": _iso(_coerce_dt(job_row.get("heartbeat_at"))),
            "error_message": str(job_row.get("error_message") or "").strip() or None,
            "last_error_code": str(job_row.get("last_error_code") or "").strip() or None,
            "metadata": _metadata_dict(job_row.get("metadata")),
        }

    run_payload: dict[str, Any] | None = None
    if isinstance(run_row, dict):
        run_config = _metadata_dict(run_row.get("config"))
        run_payload = {
            "run_id": str(run_row.get("run_id") or "").strip() or None,
            "status": str(run_row.get("status") or "").strip() or None,
            "source_scope": str(run_row.get("source_scope") or "").strip() or None,
            "execution_owner": str(run_config.get("execution_owner") or "").strip() or None,
            "execution_mode_canonical": (str(run_config.get("execution_mode_canonical") or "").strip() or None),
            "execution_backend_canonical": (str(run_config.get("execution_backend_canonical") or "").strip() or None),
            "created_at": _iso(_coerce_dt(run_row.get("created_at"))),
            "started_at": _iso(_coerce_dt(run_row.get("started_at"))),
            "completed_at": _iso(_coerce_dt(run_row.get("completed_at"))),
            "summary": _metadata_dict(run_row.get("summary")),
        }

    worker_payload = {
        "worker_id": str(worker_row.get("worker_id") or ""),
        "stage": str(worker_row.get("stage") or ""),
        "status": str(worker_row.get("status") or ""),
        "run_id": str(worker_row.get("run_id") or "").strip() or None,
        "current_job_id": str(worker_row.get("current_job_id") or "").strip() or None,
        "started_at": _iso(_coerce_dt(worker_row.get("started_at"))),
        "last_seen_at": _iso(_coerce_dt(worker_row.get("last_seen_at"))),
        "supported_platforms": list(worker_row.get("supported_platforms") or []),
        "metadata": _metadata_dict(worker_row.get("metadata")),
        "is_healthy": bool(worker_row.get("is_healthy")),
    }

    return {
        "worker": worker_payload,
        "current_job": job_payload,
        "run": run_payload,
        "currently_scraping": _compute_currently_scraping(worker=worker_payload, job=job_payload),
        "progress_made": _compute_progress_made(job=job_payload),
    }


def purge_inactive_workers(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    global _worker_health_cache
    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    if not _worker_heartbeat_schema_ready():
        return {
            "stale_after_seconds": stale_seconds,
            "active_workers": 0,
            "total_workers_before": 0,
            "total_workers_after": 0,
            "deleted_workers": 0,
            "reason": "worker_heartbeat_schema_missing",
        }

    active_clause = "status in ('starting', 'idle', 'working') and last_seen_at >= now() - (%s * interval '1 second')"
    snapshot_row = (
        pg.fetch_one(
            f"""
            select
              count(*) filter (where {active_clause})::int as active_workers,
              count(*)::int as total_workers
            from social.scrape_workers
            """,
            [stale_seconds],
        )
        or {}
    )
    deleted_rows = pg.execute_returning(
        f"""
        delete from social.scrape_workers
        where not ({active_clause})
        returning worker_id
        """,
        [stale_seconds],
    )

    active_workers = int(snapshot_row.get("active_workers") or 0)
    total_workers_before = int(snapshot_row.get("total_workers") or 0)
    deleted_workers = len(deleted_rows or [])
    with _worker_health_cache_lock:
        _worker_health_cache = None
    return {
        "stale_after_seconds": stale_seconds,
        "active_workers": active_workers,
        "total_workers_before": total_workers_before,
        "total_workers_after": max(0, total_workers_before - deleted_workers),
        "deleted_workers": deleted_workers,
        "reason": None,
    }


def assert_worker_available_when_queue_enabled() -> dict[str, Any]:
    if not is_queue_enabled():
        return {
            "healthy": True,
            "healthy_workers": 0,
            "active_workers": 0,
            "total_workers": 0,
            "workers": [],
            "reason": "queue_disabled",
        }

    if is_modal_remote_executor_enabled():
        ready, reason = _modal_social_dispatch_ready()
        if not ready:
            payload = _build_modal_executor_health_payload(reason=reason)
            raise SocialWorkerUnavailableError(
                "Modal social dispatch is not configured for remote execution.",
                worker_health=payload,
            )
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": True,
                "last_dispatch_success_at": _iso(_now_utc()),
            }
        )
        return _build_modal_executor_health_payload(reason="modal_executor_ready")

    health = get_worker_health()
    if bool(health.get("healthy")):
        return health

    reason = str(health.get("reason") or "no_healthy_workers")
    if reason == "worker_heartbeat_schema_missing":
        message = "Social worker heartbeat schema is missing. Apply migration 0130 before enabling queue mode."
    else:
        message = "No healthy social ingest workers are reporting heartbeats."
    raise SocialWorkerUnavailableError(message, worker_health=health)


def _empty_queue_status_counts() -> dict[str, int]:
    return dict.fromkeys(QUEUE_STATUS_STAGES, 0)


def _stuck_jobs_filter_clause(
    *,
    has_queue_fields: bool,
    table_alias: str = "j",
) -> tuple[str, list[Any]]:
    stale_seconds_expr, stale_seconds_params = _build_social_job_stale_seconds_sql_expr(
        table_alias=table_alias,
        has_queue_fields=has_queue_fields,
    )
    running_reference_with_queue = (
        f"coalesce({table_alias}.heartbeat_at, {table_alias}.started_at, "
        f"{table_alias}.claimed_at, {table_alias}.created_at)"
    )
    running_reference = (
        running_reference_with_queue
        if has_queue_fields
        else f"coalesce({table_alias}.started_at, {table_alias}.created_at)"
    )
    retrying_reference_with_queue = (
        f"coalesce({table_alias}.available_at, {table_alias}.heartbeat_at, "
        f"{table_alias}.started_at, {table_alias}.claimed_at, {table_alias}.created_at)"
    )
    retrying_reference = retrying_reference_with_queue if has_queue_fields else f"{table_alias}.created_at"
    stale_timeout_signal_clause = (
        f"""
        (
          coalesce({table_alias}.last_error_code, '') = 'stale_heartbeat_timeout'
          or lower(coalesce({table_alias}.metadata->>'error_code', '')) = 'stale_heartbeat_timeout'
          or coalesce({table_alias}.error_message, '') ilike 'stale_heartbeat_timeout:%%'
        )
        """
        if has_queue_fields
        else f"""
        (
          lower(coalesce({table_alias}.metadata->>'error_code', '')) = 'stale_heartbeat_timeout'
          or coalesce({table_alias}.error_message, '') ilike 'stale_heartbeat_timeout:%%'
        )
        """
    )
    return (
        f"""
        (
          (
            {table_alias}.status = 'running'
            and {running_reference} < now() - (({stale_seconds_expr}) * interval '1 second')
          )
          or (
            {table_alias}.status = 'retrying'
            and {retrying_reference} < now() - (({stale_seconds_expr}) * interval '1 second')
            and {stale_timeout_signal_clause}
          )
        )
        """,
        [*stale_seconds_params, *stale_seconds_params],
    )


def _list_stuck_jobs(
    *,
    limit: int = SOCIAL_QUEUE_STATUS_STUCK_JOBS_LIMIT_DEFAULT,
) -> tuple[list[dict[str, Any]], int]:
    safe_limit = max(1, min(int(limit), 500))
    features = _scrape_jobs_features()
    has_queue_fields = bool(features.get("has_queue_fields"))
    has_run_id = bool(features.get("has_run_id"))
    where_clause, where_params = _stuck_jobs_filter_clause(
        has_queue_fields=has_queue_fields,
        table_alias="j",
    )

    select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
    select_worker_id = "j.worker_id as worker_id" if has_queue_fields else "null::text as worker_id"
    select_heartbeat_at = "j.heartbeat_at as heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
    select_available_at = "j.available_at as available_at" if has_queue_fields else "null::timestamptz as available_at"
    select_last_error_code = (
        "j.last_error_code as last_error_code" if has_queue_fields else "null::text as last_error_code"
    )
    stuck_for_reference = (
        "coalesce(j.available_at, j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)"
        if has_queue_fields
        else "coalesce(j.started_at, j.created_at)"
    )
    rows = pg.fetch_all(
        f"""
        with stuck_jobs as (
          select
            j.id::text as id,
            {select_run_id},
            j.platform,
            j.job_type,
            j.status,
            {select_worker_id},
            j.created_at,
            {select_heartbeat_at},
            {select_available_at},
            j.error_message,
            {select_last_error_code},
            case
              when j.status = 'running' then 'running_stale_heartbeat'
              else 'retrying_stale_timeout'
            end as stuck_reason,
            greatest(0, floor(extract(epoch from (now() - {stuck_for_reference}))))::int as stuck_for_seconds
          from social.scrape_jobs j
          where {where_clause}
          order by stuck_for_seconds desc, j.created_at asc
          limit %s
        )
        select
          id,
          run_id,
          platform,
          job_type,
          status,
          worker_id,
          created_at,
          heartbeat_at,
          available_at,
          error_message,
          last_error_code,
          stuck_reason,
          stuck_for_seconds
        from stuck_jobs
        """,
        [*where_params, safe_limit],
    )
    total_row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where {where_clause}
        """,
            where_params,
        )
        or {}
    )
    entries = [
        {
            "id": str(row.get("id") or ""),
            "run_id": str(row.get("run_id") or "") or None,
            "platform": str(row.get("platform") or ""),
            "job_type": str(row.get("job_type") or ""),
            "status": str(row.get("status") or ""),
            "worker_id": str(row.get("worker_id") or "") or None,
            "created_at": _iso(_coerce_dt(row.get("created_at"))),
            "heartbeat_at": _iso(_coerce_dt(row.get("heartbeat_at"))),
            "available_at": _iso(_coerce_dt(row.get("available_at"))),
            "error_message": str(row.get("error_message") or "") or None,
            "last_error_code": str(row.get("last_error_code") or "") or None,
            "stuck_reason": str(row.get("stuck_reason") or ""),
            "stuck_for_seconds": int(row.get("stuck_for_seconds") or 0),
        }
        for row in rows
        if str(row.get("id") or "").strip()
    ]
    return entries, int(total_row.get("total") or 0)


def _count_stuck_jobs() -> int:
    features = _scrape_jobs_features()
    has_queue_fields = bool(features.get("has_queue_fields"))
    where_clause, where_params = _stuck_jobs_filter_clause(has_queue_fields=has_queue_fields, table_alias="j")
    row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where {where_clause}
        """,
            where_params,
        )
        or {}
    )
    return int(row.get("total") or 0)


_ACTIVE_CANCEL_JOB_STATUSES = ("queued", "pending", "retrying", "running", "cancelling")


def _count_active_jobs() -> int:
    row = (
        pg.fetch_one(
            """
        select count(*)::int as total
        from social.scrape_jobs
        where status = any(%s::text[])
        """,
            [list(_ACTIVE_CANCEL_JOB_STATUSES)],
        )
        or {}
    )
    return int(row.get("total") or 0)


def _invalidate_queue_status_cache() -> None:
    global _queue_status_cache, _queue_status_last_good_cache
    with _queue_status_cache_lock:
        _queue_status_cache = None
        _queue_status_last_good_cache = None


def get_queue_status(
    *,
    recent_failures_limit: int = 20,
    statement_timeout_ms: int = 5000,
    include_recent_failures: bool = True,
    include_stuck_jobs: bool = True,
    stuck_jobs_limit: int = SOCIAL_QUEUE_STATUS_STUCK_JOBS_LIMIT_DEFAULT,
    include_runs_summary: bool = True,
    fresh: bool = False,
) -> dict[str, Any]:
    global _queue_status_cache, _queue_status_last_good_cache
    safe_recent_failures_limit = max(1, min(int(recent_failures_limit), 100))
    safe_statement_timeout_ms = max(1000, min(int(statement_timeout_ms), 30000))
    safe_include_recent_failures = bool(include_recent_failures)
    safe_include_stuck_jobs = bool(include_stuck_jobs)
    safe_stuck_jobs_limit = max(1, min(int(stuck_jobs_limit), 500))
    safe_include_runs_summary = bool(include_runs_summary)
    cache_ttl_seconds = _resolve_positive_int_env(
        "SOCIAL_QUEUE_STATUS_CACHE_TTL_SECONDS",
        SOCIAL_QUEUE_STATUS_CACHE_TTL_SECONDS_DEFAULT,
        minimum=0,
    )

    if cache_ttl_seconds > 0 and not fresh:
        now = time_module.monotonic()
        with _queue_status_cache_lock:
            if _queue_status_cache is not None:
                (
                    cached_at,
                    cached_limit,
                    cached_timeout,
                    cached_include_recent_failures,
                    cached_include_stuck_jobs,
                    cached_stuck_jobs_limit,
                    cached_include_runs_summary,
                    cached_payload,
                ) = _queue_status_cache
                if (
                    cached_limit == safe_recent_failures_limit
                    and cached_timeout == safe_statement_timeout_ms
                    and cached_include_recent_failures == safe_include_recent_failures
                    and cached_include_stuck_jobs == safe_include_stuck_jobs
                    and cached_stuck_jobs_limit == safe_stuck_jobs_limit
                    and cached_include_runs_summary == safe_include_runs_summary
                    and (now - cached_at) < cache_ttl_seconds
                ):
                    return copy.deepcopy(cached_payload)

    def _finalize(payload: dict[str, Any]) -> dict[str, Any]:
        if cache_ttl_seconds > 0:
            with _queue_status_cache_lock:
                _queue_status_cache = (
                    time_module.monotonic(),
                    safe_recent_failures_limit,
                    safe_statement_timeout_ms,
                    safe_include_recent_failures,
                    safe_include_stuck_jobs,
                    safe_stuck_jobs_limit,
                    safe_include_runs_summary,
                    payload,
                )
                if not payload.get("queue", {}).get("error"):
                    _queue_status_last_good_cache = (time_module.monotonic(), copy.deepcopy(payload))
        return copy.deepcopy(payload)

    queue_payload: dict[str, Any] = {
        "by_status": _empty_queue_status_counts(),
        "by_stage": {},
        "by_stage_platform": {},
        "by_platform": {},
        "by_job_type": {},
        "recent_failures": [],
        "stuck_jobs": [],
        "stuck_jobs_total": 0,
        "stale_claims": {
            "total": 0,
            "by_reason": {},
            "by_platform": {},
            "by_stage": {},
        },
        "runs_by_status": _empty_queue_status_counts(),
        "runs_total": 0,
    }
    errors: list[str] = []

    try:
        if not _relation_exists("social.scrape_jobs"):
            queue_payload["error"] = "scrape_jobs_table_missing"
            return _finalize(
                {
                    "queue_enabled": is_queue_enabled(),
                    "workers": get_worker_health(),
                    "queue": queue_payload,
                }
            )
    except Exception as exc:  # noqa: BLE001
        errors.append(f"scrape_jobs_relation_check_failed: {exc}")

    try:
        with pg.db_connection() as conn:
            with pg.db_cursor(conn=conn) as cur:
                cur.execute("set local statement_timeout = %s", [str(safe_statement_timeout_ms)])
                aggregate_rows = pg.fetch_all_with_cursor(
                    cur,
                    """
                    select
                      coalesce(platform, 'unknown') as platform,
                      coalesce(job_type, 'unknown') as job_type,
                      coalesce(status, 'unknown') as status,
                      lower(
                        coalesce(
                          nullif(config->>'stage', ''),
                          nullif(metadata->>'stage', ''),
                          nullif(job_type, ''),
                          'unknown'
                        )
                      ) as stage,
                      count(*)::bigint as total
                    from social.scrape_jobs
                    group by 1, 2, 3, 4
                    """,
                )
        by_status = _empty_queue_status_counts()
        by_stage: dict[str, dict[str, int]] = {}
        by_stage_platform: dict[str, dict[str, dict[str, int]]] = {}
        by_platform: dict[str, dict[str, int]] = {}
        by_job_type: dict[str, dict[str, int]] = {}

        for row in aggregate_rows:
            status = str(row.get("status") or "unknown").strip().lower() or "unknown"
            platform = str(row.get("platform") or "unknown").strip().lower() or "unknown"
            job_type = str(row.get("job_type") or "unknown").strip().lower() or "unknown"
            stage = _normalize_social_job_stage_for_stale(row.get("stage")) or "unknown"
            total = int(row.get("total") or 0)

            by_status[status] = by_status.get(status, 0) + total
            stage_bucket = by_stage.setdefault(stage, {})
            stage_bucket[status] = int(stage_bucket.get(status) or 0) + total
            stage_platform_bucket = by_stage_platform.setdefault(stage, {}).setdefault(platform, {})
            stage_platform_bucket[status] = int(stage_platform_bucket.get(status) or 0) + total
            platform_bucket = by_platform.setdefault(platform, {})
            platform_bucket[status] = int(platform_bucket.get(status) or 0) + total
            job_type_bucket = by_job_type.setdefault(job_type, {})
            job_type_bucket[status] = int(job_type_bucket.get(status) or 0) + total

        queue_payload["by_status"] = by_status
        queue_payload["by_stage"] = by_stage
        queue_payload["by_stage_platform"] = by_stage_platform
        queue_payload["by_platform"] = by_platform
        queue_payload["by_job_type"] = by_job_type
    except Exception as exc:  # noqa: BLE001
        logger.warning("Queue status aggregate query failed: %s", exc)
        errors.append(f"queue_aggregate_query_failed: {exc}")

    if safe_include_recent_failures:
        try:
            features = _scrape_jobs_features()
            select_run_id = "run_id::text as run_id" if features.get("has_run_id") else "null::text as run_id"
            select_last_error_code = (
                "last_error_code" if features.get("has_queue_fields") else "null::text as last_error_code"
            )
            select_last_error_class = (
                "last_error_class" if features.get("has_queue_fields") else "null::text as last_error_class"
            )

            with pg.db_connection() as conn:
                with pg.db_cursor(conn=conn) as cur:
                    cur.execute("set local statement_timeout = %s", [str(safe_statement_timeout_ms)])
                    recent_failures = pg.fetch_all_with_cursor(
                        cur,
                        f"""
                        select
                          id::text as id,
                          {select_run_id},
                          platform,
                          job_type,
                          status,
                          error_message,
                          {select_last_error_code},
                          {select_last_error_class},
                          created_at,
                          completed_at
                        from social.scrape_jobs
                        where status in ('failed', 'retrying')
                        order by coalesce(completed_at, created_at) desc
                        limit %s
                        """,
                        [safe_recent_failures_limit],
                    )
            queue_payload["recent_failures"] = [
                {
                    "id": str(row.get("id") or ""),
                    "run_id": str(row.get("run_id") or "").strip() or None,
                    "platform": str(row.get("platform") or ""),
                    "job_type": str(row.get("job_type") or ""),
                    "status": str(row.get("status") or ""),
                    "error_message": str(row.get("error_message") or "") or None,
                    "last_error_code": str(row.get("last_error_code") or "") or None,
                    "last_error_class": str(row.get("last_error_class") or "") or None,
                    "created_at": _iso(_coerce_dt(row.get("created_at"))),
                    "completed_at": _iso(_coerce_dt(row.get("completed_at"))),
                }
                for row in recent_failures
            ]
        except Exception as exc:  # noqa: BLE001
            logger.warning("Queue status recent-failures query failed: %s", exc)
            errors.append(f"queue_recent_failures_query_failed: {exc}")

    if safe_include_stuck_jobs:
        try:
            stuck_jobs, stuck_jobs_total = _list_stuck_jobs(limit=safe_stuck_jobs_limit)
            queue_payload["stuck_jobs"] = stuck_jobs
            queue_payload["stuck_jobs_total"] = stuck_jobs_total
            stale_claims_by_reason: dict[str, int] = {}
            stale_claims_by_platform: dict[str, int] = {}
            stale_claims_by_stage: dict[str, int] = {}
            for row in stuck_jobs:
                reason = str(row.get("stuck_reason") or "unknown").strip().lower() or "unknown"
                platform = str(row.get("platform") or "unknown").strip().lower() or "unknown"
                stage = _normalize_social_job_stage_for_stale(row.get("job_type")) or "unknown"
                stale_claims_by_reason[reason] = int(stale_claims_by_reason.get(reason) or 0) + 1
                stale_claims_by_platform[platform] = int(stale_claims_by_platform.get(platform) or 0) + 1
                stale_claims_by_stage[stage] = int(stale_claims_by_stage.get(stage) or 0) + 1
            queue_payload["stale_claims"] = {
                "total": int(stuck_jobs_total or 0),
                "by_reason": stale_claims_by_reason,
                "by_platform": stale_claims_by_platform,
                "by_stage": stale_claims_by_stage,
            }
        except Exception as exc:  # noqa: BLE001
            logger.warning("Queue status stuck-jobs query failed: %s", exc)
            errors.append(f"queue_stuck_jobs_query_failed: {exc}")

    if safe_include_runs_summary:
        try:
            if _relation_exists("social.scrape_runs"):
                with pg.db_connection() as conn:
                    with pg.db_cursor(conn=conn) as cur:
                        cur.execute("set local statement_timeout = %s", [str(safe_statement_timeout_ms)])
                        run_rows = pg.fetch_all_with_cursor(
                            cur,
                            """
                            select
                              coalesce(status, 'unknown') as status,
                              count(*)::bigint as total
                            from social.scrape_runs
                            group by 1
                            """,
                        )
                runs_by_status = _empty_queue_status_counts()
                runs_total = 0
                for row in run_rows:
                    status = str(row.get("status") or "unknown").strip().lower() or "unknown"
                    total = int(row.get("total") or 0)
                    runs_by_status[status] = runs_by_status.get(status, 0) + total
                    runs_total += total
                queue_payload["runs_by_status"] = runs_by_status
                queue_payload["runs_total"] = runs_total
            else:
                queue_payload["runs_by_status"] = _empty_queue_status_counts()
                queue_payload["runs_total"] = 0
        except Exception as exc:  # noqa: BLE001
            logger.warning("Queue status runs-summary query failed: %s", exc)
            errors.append(f"queue_runs_summary_query_failed: {exc}")

    workers_payload: dict[str, Any]
    try:
        workers_payload = get_worker_health()
    except Exception as exc:  # noqa: BLE001
        logger.warning("Queue status worker-health query failed: %s", exc)
        errors.append(f"queue_worker_health_failed: {exc}")
        queue_payload["error"] = "; ".join(errors)
        workers_payload = {
            "healthy": False,
            "healthy_workers": 0,
            "fresh_workers": 0,
            "stale_workers": 0,
            "stale_hidden_count": 0,
            "active_workers": 0,
            "total_workers": 0,
            "stale_after_seconds": _resolve_positive_int_env(
                "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
                SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
                minimum=30,
            ),
            "executor_backend": "modal" if is_modal_remote_executor_enabled() else execution_backend_canonical(),
            "dispatch_enabled": False,
            "dispatcher_heartbeat_fresh": False,
            "active_invocations": 0,
            "oldest_queued_age_seconds": None,
            "stale_running_count": 0,
            "last_dispatch_success_at": None,
            "last_dispatch_error": None,
            "workers": [],
            "reason": "health_query_failed",
        }

    if errors:
        stale_fallback_seconds = _resolve_positive_int_env(
            "SOCIAL_QUEUE_STATUS_STALE_FALLBACK_SECONDS",
            SOCIAL_QUEUE_STATUS_STALE_FALLBACK_SECONDS_DEFAULT,
            minimum=0,
        )
        if stale_fallback_seconds > 0:
            with _queue_status_cache_lock:
                if _queue_status_last_good_cache is not None:
                    cached_at, cached_payload = _queue_status_last_good_cache
                    if (time_module.monotonic() - cached_at) <= stale_fallback_seconds:
                        return copy.deepcopy(cached_payload)
        queue_payload["error"] = "; ".join(errors)

    return _finalize(
        {
            "queue_enabled": is_queue_enabled(),
            "remote_plane": _configured_execution_metadata(),
            "workers": workers_payload,
            "queue": queue_payload,
        }
    )


def cancel_stuck_jobs(
    *,
    job_ids: list[str] | None = None,
    cancelled_by: str | None = None,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    if not _relation_exists("social.scrape_jobs"):
        raise ValueError("scrape_jobs table not found")

    requested_ids = []
    seen_ids: set[str] = set()
    for raw in job_ids or []:
        value = str(raw or "").strip()
        if not value or value in seen_ids:
            continue
        seen_ids.add(value)
        requested_ids.append(value)

    features = _scrape_jobs_features()
    has_queue_fields = bool(features.get("has_queue_fields"))
    where_clause, where_params = _stuck_jobs_filter_clause(has_queue_fields=has_queue_fields, table_alias="j")
    metadata_payload = {
        "cancel_reason": "stuck_job_cancelled_by_admin",
        "cancelled_by": cancelled_by,
        "cancelled_at": _iso(_now_utc()),
    }
    updated_rows = pg.fetch_all(
        f"""
        with candidate_jobs as (
          select j.id
          from social.scrape_jobs j
          where {where_clause}
            and (%s::uuid[] is null or j.id = any(%s::uuid[]))
          for update skip locked
        )
        update social.scrape_jobs as j
        set
          status = 'cancelled',
          completed_at = now(),
          error_message = coalesce(j.error_message, 'Cancelled by user request (stuck job)'),
          metadata = coalesce(j.metadata, '{{}}'::jsonb) || %s::jsonb
        from candidate_jobs c
        where j.id = c.id
        returning j.id::text as id, j.run_id::text as run_id
        """,
        [
            *where_params,
            requested_ids if requested_ids else None,
            requested_ids if requested_ids else None,
            json.dumps(metadata_payload),
        ],
    )
    cancelled_job_ids = [str(row.get("id") or "") for row in updated_rows if str(row.get("id") or "").strip()]

    for cancelled_job_id in cancelled_job_ids:
        _clear_worker_heartbeat_for_job(
            job_id=cancelled_job_id,
            status="idle",
            metadata={"source": "cancel_stuck_jobs", "job_status": "cancelled"},
        )

    affected_run_ids = sorted(
        {str(row.get("run_id") or "").strip() for row in updated_rows if str(row.get("run_id") or "").strip()}
    )
    for run_id in affected_run_ids:
        _finalize_run_status(run_id, force_recompute=True)

    _invalidate_queue_status_cache()
    return {
        "requested_job_ids_count": len(requested_ids),
        "cancelled_jobs": len(cancelled_job_ids),
        "cancelled_job_ids": cancelled_job_ids,
        "affected_run_ids": affected_run_ids,
        "stuck_jobs_remaining": _count_stuck_jobs(),
    }


def cancel_active_jobs(
    *,
    cancelled_by: str | None = None,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    if not _relation_exists("social.scrape_jobs"):
        raise ValueError("scrape_jobs table not found")

    metadata_payload = {
        "cancel_reason": "active_job_cancelled_by_admin",
        "cancelled_by": cancelled_by,
        "cancelled_at": _iso(_now_utc()),
    }
    updated_rows = pg.fetch_all(
        """
        with candidate_jobs as (
          select j.id
          from social.scrape_jobs j
          where j.status = any(%s::text[])
          for update skip locked
        )
        update social.scrape_jobs as j
        set
          status = 'cancelled',
          completed_at = now(),
          error_message = coalesce(j.error_message, 'Cancelled by user request (active job)'),
          metadata = coalesce(j.metadata, '{}'::jsonb) || %s::jsonb
        from candidate_jobs c
        where j.id = c.id
        returning j.id::text as id, j.run_id::text as run_id
        """,
        [
            list(_ACTIVE_CANCEL_JOB_STATUSES),
            json.dumps(metadata_payload),
        ],
    )
    cancelled_job_ids = [str(row.get("id") or "") for row in updated_rows if str(row.get("id") or "").strip()]

    for cancelled_job_id in cancelled_job_ids:
        _clear_worker_heartbeat_for_job(
            job_id=cancelled_job_id,
            status="idle",
            metadata={"source": "cancel_active_jobs", "job_status": "cancelled"},
        )

    affected_run_ids = sorted(
        {str(row.get("run_id") or "").strip() for row in updated_rows if str(row.get("run_id") or "").strip()}
    )
    for run_id in affected_run_ids:
        _finalize_run_status(run_id, force_recompute=True)

    _invalidate_queue_status_cache()
    return {
        "cancelled_jobs": len(cancelled_job_ids),
        "cancelled_job_ids": cancelled_job_ids,
        "affected_run_ids": affected_run_ids,
        "active_jobs_remaining": _count_active_jobs(),
    }


def _social_debug_repo_root() -> Path:
    return Path(__file__).resolve().parents[2]


def _social_debug_context_max_bytes() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_DEBUG_CONTEXT_MAX_BYTES",
        SOCIAL_DEBUG_CONTEXT_MAX_BYTES_DEFAULT,
        minimum=2_000,
    )


def _social_debug_patch_max_bytes() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_DEBUG_PATCH_MAX_BYTES",
        SOCIAL_DEBUG_PATCH_MAX_BYTES_DEFAULT,
        minimum=10_000,
    )


def _social_debug_patch_apply_enabled() -> bool:
    return _env_truthy("SOCIAL_DEBUG_PATCH_APPLY_ENABLED", default=False)


def _social_debug_model_name() -> str:
    return (
        os.getenv("SOCIAL_DEBUG_OPENAI_MODEL") or SOCIAL_DEBUG_OPENAI_MODEL_DEFAULT
    ).strip() or SOCIAL_DEBUG_OPENAI_MODEL_DEFAULT


def _social_debug_fallback_model_name() -> str:
    fallback = (os.getenv("SOCIAL_DEBUG_OPENAI_FALLBACK_MODEL") or SOCIAL_DEBUG_OPENAI_FALLBACK_MODEL_DEFAULT).strip()
    return fallback or SOCIAL_DEBUG_OPENAI_FALLBACK_MODEL_DEFAULT


def _social_debug_timeout_seconds() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_DEBUG_OPENAI_TIMEOUT_SECONDS",
        SOCIAL_DEBUG_OPENAI_TIMEOUT_SECONDS_DEFAULT,
        minimum=5,
    )


def _extract_snippet_around_marker(
    text: str,
    *,
    marker: str,
    before_chars: int = 200,
    after_chars: int = 2200,
) -> str | None:
    idx = text.find(marker)
    if idx < 0:
        return None
    start = max(0, idx - before_chars)
    end = min(len(text), idx + after_chars)
    return text[start:end].strip()


def _load_social_debug_source_context() -> list[dict[str, str]]:
    repo_root = _social_debug_repo_root()
    sources: list[tuple[str, list[str]]] = [
        (
            "trr_backend/repositories/social_season_analytics.py",
            [
                "def get_queue_status(",
                "def _claim_next_jobs(",
                "def _execute_claimed_job(",
                "def recover_stale_running_jobs(",
            ],
        ),
        (
            "scripts/socials/worker.py",
            [
                "class WorkerHeartbeat:",
                "def main() -> int:",
            ],
        ),
        (
            "api/routers/socials.py",
            [
                "def get_social_ingest_queue_status(",
                "def ingest_season_social(",
            ],
        ),
    ]
    snippets: list[dict[str, str]] = []
    per_file_budget = max(2_000, _social_debug_context_max_bytes() // max(1, len(sources)))
    for rel_path, markers in sources:
        abs_path = repo_root / rel_path
        try:
            raw = abs_path.read_text(encoding="utf-8", errors="ignore")
        except Exception:  # noqa: BLE001
            continue
        extracted: list[str] = []
        for marker in markers:
            candidate = _extract_snippet_around_marker(raw, marker=marker)
            if candidate:
                extracted.append(candidate)
        joined = "\n\n".join(extracted).strip() if extracted else raw[:per_file_budget].strip()
        if not joined:
            continue
        snippets.append(
            {
                "path": rel_path,
                "content": joined[:per_file_budget],
            }
        )
    return snippets


def _fetch_job_debug_context(job_id: str) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    features = _scrape_jobs_features()
    has_run_id = bool(features.get("has_run_id"))
    has_queue_fields = bool(features.get("has_queue_fields"))

    select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
    select_attempt_count = "j.attempt_count" if has_queue_fields else "0::int as attempt_count"
    select_max_attempts = "j.max_attempts" if has_queue_fields else "0::int as max_attempts"
    select_worker_id = "j.worker_id" if has_queue_fields else "null::text as worker_id"
    select_heartbeat_at = "j.heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
    select_last_error_code = "j.last_error_code" if has_queue_fields else "null::text as last_error_code"
    job_row = pg.fetch_one(
        f"""
        select
          j.id::text as id,
          {select_run_id},
          j.platform,
          j.job_type,
          j.status,
          j.config,
          j.metadata,
          j.items_found,
          j.error_message,
          j.started_at,
          j.created_at,
          j.completed_at,
          {select_attempt_count},
          {select_max_attempts},
          {select_worker_id},
          {select_heartbeat_at},
          {select_last_error_code}
        from social.scrape_jobs j
        where j.id = %s::uuid
        limit 1
        """,
        [job_id],
    )
    if not job_row:
        raise ValueError("job_not_found")

    worker_row: dict[str, Any] | None = None
    worker_id = str(job_row.get("worker_id") or "").strip()
    if _worker_heartbeat_schema_ready():
        if worker_id:
            worker_row = pg.fetch_one(
                """
                select
                  worker_id,
                  stage,
                  status,
                  run_id::text as run_id,
                  current_job_id::text as current_job_id,
                  metadata,
                  started_at,
                  last_seen_at
                from social.scrape_workers
                where worker_id = %s
                limit 1
                """,
                [worker_id],
            )
        if not worker_row:
            worker_row = pg.fetch_one(
                """
                select
                  worker_id,
                  stage,
                  status,
                  run_id::text as run_id,
                  current_job_id::text as current_job_id,
                  metadata,
                  started_at,
                  last_seen_at
                from social.scrape_workers
                where current_job_id = %s::uuid
                order by last_seen_at desc
                limit 1
                """,
                [job_id],
            )

    run_row: dict[str, Any] | None = None
    run_id = str(job_row.get("run_id") or "").strip()
    if run_id and _relation_exists("social.scrape_runs"):
        run_row = pg.fetch_one(
            """
            select
              id::text as run_id,
              status,
              source_scope,
              created_at,
              started_at,
              completed_at,
              summary
            from social.scrape_runs
            where id = %s::uuid
            limit 1
            """,
            [run_id],
        )

    return {
        "job": {
            "id": str(job_row.get("id") or ""),
            "run_id": run_id or None,
            "platform": str(job_row.get("platform") or ""),
            "job_type": str(job_row.get("job_type") or ""),
            "status": str(job_row.get("status") or ""),
            "items_found": _normalize_non_negative_int(job_row.get("items_found")),
            "error_message": str(job_row.get("error_message") or "").strip() or None,
            "started_at": _iso(_coerce_dt(job_row.get("started_at"))),
            "created_at": _iso(_coerce_dt(job_row.get("created_at"))),
            "completed_at": _iso(_coerce_dt(job_row.get("completed_at"))),
            "attempt_count": _normalize_non_negative_int(job_row.get("attempt_count")),
            "max_attempts": _normalize_non_negative_int(job_row.get("max_attempts")),
            "worker_id": str(job_row.get("worker_id") or "").strip() or None,
            "heartbeat_at": _iso(_coerce_dt(job_row.get("heartbeat_at"))),
            "last_error_code": str(job_row.get("last_error_code") or "").strip() or None,
            "config": _metadata_dict(job_row.get("config")),
            "metadata": _metadata_dict(job_row.get("metadata")),
        },
        "worker": {
            "worker_id": str((worker_row or {}).get("worker_id") or "").strip() or None,
            "stage": str((worker_row or {}).get("stage") or "").strip() or None,
            "status": str((worker_row or {}).get("status") or "").strip() or None,
            "run_id": str((worker_row or {}).get("run_id") or "").strip() or None,
            "current_job_id": str((worker_row or {}).get("current_job_id") or "").strip() or None,
            "metadata": _metadata_dict((worker_row or {}).get("metadata")),
            "started_at": _iso(_coerce_dt((worker_row or {}).get("started_at"))),
            "last_seen_at": _iso(_coerce_dt((worker_row or {}).get("last_seen_at"))),
        },
        "run": {
            "run_id": str((run_row or {}).get("run_id") or "").strip() or None,
            "status": str((run_row or {}).get("status") or "").strip() or None,
            "source_scope": str((run_row or {}).get("source_scope") or "").strip() or None,
            "created_at": _iso(_coerce_dt((run_row or {}).get("created_at"))),
            "started_at": _iso(_coerce_dt((run_row or {}).get("started_at"))),
            "completed_at": _iso(_coerce_dt((run_row or {}).get("completed_at"))),
            "summary": _metadata_dict((run_row or {}).get("summary")),
        },
    }


def _build_social_debug_prompt(
    *,
    job_context: dict[str, Any],
    source_context: list[dict[str, str]],
) -> str:
    prompt_payload = {
        "job_context": job_context,
        "source_context": source_context,
        "task": "Diagnose stuck/failed social ingest job and produce exact unified diff patch.",
        "required_output_schema": {
            "root_cause": "string",
            "confidence": "number between 0 and 1",
            "patch_unified_diff": "string unified diff",
            "files_touched": ["string file paths"],
            "tests_to_run": ["string commands"],
        },
        "constraints": [
            "Return strict JSON object only.",
            "patch_unified_diff must be valid unified diff with ---/+++ headers.",
            "Avoid changing unrelated files.",
            "Focus on root-cause fix with smallest safe patch.",
        ],
    }
    return json.dumps(prompt_payload, separators=(",", ":"), ensure_ascii=True)


def _run_social_debug_openai_completion(
    *,
    model: str,
    prompt: str,
    api_key: str,
    timeout_seconds: int,
) -> dict[str, Any]:
    response = requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "model": model,
            "messages": [
                {
                    "role": "system",
                    "content": "You are a senior backend engineer. Return strict JSON only.",
                },
                {"role": "user", "content": prompt},
            ],
            "temperature": 0,
            "response_format": {"type": "json_object"},
        },
        timeout=max(5, int(timeout_seconds)),
    )
    response.raise_for_status()
    payload = response.json()
    choices = payload.get("choices")
    if not isinstance(choices, list) or not choices:
        raise RuntimeError("OpenAI response missing choices")
    message = choices[0].get("message") if isinstance(choices[0], dict) else None
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("OpenAI response missing content")
    parsed = json.loads(content)
    if not isinstance(parsed, dict):
        raise RuntimeError("OpenAI response is not a JSON object")
    return parsed


def _extract_unified_diff_paths(patch_unified_diff: str) -> list[str]:
    paths: list[str] = []
    for raw_line in patch_unified_diff.splitlines():
        line = raw_line.strip()
        if not (line.startswith("+++ ") or line.startswith("--- ")):
            continue
        candidate = line[4:].strip()
        if candidate == "/dev/null":
            continue
        if candidate.startswith("a/") or candidate.startswith("b/"):
            candidate = candidate[2:]
        if not candidate:
            continue
        if candidate not in paths:
            paths.append(candidate)
    return paths


def _validate_debug_patch_paths(paths: list[str]) -> None:
    if not paths:
        raise ValueError("patch_unified_diff did not include file paths")
    for path in paths:
        normalized = str(path or "").strip()
        if not normalized:
            raise ValueError("patch path is empty")
        if normalized.startswith("/") or normalized.startswith("~"):
            raise ValueError(f"patch path is absolute: {normalized}")
        if ".." in Path(normalized).parts:
            raise ValueError(f"patch path contains traversal: {normalized}")
        top_level = normalized.split("/", 1)[0]
        if top_level not in SOCIAL_DEBUG_ALLOWED_TOP_LEVEL_PATHS:
            raise ValueError(f"patch path outside allowlist: {normalized}")


def _run_git_apply(*, patch_unified_diff: str, check_only: bool) -> subprocess.CompletedProcess[str]:
    cmd = ["git", "apply", "--whitespace=nowarn"]
    if check_only:
        cmd.append("--check")
    cmd.append("-")
    return subprocess.run(
        cmd,
        cwd=str(_social_debug_repo_root()),
        input=patch_unified_diff,
        text=True,
        capture_output=True,
        check=False,
    )


def debug_ingest_job_with_openai(
    job_id: str,
    *,
    apply_patch: bool = False,
    confirm_apply: bool = False,
    include_context: bool = True,
) -> dict[str, Any]:
    normalized_job_id = str(job_id or "").strip()
    if not normalized_job_id:
        raise ValueError("job_not_found")
    context_payload = _fetch_job_debug_context(normalized_job_id)
    api_key = (os.getenv("OPENAI_API_KEY") or "").strip()
    if not api_key:
        raise ValueError("openai_api_key_missing")

    source_context = _load_social_debug_source_context() if include_context else []
    prompt = _build_social_debug_prompt(job_context=context_payload, source_context=source_context)
    models = [_social_debug_model_name(), _social_debug_fallback_model_name()]
    models = [model for idx, model in enumerate(models) if model and (idx == 0 or model != models[0])]

    ai_payload: dict[str, Any] | None = None
    model_used: str | None = None
    fallback_used = False
    final_error: Exception | None = None
    for idx, model in enumerate(models):
        try:
            ai_payload = _run_social_debug_openai_completion(
                model=model,
                prompt=prompt,
                api_key=api_key,
                timeout_seconds=_social_debug_timeout_seconds(),
            )
            model_used = model
            fallback_used = idx > 0
            break
        except Exception as exc:  # noqa: BLE001
            final_error = exc
            continue
    if ai_payload is None or model_used is None:
        raise RuntimeError(f"openai_debug_failed: {final_error}")

    root_cause = str(ai_payload.get("root_cause") or "").strip() or "No root cause provided."
    raw_confidence = ai_payload.get("confidence")
    try:
        confidence = max(0.0, min(1.0, float(raw_confidence)))
    except (TypeError, ValueError):
        confidence = 0.0
    files_touched_raw = ai_payload.get("files_touched")
    files_touched = (
        [str(item).strip() for item in files_touched_raw if str(item).strip()]
        if isinstance(files_touched_raw, list)
        else []
    )
    tests_to_run_raw = ai_payload.get("tests_to_run")
    tests_to_run = (
        [str(item).strip() for item in tests_to_run_raw if str(item).strip()]
        if isinstance(tests_to_run_raw, list)
        else []
    )
    patch_unified_diff = str(ai_payload.get("patch_unified_diff") or "")
    patch_max_bytes = _social_debug_patch_max_bytes()
    if len(patch_unified_diff.encode("utf-8")) > patch_max_bytes:
        patch_unified_diff = patch_unified_diff.encode("utf-8")[:patch_max_bytes].decode("utf-8", errors="ignore")

    apply_enabled = _social_debug_patch_apply_enabled()
    apply_requested = bool(apply_patch)
    apply_result = {
        "enabled": apply_enabled,
        "requested": apply_requested,
        "applied": False,
        "check_ok": False,
        "error": None,
        "files_changed": [],
    }
    if apply_requested:
        if not apply_enabled:
            apply_result["error"] = "Patch apply is disabled by server configuration."
        elif not confirm_apply:
            apply_result["error"] = "confirm_apply=true is required to apply patch."
        elif not patch_unified_diff.strip():
            apply_result["error"] = "No patch_unified_diff returned by debug model."
        else:
            paths = _extract_unified_diff_paths(patch_unified_diff)
            try:
                _validate_debug_patch_paths(paths)
                check_proc = _run_git_apply(patch_unified_diff=patch_unified_diff, check_only=True)
                apply_result["check_ok"] = check_proc.returncode == 0
                if check_proc.returncode != 0:
                    apply_result["error"] = (
                        check_proc.stderr or check_proc.stdout or "git apply --check failed"
                    ).strip()
                else:
                    apply_proc = _run_git_apply(patch_unified_diff=patch_unified_diff, check_only=False)
                    if apply_proc.returncode != 0:
                        apply_result["error"] = (apply_proc.stderr or apply_proc.stdout or "git apply failed").strip()
                    else:
                        apply_result["applied"] = True
                        apply_result["files_changed"] = paths
            except Exception as exc:  # noqa: BLE001
                apply_result["error"] = str(exc)

    return {
        "job_id": context_payload["job"]["id"],
        "run_id": context_payload["job"].get("run_id"),
        "model_used": model_used,
        "fallback_used": fallback_used,
        "analysis": {
            "root_cause": root_cause,
            "confidence": confidence,
            "files_touched": files_touched,
            "tests_to_run": tests_to_run,
        },
        "patch_unified_diff": patch_unified_diff,
        "apply": apply_result,
    }


def _resolve_depth_defaults(
    *,
    max_posts_per_target: int | None,
    max_comments_per_post: int | None,
    max_replies_per_post: int | None,
    fetch_replies: bool,
) -> tuple[int, int, int, bool]:
    # Explicit zero from sync callers means "no cap" for depth limits.
    uncapped_depth_limit = 1_000_000
    default_comments = _resolve_positive_int_env(
        "SOCIAL_DEFAULT_MAX_COMMENTS_PER_POST",
        200,
        minimum=0,
    )
    default_replies = _resolve_positive_int_env(
        "SOCIAL_DEFAULT_MAX_REPLIES_PER_POST",
        100,
        minimum=0,
    )
    if max_posts_per_target is None:
        resolved_posts = 0
    else:
        resolved_posts = max(0, int(max_posts_per_target))
    if max_comments_per_post is None:
        resolved_comments = default_comments
    else:
        resolved_comments = (
            uncapped_depth_limit if int(max_comments_per_post) == 0 else max(0, int(max_comments_per_post))
        )
    if max_replies_per_post is None:
        resolved_replies = default_replies
    else:
        resolved_replies = uncapped_depth_limit if int(max_replies_per_post) == 0 else max(0, int(max_replies_per_post))
    return (
        resolved_posts,
        resolved_comments,
        resolved_replies,
        fetch_replies,
    )


def _normalize_comment_refresh_policy(raw: Any) -> str:
    normalized = str(raw or DEFAULT_COMMENT_REFRESH_POLICY).strip().lower()
    if normalized not in SUPPORTED_COMMENT_REFRESH_POLICIES:
        return DEFAULT_COMMENT_REFRESH_POLICY
    return normalized


def _normalize_platform_name(value: Any) -> str:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return ""

    normalized = re.sub(r"[^a-z0-9]+", " ", normalized).strip()
    tokens = [token for token in normalized.split() if token]
    if not tokens:
        return ""

    token_aliases = {
        "x": "twitter",
        "ig": "instagram",
        "insta": "instagram",
        "fb": "facebook",
        "meta": "facebook",
    }
    if tokens[0] == "meta" and len(tokens) > 1 and tokens[1] == "threads":
        canonical = "threads"
    else:
        canonical = token_aliases.get(tokens[0], tokens[0])
    return canonical


def _normalize_comment_anchor_source_ids(
    raw: Any,
    *,
    allowed_platforms: set[str] | None = None,
    per_platform_limit: int = MAX_COMMENT_ANCHOR_SOURCE_IDS_PER_PLATFORM,
) -> tuple[dict[str, set[str]], list[str]]:
    if not isinstance(raw, dict):
        return {}, []

    normalized: dict[str, set[str]] = {}
    overflow_platforms: list[str] = []
    for key, value in raw.items():
        platform = _normalize_platform_name(key)
        if platform not in SUPPORTED_PLATFORMS:
            continue
        if allowed_platforms is not None and platform not in allowed_platforms:
            continue

        source_ids: list[str] = []
        for item in value if isinstance(value, list) else []:
            normalized_id = str(item or "").strip()
            if normalized_id:
                source_ids.append(normalized_id)
        unique_source_ids = set(source_ids)
        if len(unique_source_ids) > per_platform_limit:
            overflow_platforms.append(platform)
            continue
        normalized[platform] = unique_source_ids
    return normalized, overflow_platforms


def _resolve_requested_platforms(platforms: list[str] | None) -> list[str]:
    if platforms is None:
        return list(SUPPORTED_PLATFORMS)

    normalized_requested = []
    for platform in platforms:
        normalized = _normalize_platform_name(platform)
        if normalized:
            normalized_requested.append(normalized)

    invalid_platforms = sorted({platform for platform in normalized_requested if platform not in SUPPORTED_PLATFORMS})
    if invalid_platforms:
        raise ValueError(f"INVALID_PLATFORM_FILTER: {', '.join(invalid_platforms)}")

    deduped: list[str] = []
    seen: set[str] = set()
    for platform in normalized_requested:
        if platform in seen:
            continue
        seen.add(platform)
        deduped.append(platform)
    if not deduped:
        raise ValueError("INVALID_PLATFORM_FILTER: no valid platforms requested")
    return deduped


def _serialize_comment_anchor_source_ids(
    source_ids: dict[str, set[str]] | None,
) -> dict[str, list[str]] | None:
    if source_ids is None:
        return None
    return {platform: sorted(values) for platform, values in source_ids.items()}


def _target_source_ids_for_platform(opts: IngestOptions, platform: str) -> set[str] | None:
    normalized_platform = _normalize_platform_name(platform)
    source_ids = opts.comment_anchor_source_ids or {}
    if normalized_platform not in source_ids:
        return None
    return set(source_ids.get(normalized_platform) or set())


def _coerce_dt(value: Any) -> datetime | None:
    if value is None:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=UTC)
    if isinstance(value, date):
        return datetime.combine(value, time.min, tzinfo=UTC)
    if isinstance(value, str):
        raw = value.strip()
        if not raw:
            return None
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
            return parsed if parsed.tzinfo else parsed.replace(tzinfo=UTC)
        except ValueError:
            return None
    return None


def _iso(dt: datetime | None) -> str | None:
    if not dt:
        return None
    return dt.astimezone(UTC).isoformat()


def _to_et_date(dt: datetime | None, tz_name: str) -> date | None:
    if dt is None:
        return None
    zone = ZoneInfo(tz_name)
    return dt.astimezone(zone).date()


def _relation_exists(qualified_name: str) -> bool:
    try:
        row = pg.fetch_one("select to_regclass(%s) is not null as exists", [qualified_name]) or {}
    except Exception:
        return False
    return bool(row.get("exists"))


_column_exists_cache: dict[tuple[str, str, str], bool] = {}
_relation_columns_cache: dict[tuple[str, str], set[str]] = {}
_scrape_jobs_features_cache: dict[str, bool] | None = None
_run_counter_columns_cache: bool | None = None
_analytics_cache: dict[tuple[Any, ...], tuple[float, dict[str, Any]]] = {}
_analytics_cache_lock = Lock()

# -- Scraper instance cache (reuse HTTP sessions across jobs on the same worker) --
_scraper_cache: dict[str, tuple[float, Any]] = {}  # key → (created_at, scraper)
_SCRAPER_CACHE_TTL_SEC = 300  # 5 minutes


def _get_cached_scraper(cookies: dict[str, str]) -> Any:
    """Return a cached InstagramScraper if one exists for these cookies and is still fresh."""
    cache_key = hashlib.sha256(json.dumps(cookies, sort_keys=True).encode()).hexdigest()[:16]
    entry = _scraper_cache.get(cache_key)
    if entry is not None:
        created_at, scraper = entry
        if time_module.time() - created_at < _SCRAPER_CACHE_TTL_SEC:
            return scraper
        # Expired — remove
        _scraper_cache.pop(cache_key, None)
    return None


def _cache_scraper(cookies: dict[str, str], scraper: Any) -> None:
    """Store a scraper instance in the cache keyed by cookies hash."""
    cache_key = hashlib.sha256(json.dumps(cookies, sort_keys=True).encode()).hexdigest()[:16]
    _scraper_cache[cache_key] = (time_module.time(), scraper)


def _column_exists(schema: str, table: str, column: str) -> bool:
    key = (schema, table, column)
    cached = _column_exists_cache.get(key)
    if cached is not None:
        return cached
    row = (
        pg.fetch_one(
            """
        select exists (
          select 1
          from information_schema.columns
          where table_schema = %s
            and table_name = %s
            and column_name = %s
        ) as exists
        """,
            [schema, table, column],
        )
        or {}
    )
    result = bool(row.get("exists"))
    _column_exists_cache[key] = result
    return result


def _relation_columns(schema: str, relation: str) -> set[str]:
    key = (schema, relation)
    cached = _relation_columns_cache.get(key)
    if cached is not None:
        return cached
    rows = pg.fetch_all(
        """
        select column_name
        from information_schema.columns
        where table_schema = %s
          and table_name = %s
        """,
        [schema, relation],
    )
    columns = {
        str(row.get("column_name") or "").strip().lower() for row in rows if str(row.get("column_name") or "").strip()
    }
    _relation_columns_cache[key] = columns
    return columns


def _scrape_jobs_features() -> dict[str, bool]:
    global _scrape_jobs_features_cache
    if _scrape_jobs_features_cache is not None:
        return _scrape_jobs_features_cache
    has_run_id = _column_exists("social", "scrape_jobs", "run_id")
    has_queue_fields = all(
        [
            _column_exists("social", "scrape_jobs", "attempt_count"),
            _column_exists("social", "scrape_jobs", "max_attempts"),
            _column_exists("social", "scrape_jobs", "priority"),
            _column_exists("social", "scrape_jobs", "available_at"),
            _column_exists("social", "scrape_jobs", "claimed_at"),
            _column_exists("social", "scrape_jobs", "heartbeat_at"),
            _column_exists("social", "scrape_jobs", "worker_id"),
            _column_exists("social", "scrape_jobs", "last_error_code"),
            _column_exists("social", "scrape_jobs", "last_error_class"),
        ]
    )
    _scrape_jobs_features_cache = {
        "has_run_id": has_run_id,
        "has_queue_fields": has_queue_fields,
    }
    return _scrape_jobs_features_cache


def _run_counter_columns_ready() -> bool:
    global _run_counter_columns_cache
    if _run_counter_columns_cache is not None:
        return _run_counter_columns_cache
    try:
        _run_counter_columns_cache = all(
            [
                _column_exists("social", "scrape_runs", "total_jobs"),
                _column_exists("social", "scrape_runs", "completed_jobs"),
                _column_exists("social", "scrape_runs", "failed_jobs"),
                _column_exists("social", "scrape_runs", "active_jobs"),
                _column_exists("social", "scrape_runs", "items_found_total"),
                _column_exists("social", "scrape_runs", "stage_counts"),
            ]
        )
    except Exception:
        _run_counter_columns_cache = False
    return _run_counter_columns_cache


def _instagram_posts_has_column(column: str) -> bool:
    """Best-effort schema guard for additive instagram_posts columns."""
    try:
        return _column_exists("social", "instagram_posts", column)
    except Exception:
        # Fall back to existing behavior if schema introspection is unavailable.
        return True


def _platform_posts_has_column(platform: str, column: str) -> bool:
    table = PLATFORM_POST_TABLES.get((platform or "").strip().lower())
    if not table:
        return False
    try:
        return _column_exists("social", table, column)
    except Exception:
        return True


def _platform_comments_has_column(platform: str, column: str) -> bool:
    table = PLATFORM_COMMENT_TABLES.get((platform or "").strip().lower())
    if not table:
        return False
    try:
        return _column_exists("social", table, column)
    except Exception:
        return True


def _tiktok_comments_has_column(column: str) -> bool:
    return _platform_comments_has_column("tiktok", column)


def _youtube_is_short_expr(alias: str) -> str:
    if _platform_posts_has_column("youtube", "is_short"):
        return f"coalesce({alias}.is_short, false)"
    return "false"


def _platform_thumbnail_expr(alias: str, platform: str) -> str:
    normalized = (platform or "").strip().lower()
    if normalized == "instagram":
        return _instagram_posts_thumbnail_expr(alias)
    if normalized == "tiktok":
        return (
            "coalesce("
            f"nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', ''), "
            f"nullif({alias}.thumbnail_url, ''), "
            f"nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, '')"
            ")"
        )
    if normalized == "youtube":
        return (
            "coalesce("
            f"nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', ''), "
            f"nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, ''), "
            f"nullif({alias}.thumbnail_url, '')"
            ")"
        )
    if normalized == "twitter":
        return (
            "coalesce("
            f"nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', ''), "
            f"nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, ''), "
            f"nullif({alias}.media_urls ->> 0, '')"
            ")"
        )
    if normalized in {"facebook", "threads"}:
        return (
            "coalesce("
            f"nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', ''), "
            f"nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, ''), "
            f"nullif({alias}.thumbnail_url, ''), "
            f"nullif({alias}.media_urls ->> 0, '')"
            ")"
        )
    return f"nullif({alias}.thumbnail_url, '')"


def _platform_hosted_media_expr(alias: str) -> str:
    return f"coalesce(to_jsonb({alias}) -> 'hosted_media_urls', '[]'::jsonb)"


def _instagram_posts_thumbnail_expr(alias: str = "p") -> str:
    return (
        "coalesce("
        f"nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', ''), "
        f"nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, ''), "
        f"nullif({alias}.thumbnail_url, '')"
        ")"
    )


def _instagram_posts_json_array_expr(alias: str, key: str) -> str:
    return f"coalesce(to_jsonb({alias}) -> '{key}', '[]'::jsonb)"


def _instagram_posts_json_text_expr(alias: str, key: str) -> str:
    return f"(to_jsonb({alias}) ->> '{key}')"


def _instagram_posts_json_int_expr(alias: str, key: str) -> str:
    return f"nullif(to_jsonb({alias}) ->> '{key}', '')::integer"


def _instagram_posts_json_timestamptz_expr(alias: str, key: str) -> str:
    return f"nullif(to_jsonb({alias}) ->> '{key}', '')::timestamptz"


def _instagram_posts_duration_expr(alias: str = "p") -> str:
    return f"nullif(to_jsonb({alias}) ->> 'duration_seconds', '')::integer"


def _assert_social_queue_schema_ready() -> None:
    missing: list[str] = []
    if not _relation_exists("social.scrape_runs"):
        missing.append("social.scrape_runs table (migration 0121)")
    for col, migration in (
        ("run_id", "0122"),
        ("available_at", "0122"),
        ("priority", "0122"),
        ("attempt_count", "0122"),
    ):
        if not _column_exists("social", "scrape_jobs", col):
            missing.append(f"social.scrape_jobs.{col} column (migration {migration})")

    if missing:
        details = "; ".join(missing)
        raise ValueError(
            f"Social ingest queue schema is not migrated. Apply migrations 0121, 0122, 0123. Missing: {details}"
        )


def _slug_words(value: str) -> list[str]:
    cleaned = re.sub(r"[^a-zA-Z0-9 ]+", " ", value).strip()
    return [token for token in cleaned.split() if token]


def _normalize_unique_terms(values: list[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for raw in values:
        value = str(raw or "").strip()
        if not value:
            continue
        key = value.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(value)
    return out


def _derive_show_terms(show_name: str | None) -> tuple[list[str], list[str]]:
    if not show_name:
        return [], []

    words = _slug_words(show_name)
    if not words:
        return [], []

    lower_name = show_name.lower()
    hashtags: list[str] = ["".join(words)]
    keywords: list[str] = [show_name]

    # Canonical RHOSLC aliases requested by product requirements.
    if "salt lake city" in lower_name:
        keywords.extend(["Real Housewives of Salt Lake City", "Salt Lake City", "RHOSLC"])
        hashtags.extend(["RHOSLC", "RealHousewivesofSaltLakeCity"])

    # Generic Real Housewives acronym fallback (e.g., RHOBH, RHOP).
    franchise_match = re.search(r"real housewives of (.+)", lower_name)
    if franchise_match:
        suffix_words = [
            token for token in _slug_words(franchise_match.group(1)) if token.lower() not in {"the", "of", "and"}
        ]
        if suffix_words:
            acronym = f"rho{''.join(token[0].lower() for token in suffix_words)}"
            keywords.append(acronym.upper())
            hashtags.append(acronym)

    return _normalize_unique_terms(hashtags), _normalize_unique_terms(keywords)


def _show_name_is_rhoslc(show_name: Any) -> bool:
    normalized = str(show_name or "").strip().lower()
    if not normalized:
        return False
    return "salt lake city" in normalized or normalized == "rhoslc"


def _show_is_rhoslc(context: SeasonContext | None) -> bool:
    if context is None:
        return False
    show_slug = str(context.show_slug or "").strip().lower()
    if show_slug == "rhoslc":
        return True
    return _show_name_is_rhoslc(context.show_name)


_BRAVO_CORE_PLATFORM_ACCOUNTS: dict[str, tuple[str, ...]] = {
    "instagram": ("bravotv", "bravowwhl"),
    "tiktok": ("bravotv", "bravowwhl"),
    "twitter": ("bravotv", "bravowwhl"),
}


def _ensure_bravo_core_platform_accounts(
    *,
    source_scope: str,
    platform: str | None,
    accounts: list[str],
) -> list[str]:
    if source_scope != "bravo":
        return accounts
    normalized_platform = _normalize_platform_name(platform)
    required_accounts = _BRAVO_CORE_PLATFORM_ACCOUNTS.get(normalized_platform)
    if not required_accounts:
        return accounts
    merged = _normalize_unique_terms([*accounts, *required_accounts])
    return [item.lower().lstrip("@") for item in merged if str(item or "").strip()]


