def _use_authoritative_account_override(
    *,
    context: SeasonContext | None,
    source_scope: str,
    platform: str,
    normalized_accounts_override: list[str],
) -> bool:
    del context
    if not normalized_accounts_override:
        return False
    if source_scope != "bravo":
        return False
    if _normalize_platform_name(platform) not in SUPPORTED_PLATFORMS:
        return False
    return True


def _has_required_rhoslc_hashtag(*, text: str | None, hashtags: list[str] | None = None) -> bool:
    for tag in hashtags or []:
        if str(tag or "").strip().lower().lstrip("#") == "rhoslc":
            return True
    return bool(re.search(r"(?<![\w.])#rhoslc\b", str(text or ""), flags=re.IGNORECASE))


def _text_contains_any_term(*, text: str | None, hashtags: list[str], keywords: list[str]) -> bool:
    term_hashtags = [str(tag).strip().lstrip("#").lower() for tag in hashtags if str(tag).strip()]
    term_keywords = [str(kw).strip().lower() for kw in keywords if str(kw).strip()]
    if not term_hashtags and not term_keywords:
        return True

    haystack = (text or "").lower()
    if not haystack:
        return False

    for tag in term_hashtags:
        if f"#{tag}" in haystack or re.search(rf"\b{re.escape(tag)}\b", haystack):
            return True
    for keyword in term_keywords:
        if keyword in haystack:
            return True
    return False


def _instagram_post_matches_show_terms(
    *,
    context: SeasonContext,
    text: str | None,
    post_hashtags: list[str],
    hashtags: list[str],
    keywords: list[str],
) -> bool:
    if _show_is_rhoslc(context):
        return _has_required_rhoslc_hashtag(text=text, hashtags=post_hashtags)

    return _text_contains_any_term(text=text, hashtags=hashtags, keywords=keywords)


def _instagram_row_has_required_rhoslc_hashtag(row: dict[str, Any]) -> bool:
    row_hashtags = _as_text_list(row.get("hashtags"), strip_prefix="#")
    return _has_required_rhoslc_hashtag(text=str(row.get("caption") or ""), hashtags=row_hashtags)


def _twitter_post_matches_show_terms(
    *,
    context: SeasonContext,
    text: str | None,
    post_hashtags: list[str],
    hashtags: list[str],
    keywords: list[str],
) -> bool:
    if _show_is_rhoslc(context):
        return _has_required_rhoslc_hashtag(text=text, hashtags=post_hashtags)
    return _text_contains_any_term(text=text, hashtags=hashtags, keywords=keywords)


def _build_post_filter_text(
    *,
    primary_text: str | None,
    hashtags: list[str] | None = None,
    mentions: list[str] | None = None,
    collaborators: list[str] | None = None,
    profile_tags: list[str] | None = None,
) -> str:
    parts: list[str] = []
    text = str(primary_text or "").strip()
    if text:
        parts.append(text)
    normalized_hashtags = _as_text_list(hashtags or [], strip_prefix="#")
    if normalized_hashtags:
        parts.append(" ".join(f"#{tag}" for tag in normalized_hashtags))
    normalized_mentions = _as_text_list(mentions or [], prefix="@", strip_prefix="@")
    if normalized_mentions:
        parts.append(" ".join(normalized_mentions))
    normalized_collaborators = _as_text_list(collaborators or [])
    if normalized_collaborators:
        parts.append(" ".join(normalized_collaborators))
    normalized_profile_tags = _as_text_list(profile_tags or [])
    if normalized_profile_tags:
        parts.append(" ".join(normalized_profile_tags))
    return "\n".join(parts)


