def _threads_should_enforce_rhoslc_relevance(*, context: SeasonContext | None) -> bool:
    return _show_is_rhoslc(context)


def _threads_normalize_match_term(value: str) -> str:
    normalized = re.sub(r"\s+", " ", str(value or "").strip().lstrip("#"))
    return normalized


def _threads_is_generic_season_term(value: str) -> bool:
    normalized = _threads_normalize_match_term(value).lower()
    return bool(normalized and THREADS_GENERIC_SEASON_TERM_RE.fullmatch(normalized))


def _threads_build_relevance_terms(
    season_id: str,
    *,
    source_scope: str,
    context: SeasonContext,
) -> tuple[list[str], list[str]]:
    # Product requirement: RHOSLC analytics should only count explicit RHOSLC mentions.
    if _threads_should_enforce_rhoslc_relevance(context=context):
        return ["RHOSLC"], ["RHOSLC"]

    fallback_hashtags, fallback_keywords = _derive_show_terms(context.show_name)
    slug_aliases: list[str] = []
    show_slug = str(context.show_slug or "").strip()
    if show_slug:
        slug_aliases.extend(
            [
                show_slug,
                show_slug.replace("-", ""),
                show_slug.replace("_", ""),
                show_slug.replace("-", " "),
                show_slug.replace("_", " "),
            ]
        )

    target_hashtags: list[str] = []
    target_keywords: list[str] = []
    try:
        targets_payload = get_targets(season_id, source_scope=source_scope)
    except Exception:  # noqa: BLE001
        logger.exception(
            "Failed to load Threads target terms for relevance filtering (season_id=%s source_scope=%s)",
            season_id,
            source_scope,
        )
        targets_payload = {"targets": []}

    for target in targets_payload.get("targets", []):
        if not target.get("is_active", True):
            continue
        if _normalize_platform_name(target.get("platform")) != "threads":
            continue
        target_hashtags.extend([str(item) for item in (target.get("hashtags") or []) if str(item).strip()])
        target_keywords.extend([str(item) for item in (target.get("keywords") or []) if str(item).strip()])

    hashtags: list[str] = []
    keywords: list[str] = []
    for term in [*target_hashtags, *fallback_hashtags, *slug_aliases]:
        normalized = _threads_normalize_match_term(term)
        if not normalized or _threads_is_generic_season_term(normalized):
            continue
        hashtags.append(normalized)
    for term in [*target_keywords, *fallback_keywords, *slug_aliases]:
        normalized = _threads_normalize_match_term(term)
        if not normalized or _threads_is_generic_season_term(normalized):
            continue
        keywords.append(normalized)
    return _normalize_unique_terms(hashtags), _normalize_unique_terms(keywords)


def _threads_normalize_raw_data(raw_data: Any) -> dict[str, Any]:
    if isinstance(raw_data, dict):
        return raw_data
    if isinstance(raw_data, str):
        raw_text = raw_data.strip()
        if not raw_text:
            return {}
        try:
            parsed = json.loads(raw_text)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _threads_coerce_topic_text(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        cleaned = re.sub(r"\s*>\s*", " > ", value)
        cleaned = re.sub(r"\s+", " ", cleaned).strip(" >")
        if not cleaned:
            return None
        if re.fullmatch(r"[0-9T:+\-.\sZ]+", cleaned):
            return None
        if " > " in cleaned:
            segments = [segment.strip() for segment in cleaned.split(">") if segment.strip()]
            deduped: list[str] = []
            seen_segments: set[str] = set()
            for segment in segments:
                normalized = re.sub(r"\s+", " ", segment).strip()
                if not normalized:
                    continue
                segment_key = normalized.lower()
                if segment_key in seen_segments:
                    continue
                seen_segments.add(segment_key)
                deduped.append(segment_key)
            if deduped:
                return " > ".join(deduped)
        return cleaned
    if isinstance(value, (list, tuple)):
        parts = []
        for item in value:
            part = _threads_coerce_topic_text(item)
            if part:
                parts.append(part)
        if not parts:
            return None
        return _threads_coerce_topic_text(" > ".join(_normalize_unique_terms(parts)))
    if isinstance(value, dict):
        collected: list[str] = []
        for key in THREADS_TOPIC_VALUE_KEYS:
            part = _threads_coerce_topic_text(value.get(key))
            if part:
                collected.append(part)
        if collected:
            return _threads_coerce_topic_text(" > ".join(_normalize_unique_terms(collected)))
    return None


def _threads_get_path_value(payload: Mapping[str, Any], path: tuple[str, ...]) -> Any:
    current: Any = payload
    for key in path:
        if not isinstance(current, Mapping):
            return None
        current = current.get(key)
    return current


def _threads_collect_topic_candidates_from_raw_data(raw_data: Any) -> list[str]:
    payload = _threads_normalize_raw_data(raw_data)
    if not payload:
        return []

    candidates: list[str] = []
    for path in THREADS_TOPIC_CANDIDATE_PATHS:
        candidate = _threads_coerce_topic_text(_threads_get_path_value(payload, path))
        if candidate:
            candidates.append(candidate)

    seen_objects: set[int] = set()
    stack: list[tuple[str, Any, int]] = [("", payload, 0)]
    while stack:
        key_hint, value, depth = stack.pop()
        if depth > 6:
            continue
        if isinstance(value, dict):
            value_id = id(value)
            if value_id in seen_objects:
                continue
            seen_objects.add(value_id)
            for child_key, child_value in value.items():
                child_key_text = str(child_key or "")
                if THREADS_TOPIC_KEY_HINT_RE.search(child_key_text):
                    candidate = _threads_coerce_topic_text(child_value)
                    if candidate:
                        candidates.append(candidate)
                stack.append((child_key_text, child_value, depth + 1))
        elif isinstance(value, list):
            value_id = id(value)
            if value_id in seen_objects:
                continue
            seen_objects.add(value_id)
            for item in value:
                if THREADS_TOPIC_KEY_HINT_RE.search(key_hint):
                    candidate = _threads_coerce_topic_text(item)
                    if candidate:
                        candidates.append(candidate)
                stack.append((key_hint, item, depth + 1))
        elif isinstance(value, str) and THREADS_TOPIC_KEY_HINT_RE.search(key_hint):
            candidate = _threads_coerce_topic_text(value)
            if candidate:
                candidates.append(candidate)

    return _normalize_unique_terms(candidates)


def _threads_extract_topic(raw_data: Any, *, text: str | None = None) -> str | None:
    candidates = _threads_collect_topic_candidates_from_raw_data(raw_data)
    if candidates:
        return candidates[0]

    # Fallback for legacy rows: infer a topic token from post text when activity metadata is absent.
    normalized_text = str(text or "")
    if not normalized_text:
        return None
    hashtag_matches = re.findall(r"#([A-Za-z0-9_]{2,40})", normalized_text)
    for tag in hashtag_matches:
        token = str(tag or "").strip()
        if not token:
            continue
        if token.lower() == "rhoslc":
            return "RHOSLC"
    if re.search(r"\brhoslc\b", normalized_text, re.IGNORECASE):
        return "RHOSLC"
    return None


def _threads_text_topic_match(
    *,
    text: str | None,
    raw_data: Any,
    hashtags: list[str],
    keywords: list[str],
) -> bool:
    if _text_contains_any_term(text=text, hashtags=hashtags, keywords=keywords):
        return True
    topic_blob = " ".join(_threads_collect_topic_candidates_from_raw_data(raw_data))
    return _text_contains_any_term(text=topic_blob, hashtags=hashtags, keywords=keywords)


def _threads_post_matches_show_terms(
    *,
    text: str | None,
    raw_data: Any,
    hashtags: list[str],
    keywords: list[str],
) -> bool:
    if not hashtags and not keywords:
        return True
    return _threads_text_topic_match(
        text=text,
        raw_data=raw_data,
        hashtags=hashtags,
        keywords=keywords,
    )


THREADS_POST_CODE_RE = re.compile(r"/post/([A-Za-z0-9_-]+)", re.IGNORECASE)


def _threads_extract_post_code(value: str | None) -> str | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    if raw.startswith("http"):
        match = THREADS_POST_CODE_RE.search(raw)
        if match:
            candidate = str(match.group(1) or "").strip()
            return candidate or None
        return None
    if raw.startswith("@") and "/post/" in raw:
        match = THREADS_POST_CODE_RE.search(raw)
        if match:
            candidate = str(match.group(1) or "").strip()
            return candidate or None
    if re.fullmatch(r"[A-Za-z0-9_-]{4,80}", raw):
        return raw
    return None


def _threads_build_post_fetch_targets(
    *,
    source_id: str | None,
    account: str | None = None,
    post_url: str | None = None,
    raw_data: Any = None,
) -> list[str]:
    candidates: list[str] = []
    seen: set[str] = set()

    def _add(value: Any) -> None:
        normalized = str(value or "").strip()
        if not normalized or normalized in seen:
            return
        seen.add(normalized)
        candidates.append(normalized)

    raw_payload = _threads_normalize_raw_data(raw_data)
    source = str(source_id or "").strip()
    handle = str(account or "").strip().lstrip("@")
    _add(post_url)
    _add(raw_payload.get("url"))
    _add(raw_payload.get("canonical_url"))
    nested_raw_payload = _threads_normalize_raw_data(raw_payload.get("raw_data"))
    _add(nested_raw_payload.get("url"))
    _add(nested_raw_payload.get("canonical_url"))
    code = _threads_extract_post_code(source) or _threads_extract_post_code(post_url)
    if code:
        if handle:
            _add(f"https://www.threads.com/@{handle}/post/{code}")
        _add(f"https://www.threads.com/post/{code}")
    elif source:
        _add(source)
    return candidates


def _threads_primary_post_fetch_target(
    *,
    source_id: str | None,
    account: str | None = None,
    post_url: str | None = None,
    raw_data: Any = None,
) -> str:
    candidates = _threads_build_post_fetch_targets(
        source_id=source_id,
        account=account,
        post_url=post_url,
        raw_data=raw_data,
    )
    return candidates[0] if candidates else str(source_id or "").strip()


def _threads_interaction_type(
    *,
    is_reply: Any = None,
    raw_data: Any = None,
) -> str:
    payload = _threads_normalize_raw_data(raw_data)
    for raw_value in (
        payload.get("interaction_type"),
        payload.get("_interaction_type"),
        payload.get("type"),
        payload.get("comment_type"),
    ):
        normalized = str(raw_value or "").strip().lower()
        if normalized in {"quote", "quoted", "quoted_post", "reshare_quote"}:
            return "quote"
        if normalized in {"reply", "comment"}:
            return "reply"

    quote_markers = [
        payload.get("is_quote"),
        payload.get("is_quote_post"),
        bool(payload.get("quote_post")),
        bool(payload.get("quoted_post")),
    ]
    if any(bool(marker) for marker in quote_markers):
        return "quote"
    if is_reply is not None:
        return "reply" if bool(is_reply) else "quote"
    return "reply"


def _threads_is_quote_interaction(*, is_reply: Any = None, raw_data: Any = None) -> bool:
    return _threads_interaction_type(is_reply=is_reply, raw_data=raw_data) == "quote"


def _youtube_title_is_cross_show_excluded(title: str | None) -> bool:
    text = str(title or "").lower()
    if not text:
        return False
    return "wife swap" in text and "real housewives edition" in text


def _youtube_video_matches_show_terms(
    *,
    title: str | None,
    description: str | None,
    tags: list[str] | None = None,
    hashtags: list[str],
    keywords: list[str],
) -> bool:
    """Apply strict show matching for YouTube ingestion.

    Rules:
    - Match if show terms appear in title or description.
    - Match if configured show hashtags appear in description with ``#`` prefix.
    - Exclude known cross-show promos by title pattern.
    """
    if _youtube_title_is_cross_show_excluded(title):
        return False

    show_hashtags = [
        str(tag).strip().lstrip("#").lower()
        for tag in hashtags
        if str(tag).strip() and not YOUTUBE_GENERIC_SEASON_TERM_RE.fullmatch(str(tag).strip().lstrip("#"))
    ]
    show_keywords = [
        str(keyword).strip()
        for keyword in keywords
        if str(keyword).strip() and not YOUTUBE_GENERIC_SEASON_TERM_RE.fullmatch(str(keyword).strip())
    ]

    if not show_hashtags and not show_keywords:
        return _text_contains_any_term(text=f"{title or ''} {description or ''}", hashtags=hashtags, keywords=keywords)

    title_match = _text_contains_any_term(text=title, hashtags=show_hashtags, keywords=show_keywords)
    if title_match:
        return True

    description_text = str(description or "")
    if description_text:
        description_lower = description_text.lower()
        if any(f"#{tag}" in description_lower for tag in show_hashtags):
            return True

        if _text_contains_any_term(text=description_text, hashtags=show_hashtags, keywords=show_keywords):
            return True

    normalized_terms: set[str] = set()
    for value in [*show_hashtags, *show_keywords]:
        token = re.sub(r"[^a-z0-9]+", "", str(value or "").lower())
        if token:
            normalized_terms.add(token)
    if not normalized_terms:
        return False

    for raw_tag in tags or []:
        tag_normalized = re.sub(r"[^a-z0-9]+", "", str(raw_tag or "").lower().lstrip("#"))
        if not tag_normalized:
            continue
        if any(term in tag_normalized for term in normalized_terms):
            return True

    return False


def _youtube_post_matches_show_terms(
    *,
    context: SeasonContext | None,
    title: str | None,
    description: str | None,
    post_hashtags: list[str] | None = None,
) -> bool:
    normalized_post_hashtags = _as_text_list(post_hashtags or [], strip_prefix="#")
    combined_text = "\n".join(
        part for part in [str(title or "").strip(), str(description or "").strip()] if part
    ).strip()
    fallback_hashtags, fallback_keywords = _derive_show_terms(context.show_name if context else None)
    slug_aliases: list[str] = []
    show_slug = str(getattr(context, "show_slug", "") or "").strip()
    if show_slug:
        slug_aliases.extend(
            [
                show_slug,
                show_slug.replace("-", ""),
                show_slug.replace("_", ""),
                show_slug.replace("-", " "),
                show_slug.replace("_", " "),
            ]
        )
    if _show_is_rhoslc(context) and _has_required_rhoslc_hashtag(text=combined_text, hashtags=normalized_post_hashtags):
        return True

    return _youtube_video_matches_show_terms(
        title=title,
        description=description,
        tags=normalized_post_hashtags,
        hashtags=[*fallback_hashtags, *slug_aliases],
        keywords=[*fallback_keywords, *slug_aliases],
    )


def _youtube_filter_sample(
    *,
    reason: str,
    title: str | None,
    video_id: str | None,
) -> dict[str, str]:
    payload: dict[str, str] = {"reason": reason}
    cleaned_title = str(title or "").strip()
    cleaned_video_id = str(video_id or "").strip()
    if cleaned_title:
        payload["title"] = cleaned_title
    if cleaned_video_id:
        payload["video_id"] = cleaned_video_id
    return payload


def _build_twitter_or_query(*, hashtags: list[str], keywords: list[str]) -> str:
    terms: list[str] = []
    for keyword in keywords:
        value = str(keyword or "").strip()
        if not value:
            continue
        if " " in value:
            terms.append(f'"{value}"')
        else:
            terms.append(value)
    for hashtag in hashtags:
        value = str(hashtag or "").strip().lstrip("#")
        if not value:
            continue
        terms.append(f"#{value}")

    unique_terms = _normalize_unique_terms(terms)
    if not unique_terms:
        return ""
    if len(unique_terms) == 1:
        return unique_terms[0]
    return f"({' OR '.join(unique_terms)})"


def _default_instagram_cookie_file_path() -> Path:
    return Path(__file__).resolve().parents[2] / "scripts" / "socials" / "instagram" / "instagram_cookies.json"


def _instagram_cookie_file_candidates() -> list[Path]:
    raw_candidates = [
        (os.getenv("SOCIAL_INSTAGRAM_COOKIES_FILE") or "").strip(),
        (os.getenv("INSTAGRAM_COOKIES_FILE") or "").strip(),
        str(_default_instagram_cookie_file_path()),
    ]
    return [Path(raw_path).expanduser() for raw_path in raw_candidates if str(raw_path or "").strip()]


def _instagram_cookie_refresh_target_path() -> Path:
    candidates = _instagram_cookie_file_candidates()
    return candidates[0] if candidates else _default_instagram_cookie_file_path()


def _instagram_auth_credentials() -> tuple[str | None, str | None]:
    username = (os.getenv("SOCIAL_AUTH_INSTAGRAM_USERNAME") or "").strip() or None
    password = (os.getenv("SOCIAL_AUTH_INSTAGRAM_PASSWORD") or "").strip() or None
    return username, password


def _instagram_cookie_auto_refresh_enabled() -> bool:
    raw = (os.getenv("SOCIAL_INSTAGRAM_COOKIE_AUTO_REFRESH") or "").strip().lower()
    if raw:
        return raw not in {"0", "false", "off", "no"}
    username, password = _instagram_auth_credentials()
    return bool(username and password)


def _instagram_cookie_validation_username() -> str:
    return (os.getenv("SOCIAL_INSTAGRAM_COOKIE_VALIDATION_USERNAME") or "").strip() or "bravotv"


def _load_instagram_cookies_from_sources() -> dict[str, str]:
    """
    Resolve Instagram auth cookies for season ingest.

    Resolution order:
    1) SOCIAL_INSTAGRAM_COOKIES_JSON / INSTAGRAM_COOKIES_JSON (inline JSON object)
    2) SOCIAL_INSTAGRAM_COOKIES_FILE / INSTAGRAM_COOKIES_FILE (path to JSON file)
    3) scripts/socials/instagram/instagram_cookies.json (repo-local default)
    """
    from trr_backend.socials.instagram import load_cookies_from_file

    candidates: list[dict[str, str]] = []

    raw_json = (os.getenv("SOCIAL_INSTAGRAM_COOKIES_JSON") or "").strip() or (
        os.getenv("INSTAGRAM_COOKIES_JSON") or ""
    ).strip()
    if raw_json:
        try:
            parsed = json.loads(raw_json)
        except json.JSONDecodeError:
            logger.warning("Invalid Instagram cookies JSON from env; falling back to file-based cookies")
        else:
            if isinstance(parsed, dict):
                cookies = {str(k): str(v) for k, v in parsed.items() if v is not None and not str(k).startswith("_")}
                if cookies:
                    candidates.append(cookies)
            elif parsed is not None:
                logger.warning("Instagram cookies JSON env value is not an object; falling back to file-based cookies")

    for path in _instagram_cookie_file_candidates():
        if not path.is_file():
            continue
        try:
            cookies = load_cookies_from_file(str(path))
        except Exception as exc:
            logger.warning("Failed to load Instagram cookies from %s: %s", path, exc)
            continue
        if cookies:
            candidates.append(cookies)

    return _select_preferred_cookie_candidate(
        candidates,
        required_cookie_names_any=("sessionid",),
        required_cookie_names_all=("csrftoken",),
    )


def _instagram_cookie_fingerprint(cookies: Mapping[str, Any]) -> str:
    payload = json.dumps(sorted((str(key), str(value)) for key, value in cookies.items()), separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _validate_instagram_cookie_health(cookies: dict[str, str]) -> tuple[bool, str | None]:
    global _instagram_cookie_validation_cache

    if not cookies.get("sessionid"):
        return False, "sessionid_missing"

    fingerprint = _instagram_cookie_fingerprint(cookies)
    ttl_seconds = _resolve_positive_int_env(
        "SOCIAL_INSTAGRAM_COOKIE_VALIDATION_TTL_SECONDS",
        SOCIAL_INSTAGRAM_COOKIE_VALIDATION_TTL_SECONDS_DEFAULT,
        minimum=30,
    )
    now = time_module.monotonic()
    cached = _instagram_cookie_validation_cache
    if cached and cached[1] == fingerprint and (now - cached[0]) < ttl_seconds:
        return cached[2], cached[3]

    from trr_backend.socials.instagram import InstagramScraper

    validation_reason: str | None = None
    is_valid = False
    try:
        scraper = InstagramScraper(cookies=cookies)
        payload = scraper.fetch_posts_graphql(
            _instagram_cookie_validation_username(),
            delay=0.0,
            request_timeout=(10, 20),
        )
        connection = (payload or {}).get("data", {}).get("xdt_api__v1__feed__user_timeline_graphql_connection", {})
        is_valid = bool(connection.get("edges"))
        if not is_valid:
            validation_reason = "graphql_validation_failed"
    except Exception as exc:  # noqa: BLE001
        validation_reason = f"validation_exception:{type(exc).__name__}"
        logger.debug("Instagram cookie validation raised %s", validation_reason, exc_info=True)

    _instagram_cookie_validation_cache = (now, fingerprint, is_valid, validation_reason)
    return is_valid, validation_reason


def _refresh_instagram_cookies(stale_reason: str | None = None) -> dict[str, str]:
    global _instagram_cookie_validation_cache, _instagram_cookie_runtime_override

    username, password = _instagram_auth_credentials()
    if not username or not password:
        return {}

    from trr_backend.socials.instagram.cookie_refresh import refresh_instagram_cookies

    try:
        refreshed = refresh_instagram_cookies(
            username=username,
            password=password,
            cookie_file=_instagram_cookie_refresh_target_path(),
            headless=(os.getenv("SOCIAL_INSTAGRAM_COOKIE_REFRESH_HEADLESS") or "true").strip().lower()
            not in {"0", "false", "off", "no"},
            timeout_seconds=_resolve_positive_int_env(
                "SOCIAL_INSTAGRAM_COOKIE_REFRESH_TIMEOUT_SECONDS",
                SOCIAL_INSTAGRAM_COOKIE_REFRESH_TIMEOUT_SECONDS_DEFAULT,
                minimum=30,
            ),
            validation_username=_instagram_cookie_validation_username(),
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Instagram cookie refresh failed%s: %s",
            f" ({stale_reason})" if stale_reason else "",
            exc,
        )
        return {}

    if refreshed:
        _instagram_cookie_runtime_override = dict(refreshed)
        _instagram_cookie_validation_cache = None
    return refreshed


def _ensure_instagram_cookies_fresh(cookies: dict[str, str]) -> dict[str, str]:
    global _instagram_cookie_runtime_override

    if _instagram_cookie_runtime_override:
        return dict(_instagram_cookie_runtime_override)
    if not _instagram_cookie_auto_refresh_enabled():
        return cookies

    is_valid, validation_reason = _validate_instagram_cookie_health(cookies)
    if is_valid:
        return cookies

    with _instagram_cookie_refresh_lock:
        latest = _instagram_cookie_runtime_override or _load_instagram_cookies_from_sources()
        latest_valid, _ = _validate_instagram_cookie_health(dict(latest))
        if latest_valid:
            _instagram_cookie_runtime_override = dict(latest)
            return dict(latest)

        refreshed = _refresh_instagram_cookies(validation_reason)
        if refreshed:
            refreshed_valid, refreshed_reason = _validate_instagram_cookie_health(refreshed)
            if refreshed_valid:
                return refreshed
            logger.warning(
                "Instagram cookies refreshed but validation still failed (%s)",
                refreshed_reason or "unknown_reason",
            )
        return cookies


def _load_instagram_cookies() -> dict[str, str]:
    cookies = _load_instagram_cookies_from_sources()
    return _ensure_instagram_cookies_fresh(cookies)


def _default_platform_cookie_file_path(platform: str) -> Path:
    return Path(__file__).resolve().parents[2] / "scripts" / "socials" / platform / f"{platform}_cookies.json"


def _platform_cookie_file_candidates(default_path: Path, *env_keys: str) -> list[Path]:
    raw_candidates = [str(os.getenv(key) or "").strip() for key in env_keys]
    raw_candidates.append(str(default_path))
    return [Path(raw_path).expanduser() for raw_path in raw_candidates if raw_path]


def _platform_cookie_refresh_target_path(default_path: Path, *env_keys: str) -> Path:
    candidates = _platform_cookie_file_candidates(default_path, *env_keys)
    return candidates[0] if candidates else default_path


def _platform_auth_credentials(username_env: str, password_env: str) -> tuple[str | None, str | None]:
    username = (os.getenv(username_env) or "").strip() or None
    password = (os.getenv(password_env) or "").strip() or None
    return username, password


def _platform_cookie_auto_refresh_enabled(toggle_env: str, username_env: str, password_env: str) -> bool:
    raw = (os.getenv(toggle_env) or "").strip().lower()
    if raw:
        return raw not in {"0", "false", "off", "no"}
    username, password = _platform_auth_credentials(username_env, password_env)
    return bool(username and password)


def _select_preferred_cookie_candidate(
    candidates: list[dict[str, str]],
    *,
    required_cookie_names_any: tuple[str, ...] = (),
    required_cookie_names_all: tuple[str, ...] = (),
) -> dict[str, str]:
    if not candidates:
        return {}
    if not required_cookie_names_any and not required_cookie_names_all:
        return dict(candidates[0])

    def _score(candidate: dict[str, str]) -> tuple[int, int]:
        has_all = int(
            all(str(candidate.get(name) or "").strip() for name in required_cookie_names_all)
            if required_cookie_names_all
            else True
        )
        has_any = int(
            any(str(candidate.get(name) or "").strip() for name in required_cookie_names_any)
            if required_cookie_names_any
            else True
        )
        return (has_all, has_any)

    best_score: tuple[int, int] | None = None
    best_candidate: dict[str, str] | None = None
    for candidate in candidates:
        score = _score(candidate)
        if best_score is None or score > best_score:
            best_score = score
            best_candidate = candidate
    return dict(best_candidate or {})


def _load_cookie_map_from_json_or_file(
    *,
    label: str,
    raw_json_env_keys: tuple[str, ...],
    file_env_keys: tuple[str, ...],
    default_path: Path,
    required_cookie_names_any: tuple[str, ...] = (),
    required_cookie_names_all: tuple[str, ...] = (),
) -> dict[str, str]:
    candidates: list[dict[str, str]] = []
    raw_json = ""
    for key in raw_json_env_keys:
        raw_json = str(os.getenv(key) or "").strip()
        if raw_json:
            break
    if raw_json:
        try:
            parsed = json.loads(raw_json)
            cookies = _coerce_cookie_map(parsed)
            if cookies:
                candidates.append(cookies)
        except json.JSONDecodeError:
            cookies = _parse_cookie_header(raw_json)
            if cookies:
                candidates.append(cookies)
            else:
                logger.warning("Invalid %s cookies JSON from env", label)

    for path in _platform_cookie_file_candidates(default_path, *file_env_keys):
        if not path.is_file():
            continue
        try:
            with open(path) as f:
                parsed = json.load(f)
        except Exception as exc:
            logger.warning("Failed to load %s cookies from %s: %s", label, path, exc)
            continue
        cookies = _coerce_cookie_map(parsed)
        if cookies:
            candidates.append(cookies)
    return _select_preferred_cookie_candidate(
        candidates,
        required_cookie_names_any=required_cookie_names_any,
        required_cookie_names_all=required_cookie_names_all,
    )


def _validate_browser_cookie_health_cached(
    *,
    platform_label: str,
    cookies: dict[str, str],
    cache_entry: tuple[float, str, bool, str | None] | None,
    validation_url: str,
    cookie_domains: tuple[str, ...],
    required_cookie_names_any: tuple[str, ...] = (),
    required_cookie_names_all: tuple[str, ...] = (),
    invalid_url_markers: tuple[str, ...] = (),
    invalid_body_patterns: tuple[str, ...] = (),
) -> tuple[tuple[float, str, bool, str | None], bool, str | None]:
    fingerprint = _instagram_cookie_fingerprint(cookies)
    ttl_seconds = _resolve_positive_int_env(
        f"SOCIAL_{platform_label.upper()}_COOKIE_VALIDATION_TTL_SECONDS",
        SOCIAL_INSTAGRAM_COOKIE_VALIDATION_TTL_SECONDS_DEFAULT,
        minimum=30,
    )
    now = time_module.monotonic()
    if cache_entry and cache_entry[1] == fingerprint and (now - cache_entry[0]) < ttl_seconds:
        return cache_entry, cache_entry[2], cache_entry[3]

    from trr_backend.socials.browser_cookie_refresh import validate_browser_cookie_session

    is_valid, reason = validate_browser_cookie_session(
        cookies=cookies,
        validation_url=validation_url,
        cookie_domains=cookie_domains,
        required_cookie_names_any=required_cookie_names_any,
        required_cookie_names_all=required_cookie_names_all,
        invalid_url_markers=invalid_url_markers,
        invalid_body_patterns=invalid_body_patterns,
        timeout_seconds=45,
    )
    new_cache = (now, fingerprint, is_valid, reason)
    return new_cache, is_valid, reason


def _load_twitter_auth_from_sources() -> tuple[dict[str, str], str | None]:
    """
    Resolve Twitter auth for season ingest.

    Returns (cookies_dict, bearer_token | None).
    Resolution:
    1) SOCIAL_TWITTER_COOKIES_JSON / TWITTER_COOKIES_JSON (inline JSON)
    2) SOCIAL_TWITTER_COOKIES_FILE / TWITTER_COOKIES_FILE (path to JSON file)
    3) SOCIAL_TWITTER_BEARER_TOKEN / TWITTER_BEARER_TOKEN (bearer token)
    """

    cookie_candidates: list[dict[str, str]] = []
    raw_cookie_header = (os.getenv("SOCIAL_TWITTER_COOKIES_HEADER") or "").strip() or (
        os.getenv("TWITTER_COOKIES_HEADER") or ""
    ).strip()
    if raw_cookie_header:
        parsed_header = _parse_cookie_header(raw_cookie_header)
        if parsed_header:
            cookie_candidates.append(parsed_header)

    raw_json = (os.getenv("SOCIAL_TWITTER_COOKIES_JSON") or "").strip() or (
        os.getenv("TWITTER_COOKIES_JSON") or ""
    ).strip()
    if raw_json:
        try:
            parsed = json.loads(raw_json)
            cookies = _coerce_cookie_map(parsed)
            if cookies:
                cookie_candidates.append(cookies)
        except json.JSONDecodeError:
            # Allow passing a raw "Cookie:" header string in *_COOKIES_JSON vars.
            parsed_header = _parse_cookie_header(raw_json)
            if parsed_header:
                cookie_candidates.append(parsed_header)
            else:
                logger.warning("Invalid Twitter cookies JSON from env")

    for p in _platform_cookie_file_candidates(
        _default_twitter_cookie_file_path(),
        "SOCIAL_TWITTER_COOKIES_FILE",
        "TWITTER_COOKIES_FILE",
    ):
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                cookies = _coerce_cookie_map(parsed)
                if cookies:
                    cookie_candidates.append(cookies)
            except Exception as exc:
                logger.warning("Failed to load Twitter cookies from %s: %s", p, exc)

    browser_cookies = _load_twitter_browser_cookies()
    if browser_cookies:
        cookie_candidates.append(browser_cookies)

    def _is_complete_cookie_candidate(candidate: dict[str, str]) -> bool:
        return bool(str(candidate.get("auth_token") or "").strip() and str(candidate.get("ct0") or "").strip())

    cookies: dict[str, str] = {}
    for candidate in cookie_candidates:
        if _is_complete_cookie_candidate(candidate):
            cookies = dict(candidate)
            break
    if not cookies:
        cookies = _select_preferred_cookie_candidate(
            cookie_candidates,
            required_cookie_names_any=("auth_token",),
            required_cookie_names_all=("ct0",),
        )

    bearer_token = (
        (os.getenv("SOCIAL_TWITTER_BEARER_TOKEN") or "").strip()
        or (os.getenv("TWITTER_BEARER_TOKEN") or "").strip()
        or None
    )

    return cookies, bearer_token


def _coerce_cookie_map(payload: Any) -> dict[str, str]:
    out: dict[str, str] = {}
    if isinstance(payload, dict):
        # Playwright/Chrome export shape: {"cookies": [{name, value, ...}, ...]}
        nested = payload.get("cookies")
        if isinstance(nested, list):
            return _coerce_cookie_map(nested)
        # Single cookie object shape.
        name = payload.get("name")
        value = payload.get("value")
        if name is not None and value is not None:
            out[str(name)] = str(value)
            return out
        # Flat cookie map shape.
        for key, value in payload.items():
            if value is None:
                continue
            key_str = str(key)
            if key_str.startswith("_"):
                continue
            if isinstance(value, (str, int, float, bool)):
                out[key_str] = str(value)
        return out
    if isinstance(payload, list):
        for item in payload:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            value = item.get("value")
            if name is None or value is None:
                continue
            out[str(name)] = str(value)
    return out


def _parse_cookie_header(raw: str) -> dict[str, str]:
    cookies: dict[str, str] = {}
    value = str(raw or "").strip()
    if not value:
        return cookies
    if value.lower().startswith("cookie:"):
        value = value.split(":", 1)[1].strip()
    for token in value.split(";"):
        pair = token.strip()
        if not pair or "=" not in pair:
            continue
        key, val = pair.split("=", 1)
        key = key.strip()
        if not key or key.startswith("_"):
            continue
        cookies[key] = val.strip()
    return cookies


def _load_twitter_browser_cookies() -> dict[str, str]:
    """
    Best-effort local browser cookie fallback for X/Twitter auth.

    Disabled unless SOCIAL_TWITTER_BROWSER_COOKIE_FALLBACK is truthy.
    """
    if not _env_truthy("SOCIAL_TWITTER_BROWSER_COOKIE_FALLBACK", default=False):
        return {}
    try:
        import browser_cookie3  # type: ignore[import-not-found]
    except Exception:
        return {}

    browser = (os.getenv("SOCIAL_TWITTER_BROWSER") or "auto").strip().lower()
    domains = [
        token.strip().lower()
        for token in (os.getenv("SOCIAL_TWITTER_COOKIE_DOMAINS") or "x.com,twitter.com").split(",")
        if token.strip()
    ]
    preferred_names = {
        token.strip()
        for token in (os.getenv("SOCIAL_TWITTER_COOKIE_NAMES") or "auth_token,ct0,twid").split(",")
        if token.strip()
    }

    browser_loader_candidates: list[Any] = []
    browser_order = ["chrome", "chromium", "brave", "edge", "opera", "vivaldi", "firefox", "safari"]
    if browser != "auto":
        browser_order = [browser]
    for browser_name in browser_order:
        browser_loader_candidates.append(getattr(browser_cookie3, browser_name, None))
    loaders = [loader for loader in browser_loader_candidates if callable(loader)]

    cookies: dict[str, str] = {}
    for loader in loaders:
        for domain in domains:
            try:
                jar = loader(domain_name=domain)
            except TypeError:
                try:
                    jar = loader()
                except Exception:
                    continue
            except Exception:
                continue
            for cookie in jar:
                name = str(getattr(cookie, "name", "") or "")
                value = str(getattr(cookie, "value", "") or "")
                cookie_domain = str(getattr(cookie, "domain", "") or "").lower()
                if not name or not value:
                    continue
                if preferred_names and name not in preferred_names:
                    continue
                if domain and not cookie_domain.endswith(domain):
                    continue
                cookies[name] = value
            if cookies.get("auth_token") and cookies.get("ct0"):
                return cookies
    return cookies


def _load_twikit_credentials(twitter_cookies: Mapping[str, Any] | None = None) -> dict[str, str] | None:
    """
    Load twikit auth from env vars, cookie file, or Twitter cookie sources.

    Resolution order (first match wins):
    1) TWIKIT_COOKIES_JSON – inline JSON cookie payload
    2) TWIKIT_COOKIES_FILE – JSON file with auth_token + ct0 keys
    3) TWIKIT_AUTH_TOKEN + TWIKIT_CT0 – inline cookie values
    4) TWIKIT_USERNAME + TWIKIT_PASSWORD (+ TWIKIT_EMAIL) – login creds
    5) Twitter cookie sources (preloaded cookies/header/JSON/file)
    6) Browser cookie fallback
    """

    def _extract_auth_ct0(payload: Any) -> tuple[str | None, str | None]:
        auth_token: str | None = None
        ct0: str | None = None
        if isinstance(payload, dict):
            if payload.get("auth_token") and payload.get("ct0"):
                return str(payload.get("auth_token")), str(payload.get("ct0"))
            nested = payload.get("cookies")
            if isinstance(nested, list):
                return _extract_auth_ct0(nested)
            name = payload.get("name")
            value = payload.get("value")
            if name == "auth_token" and value is not None:
                auth_token = str(value)
            if name == "ct0" and value is not None:
                ct0 = str(value)
            return auth_token, ct0
        if isinstance(payload, list):
            for item in payload:
                if not isinstance(item, dict):
                    continue
                name = item.get("name")
                value = item.get("value")
                if name == "auth_token" and value is not None:
                    auth_token = str(value)
                elif name == "ct0" and value is not None:
                    ct0 = str(value)
            return auth_token, ct0
        return None, None

    def _from_cookie_map(cookies: Mapping[str, Any] | None) -> dict[str, str] | None:
        if not cookies:
            return None
        auth_token = str(cookies.get("auth_token") or "").strip()
        ct0 = str(cookies.get("ct0") or "").strip()
        if auth_token and ct0:
            return {"auth_token": auth_token, "ct0": ct0}
        return None

    # 1) TWIKIT_COOKIES_JSON
    raw_cookie_json = (os.getenv("TWIKIT_COOKIES_JSON") or "").strip()
    if raw_cookie_json:
        try:
            parsed = json.loads(raw_cookie_json)
            auth_token, ct0 = _extract_auth_ct0(parsed)
            if auth_token and ct0:
                return {"auth_token": auth_token, "ct0": ct0}
        except Exception:
            logger.warning("Invalid TWIKIT_COOKIES_JSON payload; expected JSON cookie object/list")

    # 2) TWIKIT_COOKIES_FILE
    cookie_file = (os.getenv("TWIKIT_COOKIES_FILE") or "").strip()
    if cookie_file:
        p = Path(cookie_file).expanduser()
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                auth_token, ct0 = _extract_auth_ct0(parsed)
                if auth_token and ct0:
                    return {"auth_token": auth_token, "ct0": ct0}
            except Exception as exc:
                logger.warning("Failed to load twikit cookies from %s: %s", p, exc)
        else:
            logger.debug("TWIKIT_COOKIES_FILE does not exist: %s", p)

    # 3) Inline TWIKIT cookie env vars
    auth_token = (os.getenv("TWIKIT_AUTH_TOKEN") or "").strip()
    ct0 = (os.getenv("TWIKIT_CT0") or "").strip()
    if auth_token and ct0:
        return {"auth_token": auth_token, "ct0": ct0}

    # 4) TWIKIT login credentials
    username = (os.getenv("TWIKIT_USERNAME") or "").strip()
    password = (os.getenv("TWIKIT_PASSWORD") or "").strip()
    email = (os.getenv("TWIKIT_EMAIL") or "").strip()
    if username and password:
        return {"username": username, "email": email or username, "password": password}

    # 5a) Preloaded Twitter cookies from caller.
    from_preloaded = _from_cookie_map(twitter_cookies)
    if from_preloaded:
        return from_preloaded

    # 5b) Twitter cookie header env vars.
    raw_cookie_header = (os.getenv("SOCIAL_TWITTER_COOKIES_HEADER") or "").strip() or (
        os.getenv("TWITTER_COOKIES_HEADER") or ""
    ).strip()
    if raw_cookie_header:
        parsed = _parse_cookie_header(raw_cookie_header)
        from_header = _from_cookie_map(parsed)
        if from_header:
            return from_header

    # 5c) Twitter JSON cookie env vars.
    raw_twitter_cookie_json = (os.getenv("SOCIAL_TWITTER_COOKIES_JSON") or "").strip() or (
        os.getenv("TWITTER_COOKIES_JSON") or ""
    ).strip()
    if raw_twitter_cookie_json:
        try:
            parsed = json.loads(raw_twitter_cookie_json)
            from_twitter_json = _from_cookie_map(_coerce_cookie_map(parsed))
            if from_twitter_json:
                return from_twitter_json
        except json.JSONDecodeError:
            parsed_header = _parse_cookie_header(raw_twitter_cookie_json)
            from_twitter_header = _from_cookie_map(parsed_header)
            if from_twitter_header:
                return from_twitter_header

    # 5d) Twitter cookie file env vars.
    twitter_cookie_file = (os.getenv("SOCIAL_TWITTER_COOKIES_FILE") or "").strip() or (
        os.getenv("TWITTER_COOKIES_FILE") or ""
    ).strip()
    if twitter_cookie_file:
        p = Path(twitter_cookie_file).expanduser()
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                from_twitter_file = _from_cookie_map(_coerce_cookie_map(parsed))
                if from_twitter_file:
                    return from_twitter_file
            except Exception as exc:
                logger.debug("Failed to derive twikit credentials from Twitter cookie file %s: %s", p, exc)

    # 6) Browser cookie fallback.
    browser_cookies = _load_twitter_browser_cookies()
    from_browser = _from_cookie_map(browser_cookies)
    if from_browser:
        return from_browser

    return None


def _default_twitter_cookie_file_path() -> Path:
    return _default_platform_cookie_file_path("twitter")


def _validate_twitter_cookie_health(cookies: dict[str, str]) -> tuple[bool, str | None]:
    global _twitter_cookie_validation_cache
    _twitter_cookie_validation_cache, is_valid, reason = _validate_browser_cookie_health_cached(
        platform_label="twitter",
        cookies=cookies,
        cache_entry=_twitter_cookie_validation_cache,
        validation_url="https://x.com/home",
        cookie_domains=(".x.com", "x.com", ".twitter.com", "twitter.com"),
        required_cookie_names_any=("auth_token",),
        required_cookie_names_all=("ct0",),
        invalid_url_markers=("/i/flow/login", "/login"),
        invalid_body_patterns=(r"Something went wrong", r"Log in to X"),
    )
    return is_valid, reason


def _refresh_twitter_cookies(stale_reason: str | None = None) -> dict[str, str]:
    global _twitter_cookie_validation_cache, _twitter_cookie_runtime_override
    username, password = _platform_auth_credentials("SOCIAL_AUTH_X_USERNAME", "SOCIAL_AUTH_X_PASSWORD")
    if not username or not password:
        return {}
    from trr_backend.socials.twitter.cookie_refresh import refresh_twitter_cookies

    try:
        refreshed = refresh_twitter_cookies(
            username=username,
            password=password,
            cookie_file=_platform_cookie_refresh_target_path(
                _default_twitter_cookie_file_path(),
                "SOCIAL_TWITTER_COOKIES_FILE",
                "TWITTER_COOKIES_FILE",
            ),
            headless=(os.getenv("SOCIAL_TWITTER_COOKIE_REFRESH_HEADLESS") or "true").strip().lower()
            not in {"0", "false", "off", "no"},
            timeout_seconds=_resolve_positive_int_env(
                "SOCIAL_TWITTER_COOKIE_REFRESH_TIMEOUT_SECONDS",
                SOCIAL_INSTAGRAM_COOKIE_REFRESH_TIMEOUT_SECONDS_DEFAULT,
                minimum=30,
            ),
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Twitter cookie refresh failed%s: %s", f" ({stale_reason})" if stale_reason else "", exc)
        return {}
    if refreshed:
        _twitter_cookie_runtime_override = dict(refreshed)
        _twitter_cookie_validation_cache = None
    return refreshed


def _ensure_twitter_cookies_fresh(cookies: dict[str, str]) -> dict[str, str]:
    global _twitter_cookie_runtime_override
    if _twitter_cookie_runtime_override:
        return dict(_twitter_cookie_runtime_override)
    if not _platform_cookie_auto_refresh_enabled(
        "SOCIAL_TWITTER_COOKIE_AUTO_REFRESH",
        "SOCIAL_AUTH_X_USERNAME",
        "SOCIAL_AUTH_X_PASSWORD",
    ):
        return cookies
    is_valid, reason = _validate_twitter_cookie_health(cookies)
    if is_valid:
        return cookies
    with _twitter_cookie_refresh_lock:
        latest, _ = _load_twitter_auth_from_sources()
        latest = _twitter_cookie_runtime_override or latest
        latest_valid, _ = _validate_twitter_cookie_health(dict(latest))
        if latest_valid:
            _twitter_cookie_runtime_override = dict(latest)
            return dict(latest)
        refreshed = _refresh_twitter_cookies(reason)
        if refreshed:
            refreshed_valid, refreshed_reason = _validate_twitter_cookie_health(refreshed)
            if refreshed_valid:
                return refreshed
            logger.warning("Twitter cookies refreshed but validation still failed (%s)", refreshed_reason or "unknown")
        return cookies


def _load_twitter_auth() -> tuple[dict[str, str], str | None]:
    cookies, bearer_token = _load_twitter_auth_from_sources()
    return _ensure_twitter_cookies_fresh(cookies), bearer_token


