def _run_shared_account_posts_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    rows, retrieval_meta = _scrape_shared_posts_for_account(
        platform=platform,
        account_handle=account_handle,
        config=config,
        job_id=job_id,
    )
    source_ids = sorted(
        {
            _platform_source_id(platform, row)
            for row in rows
            if isinstance(row, dict) and _platform_source_id(platform, row)
        }
    )
    _touch_shared_account_source(
        source_scope=source_scope,
        platform=platform,
        account_handle=account_handle,
        run_id=run_id or None,
        job_id=job_id,
        last_scrape_status="completed",
    )
    if source_ids:
        _enqueue_shared_classify_job(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            source_ids=source_ids,
            worker_id=worker_id,
        )
    metadata = {
        "stage": SHARED_ACCOUNT_POSTS_STAGE,
        "platform": platform,
        "account": account_handle,
        "source_ids": source_ids,
        "persist_counters": {"posts_upserted": len(rows), "comments_upserted": 0},
        "activity": {"phase": "shared_account_posts_end", "last_progress_at": _iso(_now_utc())},
        "retrieval_meta": retrieval_meta,
        "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
    }
    return len(rows), 0, metadata


def _run_shared_post_classify_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    source_ids = [str(item or "").strip() for item in (config.get("source_ids") or []) if str(item or "").strip()]
    rows = _shared_post_rows_for_account(
        platform=platform,
        account_handle=account_handle,
        source_scope=source_scope,
        source_ids=source_ids or None,
        unassigned_only=False,
    )
    targets = _list_matchable_seasons(source_scope=source_scope, platform=platform)
    matched_source_ids: list[str] = []
    matched_season_ids: set[str] = set()
    ambiguous_count = 0
    unmatched_count = 0
    for row in rows:
        source_id = str(row.get("source_id") or "").strip()
        post_row_id = str(row.get("id") or "").strip()
        source_account = (
            _normalize_account_handle(row.get("source_account")) or str(row.get("source_account") or "").strip()
        )
        matches: list[dict[str, Any]] = []
        for target in targets:
            is_match, score, reason = _shared_row_matches_target(platform=platform, row=row, target=target)
            if not is_match:
                continue
            context = target["context"]
            matches.append(
                {
                    "season_id": context.season_id,
                    "show_id": context.show_id,
                    "show_name": context.show_name,
                    "season_number": context.season_number,
                    "score": score,
                    "reason": reason,
                }
            )
        matches.sort(key=lambda item: (-int(item.get("score") or 0), int(item.get("season_number") or 0)))
        if len(matches) == 1 or (
            len(matches) > 1 and int(matches[0].get("score") or 0) > int(matches[1].get("score") or 0)
        ):
            winner = matches[0]
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                matched_show_id=str(winner.get("show_id") or "") or None,
                matched_season_id=str(winner.get("season_id") or "") or None,
                status="matched",
                score=int(winner.get("score") or 0),
                reason=str(winner.get("reason") or "auto_matched"),
                candidate_matches=matches,
                metadata={"account_handle": account_handle},
                run_id=run_id,
            )
            _resolve_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                source_id=source_id,
                resolution_action="auto_matched",
                resolved_show_id=str(winner.get("show_id") or "") or None,
                resolved_season_id=str(winner.get("season_id") or "") or None,
            )
            matched_source_ids.append(source_id)
            matched_season_ids.add(str(winner.get("season_id") or ""))
        elif matches:
            ambiguous_count += 1
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                status="ambiguous",
                score=int(matches[0].get("score") or 0),
                reason="ambiguous_match",
                candidate_matches=matches,
                metadata={"account_handle": account_handle},
                run_id=run_id,
            )
            _upsert_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                review_reason="ambiguous_match",
                run_id=run_id,
                payload={"account_handle": account_handle, "candidate_matches": matches},
            )
        else:
            unmatched_count += 1
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                status="unmatched",
                score=0,
                reason="no_season_match",
                candidate_matches=[],
                metadata={"account_handle": account_handle, "retained_unassigned": True},
                run_id=run_id,
            )
            _upsert_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                review_reason="unmatched",
                run_id=run_id,
                payload={"account_handle": account_handle, "candidate_matches": []},
            )
    _touch_shared_account_source(
        source_scope=source_scope,
        platform=platform,
        account_handle=account_handle,
        last_classified_at=_now_utc(),
    )
    if matched_source_ids:
        _enqueue_shared_materialize_job(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            matched_source_ids=matched_source_ids,
            season_ids=sorted(season_id for season_id in matched_season_ids if season_id),
            worker_id=worker_id,
        )
    metadata = {
        "stage": POST_CLASSIFY_STAGE,
        "platform": platform,
        "account": account_handle,
        "matched_source_ids": matched_source_ids,
        "matched_count": len(matched_source_ids),
        "ambiguous_count": ambiguous_count,
        "unmatched_count": unmatched_count,
        "activity": {"phase": "post_classify_end", "last_progress_at": _iso(_now_utc())},
        "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
    }
    return len(rows), 0, metadata


def _run_shared_season_materialize_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    source_ids = [str(item or "").strip() for item in (config.get("source_ids") or []) if str(item or "").strip()]
    rows = pg.fetch_all(
        """
        select
          id::text as id,
          source_id,
          matched_show_id::text as matched_show_id,
          matched_season_id::text as matched_season_id,
          status
        from social.shared_post_matches
        where platform = %s
          and source_scope = %s
          and status = 'matched'
          and source_id = any(%s)
        """,
        [platform, source_scope, source_ids or [""]],
    )
    materialized = 0
    refresh_season_ids: set[str] = set()
    for row in rows:
        source_id = str(row.get("source_id") or "").strip()
        matched_season_id = str(row.get("matched_season_id") or "").strip()
        matched_show_id = str(row.get("matched_show_id") or "").strip()
        if not source_id or not matched_season_id or not matched_show_id:
            continue
        target_context = get_season_context(matched_season_id)
        post_rows = _shared_post_rows_for_account(
            platform=platform,
            account_handle=account_handle,
            source_scope=source_scope,
            source_ids=[source_id],
            unassigned_only=False,
        )
        if not post_rows:
            continue
        post_row = post_rows[0]
        post_id = str(post_row.get("id") or "").strip()
        if not post_id:
            continue
        _update_platform_post_field(platform=platform, post_id=post_id, field="season_id", value=matched_season_id)
        _update_platform_post_field(platform=platform, post_id=post_id, field="show_id", value=matched_show_id)
        comments_job_config = {
            "run_id": run_id,
            "season_id": matched_season_id,
            "show_id": matched_show_id,
            "platform": platform,
            "source_scope": source_scope,
            "stage": "comments",
            "account": account_handle,
            "hashtags": [],
            "keywords": [],
            "sync_strategy": "incremental",
            "max_posts_per_target": 0,
            "max_comments_per_post": max(
                1, _resolve_positive_int_env("SOCIAL_SHARED_DEFAULT_MAX_COMMENTS_PER_POST", 50, minimum=1)
            ),
            "max_replies_per_post": 100,
            "fetch_replies": True,
            "ingest_mode": "comments_only",
            "comment_refresh_policy": DEFAULT_COMMENT_REFRESH_POLICY,
            "comment_anchor_source_ids": {platform: [source_id]},
            "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
        }
        _create_job(
            target_context,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type="comments",
            stage="comments",
            config=comments_job_config,
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=200,
        )
        try:
            _enqueue_platform_media_mirror_job(
                target_context,
                platform=platform,
                run_id=run_id,
                source_scope=source_scope,
                account=account_handle,
                post_row=post_row,
                week_index=None,
                parent_job_id=f"shared-materialize:{source_id}",
                conn=None,
            )
        except Exception:  # noqa: BLE001
            logger.exception("Failed to enqueue media mirror during shared materialization: %s %s", platform, source_id)
        materialized += 1
        refresh_season_ids.add(matched_season_id)
    if refresh_season_ids:
        _enqueue_shared_analytics_refresh_job(
            run_id=run_id,
            source_scope=source_scope,
            season_ids=sorted(refresh_season_ids),
        )
    metadata = {
        "stage": SEASON_MATERIALIZE_STAGE,
        "platform": platform,
        "account": account_handle,
        "materialized_count": materialized,
        "season_ids": sorted(refresh_season_ids),
        "activity": {"phase": "season_materialize_end", "last_progress_at": _iso(_now_utc())},
        "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
    }
    return materialized, 0, metadata


def _run_shared_analytics_refresh_stage(
    *,
    config: Mapping[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    season_ids = [str(item or "").strip() for item in (config.get("season_ids") or []) if str(item or "").strip()]
    _invalidate_week_detail_cache_after_run_terminal_status()
    metadata = {
        "stage": ANALYTICS_REFRESH_STAGE,
        "season_ids": season_ids,
        "activity": {"phase": "analytics_refresh_end", "last_progress_at": _iso(_now_utc())},
        "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
    }
    return len(season_ids), 0, metadata


def _execute_shared_claimed_job(job: Mapping[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    job_id = str(job.get("id") or "").strip()
    run_id = str(job.get("run_id") or "").strip()
    config = dict(job.get("config") or {})
    stage = str(config.get("stage") or (job.get("metadata") or {}).get("stage") or "").strip().lower()
    platform = _normalize_platform_name(job.get("platform"))
    source_scope = str(config.get("source_scope") or job.get("source_scope") or "bravo").strip().lower()
    account_handle = _normalize_account_handle(config.get("account")) or str(config.get("account") or "").strip()
    try:
        if stage == SHARED_ACCOUNT_POSTS_STAGE:
            posts_count, comments_count, metadata = _run_shared_account_posts_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
                worker_id=worker_id,
            )
        elif stage == POST_CLASSIFY_STAGE:
            posts_count, comments_count, metadata = _run_shared_post_classify_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                worker_id=worker_id,
            )
        elif stage == SEASON_MATERIALIZE_STAGE:
            posts_count, comments_count, metadata = _run_shared_season_materialize_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
            )
        elif stage == ANALYTICS_REFRESH_STAGE:
            posts_count, comments_count, metadata = _run_shared_analytics_refresh_stage(config=config)
        else:
            raise ValueError(f"Unsupported shared ingest stage: {stage}")
        _finish_job(
            job_id,
            status="completed",
            items_found=posts_count + comments_count,
            metadata=metadata,
        )
    except Exception as exc:  # noqa: BLE001
        _finish_job(
            job_id,
            status="failed",
            items_found=0,
            error_message=str(exc),
            metadata={
                "stage": stage,
                "platform": platform,
                "account": account_handle,
                "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
                "error": str(exc),
            },
            last_error_code="shared_stage_failed",
            last_error_class=exc.__class__.__name__,
        )
        logger.exception("Shared social ingest job failed: job_id=%s stage=%s platform=%s", job_id, stage, platform)
    finally:
        if run_id:
            _finalize_run_status(run_id)
    return _load_current_job_row(job_id)


def _job_stage_from_row(job: Mapping[str, Any]) -> str:
    config = dict(job.get("config") or {})
    metadata = dict(job.get("metadata") or {})
    return (
        _normalize_social_job_stage_for_stale(config.get("stage") or metadata.get("stage") or job.get("job_type"))
        or "unknown"
    )


def _dispatch_request_is_fresh(job: Mapping[str, Any]) -> bool:
    dispatch = _job_dispatch_metadata(job)
    requested_at = _coerce_dt(dispatch.get("dispatch_requested_at"))
    if requested_at is None:
        return False
    return (_now_utc() - requested_at) < timedelta(seconds=_modal_dispatch_retry_delay_seconds())


def _list_candidate_jobs_for_modal_dispatch(*, run_id: str | None = None, limit: int = 200) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 500))
    sql = """
        select
          id::text as id,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          priority,
          created_at,
          available_at,
          config,
          metadata
        from social.scrape_jobs
        where status in ('queued', 'pending', 'retrying')
          and available_at <= now()
          and (%s::uuid is null or run_id = %s::uuid)
        order by priority asc, created_at asc
        limit %s
    """
    return pg.fetch_all(sql, [run_id, run_id, safe_limit])


def _current_modal_dispatch_running_counts() -> tuple[dict[str, int], dict[tuple[str, str], int]]:
    rows = pg.fetch_all(
        """
        select
          lower(coalesce(config->>'stage', metadata->>'stage', job_type, 'unknown')) as stage,
          lower(coalesce(platform, 'unknown')) as platform,
          count(*)::int as total
        from social.scrape_jobs
        where status = 'running'
        group by 1, 2
        """
    )
    by_stage: dict[str, int] = {}
    by_stage_platform: dict[tuple[str, str], int] = {}
    for row in rows:
        stage = _normalize_social_job_stage_for_stale(row.get("stage")) or "unknown"
        platform = _normalize_platform_name(row.get("platform")) or "unknown"
        total = int(row.get("total") or 0)
        by_stage[stage] = by_stage.get(stage, 0) + total
        by_stage_platform[(stage, platform)] = total
    return by_stage, by_stage_platform


def dispatch_due_social_jobs(*, run_id: str | None = None, limit: int | None = None) -> dict[str, Any]:
    safe_limit = max(1, min(int(limit or _modal_dispatch_limit()), SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX))
    if not is_queue_enabled():
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": "queue_disabled"}
    if not is_modal_remote_executor_enabled():
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": "remote_executor_not_modal"}
    ready, reason = _modal_social_dispatch_ready()
    if not ready:
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": False,
                "last_dispatch_error": reason,
                "last_dispatch_error_at": _iso(_now_utc()),
            }
        )
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": reason}

    candidates = _list_candidate_jobs_for_modal_dispatch(run_id=run_id, limit=max(safe_limit * 4, 50))
    running_by_stage, running_by_stage_platform = _current_modal_dispatch_running_counts()
    dispatched_job_ids: list[str] = []
    dispatch_attempts = 0

    for job in candidates:
        if len(dispatched_job_ids) >= safe_limit:
            break
        stage = _job_stage_from_row(job)
        platform = _normalize_platform_name(job.get("platform")) or "unknown"
        if _dispatch_request_is_fresh(job):
            continue
        if running_by_stage.get(stage, 0) >= _modal_dispatch_stage_global_cap(stage):
            continue
        platform_cap = _modal_dispatch_platform_cap(stage, platform)
        if platform_cap is not None and running_by_stage_platform.get((stage, platform), 0) >= platform_cap:
            continue

        job_id = str(job.get("id") or "").strip()
        if not job_id:
            continue
        dispatch_attempts += 1
        lease_expires_at = _now_utc() + timedelta(
            seconds=_resolve_stale_seconds_for_job(
                platform=platform,
                stage=stage,
                has_queue_fields=True,
            )
        )
        _touch_job_dispatch_metadata(
            job_id,
            dispatch_backend="modal",
            lease_expires_at=lease_expires_at,
            last_dispatch_error=None,
        )
        dispatch_result = dispatch_social_job(job_id=job_id)
        if dispatch_result.get("dispatched"):
            _touch_job_dispatch_metadata(
                job_id,
                dispatch_backend="modal",
                remote_invocation_id=str(dispatch_result.get("call_id") or "").strip() or None,
                lease_expires_at=lease_expires_at,
                last_dispatch_error=None,
            )
            dispatched_job_ids.append(job_id)
            running_by_stage[stage] = running_by_stage.get(stage, 0) + 1
            running_by_stage_platform[(stage, platform)] = running_by_stage_platform.get((stage, platform), 0) + 1
        else:
            _touch_job_dispatch_metadata(
                job_id,
                dispatch_backend="modal",
                lease_expires_at=lease_expires_at,
                last_dispatch_error=str(dispatch_result.get("reason") or "dispatch_failed"),
            )

    _touch_modal_social_dispatcher_heartbeat(
        metadata_updates={
            "dispatch_enabled": True,
            "active_invocations": sum(running_by_stage.values()),
            "last_dispatch_success_at": _iso(_now_utc()) if dispatched_job_ids else None,
        }
    )
    return {
        "dispatched_job_ids": dispatched_job_ids,
        "dispatch_attempts": dispatch_attempts,
        "reason": None,
    }


def claim_and_process_social_job(*, job_id: str, worker_id: str) -> dict[str, Any]:
    claimed = _claim_job_by_id(job_id=job_id, worker_id=worker_id)
    if not claimed:
        return {
            "job_id": job_id,
            "claimed": False,
            "job": _load_current_job_row(job_id),
        }
    result = process_claimed_job(claimed, worker_id=worker_id)
    run_id = str(claimed.get("run_id") or "").strip() or None
    dispatch_due_social_jobs(run_id=run_id, limit=1)
    return {
        "job_id": job_id,
        "claimed": True,
        "job": result,
    }


def recover_and_dispatch_due_social_jobs(*, limit: int | None = None) -> dict[str, Any]:
    recovered = recover_stale_running_jobs(limit=max(1, min(int(limit or _modal_dispatch_limit()), 250)))
    dispatch_summary = dispatch_due_social_jobs(limit=limit)
    return {
        "recovered_jobs": [str(row.get("id") or "").strip() for row in recovered],
        **dispatch_summary,
    }


def _claim_next_jobs(
    *,
    worker_id: str | None = None,
    run_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
    limit: int = 1,
) -> list[dict[str, Any]]:
    if not worker_id:
        logger.warning("_claim_next_jobs called without worker_id; capability filter requires worker registration")
        return []
    safe_limit = max(1, min(int(limit), SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX))
    run_in_flight_cap = _resolve_run_in_flight_cap()
    youtube_run_in_flight_cap = _resolve_youtube_run_in_flight_cap()
    stale_after_seconds = _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    return pg.fetch_all(
        """
        with worker_caps as (
          select
            coalesce(
              supported_platforms,
              array['instagram', 'tiktok', 'twitter', 'youtube', 'facebook', 'threads']
            ) as platforms,
            coalesce((metadata->'auth_capabilities'->>'instagram_authenticated')::boolean, false)
              as instagram_authenticated
          from social.scrape_workers
          where worker_id = %s
        ),
        healthy_instagram_auth_workers as (
          select count(*)::int as healthy_auth_workers
          from social.scrape_workers
          where last_seen_at >= now() - make_interval(secs => %s)
            and status in ('starting', 'idle', 'working')
            and 'instagram' = any(
              coalesce(
                supported_platforms,
                array['instagram', 'tiktok', 'twitter', 'youtube', 'facebook', 'threads']
              )
            )
            and coalesce((metadata->'auth_capabilities'->>'instagram_authenticated')::boolean, false)
        ),
        run_in_flight as (
          select run_id::text as run_id, count(*)::int as in_flight
          from social.scrape_jobs
          where status = 'running'
            and run_id is not null
          group by run_id
        ),
        run_platform_in_flight as (
          select run_id::text as run_id, platform, count(*)::int as in_flight
          from social.scrape_jobs
          where status = 'running'
            and run_id is not null
          group by run_id, platform
        ),
        eligible as (
          select
            j.id,
            j.priority,
            j.created_at,
            row_number() over (
              partition by coalesce(j.run_id::text, j.id::text)
              order by j.priority asc, j.created_at asc
            ) as run_rank,
            coalesce(rif.in_flight, 0)::int as in_flight,
            coalesce(rpif.in_flight, 0)::int as platform_in_flight
          from social.scrape_jobs j
          left join run_in_flight rif on rif.run_id = j.run_id::text
          left join run_platform_in_flight rpif
            on rpif.run_id = j.run_id::text
           and rpif.platform = j.platform
          where j.status in ('queued', 'pending', 'retrying')
            and j.available_at <= now()
            and (%s::uuid is null or j.run_id = %s::uuid)
            and (
              %s::text is null
              or coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s::text
            )
            and (%s::text is null or j.platform = %s::text)
            and exists (
              select 1
              from worker_caps wc
              where j.platform = any(wc.platforms)
            )
            and (
              j.platform <> 'instagram'
              or exists (
                select 1
                from worker_caps wc
                where wc.instagram_authenticated
              )
              or (select hiw.healthy_auth_workers from healthy_instagram_auth_workers hiw) = 0
            )
            and (
              j.worker_id is null
              or j.worker_id = %s::text
              or (j.worker_id is not null and %s::text is not null and %s::text like j.worker_id || '%%')
            )
            and (
              j.platform <> 'youtube'
              or j.run_id is null
              or coalesce(rpif.in_flight, 0) < %s
              or not exists (
                select 1
                from social.scrape_jobs other
                where other.status in ('queued', 'pending', 'retrying')
                  and other.available_at <= now()
                  and other.run_id = j.run_id
                  and other.platform <> 'youtube'
              )
            )
            and (j.run_id is null or coalesce(rif.in_flight, 0) < %s)
        ),
        candidate as (
          select id
          from eligible
          order by run_rank asc, priority asc, created_at asc
          limit %s
        )
        update social.scrape_jobs as j
        set
          status = 'running',
          started_at = coalesce(j.started_at, now()),
          claimed_at = now(),
          heartbeat_at = now(),
          worker_id = coalesce(%s, j.worker_id),
          attempt_count = j.attempt_count + 1
        from candidate
        where j.id = candidate.id
          and j.status in ('queued', 'pending', 'retrying')
        returning
          j.id::text,
          j.run_id::text as run_id,
          j.platform,
          j.job_type,
          j.status,
          j.config,
          j.metadata,
          j.attempt_count,
          j.max_attempts,
          j.source_scope,
          j.season_id::text as season_id,
          j.last_error_code
        """,
        [
            worker_id,
            stale_after_seconds,
            run_id,
            run_id,
            stage,
            stage,
            platform,
            platform,
            worker_id,
            worker_id,
            worker_id,
            youtube_run_in_flight_cap,
            run_in_flight_cap,
            safe_limit,
            worker_id,
        ],
    )


def _claim_next_job(
    *,
    worker_id: str | None = None,
    run_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    claimed = _claim_next_jobs(worker_id=worker_id, run_id=run_id, stage=stage, platform=platform, limit=1)
    return claimed[0] if claimed else None


def _execute_claimed_job(job: dict[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    job_id = str(job.get("id") or "")
    run_id = str(job.get("run_id") or "")
    platform = _normalize_platform_name(job.get("platform"))
    config: dict[str, Any] = {}
    stage = str((job.get("metadata") or {}).get("stage") or "posts")
    account = ""
    crawlee_active_execution = False
    crawlee_fallback_to_legacy = False
    auth_preflight: AuthPreflightResult | None = None

    try:
        config = dict(job.get("config") or {})
        config["_attempt_count"] = max(1, int(job.get("attempt_count") or 1))
        config["_max_attempts"] = max(1, int(job.get("max_attempts") or 1))
        config["_last_error_code"] = str(job.get("last_error_code") or "").strip().lower() or None
        stage = str(config.get("stage") or ((job.get("metadata") or {}).get("stage")) or "posts")
        if stage in {
            SHARED_ACCOUNT_POSTS_STAGE,
            POST_CLASSIFY_STAGE,
            SEASON_MATERIALIZE_STAGE,
            ANALYTICS_REFRESH_STAGE,
        }:
            return _execute_shared_claimed_job(job, worker_id=worker_id)
        context = get_season_context(str(config.get("season_id") or job.get("season_id") or ""))
        if platform not in SUPPORTED_PLATFORMS:
            logger.warning(
                "Worker %s does not support platform %s; releasing job %s back to queue",
                worker_id,
                platform,
                job_id,
            )
            _finish_job(
                job_id,
                status="retrying",
                items_found=0,
                error_message=f"Platform {platform} ingest is not supported by this worker",
                last_error_code="platform_not_supported",
                last_error_class="WorkerCapabilityMismatch",
                next_available_at=_now_utc(),
            )
            # Undo the attempt_count bump since this isn't a real attempt failure
            pg.execute(
                "UPDATE social.scrape_jobs SET attempt_count = greatest(0, attempt_count - 1) WHERE id = %s",
                [job_id],
            )
            return (
                pg.fetch_one(
                    (
                        "SELECT id::text, run_id::text as run_id, platform, job_type, "
                        "status, items_found, error_message, metadata "
                        "FROM social.scrape_jobs WHERE id = %s"
                    ),
                    [job_id],
                )
                or {}
            )
        sync_strategy = str(config.get("sync_strategy") or "incremental").strip().lower()
        if sync_strategy not in SUPPORTED_SYNC_STRATEGIES:
            sync_strategy = "incremental"
        raw_max_posts = config.get("max_posts_per_target")
        raw_max_comments = config.get("max_comments_per_post")
        raw_max_replies = config.get("max_replies_per_post")
        raw_mode = str(config.get("ingest_mode") or "posts_and_comments")
        raw_comment_refresh_policy = config.get("comment_refresh_policy")
        raw_comment_anchor_source_ids = config.get("comment_anchor_source_ids")
        raw_sound_ids = config.get("sound_ids")
        raw_fetch_replies = bool(config.get("fetch_replies", True))
        normalized_max_posts = None if raw_max_posts is None else max(0, int(raw_max_posts))
        normalized_max_comments = None if raw_max_comments is None else max(0, int(raw_max_comments))
        normalized_max_replies = None if raw_max_replies is None else max(0, int(raw_max_replies))
        resolved_posts, resolved_comments, resolved_replies, resolved_fetch_replies = _resolve_depth_defaults(
            max_posts_per_target=normalized_max_posts,
            max_comments_per_post=normalized_max_comments,
            max_replies_per_post=normalized_max_replies,
            fetch_replies=raw_fetch_replies,
        )
        normalized_mode = (raw_mode or "posts_and_comments").strip().lower()
        if normalized_mode in {"posts_only", "details_refresh"}:
            resolved_comments = 0
            resolved_replies = 0
            resolved_fetch_replies = False
        elif normalized_mode == "comments_only":
            resolved_posts = 0
        normalized_comment_refresh_policy = _normalize_comment_refresh_policy(raw_comment_refresh_policy)
        normalized_comment_anchor_source_ids: dict[str, set[str]] = {}
        if isinstance(raw_comment_anchor_source_ids, list):
            normalized_source_ids = {
                str(item or "").strip() for item in raw_comment_anchor_source_ids if str(item or "").strip()
            }
            if len(normalized_source_ids) <= MAX_COMMENT_ANCHOR_SOURCE_IDS_PER_PLATFORM:
                normalized_comment_anchor_source_ids[platform] = normalized_source_ids
        elif isinstance(raw_comment_anchor_source_ids, dict):
            normalized_comment_anchor_source_ids, _ = _normalize_comment_anchor_source_ids(
                raw_comment_anchor_source_ids,
                allowed_platforms={platform},
            )
        normalized_sound_ids = _normalize_tiktok_sound_ids(raw_sound_ids)
        opts = IngestOptions(
            platforms=None,
            source_scope=str(config.get("source_scope") or job.get("source_scope") or "bravo"),
            sync_strategy=sync_strategy,
            max_posts_per_target=resolved_posts,
            max_comments_per_post=resolved_comments,
            max_replies_per_post=resolved_replies,
            fetch_replies=resolved_fetch_replies,
            ingest_mode=normalized_mode,
            date_start=_coerce_dt(config.get("date_start")),
            date_end=_coerce_dt(config.get("date_end")),
            comment_refresh_policy=normalized_comment_refresh_policy,
            comment_anchor_source_ids=normalized_comment_anchor_source_ids or None,
            sound_ids=normalized_sound_ids or None,
        )
        account = str(config.get("account") or "")
        hashtags = [str(item).strip().lstrip("#") for item in (config.get("hashtags") or []) if str(item).strip()]
        keywords = [str(item).strip() for item in (config.get("keywords") or []) if str(item).strip()]
        use_crawlee = (
            should_use_crawlee(platform) and stage in {"posts", "comments"} and normalized_mode != "details_refresh"
        )
        runtime_config = build_runtime_config(platform)
        cancelled_result = _abort_claimed_job_if_cancelled(
            job_id=job_id,
            run_id=run_id,
            stage=stage,
            platform=platform,
            account=account,
        )
        if cancelled_result is not None:
            return cancelled_result
        _touch_job_heartbeat(job_id, worker_id=worker_id)
        if use_crawlee:
            twitter_cookies: dict[str, str] | None = None
            twitter_bearer: str | None = None
            if platform == "twitter":
                twitter_cookies, twitter_bearer = _load_twitter_auth()
            auth_preflight = check_platform_auth(
                platform=platform,
                instagram_cookies=_load_instagram_cookies() if platform == "instagram" else None,
                tiktok_cookies=_load_tiktok_cookies() if platform == "tiktok" else None,
                facebook_cookies=_load_facebook_cookies() if platform == "facebook" else None,
                threads_cookies=_load_threads_cookies() if platform == "threads" else None,
                twitter_cookies=twitter_cookies,
                twitter_bearer=twitter_bearer,
                twikit_credentials=_load_twikit_credentials() if platform == "twitter" else None,
            )
            if not auth_preflight.ok:
                strict_auth = runtime_config.auth_strict or is_auth_strict_for_platform(platform)
                if platform == "instagram" and not strict_auth:
                    crawlee_fallback_to_legacy = True
                    posts_count, comments_count, retrieval_meta = _run_platform_stage(
                        context=context,
                        run_id=run_id or None,
                        platform=platform,
                        stage=stage,
                        account=account,
                        hashtags=hashtags,
                        keywords=keywords,
                        opts=opts,
                        job_id=job_id,
                        config=config,
                    )
                    retrieval_meta = dict(retrieval_meta or {})
                    retrieval_meta["crawler_runtime"] = {
                        "engine": "legacy_fallback_after_auth_preflight",
                        "platform": platform,
                        "stage": stage,
                        "request_mode": normalized_mode,
                        "crawlee_available": True,
                        "max_concurrency": runtime_config.max_concurrency,
                        "max_retries": runtime_config.max_retries,
                        "requests_total": 0,
                        "requests_handled": 0,
                        "retries_total": 0,
                        "blocked_events": 0,
                        "session_rotations": 0,
                        "max_proxy_tier_used": 0,
                        "crawlee_request_count": 0,
                        "crawlee_retry_count": 0,
                        "crawlee_session_pool_used": False,
                    }
                    retrieval_meta["auth_context"] = build_auth_context(
                        auth_preflight,
                        fallback_to_legacy=True,
                    )
                else:
                    raise AuthPreflightError(auth_preflight)
            else:
                crawlee_active_execution = True
                posts_count, comments_count, retrieval_meta = _run_platform_stage_via_crawlee(
                    context=context,
                    run_id=run_id or None,
                    platform=platform,
                    stage=stage,
                    account=account,
                    hashtags=hashtags,
                    keywords=keywords,
                    opts=opts,
                    job_id=job_id,
                    config=config,
                    runtime_config=runtime_config,
                    auth_preflight=auth_preflight,
                )
        else:
            posts_count, comments_count, retrieval_meta = _run_platform_stage(
                context=context,
                run_id=run_id or None,
                platform=platform,
                stage=stage,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                config=config,
            )
        persist_counters = {
            "posts_upserted": _normalize_non_negative_int(
                (retrieval_meta.get("persist_counters") or {}).get("posts_upserted")
            ),
            "comments_upserted": _normalize_non_negative_int(
                (retrieval_meta.get("persist_counters") or {}).get("comments_upserted")
            ),
        }
        activity = dict(retrieval_meta.get("activity") or {})
        if not activity:
            activity = {"phase": f"{stage}_end", "last_progress_at": _iso(_now_utc())}
        fetch_counters = _comment_stats_payload(dict(retrieval_meta.get("comment_stats") or {}))
        crawler_runtime = dict(retrieval_meta.get("crawler_runtime") or {})
        auth_context = dict(retrieval_meta.get("auth_context") or {})
        base_metadata = {
            "stage": stage,
            "stage_counters": {"posts": posts_count, "comments": comments_count},
            "persist_counters": persist_counters,
            "activity": activity,
            "fetch_counters": fetch_counters,
            "platform": platform,
            "account": account,
            "crawler_runtime": crawler_runtime,
            "auth_context": auth_context,
            "retrieval_meta": retrieval_meta,
        }
        run_is_cancelled = False
        if run_id:
            run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
            run_is_cancelled = str(run_state.get("status") or "") == "cancelled"
        if run_is_cancelled:
            _finish_job(
                job_id,
                status="cancelled",
                items_found=posts_count + comments_count,
                metadata=base_metadata,
            )
            return (
                pg.fetch_one(
                    """
                select
                  id::text,
                  run_id::text as run_id,
                  platform,
                  job_type,
                  status,
                  items_found,
                  error_message,
                  metadata
                from social.scrape_jobs
                where id = %s
                """,
                    [job_id],
                )
                or {}
            )
        _finish_job(
            job_id,
            status="completed",
            items_found=posts_count + comments_count,
            metadata=base_metadata,
        )
    except Exception as exc:  # noqa: BLE001
        run_is_cancelled = False
        if run_id:
            run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
            run_is_cancelled = str(run_state.get("status") or "") == "cancelled"
        if run_is_cancelled:
            _finish_job(
                job_id,
                status="cancelled",
                items_found=0,
                error_message="Cancelled by user request",
                metadata={
                    "stage": stage,
                    "platform": platform,
                    "account": account,
                },
            )
            if run_id:
                _finalize_run_status(run_id)
            return (
                pg.fetch_one(
                    """
                select
                  id::text,
                  run_id::text as run_id,
                  platform,
                  job_type,
                  status,
                  items_found,
                  error_message,
                  metadata
                from social.scrape_jobs
                where id = %s
                """,
                    [job_id],
                )
                or {}
            )
        runtime_error_code = str(getattr(exc, "error_code", "") or "").strip().lower()
        runtime_error_class = str(getattr(exc, "error_class", "") or "").strip()
        runtime_retryable = getattr(exc, "retryable", None)
        runtime_metadata = getattr(exc, "runtime_metadata", None)
        if runtime_error_code:
            error_code = runtime_error_code
            error_class = runtime_error_class or exc.__class__.__name__
            transient = (
                bool(runtime_retryable)
                if runtime_retryable is not None
                else error_code
                in {
                    "blocked",
                    "rate_limited",
                    "network",
                }
            )
        elif crawlee_active_execution:
            error_code, error_class, transient = classify_exception(exc)
        else:
            error_code, error_class, transient = _classify_job_error(exc)
        attempt_count = int(job.get("attempt_count") or 1)
        max_attempts = int(job.get("max_attempts") or 1)
        can_retry = transient and attempt_count < max_attempts
        next_available_at = _now_utc() + timedelta(seconds=_retry_backoff_seconds(attempt_count)) if can_retry else None
        existing_job = (
            pg.fetch_one(
                "select items_found, metadata from social.scrape_jobs where id = %s",
                [job_id],
            )
            or {}
        )
        existing_metadata = dict(existing_job.get("metadata") or {})
        existing_activity = dict(existing_metadata.get("activity") or {})
        existing_activity["phase"] = "failed"
        existing_activity["last_progress_at"] = _iso(_now_utc())
        existing_metadata.update(
            {
                "stage": stage,
                "platform": platform,
                "account": account,
                "error": str(exc),
                "error_code": error_code,
                "error_class": error_class,
                "job_error_code": _normalize_job_error_code(
                    raw_error_code=error_code,
                    error_message=str(exc),
                    error_class=error_class,
                ),
                "failure_reason_code": error_code,
                "retryable": can_retry,
                "activity": existing_activity,
            }
        )
        if isinstance(runtime_metadata, dict):
            if isinstance(runtime_metadata.get("crawler_runtime"), dict):
                existing_metadata["crawler_runtime"] = runtime_metadata["crawler_runtime"]
            if isinstance(runtime_metadata.get("auth_context"), dict):
                existing_metadata["auth_context"] = runtime_metadata["auth_context"]
        elif auth_preflight is not None:
            existing_metadata["auth_context"] = build_auth_context(
                auth_preflight,
                fallback_to_legacy=crawlee_fallback_to_legacy,
            )
        _finish_job(
            job_id,
            status="retrying" if can_retry else "failed",
            items_found=_normalize_non_negative_int(existing_job.get("items_found")),
            error_message=str(exc),
            metadata=existing_metadata,
            last_error_code=error_code,
            last_error_class=error_class,
            next_available_at=next_available_at,
        )
        logger.exception("Social ingest job failed: job_id=%s stage=%s platform=%s", job_id, stage, platform)
    finally:
        if run_id:
            _finalize_run_status(run_id)

    return (
        pg.fetch_one(
            """
        select
          id::text,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          items_found,
          error_message,
          metadata
        from social.scrape_jobs
        where id = %s
        """,
            [job_id],
        )
        or {}
    )


def _fetch_next_preclaimed_job(
    *,
    worker_id: str,
    run_id: str,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    """Fetch the next pre-claimed running job owned by this worker (no status change needed)."""
    return pg.fetch_one(
        """
        select
          id::text,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          config,
          metadata,
          attempt_count,
          max_attempts,
          source_scope,
          season_id::text as season_id
        from social.scrape_jobs
        where status = 'running'
          and run_id = %s::uuid
          and (
            worker_id = %s
            or (%s::text is not null and %s::text like worker_id || '%%')
          )
          and (
            %s::text is null
            or coalesce(config->>'stage', metadata->>'stage', job_type) = %s::text
          )
          and (%s::text is null or platform = %s::text)
        order by priority asc, created_at asc
        limit 1
        """,
        [run_id, worker_id, worker_id, worker_id, stage, stage, platform, platform],
    )


def _stage_claim_candidates(stage: str | None) -> tuple[str | None, ...]:
    normalized_stage = _normalize_social_job_stage_for_stale(stage)
    if normalized_stage == "comments":
        return ("comments", "posts")
    return (stage,)


def _resolve_youtube_narrow_window_page_cap(
    *,
    date_start: datetime | None,
    date_end: datetime | None,
) -> int | None:
    span_days = _window_span_days(date_start=date_start, date_end=date_end)
    if span_days is None or span_days > 45:
        return None
    default_cap = 4 if span_days <= 14 else 6
    return _resolve_positive_int_env(
        "SOCIAL_YOUTUBE_NARROW_WINDOW_MAX_PAGES",
        default_cap,
        minimum=1,
    )


def execute_run(
    run_id: str,
    *,
    worker_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any]:
    platform = _normalize_platform_name(platform) or None
    _set_run_status(run_id, "running")
    claim_stage_candidates = _stage_claim_candidates(stage)
    claim_batch_sizes = {
        claim_stage: _resolve_job_claim_batch_size(stage=claim_stage) for claim_stage in claim_stage_candidates
    }
    claim_batch_size = max(claim_batch_sizes.values(), default=_resolve_job_claim_batch_size(stage=stage))
    claimed_jobs: list[dict[str, Any]] = []
    while True:
        if not claimed_jobs:
            for claim_stage in claim_stage_candidates:
                claimed_jobs = _claim_next_jobs(
                    worker_id=worker_id,
                    run_id=run_id,
                    stage=claim_stage,
                    platform=platform,
                    limit=min(claim_batch_size, claim_batch_sizes.get(claim_stage) or claim_batch_size),
                )
                if claimed_jobs:
                    break
        job = claimed_jobs.pop(0) if claimed_jobs else None
        if not job and worker_id:
            for claim_stage in claim_stage_candidates:
                job = _fetch_next_preclaimed_job(
                    worker_id=worker_id,
                    run_id=run_id,
                    stage=claim_stage,
                    platform=platform,
                )
                if job:
                    break
        if not job:
            break
        run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
        if str(run_state.get("status")) == "cancelled":
            _finish_job(str(job.get("id")), status="cancelled", items_found=0, metadata={"stage": "cancelled"})
            continue
        _execute_claimed_job(job, worker_id=worker_id)

    _finalize_run_status(run_id)
    return (
        pg.fetch_one(
            """
        select
          id::text,
          season_id::text as season_id,
          show_id::text as show_id,
          source_scope,
          status,
          config,
          summary,
          created_at,
          started_at,
          completed_at,
          cancelled_at
        from social.scrape_runs
        where id = %s
        """,
            [run_id],
        )
        or {}
    )


def process_next_queued_job(
    *,
    worker_id: str,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    platform = _normalize_platform_name(platform) or None
    job = _claim_next_job(worker_id=worker_id, run_id=None, stage=stage, platform=platform)
    if not job:
        return None
    return _execute_claimed_job(job, worker_id=worker_id)


def claim_next_queued_jobs(
    *,
    worker_id: str,
    stage: str | None = None,
    platform: str | None = None,
    run_id: str | None = None,
    limit: int | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_platform_name(platform) or None
    safe_limit = _resolve_job_claim_batch_size(limit, stage=stage)
    return _claim_next_jobs(
        worker_id=worker_id,
        run_id=run_id,
        stage=stage,
        platform=normalized_platform,
        limit=safe_limit,
    )


def process_claimed_job(job: dict[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    return _execute_claimed_job(job, worker_id=worker_id)


def ingest_season(
    season_id: str,
    *,
    platforms: list[str] | None,
    accounts_override: list[str] | None = None,
    hashtags_override: list[str] | None = None,
    keywords_override: list[str] | None = None,
    source_scope: str,
    sync_strategy: str = "incremental",
    max_posts_per_target: int | None,
    max_comments_per_post: int | None,
    max_replies_per_post: int | None = 100,
    fetch_replies: bool,
    ingest_mode: str = "posts_and_comments",
    date_start: datetime | None,
    date_end: datetime | None,
    comment_refresh_policy: str = DEFAULT_COMMENT_REFRESH_POLICY,
    comment_anchor_source_ids: dict[str, list[str]] | None = None,
    sound_ids: list[str] | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    youtube_source_mode: str | None = None,
    youtube_force_reindex: bool = False,
    youtube_force_media_refresh: bool = False,
    youtube_force_comment_refresh: bool = False,
    week_index: int | None = None,
    window_timezone: str | None = None,
    run_scope_label: str | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    orchestration_metadata: Mapping[str, Any] | None = None,
    initiated_by: str | None,
    inline_worker_id: str | None = None,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    context = get_season_context(season_id)
    if source_scope not in SUPPORTED_SCOPES:
        raise ValueError(f"Unsupported source scope: {source_scope}")

    normalized_mode = (ingest_mode or "posts_and_comments").strip().lower()
    if normalized_mode not in SUPPORTED_INGEST_MODES:
        raise ValueError(f"Unsupported ingest mode: {ingest_mode}")
    normalized_sync_strategy = (sync_strategy or "incremental").strip().lower()
    if normalized_sync_strategy not in SUPPORTED_SYNC_STRATEGIES:
        raise ValueError(f"Unsupported sync strategy: {sync_strategy}")
    normalized_comment_refresh_policy = (comment_refresh_policy or DEFAULT_COMMENT_REFRESH_POLICY).strip().lower()
    if normalized_comment_refresh_policy not in SUPPORTED_COMMENT_REFRESH_POLICIES:
        raise ValueError(f"Unsupported comment refresh policy: {comment_refresh_policy}")
    normalized_youtube_source_mode = _normalize_youtube_source_mode(youtube_source_mode)

    platform_filter = set(_resolve_requested_platforms(platforms)) if platforms is not None else set()
    normalized_comment_anchor_source_ids, overflow_platforms = _normalize_comment_anchor_source_ids(
        comment_anchor_source_ids,
        allowed_platforms=(platform_filter or None),
    )

    normalized_hashtags_override = _normalize_terms(hashtags_override, strip_prefix="#")
    normalized_keywords_override = _normalize_terms(keywords_override)
    normalized_sound_ids = _normalize_tiktok_sound_ids(sound_ids or [])
    normalized_accounts_override: list[str] = []
    invalid_overrides: list[str] = []
    for raw_account in [str(item or "").strip() for item in (accounts_override or []) if str(item or "").strip()]:
        normalized = _normalize_account_handle(raw_account)
        if not normalized:
            invalid_overrides.append(raw_account)
            continue
        if normalized in normalized_accounts_override:
            continue
        normalized_accounts_override.append(normalized)
    if invalid_overrides:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle override(s): {', '.join(sorted(set(invalid_overrides)))}",
        )

    resolved_posts, resolved_comments, resolved_replies, resolved_fetch_replies = _resolve_depth_defaults(
        max_posts_per_target=max_posts_per_target,
        max_comments_per_post=max_comments_per_post,
        max_replies_per_post=max_replies_per_post,
        fetch_replies=fetch_replies,
    )
    if normalized_mode in {"posts_only", "details_refresh"}:
        resolved_comments = 0
        resolved_replies = 0
        resolved_fetch_replies = False
    elif normalized_mode == "comments_only":
        # Comments-only runs should not cap anchor iteration by default.
        resolved_posts = 0

    stage_plan = (
        ["posts"]
        if normalized_mode in {"posts_only", "details_refresh"}
        else ["comments"]
        if normalized_mode == "comments_only"
        else ["posts", "comments"]
    )

    opts = IngestOptions(
        platforms=platform_filter or None,
        source_scope=source_scope,
        sync_strategy=normalized_sync_strategy,
        max_posts_per_target=resolved_posts,
        max_comments_per_post=resolved_comments,
        max_replies_per_post=resolved_replies,
        fetch_replies=resolved_fetch_replies,
        ingest_mode=normalized_mode,
        date_start=date_start,
        date_end=date_end,
        comment_refresh_policy=normalized_comment_refresh_policy,
        comment_anchor_source_ids=normalized_comment_anchor_source_ids or None,
        sound_ids=normalized_sound_ids or None,
        youtube_source_mode=normalized_youtube_source_mode,
        youtube_force_reindex=bool(youtube_force_reindex),
        youtube_force_media_refresh=bool(youtube_force_media_refresh),
        youtube_force_comment_refresh=bool(youtube_force_comment_refresh),
    )
    targets_payload = get_targets(season_id, source_scope=source_scope)
    targets_by_platform: dict[str, dict[str, list[str]]] = {}
    configured_target_platforms: set[str] = set()
    for target in targets_payload.get("targets", []):
        if not target.get("is_active", True):
            continue
        target_platform = _normalize_platform_name(target.get("platform"))
        if target_platform not in SUPPORTED_PLATFORMS:
            logger.warning(
                "Skipping ingest target with unsupported platform token: %s (season=%s source_scope=%s)",
                target.get("platform"),
                context.season_id,
                source_scope,
            )
            continue
        if platform_filter and target_platform not in platform_filter:
            continue
        configured_target_platforms.add(target_platform)
        bucket = targets_by_platform.setdefault(target_platform, {"accounts": [], "hashtags": [], "keywords": []})
        bucket["accounts"].extend(
            [str(item or "").strip() for item in (target.get("accounts") or []) if str(item or "").strip()]
        )
        bucket["hashtags"].extend(
            [str(item or "").strip() for item in (target.get("hashtags") or []) if str(item or "").strip()]
        )
        bucket["keywords"].extend(
            [str(item or "").strip() for item in (target.get("keywords") or []) if str(item or "").strip()]
        )

    for platform_name in sorted(platform_filter):
        targets_by_platform.setdefault(platform_name, {"accounts": [], "hashtags": [], "keywords": []})

    fallback_hashtags, fallback_keywords = _derive_show_terms(context.show_name)
    include_default_hashtags = len(normalized_hashtags_override) == 0
    include_default_keywords = len(normalized_keywords_override) == 0
    effective_targets: list[dict[str, Any]] = []
    invalid_target_accounts: list[str] = []
    for platform, values in sorted(targets_by_platform.items()):
        authoritative_override = _use_authoritative_account_override(
            context=context,
            source_scope=source_scope,
            platform=platform,
            normalized_accounts_override=normalized_accounts_override,
        )
        raw_accounts = [*(values.get("accounts") or []), *normalized_accounts_override]
        normalized_accounts: list[str] = []
        seen_accounts: set[str] = set()
        for raw_account in raw_accounts:
            normalized_account = _normalize_account_handle(raw_account)
            if not normalized_account:
                if str(raw_account or "").strip():
                    invalid_target_accounts.append(f"{platform}:{raw_account}")
                continue
            if platform == "instagram" and not _is_valid_instagram_account_handle(normalized_account):
                invalid_target_accounts.append(f"{platform}:{raw_account}")
                continue
            if normalized_account in seen_accounts:
                continue
            seen_accounts.add(normalized_account)
            normalized_accounts.append(normalized_account)

        hashtags = _normalize_unique_terms(
            [
                *_normalize_terms(values.get("hashtags"), strip_prefix="#"),
                *normalized_hashtags_override,
                *(fallback_hashtags if include_default_hashtags else []),
            ]
        )
        keywords = _normalize_unique_terms(
            [
                *_normalize_terms(values.get("keywords")),
                *normalized_keywords_override,
                *(fallback_keywords if include_default_keywords else []),
            ]
        )
        if not authoritative_override:
            if platform == "instagram":
                normalized_accounts = _ensure_rhoslc_instagram_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_instagram_hashtags(context, hashtags)
            elif platform == "twitter":
                normalized_accounts = _ensure_rhoslc_twitter_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_twitter_hashtags(context, hashtags)
            normalized_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=normalized_accounts,
            )
            if not normalized_accounts and platform in platform_filter and platform in configured_target_platforms:
                default_accounts = _default_platform_accounts(platform)
                if default_accounts:
                    logger.info(
                        "No %s accounts configured for season=%s; using default accounts: %s",
                        platform,
                        context.season_id,
                        default_accounts,
                    )
                    normalized_accounts = default_accounts
            if platform == "instagram":
                normalized_accounts = _ensure_rhoslc_instagram_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_instagram_hashtags(context, hashtags)
            elif platform == "twitter":
                normalized_accounts = _ensure_rhoslc_twitter_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_twitter_hashtags(context, hashtags)
            normalized_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=normalized_accounts,
            )
        if normalized_accounts:
            effective_targets.append(
                {
                    "platform": platform,
                    "accounts": normalized_accounts,
                    "hashtags": hashtags,
                    "keywords": keywords,
                }
            )

    if invalid_target_accounts:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle(s): {', '.join(sorted(set(invalid_target_accounts)))}",
        )
    if not effective_targets:
        raise SocialIngestValidationError(
            "NO_INGEST_TARGETS",
            "No executable ingest targets after applying active targets and overrides",
        )

    target_account_count = sum(
        len([str(item).strip() for item in (target.get("accounts") or []) if str(item).strip()])
        for target in effective_targets
    )
    resolved_runner_strategy, resolved_runner_count, resolved_window_shard_hours = _coerce_targeted_window_schedule(
        platforms=opts.platforms,
        account_count=target_account_count,
        ingest_mode=opts.ingest_mode,
        date_start=opts.date_start,
        date_end=opts.date_end,
        runner_strategy=runner_strategy,
        runner_count=runner_count,
        window_shard_hours=window_shard_hours,
    )
    schedule = _build_ingest_shard_schedule(
        date_start=opts.date_start,
        date_end=opts.date_end,
        runner_strategy=resolved_runner_strategy,
        runner_count=resolved_runner_count,
        window_shard_hours=resolved_window_shard_hours,
        runner_b_start_offset_hours=runner_b_start_offset_hours,
        day_weight_profile=day_weight_profile,
        priority_mode=priority_mode,
    )

    execution_metadata = _configured_execution_metadata()
    run_config = {
        "pipeline_ingest_mode": LEGACY_SEASON_TARGETED_INGEST_MODE,
        "season_id": context.season_id,
        "show_id": context.show_id,
        "source_scope": source_scope,
        "run_scope": _ingest_run_scope_type(
            week_index=week_index,
            date_start=opts.date_start,
            date_end=opts.date_end,
        ),
        "window_label": str(run_scope_label or "").strip() or None,
        "week_index": int(week_index) if week_index is not None else None,
        "window_timezone": str(window_timezone or "America/New_York").strip() or "America/New_York",
        "platforms": sorted(platform_filter) if platform_filter else "all",
        "accounts_override": normalized_accounts_override,
        "hashtags_override": normalized_hashtags_override,
        "keywords_override": normalized_keywords_override,
        "date_start": _iso(opts.date_start),
        "date_end": _iso(opts.date_end),
        "sync_strategy": opts.sync_strategy,
        "max_posts_per_target": opts.max_posts_per_target,
        "max_comments_per_post": opts.max_comments_per_post,
        "max_replies_per_post": opts.max_replies_per_post,
        "fetch_replies": opts.fetch_replies,
        "ingest_mode": opts.ingest_mode,
        "comment_refresh_policy": opts.comment_refresh_policy,
        "comment_anchor_source_ids": _serialize_comment_anchor_source_ids(opts.comment_anchor_source_ids),
        "comment_anchor_source_ids_overflow_platforms": sorted(overflow_platforms),
        "sound_ids": list(opts.sound_ids or []),
        "runner_strategy": schedule.strategy,
        "runner_count": schedule.runner_count,
        "window_shard_hours": schedule.window_shard_hours,
        "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
        "day_weight_profile": schedule.day_weight_profile,
        "priority_mode": schedule.priority_mode,
        "youtube_source_mode": opts.youtube_source_mode,
        "youtube_force_reindex": opts.youtube_force_reindex,
        "youtube_force_media_refresh": opts.youtube_force_media_refresh,
        "youtube_force_comment_refresh": opts.youtube_force_comment_refresh,
        "client_session_id": str(client_session_id or "").strip() or None,
        "client_workflow_id": str(client_workflow_id or "").strip() or None,
        **execution_metadata,
    }
    if orchestration_metadata:
        run_config.update({str(key): value for key, value in orchestration_metadata.items()})
    run_id = _create_run(
        context,
        source_scope=source_scope,
        initiated_by=initiated_by,
        config=run_config,
        status="queued",
    )

    queue_enabled = is_queue_enabled()
    initial_job_status = "queued" if queue_enabled else "pending"
    job_ids: list[str] = []
    skipped_comment_jobs = 0
    created_total_jobs = 0
    created_completed_jobs = 0
    created_failed_jobs = 0
    created_active_jobs = 0
    created_items_found_total = 0
    created_stage_counts: dict[str, dict[str, int]] = {}
    posts_shards = list(schedule.shards)
    if normalized_mode != "comments_only" and not posts_shards:
        fallback_start = _coerce_dt(opts.date_start)
        fallback_end = _coerce_dt(opts.date_end)
        if fallback_start and fallback_end and fallback_end < fallback_start:
            fallback_end = fallback_start
        if fallback_start is None:
            fallback_start = _now_utc()
        if fallback_end is None or fallback_end < fallback_start:
            fallback_end = fallback_start
        posts_shards = [
            IngestTimeShard(
                shard_index=0,
                window_start=fallback_start,
                window_end=fallback_end,
                runner_lane="A",
                priority_score=0.0,
                day_offset=0,
                day_weight=1.0,
            )
        ]
    shard_priority_by_index: dict[int, int] = {}
    for rank, shard in enumerate(
        sorted(posts_shards, key=lambda candidate: (candidate.priority_score, candidate.shard_index))
    ):
        shard_priority_by_index[shard.shard_index] = 100 + rank
    runner_b_available_at: datetime | None = None
    if schedule.run_start is not None and schedule.runner_b_offset_hours > 0 and schedule.runner_count > 1:
        runner_b_available_at = schedule.run_start + timedelta(hours=schedule.runner_b_offset_hours)

    comment_lane_index = 0
    with nullcontext(None) as enqueue_conn:
        for target in effective_targets:
            platform = str(target.get("platform") or "")
            target_posts_shards = _build_platform_posts_shards(
                platform=platform,
                schedule=schedule,
                date_start=opts.date_start,
                date_end=opts.date_end,
            )
            if normalized_mode != "comments_only" and not target_posts_shards:
                target_posts_shards = list(posts_shards)
            target_shard_priority_by_index: dict[int, int] = {}
            for rank, shard in enumerate(
                sorted(target_posts_shards, key=lambda candidate: (candidate.priority_score, candidate.shard_index))
            ):
                target_shard_priority_by_index[shard.shard_index] = 100 + rank
            ordered_target_posts_shards = sorted(
                target_posts_shards,
                key=lambda candidate: (candidate.priority_score, candidate.shard_index),
            )
            accounts = [str(item).strip() for item in (target.get("accounts") or []) if str(item).strip()]
            hashtags = _normalize_unique_terms(
                [str(item).strip().lstrip("#") for item in (target.get("hashtags") or []) if str(item).strip()]
            )
            keywords = _normalize_unique_terms(
                [str(item).strip() for item in (target.get("keywords") or []) if str(item).strip()]
            )
            platform_source_ids = normalized_comment_anchor_source_ids.get(platform)
            platform_has_explicit_targets = platform in normalized_comment_anchor_source_ids
            platform_source_ids_list = sorted(platform_source_ids) if platform_source_ids is not None else None
            account_specs: list[dict[str, Any]] = []
            for account in accounts:
                base_config = {
                    "run_id": run_id,
                    "season_id": context.season_id,
                    "show_id": context.show_id,
                    "platform": platform,
                    "source_scope": source_scope,
                    "run_scope": run_config["run_scope"],
                    "window_label": run_config["window_label"],
                    "week_index": run_config["week_index"],
                    "window_timezone": run_config["window_timezone"],
                    "account": account,
                    "hashtags": hashtags,
                    "keywords": keywords,
                    "date_start": _iso(opts.date_start),
                    "date_end": _iso(opts.date_end),
                    "sync_strategy": opts.sync_strategy,
                    "max_posts_per_target": opts.max_posts_per_target,
                    "max_comments_per_post": opts.max_comments_per_post,
                    "max_replies_per_post": opts.max_replies_per_post,
                    "fetch_replies": opts.fetch_replies,
                    "ingest_mode": opts.ingest_mode,
                    "comment_refresh_policy": opts.comment_refresh_policy,
                    "sound_ids": list(opts.sound_ids or []),
                    "runner_strategy": schedule.strategy,
                    "runner_count": schedule.runner_count,
                    "window_shard_hours": schedule.window_shard_hours,
                    "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
                    "day_weight_profile": schedule.day_weight_profile,
                    "priority_mode": schedule.priority_mode,
                    "youtube_source_mode": opts.youtube_source_mode,
                    "youtube_force_reindex": opts.youtube_force_reindex,
                    "youtube_force_media_refresh": opts.youtube_force_media_refresh,
                    "youtube_force_comment_refresh": opts.youtube_force_comment_refresh,
                    "client_session_id": str(client_session_id or "").strip() or None,
                    "client_workflow_id": str(client_workflow_id or "").strip() or None,
                    **execution_metadata,
                }
                if orchestration_metadata:
                    base_config.update({str(key): value for key, value in orchestration_metadata.items()})
                if platform_has_explicit_targets:
                    base_config["comment_anchor_source_ids"] = platform_source_ids_list
                comment_job_specs: list[dict[str, Any]] = []
                if normalized_mode in {"posts_and_comments", "comments_only"} and opts.max_comments_per_post > 0:
                    if (
                        normalized_mode == "comments_only"
                        and opts.comment_refresh_policy == "missing_only"
                        and platform_has_explicit_targets
                        and not platform_source_ids_list
                    ):
                        skipped_comment_jobs += 1
                        continue

                    # --- Comment job splitting: divide posts across N parallel jobs ---
                    comment_split_count = _resolve_positive_int_env(
                        "SOCIAL_COMMENT_JOB_SPLIT_COUNT",
                        3,
                        minimum=1,
                    )
                    comment_split_min_posts = comment_split_count * 2  # need at least 2 posts per bucket

                    # Only split if no explicit anchor targets and platform is supported
                    split_buckets: list[list[str]] | None = None
                    if (
                        not platform_has_explicit_targets
                        and comment_split_count > 1
                        and platform in {"instagram", "tiktok", "youtube", "twitter", "facebook", "threads"}
                    ):
                        source_id_col_map = {
                            "instagram": "shortcode",
                            "tiktok": "video_id",
                            "youtube": "video_id",
                            "twitter": "tweet_id",
                            "facebook": "post_id",
                            "threads": "post_id",
                        }
                        ts_col_map = {
                            "instagram": "posted_at",
                            "tiktok": "posted_at",
                            "youtube": "published_at",
                            "twitter": "created_at",
                            "facebook": "posted_at",
                            "threads": "posted_at",
                        }
                        table_map_split = {
                            "instagram": "instagram_posts",
                            "tiktok": "tiktok_posts",
                            "youtube": "youtube_videos",
                            "twitter": "twitter_tweets",
                            "facebook": "facebook_posts",
                            "threads": "meta_threads_posts",
                        }
                        sid_col = source_id_col_map[platform]
                        ts_col = ts_col_map[platform]
                        tbl = table_map_split[platform]
                        acct_expr = "ltrim(lower(coalesce(nullif(source_account, ''), nullif(username, ''), '')), '@')"
                        if platform == "youtube":
                            acct_expr = (
                                "ltrim(lower(coalesce(nullif(source_account, ''), nullif(channel_title, ''), '')), '@')"
                            )
                        norm_acct = _normalize_account_handle(account)
                        split_conditions = [
                            "season_id = %s",
                            f"{acct_expr} = %s",
                        ]
                        split_params: list[Any] = [context.season_id, norm_acct]
                        if opts.date_start:
                            split_conditions.append(f"{ts_col} >= %s")
                            split_params.append(opts.date_start)
                        if opts.date_end:
                            split_conditions.append(f"{ts_col} <= %s")
                            split_params.append(opts.date_end)
                        if platform == "twitter":
                            split_conditions.append("coalesce(is_reply, false) = false")
                            split_conditions.append("coalesce(is_quote, false) = false")
                        split_where = " AND ".join(split_conditions)
                        split_sql = (
                            f"SELECT {sid_col} AS source_id, coalesce(comments_count, 0) AS comments_count"
                            f" FROM social.{tbl}"
                            f" WHERE {split_where}"
                            f" ORDER BY coalesce(comments_count, 0) DESC, {sid_col} ASC"
                        )
                        try:
                            split_rows = pg.fetch_all(split_sql, split_params)
                        except Exception:
                            logger.debug(
                                "Comment split query failed for %s/%s, falling back to single job",
                                platform,
                                account,
                                exc_info=True,
                            )
                            split_rows = []

                        if len(split_rows) >= comment_split_min_posts:
                            split_buckets = [[] for _ in range(comment_split_count)]
                            for idx, row in enumerate(split_rows):
                                split_buckets[idx % comment_split_count].append(str(row.get("source_id") or ""))
                            # Remove any empty buckets
                            split_buckets = [b for b in split_buckets if b]

                    if split_buckets and len(split_buckets) > 1:
                        for bucket_idx, bucket_source_ids in enumerate(split_buckets):
                            comment_job_specs.append(
                                {
                                    "config": {
                                        **base_config,
                                        "stage": "comments",
                                        "comment_anchor_source_ids": sorted(bucket_source_ids),
                                        "comment_split_index": bucket_idx,
                                        "comment_split_total": len(split_buckets),
                                    }
                                }
                            )
                    else:
                        # Fallback: single comment job (not enough posts to split, or split disabled)
                        comment_job_specs.append({"config": {**base_config, "stage": "comments"}})
                account_specs.append(
                    {
                        "platform": platform,
                        "account": account,
                        "base_config": base_config,
                        "comment_job_specs": comment_job_specs,
                    }
                )
            if normalized_mode != "comments_only":
                for shard in ordered_target_posts_shards:
                    available_at = (
                        runner_b_available_at
                        if shard.runner_lane == "B" and runner_b_available_at is not None
                        else None
                    )
                    for account_spec in account_specs:
                        base_config = dict(account_spec.get("base_config") or {})
                        created_total_jobs += 1
                        job_ids.append(
                            _create_job(
                                context,
                                run_id=run_id,
                                platform=platform,
                                source_scope=source_scope,
                                job_type="posts",
                                stage="posts",
                                config={
                                    **base_config,
                                    "stage": "posts",
                                    "date_start": _iso(shard.window_start),
                                    "date_end": _iso(shard.window_end),
                                    "window_start": _iso(shard.window_start),
                                    "window_end": _iso(shard.window_end),
                                    "shard_index": shard.shard_index,
                                    "runner_lane": shard.runner_lane,
                                    "priority_score": shard.priority_score,
                                    "day_offset": shard.day_offset,
                                    "day_weight": shard.day_weight,
                                    "platform_window_shard_hours": max(
                                        1,
                                        int(max(1.0, (shard.window_end - shard.window_start).total_seconds() / 3600.0)),
                                    ),
                                },
                                initiated_by=initiated_by,
                                status=initial_job_status,
                                priority=target_shard_priority_by_index.get(shard.shard_index, 100),
                                worker_id=inline_worker_id,
                                preclaim=bool(inline_worker_id),
                                available_at=available_at,
                                conn=enqueue_conn,
                                track_run_counters=False,
                            )
                        )
                        if _status_is_active(initial_job_status):
                            created_active_jobs += 1
                            created_stage_counts = _increment_stage_counter(
                                created_stage_counts,
                                stage="posts",
                                key="active",
                                delta=1,
                            )
                        created_stage_counts = _increment_stage_counter(
                            created_stage_counts,
                            stage="posts",
                            key="total",
                            delta=1,
                        )
            max_comment_jobs = max(
                (len(list(account_spec.get("comment_job_specs") or [])) for account_spec in account_specs),
                default=0,
            )
            for bucket_index in range(max_comment_jobs):
                for account_index, account_spec in enumerate(account_specs):
                    comment_job_specs = list(account_spec.get("comment_job_specs") or [])
                    if bucket_index >= len(comment_job_specs):
                        continue
                    lane = "A"
                    if schedule.runner_count > 1:
                        lane = "B" if ((comment_lane_index + account_index) % 2 == 1) else "A"
                    available_at = runner_b_available_at if lane == "B" and runner_b_available_at is not None else None
                    comment_job_config = dict(comment_job_specs[bucket_index].get("config") or {})
                    comment_job_config["runner_lane"] = lane
                    job_ids.append(
                        _create_job(
                            context,
                            run_id=run_id,
                            platform=platform,
                            source_scope=source_scope,
                            job_type="comments",
                            stage="comments",
                            config=comment_job_config,
                            initiated_by=initiated_by,
                            status=initial_job_status,
                            priority=200,
                            worker_id=inline_worker_id,
                            preclaim=bool(inline_worker_id),
                            available_at=available_at,
                            conn=enqueue_conn,
                            track_run_counters=False,
                        )
                    )
                    comment_lane_index += 1
                    created_total_jobs += 1
                    if _status_is_active(initial_job_status):
                        created_active_jobs += 1
                    created_stage_counts = _increment_stage_counter(
                        created_stage_counts,
                        stage="comments",
                        key="total",
                        delta=1,
                    )
                    if _status_is_active(initial_job_status):
                        created_stage_counts = _increment_stage_counter(
                            created_stage_counts,
                            stage="comments",
                            key="active",
                            delta=1,
                        )

    if not job_ids:
        try:
            normalized_run_id = str(UUID(str(run_id)))
        except (ValueError, TypeError, AttributeError):
            normalized_run_id = None
        if normalized_run_id:
            try:
                pg.fetch_one(
                    "delete from social.scrape_runs where id = %s::uuid returning id::text", [normalized_run_id]
                )
            except Exception:
                logger.debug(
                    "Unable to cleanup empty ingest run %s due to database unavailability",
                    normalized_run_id,
                    exc_info=True,
                )
        raise SocialIngestValidationError(
            "NO_INGEST_TARGETS",
            "No ingest jobs were created for the requested targets and options",
        )

    if _run_counter_columns_ready():
        with pg.db_connection() as conn:
            summary = _persist_run_counters_and_summary(
                conn=conn,
                run_id=run_id,
                total_jobs=created_total_jobs,
                completed_jobs=created_completed_jobs,
                failed_jobs=created_failed_jobs,
                active_jobs=created_active_jobs,
                items_found_total=created_items_found_total,
                stage_counts=created_stage_counts,
            )
    else:
        summary = _update_run_summary(run_id)
    if skipped_comment_jobs:
        summary = dict(summary or {})
        summary["skipped_comment_jobs"] = skipped_comment_jobs
    if queue_enabled and is_modal_remote_executor_enabled():
        dispatch_due_social_jobs(run_id=run_id)
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "run_id": run_id,
        "status": "queued" if queue_enabled else "pending",
        "stages": stage_plan,
        "queued_or_started_jobs": len(job_ids),
        "summary": summary,
        "execution_owner": execution_metadata["execution_owner"],
        "execution_mode_canonical": execution_metadata["execution_mode_canonical"],
        "execution_backend_canonical": execution_metadata["execution_backend_canonical"],
        "ingest_mode": LEGACY_SEASON_TARGETED_INGEST_MODE,
    }


def ingest_shared_accounts(
    *,
    platforms: list[str] | None = None,
    source_scope: str = "bravo",
    accounts_override: list[str] | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    initiated_by: str | None = None,
    inline_worker_id: str | None = None,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    if source_scope not in SUPPORTED_SCOPES:
        raise ValueError(f"Unsupported source scope: {source_scope}")
    normalized_platforms = set(_resolve_requested_platforms(platforms)) if platforms else set(SUPPORTED_PLATFORMS)
    configured_sources = get_shared_account_sources(
        source_scope=source_scope,
        include_inactive=False,
        platforms=sorted(normalized_platforms),
    )
    sources = list(configured_sources.get("sources") or [])
    override_accounts = {
        _normalize_account_handle(item) for item in (accounts_override or []) if _normalize_account_handle(item)
    }
    if override_accounts:
        sources = [row for row in sources if _normalize_account_handle(row.get("account_handle")) in override_accounts]
    if not sources:
        raise SocialIngestValidationError(
            "NO_SHARED_ACCOUNT_SOURCES", "No active shared account sources are configured"
        )

    run_config = {
        "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
        "source_scope": source_scope,
        "platforms": sorted(normalized_platforms),
        "accounts_override": sorted(override_accounts),
        "date_start": _iso(date_start),
        "date_end": _iso(date_end),
        **_configured_execution_metadata(),
    }
    run_id = _create_run(
        None,
        source_scope=source_scope,
        initiated_by=initiated_by,
        config=run_config,
        status="queued",
    )
    initial_job_status = "queued" if is_queue_enabled() else "pending"
    job_ids: list[str] = []
    for row in sources:
        platform = _normalize_platform_name(row.get("platform"))
        account_handle = (
            _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
        )
        if not platform or not account_handle:
            continue
        job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "date_start": _iso(date_start),
                "date_end": _iso(date_end),
                "shared_account_source_id": row.get("id"),
                "pipeline_ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
            },
            initiated_by=initiated_by,
            status=initial_job_status,
            priority=max(1, int(row.get("scrape_priority") or 100)),
            worker_id=inline_worker_id,
            preclaim=bool(inline_worker_id),
            track_run_counters=False,
        )
        job_ids.append(job_id)
    if not job_ids:
        raise SocialIngestValidationError("NO_SHARED_ACCOUNT_SOURCES", "No shared account jobs were created")
    if _run_counter_columns_ready():
        with pg.db_connection() as conn:
            summary = _persist_run_counters_and_summary(
                conn=conn,
                run_id=run_id,
                total_jobs=len(job_ids),
                completed_jobs=0,
                failed_jobs=0,
                active_jobs=len(job_ids) if _status_is_active(initial_job_status) else 0,
                items_found_total=0,
                stage_counts={
                    SHARED_ACCOUNT_POSTS_STAGE: {
                        "total": len(job_ids),
                        "completed": 0,
                        "failed": 0,
                        "active": len(job_ids) if _status_is_active(initial_job_status) else 0,
                    }
                },
            )
    else:
        summary = _update_run_summary(run_id)
    if is_queue_enabled() and is_modal_remote_executor_enabled():
        dispatch_due_social_jobs(run_id=run_id)
    return {
        "run_id": run_id,
        "status": initial_job_status,
        "source_scope": source_scope,
        "ingest_mode": SHARED_ACCOUNT_ASYNC_INGEST_MODE,
        "shared_scrape_status": {"status": initial_job_status, "job_count": len(job_ids)},
        "classification_status": None,
        "materialization_status": None,
        "review_queue_count": list_shared_review_queue(source_scope=source_scope, review_status="open", limit=1).get(
            "count", 0
        ),
        "summary": summary,
        "execution_owner": run_config["execution_owner"],
        "execution_mode_canonical": run_config["execution_mode_canonical"],
        "execution_backend_canonical": run_config["execution_backend_canonical"],
    }


def list_shared_runs(
    *,
    limit: int = 50,
    status: str | None = None,
    source_scope: str | None = None,
    run_id: str | None = None,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 250))
    sql = """
        select
          id::text as id,
          season_id::text as season_id,
          show_id::text as show_id,
          source_scope,
          status,
          config,
          summary,
          initiated_by,
          created_at,
          started_at,
          completed_at,
          cancelled_at
        from social.scrape_runs
        where coalesce(config->>'pipeline_ingest_mode', '') = %s
    """
    params: list[Any] = [SHARED_ACCOUNT_ASYNC_INGEST_MODE]
    if status:
        sql += " and status = %s"
        params.append(status)
    if source_scope:
        sql += " and source_scope = %s"
        params.append(source_scope)
    if run_id:
        sql += " and id = %s::uuid"
        params.append(run_id)
    sql += " order by created_at desc limit %s"
    params.append(safe_limit)
    rows = pg.fetch_all(sql, params)
    for row in rows:
        config = dict(row.get("config") or {})
        row["execution_owner"] = str(config.get("execution_owner") or "").strip() or None
        row["execution_mode_canonical"] = str(config.get("execution_mode_canonical") or "").strip() or None
        row["execution_backend_canonical"] = str(config.get("execution_backend_canonical") or "").strip() or None
        row["ingest_mode"] = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE)
    return rows


def cancel_shared_run(run_id: str, *, cancelled_by: str | None = None) -> dict[str, Any]:
    run_row = pg.fetch_one(
        """
        select id::text as id
        from social.scrape_runs
        where id = %s::uuid
          and coalesce(config->>'pipeline_ingest_mode', '') = %s
        """,
        [run_id, SHARED_ACCOUNT_ASYNC_INGEST_MODE],
    )
    if not run_row:
        raise ValueError("Shared run not found")
    pg.fetch_one(
        """
        update social.scrape_runs
        set
          status = 'cancelled',
          cancelled_at = now(),
          completed_at = now(),
          summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object('cancelled_by', %s)
        where id = %s::uuid
        returning id::text
        """,
        [cancelled_by, run_id],
    )
    cancelled_jobs = pg.execute_returning(
        """
        update social.scrape_jobs
        set
          status = 'cancelled',
          completed_at = now(),
          error_message = coalesce(error_message, 'Cancelled by user request')
        where run_id = %s::uuid
          and status in ('queued', 'pending', 'retrying', 'running', 'cancelling')
        returning id::text as id
        """,
        [run_id],
    )
    for row in cancelled_jobs:
        job_id = str(row.get("id") or "").strip()
        if job_id:
            _clear_worker_heartbeat_for_job(
                job_id=job_id,
                status="idle",
                metadata={"source": "cancel_shared_run", "job_status": "cancelled"},
            )
    summary = _update_run_summary(run_id, force_recompute=True)
    return {"run_id": run_id, "status": "cancelled", "summary": summary}


def list_canonical_week_windows(
    season_id: str,
    *,
    timezone: str = "America/New_York",
    source_scope: str = "bravo",
    now_utc: datetime | None = None,
) -> list[dict[str, Any]]:
    context = get_season_context(season_id)
    week_windows, _ = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now_utc or _now_utc(),
    )
    payload: list[dict[str, Any]] = []
    for window in week_windows:
        payload.append(
            {
                "week_index": int(window.week_index),
                "label": _week_window_label(window, timezone=timezone),
                "week_type": str(window.week_type),
                "episode_number": int(window.episode_number) if window.episode_number is not None else None,
                "start_local": window.start_local.isoformat(),
                "end_local": window.end_local.isoformat(),
                "date_start": _iso(window.start_local.astimezone(UTC)),
                "date_end": _iso(window.end_local.astimezone(UTC)),
            }
        )
    return payload


def orchestrate_season_ingest(
    season_id: str,
    *,
    platforms: list[str] | None,
    source_scope: str,
    timezone: str = "America/New_York",
    week_index: int | None = None,
    sync_strategy: str = "incremental",
    max_posts_per_target: int | None,
    max_comments_per_post: int | None,
    max_replies_per_post: int | None = 100,
    fetch_replies: bool,
    ingest_mode: str = "posts_and_comments",
    comment_refresh_policy: str = DEFAULT_COMMENT_REFRESH_POLICY,
    comment_anchor_source_ids: dict[str, list[str]] | None = None,
    sound_ids: list[str] | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    youtube_source_mode: str | None = None,
    youtube_force_reindex: bool = False,
    youtube_force_media_refresh: bool = False,
    youtube_force_comment_refresh: bool = False,
    accounts_override: list[str] | None = None,
    hashtags_override: list[str] | None = None,
    keywords_override: list[str] | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    resume_existing: bool = True,
    initiated_by: str | None = None,
) -> dict[str, Any]:
    normalized_platforms = _resolve_requested_platforms(platforms)
    if not normalized_platforms:
        normalized_platforms = sorted(SUPPORTED_PLATFORMS)

    canonical_windows = list_canonical_week_windows(
        season_id,
        timezone=timezone,
        source_scope=source_scope,
    )
    if week_index is not None:
        selected_windows = [
            window for window in canonical_windows if int(window.get("week_index") or -1) == int(week_index)
        ]
        if not selected_windows:
            raise ValueError(f"Week {week_index} is not available for this season")
    else:
        selected_windows = canonical_windows
    if not selected_windows:
        raise ValueError("No canonical season weeks are available for orchestration")

    orchestration_scope = (
        "single_week_single_platform"
        if len(selected_windows) == 1 and len(normalized_platforms) == 1
        else "single_week_all_platforms"
        if len(selected_windows) == 1
        else "full_season_single_platform"
        if len(normalized_platforms) == 1
        else "full_season_all_platforms"
    )

    normalized_workflow_id = str(client_workflow_id or "").strip()
    if not normalized_workflow_id:
        request_fingerprint = hashlib.sha1(
            json.dumps(
                {
                    "season_id": season_id,
                    "source_scope": source_scope,
                    "timezone": timezone,
                    "platforms": normalized_platforms,
                    "weeks": [int(window.get("week_index") or 0) for window in selected_windows],
                    "sync_strategy": sync_strategy,
                    "ingest_mode": ingest_mode,
                    "comment_refresh_policy": comment_refresh_policy,
                    "accounts_override": list(accounts_override or []),
                    "hashtags_override": list(hashtags_override or []),
                    "keywords_override": list(keywords_override or []),
                    "sound_ids": list(sound_ids or []),
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()[:16]
        normalized_workflow_id = f"social-orch-{request_fingerprint}"

    existing_runs_by_slot: dict[str, dict[str, Any]] = {}
    if resume_existing:
        for row in list_runs(season_id, limit=250, client_workflow_id=normalized_workflow_id):
            slot_key = str(row.get("orchestration_slot_key") or "").strip()
            if slot_key and slot_key not in existing_runs_by_slot:
                existing_runs_by_slot[slot_key] = row

    created_runs: list[dict[str, Any]] = []
    reused_runs: list[dict[str, Any]] = []
    requested_runs: list[dict[str, Any]] = []
    slot_position = 0
    total_slots = len(selected_windows) * len(normalized_platforms)

    for window in selected_windows:
        current_week_index = int(window.get("week_index") or 0)
        window_label = str(window.get("label") or f"Week {current_week_index}").strip()
        for platform in normalized_platforms:
            slot_position += 1
            slot_key = f"week:{current_week_index}|platform:{platform}"
            requested_runs.append(
                {
                    "slot_key": slot_key,
                    "week_index": current_week_index,
                    "week_label": window_label,
                    "platform": platform,
                }
            )
            existing_run = existing_runs_by_slot.get(slot_key)
            if existing_run and str(existing_run.get("status") or "").strip().lower() not in {"failed", "cancelled"}:
                reused_runs.append(existing_run)
                continue

            run_payload = ingest_season(
                season_id,
                platforms=[platform],
                accounts_override=accounts_override,
                hashtags_override=hashtags_override,
                keywords_override=keywords_override,
                source_scope=source_scope,
                sync_strategy=sync_strategy,
                max_posts_per_target=max_posts_per_target,
                max_comments_per_post=max_comments_per_post,
                max_replies_per_post=max_replies_per_post,
                fetch_replies=fetch_replies,
                ingest_mode=ingest_mode,
                date_start=_coerce_dt(window.get("date_start")),
                date_end=_coerce_dt(window.get("date_end")),
                comment_refresh_policy=comment_refresh_policy,
                comment_anchor_source_ids=comment_anchor_source_ids,
                sound_ids=sound_ids,
                runner_strategy=runner_strategy,
                runner_count=runner_count,
                window_shard_hours=window_shard_hours,
                runner_b_start_offset_hours=runner_b_start_offset_hours,
                day_weight_profile=day_weight_profile,
                priority_mode=priority_mode,
                youtube_source_mode=youtube_source_mode,
                youtube_force_reindex=youtube_force_reindex,
                youtube_force_media_refresh=youtube_force_media_refresh,
                youtube_force_comment_refresh=youtube_force_comment_refresh,
                week_index=current_week_index,
                window_timezone=timezone,
                run_scope_label=window_label,
                client_session_id=client_session_id,
                client_workflow_id=normalized_workflow_id,
                orchestration_metadata={
                    "orchestration_id": normalized_workflow_id,
                    "orchestration_scope": orchestration_scope,
                    "orchestration_slot_key": slot_key,
                    "orchestration_position": slot_position,
                    "orchestration_total_runs": total_slots,
                    "orchestration_week_index": current_week_index,
                    "orchestration_platform": platform,
                    "orchestration_week_label": window_label,
                },
                initiated_by=initiated_by,
                inline_worker_id=None,
            )
            created_runs.append(
                {
                    "run_id": str(run_payload.get("run_id") or "").strip() or None,
                    "status": str(run_payload.get("status") or "").strip() or None,
                    "execution_owner": str(run_payload.get("execution_owner") or "").strip() or None,
                    "execution_mode_canonical": (
                        str(run_payload.get("execution_mode_canonical") or "").strip() or None
                    ),
                    "slot_key": slot_key,
                    "week_index": current_week_index,
                    "week_label": window_label,
                    "platform": platform,
                }
            )

    return {
        "season_id": season_id,
        "orchestration_id": normalized_workflow_id,
        "scope": orchestration_scope,
        "resume_existing": bool(resume_existing),
        "weeks": selected_windows,
        "platforms": normalized_platforms,
        "requested_runs": requested_runs,
        "created_runs": created_runs,
        "reused_runs": reused_runs,
        "total_requested_runs": total_slots,
        "created_count": len(created_runs),
        "reused_count": len(reused_runs),
        **_configured_execution_metadata(),
    }


def preview_ingest_schedule(
    season_id: str,
    *,
    platforms: list[str] | None,
    source_scope: str,
    accounts_override: list[str] | None = None,
    ingest_mode: str = "posts_and_comments",
    max_comments_per_post: int | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    week_index: int | None = None,
    window_timezone: str | None = None,
    run_scope_label: str | None = None,
) -> dict[str, Any]:
    context = get_season_context(season_id)
    if source_scope not in SUPPORTED_SCOPES:
        raise ValueError(f"Unsupported source scope: {source_scope}")
    normalized_mode = (ingest_mode or "posts_and_comments").strip().lower()
    if normalized_mode not in SUPPORTED_INGEST_MODES:
        raise ValueError(f"Unsupported ingest mode: {ingest_mode}")
    requested_platforms = _resolve_requested_platforms(platforms)

    normalized_accounts_override: list[str] = []
    invalid_overrides: list[str] = []
    for raw_account in [str(item or "").strip() for item in (accounts_override or []) if str(item or "").strip()]:
        normalized = _normalize_account_handle(raw_account)
        if not normalized:
            invalid_overrides.append(raw_account)
            continue
        if normalized in normalized_accounts_override:
            continue
        normalized_accounts_override.append(normalized)
    if invalid_overrides:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle override(s): {', '.join(sorted(set(invalid_overrides)))}",
        )

    schedule = _build_ingest_shard_schedule(
        date_start=date_start,
        date_end=date_end,
        runner_strategy=runner_strategy,
        runner_count=runner_count,
        window_shard_hours=window_shard_hours,
        runner_b_start_offset_hours=runner_b_start_offset_hours,
        day_weight_profile=day_weight_profile,
        priority_mode=priority_mode,
    )
    projected_shards = list(schedule.shards)
    if normalized_mode != "comments_only" and not projected_shards:
        fallback_start = _coerce_dt(date_start) or _now_utc()
        fallback_end = _coerce_dt(date_end)
        if fallback_end is None or fallback_end < fallback_start:
            fallback_end = fallback_start
        projected_shards = [
            IngestTimeShard(
                shard_index=0,
                window_start=fallback_start,
                window_end=fallback_end,
                runner_lane="A",
                priority_score=0.0,
                day_offset=0,
                day_weight=1.0,
            )
        ]

    account_map = _target_accounts_by_platform(season_id, source_scope=source_scope, context=context)
    effective_accounts_by_platform: dict[str, list[str]] = {}
    for platform in requested_platforms:
        authoritative_override = _use_authoritative_account_override(
            context=context,
            source_scope=source_scope,
            platform=platform,
            normalized_accounts_override=normalized_accounts_override,
        )
        merged_accounts = _normalize_unique_terms(
            [
                *sorted(account_map.get(platform, set())),
                *normalized_accounts_override,
            ]
        )
        if not authoritative_override:
            if platform == "instagram":
                merged_accounts = _ensure_rhoslc_instagram_accounts(context, merged_accounts)
            elif platform == "twitter":
                merged_accounts = _ensure_rhoslc_twitter_accounts(context, merged_accounts)
            merged_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=merged_accounts,
            )
            if not merged_accounts:
                merged_accounts = _default_platform_accounts(platform)
        effective_accounts_by_platform[platform] = merged_accounts

    projected_posts_jobs = 0
    projected_comments_jobs = 0
    per_platform_counts: dict[str, dict[str, int]] = {}
    for platform in requested_platforms:
        account_count = len(effective_accounts_by_platform.get(platform) or [])
        posts_jobs = account_count * (len(projected_shards) if normalized_mode != "comments_only" else 0)
        comments_jobs = (
            account_count
            if normalized_mode in {"posts_and_comments", "comments_only"} and int(max_comments_per_post or 0) > 0
            else 0
        )
        projected_posts_jobs += posts_jobs
        projected_comments_jobs += comments_jobs
        per_platform_counts[platform] = {
            "accounts": account_count,
            "posts_jobs": posts_jobs,
            "comments_jobs": comments_jobs,
        }

    day_weights_payload = {f"D+{offset}": round(weight, 4) for offset, weight in sorted(schedule.day_weights.items())}
    dominant_day = max(schedule.day_weights.items(), key=lambda item: item[1])[0] if schedule.day_weights else 0
    lane_a = [shard for shard in projected_shards if shard.runner_lane == "A"]
    lane_b = [shard for shard in projected_shards if shard.runner_lane == "B"]
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "scope": {
            "type": _ingest_run_scope_type(
                week_index=week_index,
                date_start=_coerce_dt(date_start),
                date_end=_coerce_dt(date_end),
            ),
            "label": str(run_scope_label or "").strip() or None,
            "week_index": int(week_index) if week_index is not None else None,
            "timezone": str(window_timezone or "America/New_York").strip() or "America/New_York",
        },
        "ingest_mode": normalized_mode,
        "scheduler": {
            "strategy": schedule.strategy,
            "runner_count": schedule.runner_count,
            "window_shard_hours": schedule.window_shard_hours,
            "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
            "day_weight_profile": schedule.day_weight_profile,
            "priority_mode": schedule.priority_mode,
            "busiest_day": f"D+{dominant_day}",
            "day_weights": day_weights_payload,
        },
        "date_window": {
            "start": _iso(_coerce_dt(date_start)),
            "end": _iso(_coerce_dt(date_end)),
        },
        "projected_counts": {
            "posts_jobs": projected_posts_jobs,
            "comments_jobs": projected_comments_jobs,
            "total_jobs": projected_posts_jobs + projected_comments_jobs,
            "by_platform": per_platform_counts,
        },
        "lanes": {
            "A": [
                {
                    "shard_index": shard.shard_index,
                    "window_start": _iso(shard.window_start),
                    "window_end": _iso(shard.window_end),
                    "priority_score": shard.priority_score,
                    "day_offset": shard.day_offset,
                    "day_weight": shard.day_weight,
                }
                for shard in lane_a
            ],
            "B": [
                {
                    "shard_index": shard.shard_index,
                    "window_start": _iso(shard.window_start),
                    "window_end": _iso(shard.window_end),
                    "priority_score": shard.priority_score,
                    "day_offset": shard.day_offset,
                    "day_weight": shard.day_weight,
                }
                for shard in lane_b
            ],
        },
    }


def cancel_run(season_id: str, run_id: str, *, cancelled_by: str | None = None) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    run_row = pg.fetch_one(
        """
        select id::text, season_id::text, status
        from social.scrape_runs
        where id = %s and season_id = %s
        """,
        [run_id, season_id],
    )
    if not run_row:
        raise ValueError("Run not found")

    pg.fetch_one(
        """
        update social.scrape_runs
        set
          status = 'cancelled',
          cancelled_at = now(),
          completed_at = now(),
          summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object('cancelled_by', %s)
        where id = %s
        returning id::text
        """,
        [cancelled_by, run_id],
    )
    cancelled_jobs = pg.execute_returning(
        """
        update social.scrape_jobs
        set
          status = 'cancelled',
          completed_at = now(),
          error_message = coalesce(error_message, 'Cancelled by user request')
        where run_id = %s
          and status in ('queued', 'pending', 'retrying', 'running', 'cancelling')
        returning id::text, run_id::text as run_id
        """,
        [run_id],
    )
    cancelled_job_ids = [str(row.get("id") or "").strip() for row in cancelled_jobs if str(row.get("id") or "").strip()]
    for job_id in cancelled_job_ids:
        _clear_worker_heartbeat_for_job(
            job_id=job_id,
            status="idle",
            metadata={"source": "cancel_run", "job_status": "cancelled"},
        )
    summary = _update_run_summary(run_id, force_recompute=True)
    _invalidate_week_detail_cache_after_run_terminal_status()
    return {
        "run_id": run_id,
        "season_id": season_id,
        "status": "cancelled",
        "cancelled_jobs": len(cancelled_job_ids),
        "summary": summary,
    }


def requeue_media_mirror_jobs(
    season_id: str,
    *,
    platform: str,
    source_scope: str = "bravo",
    limit: int = 1000,
    failed_only: bool = False,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> dict[str, Any]:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    source_id_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    posted_at_column = PLATFORM_POSTED_AT_COLUMN.get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        raise ValueError(f"Unsupported platform: {platform}")

    context = get_season_context(season_id)
    safe_limit = max(1, min(int(limit), 5000))
    account_expr = (
        "coalesce(nullif(p.source_account, ''), nullif(p.channel_title, ''), '')"
        if normalized_platform == "youtube"
        else "coalesce(nullif(p.source_account, ''), nullif(p.username, ''), '')"
    )
    thumbnail_expr = (
        "coalesce(nullif(p.media_urls ->> 0, ''), '')"
        if normalized_platform == "twitter"
        else "coalesce(nullif(p.thumbnail_url, ''), '')"
    )
    media_urls_expr = "p.media_urls" if _platform_posts_has_column(normalized_platform, "media_urls") else "'[]'::jsonb"
    start_dt = _coerce_dt(date_start)
    end_dt = _coerce_dt(date_end)
    if start_dt and end_dt and end_dt < start_dt:
        end_dt = start_dt
    window_filter = ""
    params: list[Any] = [season_id]
    if start_dt:
        window_filter += f" and p.{posted_at_column} >= %s"
        params.append(start_dt)
    if end_dt:
        window_filter += f" and p.{posted_at_column} <= %s"
        params.append(end_dt)
    params.append(safe_limit)
    rows = pg.fetch_all(
        f"""
        select
          p.id::text as id,
          p.{source_id_column} as source_id,
          {account_expr} as account,
          p.{posted_at_column} as posted_at,
          {thumbnail_expr} as thumbnail_url,
          {media_urls_expr} as media_urls,
          coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', '') as hosted_thumbnail_url,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(p) ->> 'media_mirror_status', '') as media_mirror_status
        from social.{table} p
        where p.season_id = %s
          {window_filter}
        order by coalesce(p.{posted_at_column}, p.scraped_at) desc
        limit %s
        """,
        params,
    )

    try:
        week_windows, _ = _resolve_week_windows(
            context,
            timezone="America/New_York",
            source_scope=source_scope,
            now_utc=_now_utc(),
        )
    except Exception:  # noqa: BLE001
        week_windows = []

    scanned = 0
    queued = 0
    skipped = 0
    failed = 0
    with pg.db_connection() as conn:
        for row in rows:
            scanned += 1
            mirror_status = str(row.get("media_mirror_status") or "").strip().lower()
            if failed_only and mirror_status not in {"failed", "partial"}:
                skipped += 1
                continue
            if not _platform_post_needs_media_mirror(normalized_platform, row):
                skipped += 1
                continue
            week_index: int | None = None
            posted_at = _coerce_dt(row.get("posted_at"))
            if posted_at and week_windows:
                week_window = _week_for_timestamp(posted_at, windows=week_windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            try:
                job_id = _enqueue_platform_media_mirror_job(
                    context,
                    platform=normalized_platform,
                    run_id=None,
                    source_scope=source_scope,
                    account=str(row.get("account") or ""),
                    post_row=row,
                    week_index=week_index,
                    parent_job_id=f"manual-{normalized_platform}-mirror-requeue",
                    conn=conn,
                )
            except Exception:  # noqa: BLE001
                failed += 1
                logger.exception(
                    "[%s] Failed to enqueue mirror requeue job for post=%s source_id=%s",
                    normalized_platform,
                    str(row.get("id") or ""),
                    str(row.get("source_id") or ""),
                )
                continue
            if job_id:
                queued += 1
            else:
                skipped += 1

    return {
        "season_id": season_id,
        "platform": normalized_platform,
        "source_scope": source_scope,
        "failed_only": bool(failed_only),
        "window_applied": bool(start_dt or end_dt),
        "window": {
            "start": _iso(start_dt),
            "end": _iso(end_dt),
        },
        "eligible_in_window": len(rows),
        "scanned": scanned,
        "queued_jobs": queued,
        "skipped": skipped,
        "failed": failed,
    }


def requeue_instagram_media_mirror_jobs(
    season_id: str,
    *,
    source_scope: str = "bravo",
    limit: int = 1000,
    failed_only: bool = False,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> dict[str, Any]:
    return requeue_media_mirror_jobs(
        season_id,
        platform="instagram",
        source_scope=source_scope,
        limit=limit,
        failed_only=failed_only,
        date_start=date_start,
        date_end=date_end,
    )


def list_jobs(
    season_id: str,
    *,
    limit: int = 50,
    offset: int = 0,
    run_id: str | None = None,
    status: str | None = None,
    platform: str | None = None,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 250))
    safe_offset = max(0, min(int(offset), 5000))
    features = _scrape_jobs_features()
    has_run_id = bool(features.get("has_run_id"))
    has_queue_fields = bool(features.get("has_queue_fields"))

    select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
    select_attempt_count = "j.attempt_count" if has_queue_fields else "0::int as attempt_count"
    select_max_attempts = "j.max_attempts" if has_queue_fields else "0::int as max_attempts"
    select_priority = "j.priority" if has_queue_fields else "0::int as priority"
    select_available_at = "j.available_at" if has_queue_fields else "null::timestamptz as available_at"
    select_claimed_at = "j.claimed_at" if has_queue_fields else "null::timestamptz as claimed_at"
    select_heartbeat_at = "j.heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
    select_worker_id = "j.worker_id" if has_queue_fields else "null::text as worker_id"
    select_last_error_code = "j.last_error_code" if has_queue_fields else "null::text as last_error_code"
    select_last_error_class = "j.last_error_class" if has_queue_fields else "null::text as last_error_class"

    where_clauses = ["season_id = %s"]
    where_params: list[Any] = [season_id]
    if run_id and has_run_id:
        where_clauses.append("run_id = %s")
        where_params.append(run_id)
    if status:
        where_clauses.append("status = %s")
        where_params.append(status)
    if platform:
        where_clauses.append("platform = %s")
        where_params.append(platform)
    where_sql = " and ".join(where_clauses)

    select_sql = f"""
        select
          j.id::text,
          {select_run_id},
          j.platform,
          j.job_type,
          j.status,
          j.items_found,
          j.error_message,
          j.started_at,
          j.completed_at,
          j.created_at,
          j.config,
          j.metadata,
          j.source_scope,
          j.initiated_by,
          {select_attempt_count},
          {select_max_attempts},
          {select_priority},
          {select_available_at},
          {select_claimed_at},
          {select_heartbeat_at},
          {select_worker_id},
          {select_last_error_code},
          {select_last_error_class}
    """

    # Unscoped polling is the hottest path; preselect IDs to avoid scanning heavy JSON columns
    # before ORDER/LIMIT when no specific run_id is requested.
    use_unscoped_fast_path = not (run_id and has_run_id)
    if use_unscoped_fast_path:
        sql = f"""
            with candidate_jobs as (
              select id
              from social.scrape_jobs
              where {where_sql}
              order by created_at desc
              limit %s
              offset %s
            )
            {select_sql}
            from social.scrape_jobs j
            join candidate_jobs c on c.id = j.id
            order by j.created_at desc
        """
        params = [*where_params, safe_limit, safe_offset]
    else:
        sql = f"""
            {select_sql}
            from social.scrape_jobs j
            where {where_sql}
            order by j.created_at desc
            limit %s
            offset %s
        """
        params = [*where_params, safe_limit, safe_offset]

    rows = pg.fetch_all(sql, params)
    for row in rows:
        metadata = row.get("metadata")
        metadata_map = metadata if isinstance(metadata, dict) else {}
        metadata_error_code = metadata_map.get("job_error_code")
        normalized = _normalize_job_error_code(
            raw_error_code=str(row.get("last_error_code") or ""),
            error_message=str(row.get("error_message") or ""),
            error_class=str(row.get("last_error_class") or ""),
        )
        row["job_error_code"] = (
            str(metadata_error_code).strip().upper()
            if isinstance(metadata_error_code, str) and metadata_error_code.strip()
            else normalized
        )
    return rows


def list_runs(
    season_id: str,
    *,
    limit: int = 50,
    status: str | None = None,
    source_scope: str | None = None,
    run_id: str | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    platforms: list[str] | None = None,
    week_index: int | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 250))
    normalized_platforms = _resolve_requested_platforms(platforms) if platforms else None
    normalized_date_start = _coerce_dt(date_start)
    normalized_date_end = _coerce_dt(date_end)
    requires_config_filtering = any(
        [
            normalized_platforms is not None,
            week_index is not None,
            normalized_date_start is not None,
            normalized_date_end is not None,
        ]
    )
    sql = """
        select
          id::text,
          season_id::text as season_id,
          show_id::text as show_id,
          source_scope,
          status,
          config,
          summary,
          initiated_by,
          created_at,
          started_at,
          completed_at,
          cancelled_at
        from social.scrape_runs
        where season_id = %s
    """
    params: list[Any] = [season_id]
    if status:
        sql += " and status = %s"
        params.append(status)
    if source_scope:
        sql += " and source_scope = %s"
        params.append(source_scope)
    if run_id:
        sql += " and id = %s::uuid"
        params.append(run_id)
    if client_session_id:
        sql += " and coalesce(config->>'client_session_id', '') = %s"
        params.append(client_session_id)
    if client_workflow_id:
        sql += " and coalesce(config->>'client_workflow_id', '') = %s"
        params.append(client_workflow_id)
    sql += " order by created_at desc limit %s"
    params.append(250 if requires_config_filtering else safe_limit)
    rows = pg.fetch_all(sql, params)
    filtered_rows: list[dict[str, Any]] = []
    for row in rows:
        config = row.get("config") if isinstance(row.get("config"), dict) else {}
        if not _run_matches_scope_filters(
            config,
            platforms=normalized_platforms,
            week_index=week_index,
            date_start=normalized_date_start,
            date_end=normalized_date_end,
        ):
            continue
        summary = row.get("summary") if isinstance(row.get("summary"), dict) else {}
        total_jobs = int(summary.get("total_jobs") or 0)
        completed_jobs = int(summary.get("completed_jobs") or 0)
        failed_jobs = int(summary.get("failed_jobs") or 0)
        active_jobs = int(summary.get("active_jobs") or 0)
        if completed_jobs == 0 and total_jobs > 0:
            completed_jobs = max(0, total_jobs - failed_jobs - active_jobs)
        summary_normalized = dict(summary)
        if summary_normalized:
            summary_normalized["completed_jobs"] = completed_jobs
        row["summary_normalized"] = summary_normalized
        row["execution_owner"] = str(config.get("execution_owner") or "").strip() or None
        row["execution_mode_canonical"] = str(config.get("execution_mode_canonical") or "").strip() or None
        row["execution_backend_canonical"] = str(config.get("execution_backend_canonical") or "").strip() or None
        row["ingest_mode"] = (
            str(config.get("pipeline_ingest_mode") or LEGACY_SEASON_TARGETED_INGEST_MODE).strip()
            or LEGACY_SEASON_TARGETED_INGEST_MODE
        )
        row["orchestration_id"] = (
            str(config.get("orchestration_id") or config.get("client_workflow_id") or "").strip() or None
        )
        row["orchestration_scope"] = str(config.get("orchestration_scope") or "").strip() or None
        row["orchestration_slot_key"] = str(config.get("orchestration_slot_key") or "").strip() or None
        row["orchestration_position"] = _normalize_non_negative_int(config.get("orchestration_position"))
        row["orchestration_total_runs"] = _normalize_non_negative_int(config.get("orchestration_total_runs"))
        row["orchestration_week_index"] = (
            _normalize_non_negative_int(config.get("orchestration_week_index"))
            if config.get("orchestration_week_index") is not None
            else None
        )
        row["orchestration_platform"] = str(config.get("orchestration_platform") or "").strip() or None
        filtered_rows.append(row)
        if len(filtered_rows) >= safe_limit:
            break
    return filtered_rows


def list_run_summaries(
    season_id: str,
    *,
    limit: int = 20,
    source_scope: str | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    platforms: list[str] | None = None,
    week_index: int | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> list[dict[str, Any]]:
    runs = list_runs(
        season_id,
        limit=limit,
        source_scope=source_scope,
        client_session_id=client_session_id,
        client_workflow_id=client_workflow_id,
        platforms=platforms,
        week_index=week_index,
        date_start=date_start,
        date_end=date_end,
    )
    if not runs:
        return []

    run_ids = [str(run.get("id") or "") for run in runs if str(run.get("id") or "").strip()]
    if not run_ids:
        return []

    job_rows = pg.fetch_all(
        """
        select
          run_id::text as run_id,
          platform,
          status,
          error_message,
          last_error_code,
          last_error_class,
          metadata
        from social.scrape_jobs
        where season_id = %s
          and run_id = any(%s::uuid[])
        """,
        [season_id, run_ids],
    )

    by_run: dict[str, dict[str, Any]] = {}
    for row in job_rows:
        run_id = str(row.get("run_id") or "")
        if not run_id:
            continue
        bucket = by_run.setdefault(
            run_id,
            {
                "affected_platforms": set(),
                "error_counts": Counter(),
                "failed_jobs": 0,
                "active_jobs": 0,
                "total_jobs": 0,
            },
        )
        bucket["total_jobs"] += 1
        platform = str(row.get("platform") or "").strip().lower()
        if platform:
            bucket["affected_platforms"].add(platform)
        status = str(row.get("status") or "").strip().lower()
        if status == "failed":
            bucket["failed_jobs"] += 1
        if status in {"queued", "pending", "retrying", "running"}:
            bucket["active_jobs"] += 1
        if status in {"failed", "retrying"}:
            metadata = row.get("metadata")
            metadata_map = metadata if isinstance(metadata, dict) else {}
            metadata_error_code = metadata_map.get("job_error_code")
            normalized = (
                str(metadata_error_code).strip().upper()
                if isinstance(metadata_error_code, str) and metadata_error_code.strip()
                else _normalize_job_error_code(
                    raw_error_code=str(row.get("last_error_code") or ""),
                    error_message=str(row.get("error_message") or ""),
                    error_class=str(row.get("last_error_class") or ""),
                )
            )
            bucket["error_counts"][normalized] += 1

    now_utc = _now_utc()
    summaries: list[dict[str, Any]] = []
    for run in runs:
        run_id = str(run.get("id") or "")
        if not run_id:
            continue
        summary = run.get("summary") if isinstance(run.get("summary"), dict) else {}
        aggregate = by_run.get(run_id) or {}
        started_at = run.get("started_at")
        completed_at = run.get("completed_at")
        duration_seconds: int | None = None
        if isinstance(started_at, datetime):
            end_ref = completed_at if isinstance(completed_at, datetime) else now_utc
            duration_seconds = max(0, int((end_ref - started_at).total_seconds()))

        total_jobs = int(summary.get("total_jobs") or aggregate.get("total_jobs") or 0)
        completed_jobs = int(summary.get("completed_jobs") or 0)
        failed_jobs = int(summary.get("failed_jobs") or aggregate.get("failed_jobs") or 0)
        active_jobs = int(summary.get("active_jobs") or aggregate.get("active_jobs") or 0)
        if completed_jobs == 0 and total_jobs > 0:
            completed_jobs = max(0, total_jobs - failed_jobs - active_jobs)
        items_found_total = int(summary.get("items_found_total") or 0)
        stage_counts = summary.get("stage_counts") if isinstance(summary.get("stage_counts"), dict) else {}
        affected_platforms = sorted(aggregate.get("affected_platforms") or set())
        error_counts = dict(sorted((aggregate.get("error_counts") or Counter()).items()))
        success_rate_pct = _safe_percent(completed_jobs, max(1, total_jobs))

        summaries.append(
            {
                "run_id": run_id,
                "status": run.get("status"),
                "source_scope": run.get("source_scope"),
                "execution_owner": run.get("execution_owner"),
                "execution_mode_canonical": run.get("execution_mode_canonical"),
                "execution_backend_canonical": run.get("execution_backend_canonical"),
                "ingest_mode": run.get("ingest_mode"),
                "orchestration_id": run.get("orchestration_id"),
                "orchestration_scope": run.get("orchestration_scope"),
                "orchestration_slot_key": run.get("orchestration_slot_key"),
                "orchestration_position": run.get("orchestration_position"),
                "orchestration_total_runs": run.get("orchestration_total_runs"),
                "orchestration_week_index": run.get("orchestration_week_index"),
                "orchestration_platform": run.get("orchestration_platform"),
                "created_at": _iso(run.get("created_at")),
                "started_at": _iso(started_at),
                "completed_at": _iso(completed_at),
                "duration_seconds": duration_seconds,
                "total_jobs": total_jobs,
                "completed_jobs": completed_jobs,
                "failed_jobs": failed_jobs,
                "active_jobs": active_jobs,
                "items_found_total": items_found_total,
                "stage_counts": stage_counts,
                "affected_platforms": affected_platforms,
                "error_counts": error_counts,
                "success_rate_pct": success_rate_pct,
            }
        )
    return summaries


_RUN_PROGRESS_ACTIVE_JOB_STATUSES = {"queued", "pending", "retrying", "running", "cancelling"}
_RUN_PROGRESS_STAGE_BUCKETS = (
    "posts",
    "comments",
    "media_mirror",
    "comment_media_mirror",
    SHARED_ACCOUNT_POSTS_STAGE,
    POST_CLASSIFY_STAGE,
    SEASON_MATERIALIZE_STAGE,
    ANALYTICS_REFRESH_STAGE,
    "other",
)


def _normalize_run_progress_stage(stage: Any) -> str:
    normalized = _normalize_social_job_stage_for_stale(stage)
    return normalized or "other"


def _run_progress_stage_bucket(stage: str) -> str:
    return (
        stage
        if stage
        in {
            "posts",
            "comments",
            "media_mirror",
            "comment_media_mirror",
            SHARED_ACCOUNT_POSTS_STAGE,
            POST_CLASSIFY_STAGE,
            SEASON_MATERIALIZE_STAGE,
            ANALYTICS_REFRESH_STAGE,
        }
        else "other"
    )


def _run_progress_account_handle(config: dict[str, Any], metadata: dict[str, Any]) -> str:
    for candidate in (
        config.get("account"),
        config.get("account_handle"),
        config.get("username"),
        config.get("source_account"),
        metadata.get("account"),
        metadata.get("account_handle"),
        metadata.get("username"),
        metadata.get("source_account"),
    ):
        normalized = _normalize_account_handle(candidate)
        if normalized:
            return normalized
    return "unknown"


def _run_progress_stage_counters(metadata: dict[str, Any], items_found: Any) -> tuple[int, int]:
    stage_counters = _metadata_dict(metadata.get("stage_counters"))
    persist_counters = _metadata_dict(metadata.get("persist_counters"))
    stage_has_values = any(field in stage_counters for field in ("posts", "comments"))
    scraped_count = (
        _normalize_non_negative_int(stage_counters.get("posts"))
        + _normalize_non_negative_int(stage_counters.get("comments"))
        if stage_has_values
        else _normalize_non_negative_int(items_found)
    )
    saved_count = _normalize_non_negative_int(persist_counters.get("posts_upserted")) + _normalize_non_negative_int(
        persist_counters.get("comments_upserted")
    )
    return scraped_count, saved_count


def _format_run_progress_stage_label(stage: str) -> str:
    normalized = str(stage or "").strip().lower()
    if normalized == "posts":
        return "posts"
    if normalized == "comments":
        return "comments"
    if normalized == "media_mirror":
        return "media mirror"
    if normalized == "comment_media_mirror":
        return "comment media mirror"
    if normalized == SHARED_ACCOUNT_POSTS_STAGE:
        return "shared account scrape"
    if normalized == POST_CLASSIFY_STAGE:
        return "post classify"
    if normalized == SEASON_MATERIALIZE_STAGE:
        return "season materialize"
    if normalized == ANALYTICS_REFRESH_STAGE:
        return "analytics refresh"
    return normalized.replace("_", " ") if normalized else "stage"


def _normalize_run_config_platforms(config: Mapping[str, Any]) -> list[str] | None:
    raw = config.get("platforms")
    if raw is None:
        return None
    if isinstance(raw, str):
        normalized = _normalize_platform_name(raw)
        return [normalized] if normalized else None
    if not isinstance(raw, list):
        return None
    normalized: list[str] = []
    seen: set[str] = set()
    for item in raw:
        platform = _normalize_platform_name(item)
        if not platform or platform in seen:
            continue
        seen.add(platform)
        normalized.append(platform)
    return normalized or None


def _timestamps_match(left: datetime | None, right: datetime | None) -> bool:
    if left is None and right is None:
        return True
    if left is None or right is None:
        return False
    return left.astimezone(UTC) == right.astimezone(UTC)


def _run_matches_scope_filters(
    config: Mapping[str, Any],
    *,
    platforms: list[str] | None,
    week_index: int | None,
    date_start: datetime | None,
    date_end: datetime | None,
) -> bool:
    if platforms is not None:
        run_platforms = _normalize_run_config_platforms(config)
        if run_platforms is None or sorted(run_platforms) != sorted(platforms):
            return False
    if week_index is not None:
        run_week_index = _normalize_non_negative_int(
            config.get("week_index") if config.get("week_index") is not None else config.get("orchestration_week_index")
        )
        if run_week_index != week_index:
            return False
    if date_start is not None:
        run_date_start = _coerce_dt(config.get("date_start"))
        if not _timestamps_match(run_date_start, date_start):
            return False
    if date_end is not None:
        run_date_end = _coerce_dt(config.get("date_end"))
        if not _timestamps_match(run_date_end, date_end):
            return False
    return True


def _format_run_progress_activity_summary(metadata: dict[str, Any]) -> str:
    activity = _metadata_dict(metadata.get("activity"))
    if not activity:
        return ""
    parts: list[str] = []
    phase = str(activity.get("phase") or "").strip()
    if phase:
        parts.append(phase.replace("_", " "))
    if "pages_scanned" in activity:
        parts.append(f"{_normalize_non_negative_int(activity.get('pages_scanned'))}pg")
    if "posts_checked" in activity:
        parts.append(f"{_normalize_non_negative_int(activity.get('posts_checked'))}chk")
    if "matched_posts" in activity:
        parts.append(f"{_normalize_non_negative_int(activity.get('matched_posts'))}match")
    return " · ".join(part for part in parts if part)


def get_run_progress_snapshot(
    season_id: str,
    run_id: str,
    *,
    recent_log_limit: int = 20,
) -> dict[str, Any]:
    safe_recent_log_limit = max(1, min(int(recent_log_limit), 100))
    if not _relation_exists("social.scrape_runs") or not _relation_exists("social.scrape_jobs"):
        raise ValueError("social_ingest_queue_schema_missing")
    features = _scrape_jobs_features()
    if not bool(features.get("has_run_id")):
        raise ValueError("run_progress_requires_scrape_jobs_run_id")

    run_row = pg.fetch_one(
        """
        select
          id::text as run_id,
          season_id::text as season_id,
          status,
          source_scope,
          config,
          summary,
          created_at,
          started_at,
          completed_at
        from social.scrape_runs
        where id = %s::uuid
          and season_id = %s::uuid
        limit 1
        """,
        [run_id, season_id],
    )
    if not run_row:
        raise ValueError("run_not_found")

    select_worker_id = "j.worker_id" if bool(features.get("has_queue_fields")) else "null::text as worker_id"
    job_rows = pg.fetch_all(
        f"""
        select
          j.id::text as id,
          j.platform,
          j.job_type,
          j.status,
          j.items_found,
          j.error_message,
          j.created_at,
          j.started_at,
          j.completed_at,
          j.config,
          j.metadata,
          {select_worker_id}
        from social.scrape_jobs j
        where j.season_id = %s::uuid
          and j.run_id = %s::uuid
        order by coalesce(j.completed_at, j.started_at, j.created_at) desc, j.created_at desc
        """,
        [season_id, run_id],
    )

    computed_total_jobs = len(job_rows)
    computed_completed_jobs = 0
    computed_failed_jobs = 0
    computed_active_jobs = 0
    computed_items_found_total = 0
    for row in job_rows:
        status = str(row.get("status") or "").strip().lower()
        if status == "completed":
            computed_completed_jobs += 1
        elif status == "failed":
            computed_failed_jobs += 1
        elif status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES:
            computed_active_jobs += 1
        computed_items_found_total += _normalize_non_negative_int(row.get("items_found"))

    stored_summary = _metadata_dict(run_row.get("summary"))
    summary_needs_refresh = (
        _normalize_non_negative_int(stored_summary.get("total_jobs")) != computed_total_jobs
        or _normalize_non_negative_int(stored_summary.get("completed_jobs")) != computed_completed_jobs
        or _normalize_non_negative_int(stored_summary.get("failed_jobs")) != computed_failed_jobs
        or _normalize_non_negative_int(stored_summary.get("active_jobs")) != computed_active_jobs
        or _normalize_non_negative_int(stored_summary.get("items_found_total")) != computed_items_found_total
    )
    run_status = str(run_row.get("status") or "").strip().lower()
    if summary_needs_refresh or (run_status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES and computed_active_jobs == 0):
        if run_status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES and computed_active_jobs == 0:
            _finalize_run_status(run_id, force_recompute=True)
        else:
            _update_run_summary(run_id, force_recompute=True)
        refreshed_run_row = pg.fetch_one(
            """
            select
              id::text as run_id,
              season_id::text as season_id,
              status,
              source_scope,
              config,
              summary,
              created_at,
              started_at,
              completed_at
            from social.scrape_runs
            where id = %s::uuid
              and season_id = %s::uuid
            limit 1
            """,
            [run_id, season_id],
        )
        if refreshed_run_row:
            run_row = refreshed_run_row

    stages_payload: dict[str, dict[str, int]] = {
        key: {
            "jobs_total": 0,
            "jobs_completed": 0,
            "jobs_failed": 0,
            "jobs_active": 0,
            "jobs_running": 0,
            "jobs_waiting": 0,
            "scraped_count": 0,
            "saved_count": 0,
        }
        for key in _RUN_PROGRESS_STAGE_BUCKETS
    }

    per_handle_buckets: dict[tuple[str, str, str], dict[str, Any]] = {}
    handle_stage_summary: dict[tuple[str, str], dict[str, dict[str, int]]] = {}
    active_worker_ids: set[str] = set()
    recent_entries: list[dict[str, Any]] = []

    for row in job_rows:
        config = _metadata_dict(row.get("config"))
        metadata = _metadata_dict(row.get("metadata"))
        platform = _normalize_platform_name(row.get("platform")) or "unknown"
        status = str(row.get("status") or "").strip().lower() or "unknown"
        stage = _normalize_run_progress_stage(config.get("stage") or metadata.get("stage") or row.get("job_type"))
        stage_bucket = _run_progress_stage_bucket(stage)
        account_handle = _run_progress_account_handle(config, metadata)
        scraped_count, saved_count = _run_progress_stage_counters(metadata, row.get("items_found"))
        stage_payload = stages_payload[stage_bucket]
        stage_payload["jobs_total"] += 1
        if status == "completed":
            stage_payload["jobs_completed"] += 1
        elif status == "failed":
            stage_payload["jobs_failed"] += 1
        elif status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES:
            stage_payload["jobs_active"] += 1
            if status == "running":
                stage_payload["jobs_running"] += 1
            else:
                stage_payload["jobs_waiting"] += 1
        stage_payload["scraped_count"] += scraped_count
        stage_payload["saved_count"] += saved_count

        key = (platform, account_handle, stage)
        handle_bucket = per_handle_buckets.get(key)
        if handle_bucket is None:
            handle_bucket = {
                "platform": platform,
                "account_handle": account_handle,
                "stage": stage,
                "jobs_total": 0,
                "jobs_completed": 0,
                "jobs_failed": 0,
                "jobs_active": 0,
                "jobs_running": 0,
                "jobs_waiting": 0,
                "scraped_count": 0,
                "saved_count": 0,
                "runner_lanes": set(),
                "has_started": False,
                "next_stage": None,
            }
            per_handle_buckets[key] = handle_bucket
        handle_bucket["jobs_total"] += 1
        if status == "completed":
            handle_bucket["jobs_completed"] += 1
        elif status == "failed":
            handle_bucket["jobs_failed"] += 1
        elif status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES:
            handle_bucket["jobs_active"] += 1
            if status == "running":
                handle_bucket["jobs_running"] += 1
            else:
                handle_bucket["jobs_waiting"] += 1
        handle_bucket["scraped_count"] += scraped_count
        handle_bucket["saved_count"] += saved_count
        runner_lane = str(config.get("runner_lane") or "").strip().upper()
        if runner_lane:
            cast("set[str]", handle_bucket["runner_lanes"]).add(runner_lane)
        if status not in {"queued", "pending"}:
            handle_bucket["has_started"] = True

        handle_key = (platform, account_handle)
        stage_summary = handle_stage_summary.setdefault(handle_key, {})
        if stage not in stage_summary:
            stage_summary[stage] = {
                "jobs_total": 0,
                "jobs_completed": 0,
                "jobs_active": 0,
                "jobs_waiting": 0,
            }
        stage_summary[stage]["jobs_total"] += 1
        if status == "completed":
            stage_summary[stage]["jobs_completed"] += 1
        elif status in _RUN_PROGRESS_ACTIVE_JOB_STATUSES:
            stage_summary[stage]["jobs_active"] += 1
            if status != "running":
                stage_summary[stage]["jobs_waiting"] += 1

        worker_id = str(row.get("worker_id") or "").strip()
        if status == "running" and worker_id:
            active_worker_ids.add(worker_id)

        timestamp = _coerce_dt(row.get("completed_at") or row.get("started_at") or row.get("created_at"))
        ts_for_sort = timestamp if isinstance(timestamp, datetime) else None
        ts_label = (
            ts_for_sort.astimezone(ZoneInfo("America/New_York")).strftime("%-I:%M %p")
            if ts_for_sort is not None
            else "--:--"
        )
        platform_label = platform.capitalize() if platform != "twitter" else "Twitter/X"
        stage_label = _format_run_progress_stage_label(stage)
        account_label = f" @{account_handle}" if account_handle and account_handle != "unknown" else ""
        parts = [f"{ts_label} · {platform_label}{account_label} {stage_label} {status}"]
        if scraped_count > 0:
            parts.append(f"scraped {scraped_count}")
        if saved_count > 0:
            parts.append(f"saved {saved_count}")
        activity_summary = _format_run_progress_activity_summary(metadata)
        if activity_summary:
            parts.append(activity_summary)
        if status == "failed":
            error_message = str(row.get("error_message") or "").strip()
            if error_message:
                parts.append(error_message[:180])
        non_zero_signal = (
            scraped_count > 0 or saved_count > 0 or _normalize_non_negative_int(row.get("items_found")) > 0
        )
        recent_entries.append(
            {
                "id": str(row.get("id") or ""),
                "timestamp": _iso(timestamp),
                "platform": platform,
                "account_handle": account_handle,
                "stage": stage,
                "status": status,
                "non_zero_signal": non_zero_signal,
                "line": " · ".join(part for part in parts if part),
                "sort_ts_epoch": int(ts_for_sort.timestamp()) if ts_for_sort is not None else 0,
            }
        )

    recent_entries.sort(
        key=lambda entry: (
            0 if bool(entry.get("non_zero_signal")) else 1,
            -int(entry.get("sort_ts_epoch") or 0),
        )
    )
    trimmed_recent = [
        {
            "id": entry.get("id"),
            "timestamp": entry.get("timestamp"),
            "platform": entry.get("platform"),
            "account_handle": entry.get("account_handle"),
            "stage": entry.get("stage"),
            "status": entry.get("status"),
            "line": entry.get("line"),
        }
        for entry in recent_entries[:safe_recent_log_limit]
    ]

    run_config = _metadata_dict(run_row.get("config"))
    runner_count = max(1, _normalize_non_negative_int(run_config.get("runner_count")) or 1)
    scheduler_lanes = ["A", "B"] if runner_count >= 2 else ["A"]
    stage_sort_order = {
        "posts": 0,
        "comments": 1,
        "media_mirror": 2,
        "comment_media_mirror": 3,
        "classify": 4,
        "materialize": 5,
        "analytics_refresh": 6,
        "other": 99,
    }
    next_stage_by_handle: dict[tuple[str, str], str | None] = {}
    for handle_key, stage_summary in handle_stage_summary.items():
        ordered_stages = sorted(
            stage_summary.items(),
            key=lambda item: (stage_sort_order.get(item[0], 50), item[0]),
        )
        next_stage: str | None = None
        for stage_name, counts in ordered_stages:
            if int(counts.get("jobs_active") or 0) > 0 or int(counts.get("jobs_waiting") or 0) > 0:
                next_stage = stage_name
                break
            if int(counts.get("jobs_completed") or 0) < int(counts.get("jobs_total") or 0):
                next_stage = stage_name
                break
        next_stage_by_handle[handle_key] = next_stage
    for key, handle_bucket in per_handle_buckets.items():
        handle_bucket["runner_lanes"] = sorted(cast("set[str]", handle_bucket.get("runner_lanes") or set()))
        handle_bucket["next_stage"] = next_stage_by_handle.get((key[0], key[1]))
    per_handle_payload = sorted(
        per_handle_buckets.values(),
        key=lambda item: (
            str(item.get("platform") or ""),
            str(item.get("account_handle") or ""),
            str(item.get("stage") or ""),
        ),
    )

    return {
        "season_id": str(run_row.get("season_id") or season_id),
        "run_id": str(run_row.get("run_id") or run_id),
        "run_status": str(run_row.get("status") or ""),
        "source_scope": str(run_row.get("source_scope") or ""),
        "created_at": _iso(_coerce_dt(run_row.get("created_at"))),
        "started_at": _iso(_coerce_dt(run_row.get("started_at"))),
        "completed_at": _iso(_coerce_dt(run_row.get("completed_at"))),
        "stages": stages_payload,
        "per_handle": per_handle_payload,
        "recent_log": trimmed_recent,
        "worker_runtime": {
            "runner_strategy": str(run_config.get("runner_strategy") or ""),
            "scheduler_lanes": scheduler_lanes,
            "active_workers_now": len(active_worker_ids),
            "worker_ids_sample": sorted(active_worker_ids)[:12],
        },
        "summary": _metadata_dict(run_row.get("summary")),
        "updated_at": _iso(_now_utc()),
    }


def _week_live_health_platform_specs() -> dict[str, dict[str, str]]:
    return {
        "instagram": {
            "table": "instagram_posts",
            "ts_col": "posted_at",
            "account_expr": "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')",
            "comments_expr": "coalesce(nullif(to_jsonb(p)->>'comments_count', '')::bigint, 0)",
        },
        "tiktok": {
            "table": "tiktok_posts",
            "ts_col": "posted_at",
            "account_expr": "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')",
            "comments_expr": "coalesce(nullif(to_jsonb(p)->>'comments_count', '')::bigint, 0)",
        },
        "youtube": {
            "table": "youtube_videos",
            "ts_col": "published_at",
            "account_expr": "coalesce(nullif(p.source_account, ''), nullif(p.channel_title, ''), '')",
            "comments_expr": "coalesce(nullif(to_jsonb(p)->>'comments_count', '')::bigint, 0)",
        },
        "twitter": {
            "table": "twitter_tweets",
            "ts_col": "created_at",
            "account_expr": "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')",
            "comments_expr": (
                "coalesce(nullif(to_jsonb(p)->>'replies_count', '')::bigint, 0) "
                "+ coalesce(nullif(to_jsonb(p)->>'quotes', '')::bigint, 0)"
            ),
        },
        "facebook": {
            "table": "facebook_posts",
            "ts_col": "posted_at",
            "account_expr": "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')",
            "comments_expr": "coalesce(nullif(to_jsonb(p)->>'comments_count', '')::bigint, 0)",
        },
        "threads": {
            "table": "meta_threads_posts",
            "ts_col": "posted_at",
            "account_expr": "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')",
            "comments_expr": (
                "coalesce(nullif(to_jsonb(p)->>'replies_count', '')::bigint, 0) "
                "+ coalesce(nullif(to_jsonb(p)->>'quotes', '')::bigint, 0)"
            ),
        },
    }


def _week_live_health_asset_type(url: str | None) -> str | None:
    normalized = str(url or "").strip()
    if not normalized:
        return None
    if _is_video_like_media_url(normalized) or _is_page_like_media_url(normalized):
        return "videos"
    return "images"


def _week_live_health_to_url_list(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    if isinstance(value, str):
        parsed = _as_text_list(value)
        return [str(item).strip() for item in parsed if str(item).strip()]
    return []


def get_week_live_health_snapshot(
    season_id: str,
    *,
    week_index: int,
    platforms: list[str] | None,
    timezone: str,
    source_scope: str,
) -> dict[str, Any]:
    context = get_season_context(season_id)
    selected_platforms = _resolve_requested_platforms(platforms)
    now_utc = _now_utc()
    week_windows, _ = _resolve_week_windows(context, timezone=timezone, source_scope=source_scope, now_utc=now_utc)
    window = next((candidate for candidate in week_windows if candidate.week_index == int(week_index)), None)
    if window is None:
        raise ValueError(f"Week {week_index} is not available for this season")

    start_utc = window.start_local.astimezone(UTC)
    end_utc = window.end_local.astimezone(UTC)
    platform_specs = _week_live_health_platform_specs()
    account_map = _target_accounts_by_platform(season_id, source_scope=source_scope, context=context)
    day_account_buckets: dict[tuple[str, str, str], dict[str, Any]] = {}
    asset_health: dict[str, dict[str, int]] = {
        "images": {"scraped": 0, "saved": 0},
        "videos": {"scraped": 0, "saved": 0},
        "captions": {"scraped": 0, "saved": 0},
        "profile_pictures": {"scraped": 0, "saved": 0},
    }
    requires_target_accounts = source_scope in {"bravo", "creator"}

    for platform in selected_platforms:
        spec = platform_specs.get(platform)
        if spec is None:
            continue
        table_name = spec["table"]
        ts_col = spec["ts_col"]
        account_expr = spec["account_expr"]
        comments_expr = spec["comments_expr"]
        platform_accounts = sorted(set(account_map.get(platform, set())))
        if requires_target_accounts and not platform_accounts:
            continue
        account_filter_sql = ""
        params: list[Any] = [timezone, season_id, start_utc, end_utc]
        if source_scope != "community" and platform_accounts:
            account_filter_sql = f" and ltrim(lower({account_expr}), '@') = any(%s)"
            params.append(platform_accounts)
        rows = pg.fetch_all(
            f"""
            select
              timezone(%s, p.{ts_col})::date as day_local,
              ltrim(lower({account_expr}), '@') as account_handle,
              {comments_expr} as comments_count,
              coalesce(nullif(to_jsonb(p)->>'likes', '')::bigint, 0) as likes_count,
              coalesce(to_jsonb(p)->'media_urls', '[]'::jsonb) as media_urls,
              nullif(to_jsonb(p)->>'thumbnail_url', '') as thumbnail_url,
              coalesce(to_jsonb(p)->'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              nullif(to_jsonb(p)->>'hosted_thumbnail_url', '') as hosted_thumbnail_url,
              nullif(to_jsonb(p)->>'caption', '') as caption,
              nullif(to_jsonb(p)->>'description', '') as description,
              nullif(to_jsonb(p)->>'text', '') as text,
              nullif(to_jsonb(p)->>'title', '') as title,
              nullif(to_jsonb(p)->>'owner_profile_pic_url', '') as owner_profile_pic_url,
              nullif(to_jsonb(p)->>'user_avatar_url', '') as user_avatar_url,
              nullif(to_jsonb(p)->>'avatar_url', '') as avatar_url,
              nullif(to_jsonb(p)->>'profile_pic_url', '') as profile_pic_url,
              nullif(to_jsonb(p)->>'hosted_owner_profile_pic_url', '') as hosted_owner_profile_pic_url,
              coalesce(to_jsonb(p)->'hosted_tagged_profile_pics', '{{}}'::jsonb) as hosted_tagged_profile_pics
            from social.{table_name} p
            where p.season_id = %s::uuid
              and p.{ts_col} >= %s
              and p.{ts_col} < %s
              {account_filter_sql}
            """,
            params,
        )

        for row in rows:
            day_local = str(row.get("day_local") or "")
            if not day_local:
                continue
            account_handle = _normalize_account_handle(row.get("account_handle")) or "unknown"
            bucket_key = (day_local, platform, account_handle)
            bucket = day_account_buckets.get(bucket_key)
            if bucket is None:
                bucket = {
                    "day": day_local,
                    "platform": platform,
                    "account": account_handle,
                    "posts": 0,
                    "comments": 0,
                    "likes": 0,
                }
                day_account_buckets[bucket_key] = bucket
            bucket["posts"] += 1
            bucket["comments"] += _normalize_non_negative_int(row.get("comments_count"))
            bucket["likes"] += _normalize_non_negative_int(row.get("likes_count"))

            source_urls = [
                *_week_live_health_to_url_list(row.get("media_urls")),
                str(row.get("thumbnail_url") or "").strip(),
            ]
            hosted_urls = [
                *_week_live_health_to_url_list(row.get("hosted_media_urls")),
                str(row.get("hosted_thumbnail_url") or "").strip(),
            ]
            for source_url in source_urls:
                asset_type = _week_live_health_asset_type(source_url)
                if asset_type:
                    asset_health[asset_type]["scraped"] += 1
            for hosted_url in hosted_urls:
                asset_type = _week_live_health_asset_type(hosted_url)
                if asset_type:
                    asset_health[asset_type]["saved"] += 1

            caption_present = any(
                str(row.get(field) or "").strip() for field in ("caption", "description", "text", "title")
            )
            if caption_present:
                asset_health["captions"]["scraped"] += 1
                asset_health["captions"]["saved"] += 1

            profile_scraped = any(
                str(row.get(field) or "").strip()
                for field in ("owner_profile_pic_url", "user_avatar_url", "avatar_url", "profile_pic_url")
            )
            if profile_scraped:
                asset_health["profile_pictures"]["scraped"] += 1
            hosted_profile_map = _as_json_object(row.get("hosted_tagged_profile_pics"))
            profile_saved = bool(str(row.get("hosted_owner_profile_pic_url") or "").strip()) or bool(hosted_profile_map)
            if profile_saved:
                asset_health["profile_pictures"]["saved"] += 1

    day_account_rows = sorted(
        day_account_buckets.values(),
        key=lambda item: (
            str(item.get("day") or ""),
            str(item.get("platform") or ""),
            str(item.get("account") or ""),
        ),
    )
    asset_health_rows = [
        {"asset": "images", **asset_health["images"]},
        {"asset": "videos", **asset_health["videos"]},
        {"asset": "captions", **asset_health["captions"]},
        {"asset": "profile_pictures", **asset_health["profile_pictures"]},
    ]
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "source_scope": source_scope,
        "week": {
            "week_index": int(window.week_index),
            "label": _week_window_label(window, timezone=timezone),
            "start": _iso(start_utc),
            "end": _iso(end_utc),
        },
        "timezone": timezone,
        "day_account_rows": day_account_rows,
        "asset_health": asset_health_rows,
        "updated_at": _iso(now_utc),
    }


# ---------------------------------------------------------------------------
# Analytics + exports
# ---------------------------------------------------------------------------


def _default_sentiment_context() -> SentimentAnalyzerContext:
    return SentimentAnalyzerContext(cast_terms=set(), cast_phrases=set(), episode_terms=set(), episode_summary="")


def _normalize_sentiment_text_key(text: str | None) -> str:
    raw = (text or "").strip().lower()
    if not raw:
        return ""
    return re.sub(r"\s+", " ", raw)


def _tokenize_handle_terms(value: str | None) -> set[str]:
    if not value:
        return set()
    return {token.lower() for token in re.split(r"[^A-Za-z0-9]+", value) if token and len(token) >= 3}


def _build_cast_entity_terms(names: list[str]) -> tuple[set[str], set[str]]:
    cast_terms: set[str] = set()
    cast_phrases: set[str] = set()
    for raw_name in names:
        cleaned = str(raw_name or "").strip()
        if not cleaned:
            continue
        lower_phrase = cleaned.lower()
        cast_phrases.add(lower_phrase)
        for token in TOKEN_RE.findall(cleaned):
            lower = token.lower()
            if len(lower) >= 3:
                cast_terms.add(lower)
    return cast_terms, cast_phrases


def _load_cast_names_for_show(show_id: str) -> list[str]:
    try:
        rows = pg.fetch_all(
            """
            select distinct p.full_name
            from core.credits c
            join core.people p on p.id = c.person_id
            where c.show_id = %s
              and lower(coalesce(c.credit_category, '')) = 'self'
              and nullif(trim(coalesce(p.full_name, '')), '') is not null
            order by p.full_name asc
            """,
            [show_id],
        )
        names = [str(row.get("full_name") or "").strip() for row in rows]
        names = [name for name in names if name]
        if names:
            return names
    except Exception:  # noqa: BLE001
        logger.warning("Failed to load cast names from core.credits for show %s", show_id, exc_info=True)

    try:
        fallback_rows = pg.fetch_all(
            """
            select distinct cast_member_name
            from core.v_show_cast
            where show_id = %s
              and nullif(trim(coalesce(cast_member_name, '')), '') is not null
            order by cast_member_name asc
            """,
            [show_id],
        )
        return [
            str(row.get("cast_member_name") or "").strip()
            for row in fallback_rows
            if str(row.get("cast_member_name") or "").strip()
        ]
    except Exception:  # noqa: BLE001
        logger.warning("Failed to load cast names from core.v_show_cast for show %s", show_id, exc_info=True)
        return []


def _load_episode_sentiment_context(season_id: str) -> EpisodeSentimentContext:
    try:
        rows = pg.fetch_all(
            """
            select episode_number, title, coalesce(nullif(overview, ''), nullif(synopsis, ''), '') as summary
            from core.episodes
            where season_id = %s
            order by episode_number asc
            """,
            [season_id],
        )
    except Exception:  # noqa: BLE001
        logger.warning("Failed to load episode sentiment context for season %s", season_id, exc_info=True)
        return EpisodeSentimentContext(summary="", terms=set())

    terms: set[str] = set()
    snippets: list[str] = []
    for row in rows:
        title = str(row.get("title") or "").strip()
        summary = str(row.get("summary") or "").strip()
        episode_number = row.get("episode_number")
        for token in TOKEN_RE.findall(f"{title} {summary}"):
            lower = token.lower()
            if len(lower) >= 4 and lower not in STOPWORDS:
                terms.add(lower)
        if title or summary:
            short_summary = re.sub(r"\s+", " ", summary)
            if len(short_summary) > 90:
                short_summary = f"{short_summary[:87].rstrip()}..."
            episode_label = f"E{episode_number}" if isinstance(episode_number, int) else "Episode"
            if short_summary:
                snippets.append(f"{episode_label}: {title or 'Untitled'} — {short_summary}")
            else:
                snippets.append(f"{episode_label}: {title or 'Untitled'}")

    return EpisodeSentimentContext(summary="; ".join(snippets[:10]), terms=terms)


def _build_sentiment_context(context: SeasonContext) -> SentimentAnalyzerContext:
    cast_names = _load_cast_names_for_show(context.show_id)
    cast_terms, cast_phrases = _build_cast_entity_terms(cast_names)
    episode_context = _load_episode_sentiment_context(context.season_id)
    return SentimentAnalyzerContext(
        cast_terms=cast_terms,
        cast_phrases=cast_phrases,
        episode_terms=episode_context.terms,
        episode_summary=episode_context.summary,
    )


def _has_negation(tokens: list[str], index: int) -> bool:
    start = max(0, index - 3)
    return any(token in NEGATION_WORDS for token in tokens[start:index])


def _modifier_weight(tokens: list[str], index: int) -> float:
    if index <= 0:
        return 1.0
    weight = 1.0
    prev = tokens[index - 1]
    weight *= INTENSIFIER_WEIGHTS.get(prev, 1.0)
    weight *= DIMINISHER_WEIGHTS.get(prev, 1.0)
    if index >= 2 and tokens[index - 1] == "of":
        weight *= DIMINISHER_WEIGHTS.get(tokens[index - 2], 1.0)
    return weight


def _score_with_contrast(tokens: list[str], contributions: list[float]) -> float:
    total = sum(contributions)
    markers = [idx for idx, token in enumerate(tokens) if token in CONTRAST_MARKERS]
    if not markers:
        return total

    pivot = markers[-1]
    before = sum(contributions[:pivot])
    after = sum(contributions[pivot + 1 :])
    if before == 0 or after == 0:
        return total
    return (before * 0.6) + (after * 1.4)


def _rule_based_sentiment_for_text(
    text: str | None,
    *,
    analyzer_context: SentimentAnalyzerContext,
) -> SentimentRuleResult:
    raw_text = str(text or "").strip()
    if not raw_text:
        return SentimentRuleResult(label="neutral", score=0.0, confidence=1.0, ambiguous=False)

    lowered = raw_text.lower()
    tokens = [token.lower() for token in TOKEN_RE.findall(raw_text)]
    if not tokens:
        return SentimentRuleResult(label="neutral", score=0.0, confidence=0.95, ambiguous=False)

    mention_terms = {
        token.lower() for mention in MENTION_TOKEN_RE.findall(raw_text) for token in _tokenize_handle_terms(mention)
    }
    blocked_entity_terms = set(analyzer_context.cast_terms)
    blocked_entity_terms.update(mention_terms)

    contributions: list[float] = [0.0 for _ in tokens]
    sentiment_hits = 0
    for index, token in enumerate(tokens):
        if token in blocked_entity_terms:
            continue
        base = 0.0
        if token in POSITIVE_WORDS:
            base = 1.0
        elif token in NEGATIVE_WORDS:
            base = -1.0
        if base == 0.0:
            continue

        sentiment_hits += 1
        if _has_negation(tokens, index):
            base *= -1.0
        contributions[index] = base * _modifier_weight(tokens, index)

    if sentiment_hits == 0:
        has_context_only_signal = any(token in analyzer_context.cast_terms for token in tokens) or any(
            token in analyzer_context.episode_terms for token in tokens
        )
        confidence = 0.94 if has_context_only_signal else 0.85
        return SentimentRuleResult(label="neutral", score=0.0, confidence=confidence, ambiguous=False)

    score = _score_with_contrast(tokens, contributions)
    exclamation_count = lowered.count("!")
    if exclamation_count > 0:
        score *= min(1.35, 1.0 + (0.08 * exclamation_count))

    if score >= 0.55:
        label = "positive"
    elif score <= -0.55:
        label = "negative"
    else:
        label = "neutral"

    confidence = min(0.99, abs(score) / max(1.0, sentiment_hits * 0.9))
    if label == "neutral":
        confidence = min(confidence, 0.45)
    confidence = max(0.15, confidence)

    ambiguous = label == "neutral" or confidence < 0.5 or abs(score) < 0.9
    return SentimentRuleResult(label=label, score=score, confidence=confidence, ambiguous=ambiguous)


def _score_from_label(label: str) -> int:
    if label == "positive":
        return 1
    if label == "negative":
        return -1
    return 0


def _resolve_sentiment_gemini_model_selection() -> tuple[str, str, str | None]:
    custom = (os.getenv("SOCIAL_SENTIMENT_GEMINI_MODEL") or "").strip()
    if custom:
        return custom, "SOCIAL_SENTIMENT_GEMINI_MODEL", None

    pro = (os.getenv("GEMINI_MODEL_PRO") or "").strip()
    if pro:
        return pro, "GEMINI_MODEL_PRO", "SOCIAL_SENTIMENT_GEMINI_MODEL->GEMINI_MODEL_PRO"

    google_alias = (os.getenv("GOOGLE_GEMINI_MODEL") or "").strip()
    if google_alias:
        return (
            google_alias,
            "GOOGLE_GEMINI_MODEL",
            "SOCIAL_SENTIMENT_GEMINI_MODEL->GEMINI_MODEL_PRO->GOOGLE_GEMINI_MODEL",
        )

    canonical = (os.getenv("GEMINI_MODEL") or "").strip()
    if canonical:
        return (
            canonical,
            "GEMINI_MODEL",
            "SOCIAL_SENTIMENT_GEMINI_MODEL->GEMINI_MODEL_PRO->GOOGLE_GEMINI_MODEL->GEMINI_MODEL",
        )

    fast = (os.getenv("GEMINI_MODEL_FAST") or "").strip()
    if fast:
        return (
            fast,
            "GEMINI_MODEL_FAST",
            "SOCIAL_SENTIMENT_GEMINI_MODEL->GEMINI_MODEL_PRO->GOOGLE_GEMINI_MODEL->GEMINI_MODEL->GEMINI_MODEL_FAST",
        )

    return (
        DEFAULT_GEMINI_SENTIMENT_MODEL,
        "default",
        "SOCIAL_SENTIMENT_GEMINI_MODEL->GEMINI_MODEL_PRO->GOOGLE_GEMINI_MODEL->GEMINI_MODEL->GEMINI_MODEL_FAST->default",
    )


def _resolve_sentiment_gemini_model() -> str:
    model_name, _model_source, _fallback_path = _resolve_sentiment_gemini_model_selection()
    return model_name


def _resolve_sentiment_gemini_max_comments() -> int:
    raw = (os.getenv("SOCIAL_SENTIMENT_GEMINI_MAX_COMMENTS") or "").strip()
    if raw.isdigit():
        return max(1, min(int(raw), SENTIMENT_GEMINI_MAX_COMMENTS_CAP))
    return min(40, SENTIMENT_GEMINI_MAX_COMMENTS_CAP)


def _resolve_sentiment_gemini_batch_size() -> int:
    raw = (os.getenv("SOCIAL_SENTIMENT_GEMINI_BATCH_SIZE") or "").strip()
    if raw.isdigit():
        return max(1, min(int(raw), SENTIMENT_GEMINI_BATCH_SIZE_CAP))
    return min(10, SENTIMENT_GEMINI_BATCH_SIZE_CAP)


def _extract_gemini_text(response: Any) -> str:
    text = getattr(response, "text", None)
    if isinstance(text, str) and text.strip():
        return text
    candidates = getattr(response, "candidates", None) or []
    for candidate in candidates:
        content = getattr(candidate, "content", None)
        parts = getattr(content, "parts", None) or []
        for part in parts:
            candidate_text = getattr(part, "text", None)
            if isinstance(candidate_text, str) and candidate_text.strip():
                return candidate_text
    return ""


def _build_gemini_text_generator(*, api_key: str, model_name: str):
    try:
        from google import genai as google_genai  # type: ignore

        client = google_genai.Client(api_key=api_key)

        def _generate(prompt: str) -> Any:
            return client.models.generate_content(model=model_name, contents=prompt)

        return _generate, "google-genai"
    except Exception:  # noqa: BLE001
        return None, None


def _parse_gemini_sentiment_payload(raw: str) -> dict[int, tuple[str, float]]:
    if not raw:
        return {}
    candidate = raw.strip()
    candidate = re.sub(r"^```(?:json)?\s*", "", candidate, flags=re.IGNORECASE)
    candidate = re.sub(r"\s*```$", "", candidate)

    payload: Any
    try:
        payload = json.loads(candidate)
    except json.JSONDecodeError:
        match = re.search(r"(\[[\s\S]*\]|\{[\s\S]*\})", candidate)
        if not match:
            return {}
        try:
            payload = json.loads(match.group(1))
        except json.JSONDecodeError:
            return {}

    items: list[dict[str, Any]]
    if isinstance(payload, list):
        items = [item for item in payload if isinstance(item, dict)]
    elif isinstance(payload, dict):
        raw_items = payload.get("items")
        if isinstance(raw_items, list):
            items = [item for item in raw_items if isinstance(item, dict)]
        else:
            return {}
    else:
        return {}

    parsed: dict[int, tuple[str, float]] = {}
    for item in items:
        index_raw = item.get("index")
        sentiment_raw = str(item.get("sentiment") or "").strip().lower()
        confidence_raw = item.get("confidence")
        if sentiment_raw not in {"positive", "neutral", "negative"}:
            continue
        if not isinstance(index_raw, int):
            continue
        confidence = 0.5
        if isinstance(confidence_raw, (int, float)):
            confidence = max(0.0, min(float(confidence_raw), 1.0))
        parsed[index_raw] = (sentiment_raw, confidence)
    return parsed


def _classify_ambiguous_sentiments_with_gemini(
    entries: list[tuple[str, str]],
    *,
    context: SeasonContext,
    analyzer_context: SentimentAnalyzerContext,
) -> dict[str, tuple[str, float]]:
    if not entries:
        return {}
    if not _env_truthy("SOCIAL_SENTIMENT_GEMINI_ENABLED", default=False):
        return {}

    api_key = (os.getenv("GEMINI_API_KEY") or "").strip() or (os.getenv("GOOGLE_GEMINI_API_KEY") or "").strip()
    if not api_key:
        logger.info("Gemini sentiment disambiguation enabled but API key is missing; falling back to rules")
        return {}

    model_name, model_source, fallback_path = _resolve_sentiment_gemini_model_selection()
    batch_size = _resolve_sentiment_gemini_batch_size()
    max_comments = _resolve_sentiment_gemini_max_comments()
    limited_entries = entries[:max_comments]

    generate_content, sdk_name = _build_gemini_text_generator(api_key=api_key, model_name=model_name)
    if generate_content is None:
        logger.warning("Gemini sentiment disambiguation unavailable: no supported SDK import found")
        return {}

    logger.info(
        "Gemini sentiment route=pro model=%s sdk=%s source=%s fallback_path=%s",
        model_name,
        sdk_name,
        model_source,
        fallback_path or "none",
    )

    cast_preview = ", ".join(sorted(analyzer_context.cast_phrases)[:20]) or "None"
    episode_summary = analyzer_context.episode_summary or "Unavailable"
    overrides: dict[str, tuple[str, float]] = {}

    for offset in range(0, len(limited_entries), batch_size):
        batch = limited_entries[offset : offset + batch_size]
        batch_comments = [{"index": index, "text": text} for index, (_, text) in enumerate(batch)]
        prompt = (
            "Classify each social comment sentiment for a Bravo reality TV season.\n"
            f"Show: {context.show_name or context.show_id}\n"
            f"Season: {context.season_number}\n"
            f"Episode context: {episode_summary}\n"
            f"Cast/entity names (treat as entities, not inherently sentiment): {cast_preview}\n"
            "Rules: label each comment as positive, neutral, or negative based on intent/context.\n"
            "Return only valid JSON as an array of objects: "
            '[{"index":0,"sentiment":"positive|neutral|negative","confidence":0.0}].\n'
            f"Comments: {json.dumps(batch_comments, ensure_ascii=True)}"
        )

        try:
            response = generate_content(prompt)
            parsed = _parse_gemini_sentiment_payload(_extract_gemini_text(response))
        except Exception:  # noqa: BLE001
            logger.warning("Gemini sentiment request failed; falling back to rule-based sentiment", exc_info=True)
            continue

        for index, (sentiment, confidence) in parsed.items():
            if index < 0 or index >= len(batch):
                continue
            key = batch[index][0]
            overrides[key] = (sentiment, confidence)

    return overrides


def _apply_optional_gemini_sentiment(
    rows: list[dict[str, Any]],
    *,
    context: SeasonContext,
    analyzer_context: SentimentAnalyzerContext,
) -> None:
    if not rows or not _env_truthy("SOCIAL_SENTIMENT_GEMINI_ENABLED", default=False):
        return

    deduped: dict[str, str] = {}
    for row in rows:
        if row.get("kind") != "comment":
            continue
        if not bool(row.get("_sentiment_ambiguous")):
            continue
        text_key = str(row.get("_sentiment_key") or "")
        if not text_key or text_key in deduped:
            continue
        deduped[text_key] = str(row.get("text") or "")

    if not deduped:
        return

    entries = list(deduped.items())
    overrides = _classify_ambiguous_sentiments_with_gemini(entries, context=context, analyzer_context=analyzer_context)
    if not overrides:
        return

    for row in rows:
        if row.get("kind") != "comment":
            continue
        text_key = str(row.get("_sentiment_key") or "")
        override = overrides.get(text_key)
        if not override:
            continue
        sentiment, confidence = override
        row["sentiment"] = sentiment
        row["sentiment_score"] = _score_from_label(sentiment)
        row["_sentiment_confidence"] = confidence
        row["_sentiment_ambiguous"] = False


def sentiment_for_text(text: str | None) -> tuple[str, int]:
    result = _rule_based_sentiment_for_text(text, analyzer_context=_default_sentiment_context())
    if result.label == "neutral":
        return "neutral", 0
    rounded = int(round(result.score))
    if rounded == 0:
        rounded = _score_from_label(result.label)
    return result.label, rounded


def _text_is_trailer_marker(value: str | None) -> bool:
    if not value:
        return False
    return bool(TRAILER_MARKER_RE.search(value))


def _video_matches_season(video: dict[str, Any], season_number: int) -> bool:
    raw = video.get("season_number")
    if isinstance(raw, int):
        return raw == season_number
    if isinstance(raw, str):
        stripped = raw.strip()
        if stripped.isdigit():
            return int(stripped) == season_number

    searchable = f"{video.get('title') or ''} {video.get('kicker') or ''}".lower()
    return f"season {season_number}" in searchable or f"s{season_number}" in searchable


def _load_bravo_snapshot_videos(show_id: str, season_number: int) -> list[dict[str, Any]]:
    row = pg.fetch_one(
        """
        select payload
        from core.show_source_latest
        where show_id = %s
          and source_id = 'bravo'
          and variant = 'default'
        limit 1
        """,
        [show_id],
    )
    if not row:
        return []

    payload = row.get("payload")
    if not isinstance(payload, dict):
        return []

    normalized = payload.get("normalized")
    if not isinstance(normalized, dict):
        return []

    videos_raw = normalized.get("videos_show")
    if not isinstance(videos_raw, list):
        return []

    videos: list[dict[str, Any]] = []
    for item in videos_raw:
        if not isinstance(item, dict):
            continue
        if not _video_matches_season(item, season_number):
            continue
        videos.append(item)
    return videos


def _find_week_zero_start_from_snapshot(
    *,
    context: SeasonContext,
    premiere_local: datetime,
    timezone: str,
) -> datetime | None:
    zone = ZoneInfo(timezone)
    candidates: list[tuple[datetime, bool]] = []

    for video in _load_bravo_snapshot_videos(context.show_id, context.season_number):
        published_at = _coerce_dt(video.get("published_at"))
        if not published_at:
            continue
        published_local = published_at.astimezone(zone)
        if published_local >= premiere_local:
            continue
        marker_hit = _text_is_trailer_marker(f"{video.get('title') or ''} {video.get('kicker') or ''}")
        candidates.append((published_local, marker_hit))

    if not candidates:
        return None

    marker_only = [value for value, marker in candidates if marker]
    if marker_only:
        return min(marker_only)
    return min(value for value, _ in candidates)


def _find_week_zero_start_from_social_rows(
    *,
    season_id: str,
    season_number: int,
    premiere_utc: datetime,
    timezone: str,
) -> datetime | None:
    lookback_utc = premiere_utc - timedelta(days=180)
    rows = pg.fetch_all(
        """
        with source_rows as (
          select posted_at as ts, caption as text from social.instagram_posts where season_id = %s
          union all
          select posted_at as ts, description as text from social.tiktok_posts where season_id = %s
          union all
          select created_at as ts, text as text from social.twitter_tweets where season_id = %s
          union all
          select published_at as ts, coalesce(title, '') || ' ' || coalesce(description, '') as text
          from social.youtube_videos
          where season_id = %s
        )
        select ts, text
        from source_rows
        where ts is not null
          and ts >= %s
          and ts < %s
        order by ts asc
        """,
        [season_id, season_id, season_id, season_id, lookback_utc, premiere_utc],
    )
    if not rows:
        return None

    zone = ZoneInfo(timezone)
    trailer_like_season_specific: list[datetime] = []
    trailer_like_generic: list[datetime] = []
    season_marker_variants = (
        f"season {season_number}",
        f"s{season_number}",
    )
    for row in rows:
        ts = _coerce_dt(row.get("ts"))
        if ts is None:
            continue
        text = str(row.get("text") or "")
        if not _text_is_trailer_marker(text):
            continue
        text_lower = text.lower()
        ts_local = ts.astimezone(zone)
        if any(marker in text_lower for marker in season_marker_variants):
            trailer_like_season_specific.append(ts_local)
        else:
            trailer_like_generic.append(ts_local)

    if trailer_like_season_specific:
        return min(trailer_like_season_specific)
    if trailer_like_generic:
        return min(trailer_like_generic)
    return _coerce_dt(rows[0].get("ts")).astimezone(zone) if rows[0].get("ts") else None


def _parse_local_override_datetime(value: Any, timezone: str) -> datetime | None:
    zone = ZoneInfo(timezone)
    if value is None:
        return None
    if isinstance(value, datetime):
        if value.tzinfo:
            return value.astimezone(zone)
        return value.replace(tzinfo=zone)
    if isinstance(value, date):
        return datetime.combine(value, time.min, tzinfo=zone)
    if isinstance(value, str):
        raw = value.strip()
        if not raw:
            return None
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
            parsed_date = datetime.fromisoformat(raw).date()
            return datetime.combine(parsed_date, time.min, tzinfo=zone)
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError:
            return None
        if parsed.tzinfo:
            return parsed.astimezone(zone)
        return parsed.replace(tzinfo=zone)
    return None


def _find_week_zero_start_override(
    *,
    season_id: str,
    source_scope: str,
    timezone: str,
    premiere_local: datetime,
) -> datetime | None:
    rows = pg.fetch_all(
        """
        select config
        from social.season_targets
        where season_id = %s
          and source_scope = %s
          and is_active = true
        """,
        [season_id, source_scope],
    )
    if not rows:
        return None

    candidates: list[datetime] = []
    for row in rows:
        config = row.get("config")
        if not isinstance(config, dict):
            continue
        for key in ("preseason_start", "preseason_start_at", "week_zero_start"):
            parsed = _parse_local_override_datetime(config.get(key), timezone)
            if parsed is None:
                continue
            if parsed >= premiere_local:
                continue
            candidates.append(parsed)
            break

    if not candidates:
        return None
    return min(candidates)


def _resolve_week_windows(
    context: SeasonContext,
    *,
    timezone: str,
    source_scope: str,
    now_utc: datetime,
) -> tuple[list[WeekWindow], datetime]:
    zone = ZoneInfo(timezone)
    now_local = now_utc.astimezone(zone)
    episode_rows = pg.fetch_all(
        """
        select episode_number, air_date
        from core.episodes
        where season_id = %s
          and air_date is not null
        order by episode_number asc, air_date asc
        """,
        [context.season_id],
    )

    episode_starts: list[tuple[int, datetime]] = []
    seen_numbers: set[int] = set()
    for row in episode_rows:
        raw_num = row.get("episode_number")
        air_date = row.get("air_date")
        if not isinstance(raw_num, int) or raw_num < 1 or not isinstance(air_date, date):
            continue
        if raw_num in seen_numbers:
            continue
        seen_numbers.add(raw_num)
        episode_starts.append((raw_num, datetime.combine(air_date, time(20, 0), tzinfo=zone)))

    if not episode_starts:
        anchor_local = datetime.combine(context.anchor_date, time.min, tzinfo=zone)
        return [WeekWindow(1, anchor_local, now_local, week_type="episode", episode_number=1)], anchor_local

    premiere_local = episode_starts[0][1]
    trailer_start_local = _find_week_zero_start_override(
        season_id=context.season_id,
        source_scope=source_scope,
        timezone=timezone,
        premiere_local=premiere_local,
    )
    if trailer_start_local is None:
        trailer_start_local = _find_week_zero_start_from_snapshot(
            context=context,
            premiere_local=premiere_local,
            timezone=timezone,
        )
    if trailer_start_local is None:
        trailer_start_local = _find_week_zero_start_from_social_rows(
            season_id=context.season_id,
            season_number=context.season_number,
            premiere_utc=premiere_local.astimezone(UTC),
            timezone=timezone,
        )
    if trailer_start_local is None:
        trailer_start_local = premiere_local - timedelta(days=7)
    if trailer_start_local >= premiere_local:
        trailer_start_local = premiere_local - timedelta(days=1)

    windows: list[WeekWindow] = [
        WeekWindow(0, trailer_start_local, premiere_local, week_type="preseason", episode_number=None)
    ]

    next_week_index = 1
    final_episode_end: datetime | None = None
    for idx, (episode_number, episode_start) in enumerate(episode_starts):
        next_episode_start = episode_starts[idx + 1][1] if idx + 1 < len(episode_starts) else None
        episode_end = episode_start + timedelta(days=7)
        if next_episode_start is not None and next_episode_start < episode_end:
            episode_end = next_episode_start
        if episode_end <= episode_start:
            continue
        windows.append(
            WeekWindow(
                next_week_index,
                episode_start,
                episode_end,
                week_type="episode",
                episode_number=episode_number,
            )
        )
        final_episode_end = episode_end
        next_week_index += 1

        if next_episode_start is None or next_episode_start <= episode_end:
            continue

        bye_start = episode_end
        while bye_start < next_episode_start:
            bye_end = min(bye_start + timedelta(days=7), next_episode_start)
            if bye_end <= bye_start:
                break
            windows.append(
                WeekWindow(
                    next_week_index,
                    bye_start,
                    bye_end,
                    week_type="bye",
                    episode_number=None,
                )
            )
            next_week_index += 1
            bye_start = bye_end

    if final_episode_end is not None:
        postseason_start = final_episode_end
        for _ in range(POSTSEASON_WEEK_COUNT):
            postseason_end = postseason_start + timedelta(days=7)
            windows.append(
                WeekWindow(
                    next_week_index,
                    postseason_start,
                    postseason_end,
                    week_type="postseason",
                    episode_number=None,
                )
            )
            next_week_index += 1
            postseason_start = postseason_end

    return windows, trailer_start_local


def _format_month_day_label(value: datetime, *, timezone: str) -> str:
    local_value = value.astimezone(ZoneInfo(timezone))
    return f"{local_value.strftime('%b')} {local_value.day}"


def _week_window_label(window: WeekWindow, *, timezone: str) -> str:
    if window.week_type == "preseason":
        return "Pre-Season"
    if window.week_type == "bye":
        start_label = _format_month_day_label(window.start_local, timezone=timezone)
        end_label = _format_month_day_label(
            window.end_local - timedelta(microseconds=1),
            timezone=timezone,
        )
        return f"BYE WEEK ({start_label}-{end_label})"
    return f"Week {window.week_index}"


def resolve_week_window(
    season_id: str,
    *,
    week_index: int,
    timezone: str = "America/New_York",
    source_scope: str = "bravo",
    now_utc: datetime | None = None,
) -> dict[str, Any]:
    """Resolve a canonical UTC window for a season week."""
    context = get_season_context(season_id)
    week_windows, _week_zero_start_local = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now_utc or _now_utc(),
    )
    window = next((candidate for candidate in week_windows if candidate.week_index == int(week_index)), None)
    if window is None:
        raise ValueError(f"Week {week_index} is not available for this season")

    week_end_inclusive = window.end_local - timedelta(microseconds=1)
    return {
        "week_index": int(window.week_index),
        "label": _week_window_label(window, timezone=timezone),
        "start": _iso(window.start_local.astimezone(UTC)),
        "end": _iso(week_end_inclusive.astimezone(UTC)),
        "week_type": window.week_type,
        "episode_number": window.episode_number,
        "timezone": timezone,
    }


def _week_for_timestamp(ts: datetime, *, windows: list[WeekWindow], timezone: str) -> WeekWindow | None:
    local_dt = ts.astimezone(ZoneInfo(timezone))
    for window in windows:
        if window.start_local <= local_dt < window.end_local:
            return window
    return None


def _rows_for_platform(
    season_id: str,
    *,
    platform: str,
    start_dt: datetime,
    end_dt: datetime,
    source_scope: str,
    target_accounts_by_platform: dict[str, set[str]] | None = None,
    season_context: SeasonContext | None = None,
    include_post_text: bool = True,
) -> list[dict[str, Any]]:
    account_map = (
        target_accounts_by_platform
        if target_accounts_by_platform is not None
        else _target_accounts_by_platform(season_id, source_scope=source_scope)
    )
    platform_accounts = set(account_map.get(platform, set()))
    requires_target_accounts = source_scope in {"bravo", "creator"}
    if requires_target_accounts and not platform_accounts:
        return []
    apply_account_filter = source_scope != "community" and bool(platform_accounts)
    platform_accounts_list = sorted(platform_accounts)
    instagram_post_text_expr = "p.caption" if include_post_text else "left(coalesce(p.caption, ''), 240)"
    tiktok_post_text_expr = "p.description" if include_post_text else "left(coalesce(p.description, ''), 240)"
    youtube_post_text_expr = "v.title" if include_post_text else "left(coalesce(v.title, ''), 240)"
    twitter_post_text_expr = "t.text" if include_post_text else "left(coalesce(t.text, ''), 240)"
    facebook_post_text_expr = "p.caption" if include_post_text else "left(coalesce(p.caption, ''), 240)"
    threads_post_text_expr = "p.text" if include_post_text else "left(coalesce(p.text, ''), 240)"
    threads_comment_active_filter = (
        "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("meta_threads_comments") else ""
    )

    if platform == "instagram":
        thumbnail_expr = _instagram_posts_thumbnail_expr("p")
        account_filter_posts = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        account_filter_comments = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params: list[Any] = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(platform_accounts_list)
        params.extend([season_id, start_dt, end_dt])
        if apply_account_filter:
            params.append(platform_accounts_list)
        return pg.fetch_all(
            f"""
            with posts as (
              select
                'instagram'::text as platform,
                'post'::text as kind,
                p.shortcode as source_id,
                {instagram_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(p.likes, 0) + coalesce(p.comments_count, 0) + coalesce(p.views, 0)
                )::bigint as engagement,
                p.posted_at as ts,
                ('https://www.instagram.com/p/' || p.shortcode || '/')::text as url,
                p.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.instagram_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter_posts}
            ), comments as (
              select
                'instagram'::text as platform,
                'comment'::text as kind,
                c.comment_id as source_id,
                c.text as text,
                greatest(0, coalesce(c.likes, 0))::bigint as engagement,
                c.created_at as ts,
                ('https://www.instagram.com/p/' || p.shortcode || '/')::text as url,
                c.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments
              from social.instagram_comments c
              join social.instagram_posts p on p.id = c.post_id
              where c.season_id = %s
                and c.created_at >= %s
                and c.created_at <= %s
                {account_filter_comments}
            )
            select * from posts
            union all
            select * from comments
            """,
            params,
        )

    if platform == "tiktok":
        thumbnail_expr = _platform_thumbnail_expr("p", "tiktok")
        account_filter_posts = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        account_filter_comments = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(platform_accounts_list)
        params.extend([season_id, start_dt, end_dt])
        if apply_account_filter:
            params.append(platform_accounts_list)
        return pg.fetch_all(
            f"""
            with posts as (
              select
                'tiktok'::text as platform,
                'post'::text as kind,
                p.video_id as source_id,
                {tiktok_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(p.likes, 0)
                  + coalesce(p.comments_count, 0)
                  + coalesce(p.shares, 0)
                  + coalesce(p.views, 0)
                )::bigint as engagement,
                p.posted_at as ts,
                ('https://www.tiktok.com/@' || p.username || '/video/' || p.video_id)::text as url,
                p.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.tiktok_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter_posts}
            ), comments as (
              select
                'tiktok'::text as platform,
                'comment'::text as kind,
                c.comment_id as source_id,
                c.text as text,
                greatest(0, coalesce(c.likes, 0))::bigint as engagement,
                c.created_at as ts,
                ('https://www.tiktok.com/@' || p.username || '/video/' || p.video_id)::text as url,
                c.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments
              from social.tiktok_comments c
              join social.tiktok_posts p on p.id = c.post_id
              where c.season_id = %s
                and c.created_at >= %s
                and c.created_at <= %s
                {account_filter_comments}
            )
            select * from posts
            union all
            select * from comments
            """,
            params,
        )

    if platform == "youtube":
        thumbnail_expr = _platform_thumbnail_expr("v", "youtube")
        youtube_is_short_expr = _youtube_is_short_expr("v")
        account_filter_videos = (
            "and ltrim(lower(coalesce(nullif(v.channel_title, ''), nullif(v.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        account_filter_comments = (
            "and ltrim(lower(coalesce(nullif(v.channel_title, ''), nullif(v.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(platform_accounts_list)
        params.extend([season_id, start_dt, end_dt])
        if apply_account_filter:
            params.append(platform_accounts_list)
        return pg.fetch_all(
            f"""
            with videos as (
              select
                'youtube'::text as platform,
                'post'::text as kind,
                v.video_id as source_id,
                {youtube_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(v.views, 0) + coalesce(v.likes, 0) + coalesce(v.comments_count, 0)
                )::bigint as engagement,
                v.published_at as ts,
                (
                  case
                    when {youtube_is_short_expr} then 'https://www.youtube.com/shorts/' || v.video_id
                    else 'https://www.youtube.com/watch?v=' || v.video_id
                  end
                )::text as url,
                v.channel_title as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(v.comments_count, 0))::bigint as reported_comments,
                {youtube_is_short_expr} as is_short
              from social.youtube_videos v
              where v.season_id = %s
                and v.published_at >= %s
                and v.published_at <= %s
                {account_filter_videos}
            ), comments as (
              select
                'youtube'::text as platform,
                'comment'::text as kind,
                c.comment_id as source_id,
                c.text as text,
                greatest(0, coalesce(c.likes, 0))::bigint as engagement,
                c.created_at as ts,
                ('https://www.youtube.com/watch?v=' || v.video_id)::text as url,
                c.author as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments,
                false as is_short
              from social.youtube_comments c
              join social.youtube_videos v on v.id = c.video_id
              where c.season_id = %s
                and c.created_at >= %s
                and c.created_at <= %s
                {account_filter_comments}
            )
            select * from videos
            union all
            select * from comments
            """,
            params,
        )

    if platform == "twitter":
        thumbnail_expr = _platform_thumbnail_expr("t", "twitter")
        if apply_account_filter:
            return pg.fetch_all(
                f"""
                with recursive in_scope_posts as (
                  select p.tweet_id
                  from social.twitter_tweets p
                  where p.season_id = %s
                    and p.is_reply = false
                    and p.created_at >= %s
                    and p.created_at <= %s
                    and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)
                ), legacy_thread_replies as (
                  select r.tweet_id
                  from social.twitter_tweets r
                  where r.season_id = %s
                    and r.is_reply = true
                    and (r.source_account is null or btrim(r.source_account) = '')
                    and r.reply_to_tweet_id in (select tweet_id from in_scope_posts)
                  union
                  select child.tweet_id
                  from social.twitter_tweets child
                  join legacy_thread_replies parent on child.reply_to_tweet_id = parent.tweet_id
                  where child.season_id = %s
                    and child.is_reply = true
                    and (child.source_account is null or btrim(child.source_account) = '')
                ), posts as (
                  select
                    'twitter'::text as platform,
                    'post'::text as kind,
                    t.tweet_id as source_id,
                    {twitter_post_text_expr} as text,
                    greatest(
                      0,
                      coalesce(t.likes, 0)
                      + coalesce(t.retweets, 0)
                      + coalesce(t.replies_count, 0)
                      + coalesce(t.quotes, 0)
                      + coalesce(t.views, 0)
                    )::bigint as engagement,
                    t.created_at as ts,
                    (
                      'https://x.com/'
                      || coalesce(nullif(t.username, ''), nullif(t.source_account, ''), 'i')
                      || '/status/'
                      || t.tweet_id
                    )::text as url,
                    coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                    {thumbnail_expr}::text as thumbnail_url,
                    greatest(0, coalesce(t.replies_count, 0) + coalesce(t.quotes, 0))::bigint as reported_comments
                  from social.twitter_tweets t
                  where t.season_id = %s
                    and t.created_at >= %s
                    and t.created_at <= %s
                    and t.is_reply = false
                    and ltrim(lower(coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '')), '@') = any(%s)
                ), comments as (
                  select
                    'twitter'::text as platform,
                    'comment'::text as kind,
                    t.tweet_id as source_id,
                    t.text as text,
                    greatest(
                      0,
                      coalesce(t.likes, 0)
                      + coalesce(t.retweets, 0)
                      + coalesce(t.replies_count, 0)
                      + coalesce(t.quotes, 0)
                      + coalesce(t.views, 0)
                    )::bigint as engagement,
                    t.created_at as ts,
                    (
                      'https://x.com/'
                      || coalesce(nullif(t.username, ''), nullif(t.source_account, ''), 'i')
                      || '/status/'
                      || t.tweet_id
                    )::text as url,
                    coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                    {thumbnail_expr}::text as thumbnail_url,
                    0::bigint as reported_comments
                  from social.twitter_tweets t
                  where t.season_id = %s
                    and t.created_at >= %s
                    and t.created_at <= %s
                    and t.is_reply = true
                    and (
                      ltrim(lower(coalesce(nullif(t.source_account, ''), nullif(t.username, ''), '')), '@') = any(%s)
                      or t.tweet_id in (select tweet_id from legacy_thread_replies)
                    )
                )
                select * from posts
                union all
                select * from comments
                """,
                [
                    season_id,
                    start_dt,
                    end_dt,
                    platform_accounts_list,
                    season_id,
                    season_id,
                    season_id,
                    start_dt,
                    end_dt,
                    platform_accounts_list,
                    season_id,
                    start_dt,
                    end_dt,
                    platform_accounts_list,
                ],
            )

        return pg.fetch_all(
            f"""
            with posts as (
              select
                'twitter'::text as platform,
                'post'::text as kind,
                t.tweet_id as source_id,
                {twitter_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(t.likes, 0)
                  + coalesce(t.retweets, 0)
                  + coalesce(t.replies_count, 0)
                  + coalesce(t.quotes, 0)
                  + coalesce(t.views, 0)
                )::bigint as engagement,
                t.created_at as ts,
                (
                  'https://x.com/'
                  || coalesce(nullif(t.username, ''), nullif(t.source_account, ''), 'i')
                  || '/status/'
                  || t.tweet_id
                )::text as url,
                coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(t.replies_count, 0) + coalesce(t.quotes, 0))::bigint as reported_comments
              from social.twitter_tweets t
              where t.season_id = %s
                and t.created_at >= %s
                and t.created_at <= %s
                and t.is_reply = false
            ), comments as (
              select
                'twitter'::text as platform,
                'comment'::text as kind,
                t.tweet_id as source_id,
                t.text as text,
                greatest(
                  0,
                  coalesce(t.likes, 0)
                  + coalesce(t.retweets, 0)
                  + coalesce(t.replies_count, 0)
                  + coalesce(t.quotes, 0)
                  + coalesce(t.views, 0)
                )::bigint as engagement,
                t.created_at as ts,
                (
                  'https://x.com/'
                  || coalesce(nullif(t.username, ''), nullif(t.source_account, ''), 'i')
                  || '/status/'
                  || t.tweet_id
                )::text as url,
                coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments
              from social.twitter_tweets t
              where t.season_id = %s
                and t.created_at >= %s
                and t.created_at <= %s
                and t.is_reply = true
            )
            select * from posts
            union all
            select * from comments
            """,
            [season_id, start_dt, end_dt, season_id, start_dt, end_dt],
        )

    if platform == "facebook":
        thumbnail_expr = _platform_thumbnail_expr("p", "facebook")
        account_filter_posts = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        account_filter_comments = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(platform_accounts_list)
        params.extend([season_id, start_dt, end_dt])
        if apply_account_filter:
            params.append(platform_accounts_list)
        return pg.fetch_all(
            f"""
            with posts as (
              select
                'facebook'::text as platform,
                'post'::text as kind,
                p.post_id as source_id,
                {facebook_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(p.likes, 0)
                  + coalesce(p.comments_count, 0)
                  + coalesce(p.shares, 0)
                  + coalesce(p.views, 0)
                )::bigint as engagement,
                p.posted_at as ts,
                (
                  case
                    when lower(coalesce(p.post_type, '')) = 'reel' then 'https://www.facebook.com/reel/' || p.post_id
                    else (
                      'https://www.facebook.com/'
                      || coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')
                      || '/posts/'
                      || p.post_id
                    )
                  end
                )::text as url,
                coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '') as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.facebook_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter_posts}
            ), comments as (
              select
                'facebook'::text as platform,
                'comment'::text as kind,
                c.comment_id as source_id,
                c.text as text,
                greatest(0, coalesce(c.likes, 0))::bigint as engagement,
                c.created_at as ts,
                (
                  case
                    when lower(coalesce(p.post_type, '')) = 'reel' then 'https://www.facebook.com/reel/' || p.post_id
                    else (
                      'https://www.facebook.com/'
                      || coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')
                      || '/posts/'
                      || p.post_id
                    )
                  end
                )::text as url,
                c.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments
              from social.facebook_comments c
              join social.facebook_posts p on p.id = c.post_id
              where c.season_id = %s
                and c.created_at >= %s
                and c.created_at <= %s
                {account_filter_comments}
            )
            select * from posts
            union all
            select * from comments
            """,
            params,
        )

    if platform == "threads":
        thumbnail_expr = _platform_thumbnail_expr("p", "threads")
        account_filter_posts = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        account_filter_comments = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(platform_accounts_list)
        params.extend([season_id, start_dt, end_dt])
        if apply_account_filter:
            params.append(platform_accounts_list)
        rows = pg.fetch_all(
            f"""
            with posts as (
              select
                'threads'::text as platform,
                'post'::text as kind,
                p.id::text as post_db_id,
                p.post_id as source_id,
                {threads_post_text_expr} as text,
                greatest(
                  0,
                  coalesce(p.likes, 0)
                  + coalesce(p.replies_count, 0)
                  + coalesce(p.reposts, 0)
                  + coalesce(p.quotes, 0)
                  + coalesce(p.views, 0)
                )::bigint as engagement,
                p.posted_at as ts,
                (
                  'https://www.threads.com/@'
                  || coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')
                  || '/post/'
                  || p.post_id
                )::text as url,
                coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '') as author,
                {thumbnail_expr}::text as thumbnail_url,
                greatest(0, coalesce(p.replies_count, 0) + coalesce(p.quotes, 0))::bigint as reported_comments,
                coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data
              from social.meta_threads_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter_posts}
            ), comments as (
              select
                'threads'::text as platform,
                'comment'::text as kind,
                c.post_id::text as post_db_id,
                c.comment_id as source_id,
                c.text as text,
                greatest(0, coalesce(c.likes, 0))::bigint as engagement,
                c.created_at as ts,
                (
                  'https://www.threads.com/@'
                  || coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')
                  || '/post/'
                  || p.post_id
                )::text as url,
                c.username as author,
                {thumbnail_expr}::text as thumbnail_url,
                0::bigint as reported_comments,
                coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data
              from social.meta_threads_comments c
              join social.meta_threads_posts p on p.id = c.post_id
              where c.season_id = %s
                and c.created_at >= %s
                and c.created_at <= %s
                {threads_comment_active_filter}
                {account_filter_comments}
            )
            select * from posts
            union all
            select * from comments
            """,
            params,
        )
        context = season_context
        if context is None:
            return rows
        if not _threads_should_enforce_rhoslc_relevance(context=context):
            return rows

        hashtags, keywords = _threads_build_relevance_terms(
            season_id,
            source_scope=source_scope,
            context=context,
        )
        relevant_post_db_ids: set[str] = set()
        for row in rows:
            if str(row.get("kind") or "") != "post":
                continue
            if _threads_text_topic_match(
                text=row.get("text"),
                raw_data=row.get("raw_data"),
                hashtags=hashtags,
                keywords=keywords,
            ):
                post_db_id = str(row.get("post_db_id") or "").strip()
                if post_db_id:
                    relevant_post_db_ids.add(post_db_id)

        if not relevant_post_db_ids:
            return []

        return [row for row in rows if str(row.get("post_db_id") or "").strip() in relevant_post_db_ids]

    return []


def _compute_post_metadata(
    season_id: str,
    *,
    platforms: list[str],
    start_dt: datetime,
    end_dt: datetime,
    target_accounts_by_platform: dict[str, set[str]],
) -> dict[str, Any] | None:
    """Compute post metadata coverage across all platform tables."""
    platform_queries: dict[str, dict[str, str | None]] = {
        "instagram": {
            "table": "social.instagram_posts",
            "ts_col": "posted_at",
            "text_expr": "p.caption",
            "token_text_expr": "p.caption",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": "collaborators",
            "media_type_col": "media_type",
        },
        "tiktok": {
            "table": "social.tiktok_posts",
            "ts_col": "posted_at",
            "text_expr": "p.description",
            "token_text_expr": "p.description",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": None,
            "media_type_col": None,
        },
        "youtube": {
            "table": "social.youtube_videos",
            "ts_col": "published_at",
            "text_expr": "coalesce(nullif(trim(p.description), ''), nullif(trim(p.title), ''))",
            "token_text_expr": "coalesce(p.description, p.title, '')",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": None,
            "media_type_col": None,
        },
        "twitter": {
            "table": "social.twitter_tweets",
            "ts_col": "created_at",
            "text_expr": "p.text",
            "token_text_expr": "p.text",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": None,
            "media_type_col": None,
        },
        "facebook": {
            "table": "social.facebook_posts",
            "ts_col": "posted_at",
            "text_expr": "p.caption",
            "token_text_expr": "p.caption",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": None,
            "media_type_col": "post_type",
        },
        "threads": {
            "table": "social.meta_threads_posts",
            "ts_col": "posted_at",
            "text_expr": "p.text",
            "token_text_expr": "p.text",
            "hashtags_col": "hashtags",
            "mentions_col": "mentions",
            "collaborators_col": None,
            "media_type_col": "media_type",
        },
    }

    total_posts = 0
    posts_with_caption = 0
    posts_with_tags = 0
    posts_with_mentions = 0
    posts_with_collaborators = 0
    content_type_counts: dict[str, int] = {}

    for platform in platforms:
        cfg = platform_queries.get((platform or "").strip().lower())
        if not cfg:
            continue
        table = str(cfg["table"])
        ts_col = str(cfg["ts_col"])
        text_expr = str(cfg["text_expr"])
        token_text_expr = str(cfg["token_text_expr"])
        hashtags_col_raw = cfg.get("hashtags_col")
        mentions_col_raw = cfg.get("mentions_col")
        collaborators_col_raw = cfg.get("collaborators_col")
        media_type_col_raw = cfg.get("media_type_col")

        hashtags_col = (
            str(hashtags_col_raw)
            if hashtags_col_raw and _platform_posts_has_column(platform, str(hashtags_col_raw))
            else None
        )
        mentions_col = (
            str(mentions_col_raw)
            if mentions_col_raw and _platform_posts_has_column(platform, str(mentions_col_raw))
            else None
        )
        collaborators_col = (
            str(collaborators_col_raw)
            if collaborators_col_raw and _platform_posts_has_column(platform, str(collaborators_col_raw))
            else None
        )
        media_type_col = (
            str(media_type_col_raw)
            if media_type_col_raw and _platform_posts_has_column(platform, str(media_type_col_raw))
            else None
        )

        account_handles = sorted(target_accounts_by_platform.get(platform, set()))
        if platform == "youtube":
            account_filter = (
                (
                    "and ltrim(lower(coalesce(nullif(p.channel_title, ''), "
                    "nullif(p.source_account, ''), '')), '@') = any(%s)"
                )
                if account_handles
                else ""
            )
        else:
            account_filter = (
                "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
                if account_handles
                else ""
            )

        has_caption_expr = f"nullif(trim({text_expr}), '') is not null"
        hashtag_regex_expr = f"coalesce({token_text_expr}, '') ~ '(?<![A-Za-z0-9_.])#[A-Za-z0-9_]+'"
        mention_regex_expr = f"coalesce({token_text_expr}, '') ~ '(?<![A-Za-z0-9_.])@[A-Za-z0-9_.]+'"

        hashtag_json_expr = (
            (
                f"(p.{hashtags_col} is not null and jsonb_typeof(p.{hashtags_col}) = 'array' "
                f"and jsonb_array_length(p.{hashtags_col}) > 0)"
            )
            if hashtags_col
            else None
        )
        mention_json_expr = (
            (
                f"(p.{mentions_col} is not null and jsonb_typeof(p.{mentions_col}) = 'array' "
                f"and jsonb_array_length(p.{mentions_col}) > 0)"
            )
            if mentions_col
            else None
        )
        collaborators_json_expr = (
            (
                f"(p.{collaborators_col} is not null and "
                f"jsonb_typeof(p.{collaborators_col}) = 'array' and "
                f"jsonb_array_length(p.{collaborators_col}) > 0)"
            )
            if collaborators_col
            else None
        )

        has_tags_expr = f"({hashtag_json_expr} or {hashtag_regex_expr})" if hashtag_json_expr else hashtag_regex_expr
        has_mentions_expr = (
            f"({mention_json_expr} or {mention_regex_expr})" if mention_json_expr else mention_regex_expr
        )

        selects = [
            "count(*) as total",
            f"count(*) filter (where {has_caption_expr}) as has_caption",
            f"count(*) filter (where {has_tags_expr}) as has_tags",
            f"count(*) filter (where {has_mentions_expr}) as has_mentions",
        ]
        if collaborators_json_expr:
            selects.append(f"count(*) filter (where {collaborators_json_expr}) as has_collaborators")
        if media_type_col:
            selects.append(f"coalesce(nullif(trim(p.{media_type_col}), ''), 'other') as mtype")
            group_by = f"group by coalesce(nullif(trim(p.{media_type_col}), ''), 'other')"
        else:
            group_by = ""

        query_selects = ", ".join(selects)
        params: list[Any] = [season_id, start_dt, end_dt]
        if account_handles:
            params.append(account_handles)

        sql = f"""
            select {query_selects}
            from {table} p
            where p.season_id = %s
              and p.{ts_col} >= %s
              and p.{ts_col} <= %s
              {account_filter}
            {group_by}
        """
        db_rows = pg.fetch_all(sql, params)
        if media_type_col:
            for row in db_rows:
                count = int(row.get("total") or 0)
                total_posts += count
                posts_with_caption += int(row.get("has_caption") or 0)
                posts_with_tags += int(row.get("has_tags") or 0)
                posts_with_mentions += int(row.get("has_mentions") or 0)
                if collaborators_json_expr:
                    posts_with_collaborators += int(row.get("has_collaborators") or 0)
                mtype = str(row.get("mtype") or "other").lower().strip()
                if not mtype:
                    mtype = "other"
                content_type_counts[mtype] = content_type_counts.get(mtype, 0) + count
        elif db_rows:
            row = db_rows[0]
            count = int(row.get("total") or 0)
            total_posts += count
            posts_with_caption += int(row.get("has_caption") or 0)
            posts_with_tags += int(row.get("has_tags") or 0)
            posts_with_mentions += int(row.get("has_mentions") or 0)
            if collaborators_json_expr:
                posts_with_collaborators += int(row.get("has_collaborators") or 0)
            # Assign a generic content type for platforms without media_type column
            generic_type = "video" if platform in ("tiktok", "youtube") else "post"
            if count > 0:
                content_type_counts[generic_type] = content_type_counts.get(generic_type, 0) + count

    if total_posts == 0:
        return None

    def _coverage(with_count: int) -> dict[str, Any]:
        return {
            "posts_with": with_count,
            "pct": round((with_count * 100.0) / total_posts, 1) if total_posts > 0 else None,
        }

    # Normalize raw media_type codes to canonical labels
    media_type_normalize: dict[str, str] = {
        "1": "photo",
        "2": "photo",
        "image": "photo",
        "8": "video",
        "reel": "video",
        "19": "album",
        "carousel": "album",
        "carousel_album": "album",
        "sidecar": "album",
        "graphimage": "photo",
        "graphvideo": "video",
        "graphsidecar": "album",
    }
    normalized_counts: dict[str, int] = {}
    for raw_key, count in content_type_counts.items():
        key = media_type_normalize.get(raw_key, raw_key)
        normalized_counts[key] = normalized_counts.get(key, 0) + count

    # Build content type buckets
    buckets = []
    for key, count in sorted(normalized_counts.items(), key=lambda kv: -kv[1]):
        buckets.append(
            {
                "key": key,
                "count": count,
                "pct": round((count * 100.0) / total_posts, 1) if total_posts > 0 else None,
            }
        )

    return {
        "total_posts": total_posts,
        "captions": _coverage(posts_with_caption),
        "tags": _coverage(posts_with_tags),
        "mentions": _coverage(posts_with_mentions),
        "collaborators": _coverage(posts_with_collaborators),
        "content_types": {
            "total_posts": total_posts,
            "buckets": buckets,
        },
    }


def _build_rows(
    season_id: str,
    *,
    platforms: list[str],
    start_dt: datetime,
    end_dt: datetime,
    source_scope: str,
    season_context: SeasonContext,
    analyzer_context: SentimentAnalyzerContext,
    target_accounts_by_platform: dict[str, set[str]],
    include_post_text: bool = True,
) -> list[dict[str, Any]]:
    def _load_platform_rows(platform: str) -> list[dict[str, Any]]:
        base_kwargs: dict[str, Any] = {
            "platform": platform,
            "start_dt": start_dt,
            "end_dt": end_dt,
            "source_scope": source_scope,
            "target_accounts_by_platform": target_accounts_by_platform,
        }
        attempts: list[dict[str, Any]] = [
            {
                **base_kwargs,
                "season_context": season_context,
                "include_post_text": include_post_text,
            },
            {**base_kwargs, "season_context": season_context},
            {**base_kwargs, "include_post_text": include_post_text},
            base_kwargs,
        ]
        last_exc: TypeError | None = None
        for attempt_kwargs in attempts:
            try:
                return _rows_for_platform(season_id, **attempt_kwargs)
            except TypeError as exc:
                # Backward-compat shim for tests/mocks using older helper signatures.
                if "unexpected keyword argument" not in str(exc):
                    raise
                last_exc = exc
                continue
        assert last_exc is not None
        raise last_exc

    rows: list[dict[str, Any]] = []
    if len(platforms) <= 1:
        for platform in platforms:
            rows.extend(_load_platform_rows(platform))
    else:
        max_workers = max(1, min(len(platforms), 4))
        ordered_rows_by_platform: dict[str, list[dict[str, Any]]] = {}
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_platform = {executor.submit(_load_platform_rows, platform): platform for platform in platforms}
            for future in as_completed(future_to_platform):
                platform = future_to_platform[future]
                ordered_rows_by_platform[platform] = future.result()
        for platform in platforms:
            rows.extend(ordered_rows_by_platform.get(platform, []))

    normalized: list[dict[str, Any]] = []
    comment_sentiment_cache: dict[str, tuple[str, int, float, bool, str]] = {}
    for row in rows:
        ts = _coerce_dt(row.get("ts"))
        if ts is None:
            continue
        kind = str(row.get("kind") or "").lower()
        text_value = row.get("text")
        text = str(text_value) if text_value is not None else ""
        if kind == "comment":
            sentiment_cache_key = (
                f"{str(row.get('platform') or '').lower()}:{str(row.get('source_id') or '')}:"
                f"{hashlib.sha1(_normalize_sentiment_text_key(text).encode('utf-8', 'ignore')).hexdigest()}"
            )
            cached_sentiment = comment_sentiment_cache.get(sentiment_cache_key)
            if cached_sentiment is None:
                rule_result = _rule_based_sentiment_for_text(text, analyzer_context=analyzer_context)
                sentiment = rule_result.label
                if sentiment == "neutral":
                    score = 0
                else:
                    rounded = int(round(rule_result.score))
                    score = rounded if rounded != 0 else _score_from_label(sentiment)
                confidence = rule_result.confidence
                ambiguous = rule_result.ambiguous
                sentiment_key = _normalize_sentiment_text_key(text)
                cached_sentiment = (sentiment, score, confidence, ambiguous, sentiment_key)
                comment_sentiment_cache[sentiment_cache_key] = cached_sentiment
            sentiment, score, confidence, ambiguous, sentiment_key = cached_sentiment
        else:
            sentiment = "neutral"
            score = 0
            confidence = 1.0
            ambiguous = False
            sentiment_key = ""
        normalized.append(
            {
                "platform": str(row.get("platform") or ""),
                "kind": kind,
                "source_id": str(row.get("source_id") or ""),
                "text": text,
                "engagement": int(row.get("engagement") or 0),
                "ts": ts,
                "url": str(row.get("url") or ""),
                "author": str(row.get("author") or ""),
                "thumbnail_url": str(row.get("thumbnail_url") or "") or None,
                "reported_comments": int(row.get("reported_comments") or 0),
                "is_short": bool(row.get("is_short")) if str(row.get("platform") or "") == "youtube" else False,
                "sentiment": sentiment,
                "sentiment_score": score,
                "_sentiment_confidence": confidence,
                "_sentiment_ambiguous": ambiguous,
                "_sentiment_key": sentiment_key,
            }
        )

    _apply_optional_gemini_sentiment(normalized, context=season_context, analyzer_context=analyzer_context)
    normalized.sort(key=lambda item: item["ts"], reverse=True)
    return normalized


def _build_drivers(
    rows: list[dict[str, Any]],
    *,
    analyzer_context: SentimentAnalyzerContext | None = None,
) -> dict[str, list[dict[str, Any]]]:
    effective_context = analyzer_context or _default_sentiment_context()
    token_counts: Counter[str] = Counter()
    token_scores: defaultdict[str, int] = defaultdict(int)
    blocked_terms = set(STOPWORDS)
    blocked_terms.update(effective_context.cast_terms)

    account_terms: set[str] = set()
    for row in rows:
        account_terms.update(_tokenize_handle_terms(str(row.get("author") or "")))
        for mention in MENTION_TOKEN_RE.findall(str(row.get("text") or "")):
            account_terms.update(_tokenize_handle_terms(mention))
    blocked_terms.update(account_terms)

    for row in rows:
        if row["kind"] != "comment":
            continue
        text = row.get("text") or ""
        sentiment = str(row.get("sentiment") or "neutral").lower()
        sentiment_score = _score_from_label(sentiment)
        if sentiment_score == 0:
            continue
        row_mentions = {
            token.lower()
            for mention in MENTION_TOKEN_RE.findall(str(text))
            for token in _tokenize_handle_terms(mention)
        }
        tokens = [token.lower() for token in TOKEN_RE.findall(text)]
        for token in tokens:
            if len(token) < 4 or token in blocked_terms or token in row_mentions:
                continue
            token_counts[token] += 1
            token_scores[token] += sentiment_score

    positive = [
        {
            "term": term,
            "count": token_counts[term],
            "score": token_scores[term],
        }
        for term in token_counts
        if token_counts[term] >= 2 and token_scores[term] > 0
    ]
    negative = [
        {
            "term": term,
            "count": token_counts[term],
            "score": token_scores[term],
        }
        for term in token_counts
        if token_counts[term] >= 2 and token_scores[term] < 0
    ]

    positive.sort(key=lambda item: (-item["score"], -item["count"], item["term"]))
    negative.sort(key=lambda item: (item["score"], -item["count"], item["term"]))

    return {
        "positive": positive[:10],
        "negative": negative[:10],
    }


def _platform_int_payload(values: dict[str, Any] | None) -> dict[str, int]:
    payload = values if isinstance(values, dict) else {}
    return {platform: int(payload.get(platform, 0) or 0) for platform in SUPPORTED_PLATFORMS}


def _analytics_cache_key(
    *,
    season_id: str,
    platforms: list[str] | None,
    timezone: str,
    week: int | None,
    source_scope: str,
    include_rows: bool,
    include_jobs: bool,
    include_flags: bool,
    include_schedule: bool,
    include_benchmark: bool,
) -> tuple[Any, ...]:
    platform_key = tuple(sorted(platforms or []))
    return (
        season_id,
        platform_key,
        timezone,
        week,
        source_scope,
        include_rows,
        include_jobs,
        include_flags,
        include_schedule,
        include_benchmark,
    )


def _get_cached_analytics(cache_key: tuple[Any, ...]) -> dict[str, Any] | None:
    now = time_module.monotonic()
    with _analytics_cache_lock:
        cached = _analytics_cache.get(cache_key)
        if cached is None:
            return None
        expires_at, payload = cached
        if expires_at <= now:
            _analytics_cache.pop(cache_key, None)
            return None
        return copy.deepcopy(payload)


def _set_cached_analytics(cache_key: tuple[Any, ...], payload: dict[str, Any]) -> None:
    with _analytics_cache_lock:
        _analytics_cache[cache_key] = (
            time_module.monotonic() + ANALYTICS_CACHE_TTL_SECONDS,
            copy.deepcopy(payload),
        )


def get_analytics(
    season_id: str,
    *,
    platforms: list[str] | None,
    timezone: str,
    week: int | None,
    source_scope: str,
    include_rows: bool = False,
    include_jobs: bool = False,
    include_flags: bool = True,
    include_schedule: bool = True,
    include_benchmark: bool = True,
) -> dict[str, Any]:
    cache_key = _analytics_cache_key(
        season_id=season_id,
        platforms=platforms,
        timezone=timezone,
        week=week,
        source_scope=source_scope,
        include_rows=include_rows,
        include_jobs=include_jobs,
        include_flags=include_flags,
        include_schedule=include_schedule,
        include_benchmark=include_benchmark,
    )
    cached_response = _get_cached_analytics(cache_key)
    if cached_response is not None:
        return cached_response

    context = get_season_context(season_id)
    available_platforms = _resolve_requested_platforms(platforms)

    now = _now_utc()
    week_windows, week_zero_start_local = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now,
    )
    windows_by_index = {item.week_index: item for item in week_windows}

    selected_window = windows_by_index.get(week) if week is not None else None
    if week is not None and selected_window is None:
        raise ValueError(f"Week {week} is not available for this season")

    latest_window_end_local = max(
        (item.end_local for item in week_windows),
        default=week_zero_start_local,
    )
    latest_window_end_utc = latest_window_end_local.astimezone(UTC)

    if selected_window:
        start_dt = selected_window.start_local.astimezone(UTC)
        end_dt = (selected_window.end_local - timedelta(microseconds=1)).astimezone(UTC)
    else:
        start_dt = week_zero_start_local.astimezone(UTC)
        end_dt = min(now, latest_window_end_utc)
    if end_dt < start_dt:
        end_dt = start_dt

    sentiment_context = _build_sentiment_context(context)
    target_accounts_by_platform = _target_accounts_by_platform(
        season_id,
        source_scope=source_scope,
        context=context,
    )
    rows = _build_rows(
        season_id,
        platforms=available_platforms,
        start_dt=start_dt,
        end_dt=end_dt,
        source_scope=source_scope,
        season_context=context,
        analyzer_context=sentiment_context,
        target_accounts_by_platform=target_accounts_by_platform,
        include_post_text=include_rows,
    )

    try:
        post_metadata = _compute_post_metadata(
            season_id,
            platforms=available_platforms,
            start_dt=start_dt,
            end_dt=end_dt,
            target_accounts_by_platform=target_accounts_by_platform,
        )
    except Exception as exc:
        exc_text = str(exc).lower()
        if (
            exc_text.startswith("database pool initialization failed")
            or "invalid input syntax for type uuid" in exc_text
        ):
            logger.debug("Skipping data quality post metadata due unavailable database URL")
            post_metadata = None
        else:
            raise

    posts = [row for row in rows if row["kind"] == "post"]
    comments = [row for row in rows if row["kind"] == "comment"]

    sentiment_counts = {
        "positive": sum(1 for row in comments if row["sentiment"] == "positive"),
        "neutral": sum(1 for row in comments if row["sentiment"] == "neutral"),
        "negative": sum(1 for row in comments if row["sentiment"] == "negative"),
    }

    total_comments = max(1, len(comments))
    sentiment_mix = {
        "positive": round(sentiment_counts["positive"] / total_comments, 4),
        "neutral": round(sentiment_counts["neutral"] / total_comments, 4),
        "negative": round(sentiment_counts["negative"] / total_comments, 4),
        "counts": sentiment_counts,
    }

    visible_windows = [selected_window] if selected_window else week_windows
    weekly_map: dict[int, dict[str, Any]] = {
        item.week_index: {
            "post_volume": 0,
            "comment_volume": 0,
            "engagement": 0,
            "sentiment": {"positive": 0, "neutral": 0, "negative": 0},
            "week_start": item.start_local,
            "week_end": item.end_local,
            "week_type": item.week_type,
            "episode_number": item.episode_number,
            "label": _week_window_label(item, timezone=timezone),
        }
        for item in visible_windows
    }

    for row in rows:
        week_window = _week_for_timestamp(row["ts"], windows=visible_windows, timezone=timezone)
        if not week_window:
            continue
        entry = weekly_map[week_window.week_index]
        entry["engagement"] += int(row["engagement"])
        if row["kind"] == "post":
            entry["post_volume"] += 1
        else:
            entry["comment_volume"] += 1
            entry["sentiment"][row["sentiment"]] += 1

    weekly = []
    for week_index in sorted(weekly_map):
        entry = weekly_map[week_index]
        week_end_inclusive = entry["week_end"] - timedelta(microseconds=1)
        weekly.append(
            {
                "week_index": week_index,
                "label": entry["label"],
                "start": _iso(entry["week_start"].astimezone(UTC)),
                "end": _iso(week_end_inclusive.astimezone(UTC)),
                "week_type": entry["week_type"],
                "episode_number": entry["episode_number"],
                "post_volume": entry["post_volume"],
                "comment_volume": entry["comment_volume"],
                "engagement": entry["engagement"],
                "sentiment": entry["sentiment"],
            }
        )

    weekly_platform_posts_map: dict[int, dict[str, int]] = {
        item.week_index: dict.fromkeys(SUPPORTED_PLATFORMS, 0) for item in visible_windows
    }
    weekly_platform_comments_map: dict[int, dict[str, int]] = {
        item.week_index: dict.fromkeys(SUPPORTED_PLATFORMS, 0) for item in visible_windows
    }
    weekly_platform_reported_comments_map: dict[int, dict[str, int]] = {
        item.week_index: dict.fromkeys(SUPPORTED_PLATFORMS, 0) for item in visible_windows
    }
    weekly_platform_engagement_map: dict[int, dict[str, int]] = {
        item.week_index: dict.fromkeys(SUPPORTED_PLATFORMS, 0) for item in visible_windows
    }
    local_zone = ZoneInfo(timezone)
    weekly_daily_activity_map: dict[int, dict[str, Any]] = {}
    day_seconds = 24 * 60 * 60
    for window in visible_windows:
        week_start_local = window.start_local.astimezone(local_zone)
        week_end_local = window.end_local.astimezone(local_zone)
        duration_seconds = max(0.0, (week_end_local - week_start_local).total_seconds())
        day_count = max(1, int((duration_seconds + day_seconds - 1) // day_seconds))
        days: list[dict[str, Any]] = []
        for day_index in range(day_count):
            day_start = week_start_local + timedelta(days=day_index)
            days.append(
                {
                    "day_index": day_index,
                    "date_local": day_start.date().isoformat(),
                    "posts": dict.fromkeys(SUPPORTED_PLATFORMS, 0),
                    "comments": dict.fromkeys(SUPPORTED_PLATFORMS, 0),
                    "reported_comments": dict.fromkeys(SUPPORTED_PLATFORMS, 0),
                    "total_posts": 0,
                    "total_comments": 0,
                    "total_reported_comments": 0,
                }
            )
        weekly_daily_activity_map[window.week_index] = {
            "week_index": window.week_index,
            "days": days,
            "week_start": week_start_local,
            "week_start_date": week_start_local.date(),
        }
    for row in rows:
        week_window = _week_for_timestamp(row["ts"], windows=visible_windows, timezone=timezone)
        if not week_window:
            continue
        platform = row["platform"]
        if platform in weekly_platform_engagement_map[week_window.week_index]:
            weekly_platform_engagement_map[week_window.week_index][platform] += int(row["engagement"] or 0)
        if row["kind"] == "post" and platform in weekly_platform_posts_map[week_window.week_index]:
            weekly_platform_posts_map[week_window.week_index][platform] += 1
            weekly_platform_reported_comments_map[week_window.week_index][platform] += int(
                row.get("reported_comments") or 0
            )
        elif row["kind"] == "comment" and platform in weekly_platform_comments_map[week_window.week_index]:
            weekly_platform_comments_map[week_window.week_index][platform] += 1

        day_bucket = weekly_daily_activity_map.get(week_window.week_index)
        if not day_bucket:
            continue
        day_entries = day_bucket.get("days") or []
        if not day_entries:
            continue
        local_ts = row["ts"].astimezone(local_zone)
        day_index = (local_ts.date() - day_bucket["week_start_date"]).days
        if day_index < 0:
            continue
        if day_index >= len(day_entries):
            day_index = len(day_entries) - 1
        day_entry = day_entries[day_index]
        if platform not in day_entry["posts"]:
            continue
        if row["kind"] == "post":
            day_entry["posts"][platform] += 1
            day_entry["total_posts"] += 1
            reported_comments = int(row.get("reported_comments") or 0)
            day_entry["reported_comments"][platform] += reported_comments
            day_entry["total_reported_comments"] += reported_comments
        elif row["kind"] == "comment":
            day_entry["comments"][platform] += 1
            day_entry["total_comments"] += 1

    weekly_platform_posts: list[dict[str, Any]] = []
    for week_entry in weekly:
        week_index = int(week_entry["week_index"])
        platform_posts = weekly_platform_posts_map.get(
            week_index,
            dict.fromkeys(SUPPORTED_PLATFORMS, 0),
        )
        platform_comments = weekly_platform_comments_map.get(
            week_index,
            dict.fromkeys(SUPPORTED_PLATFORMS, 0),
        )
        platform_reported_comments = weekly_platform_reported_comments_map.get(
            week_index,
            dict.fromkeys(SUPPORTED_PLATFORMS, 0),
        )
        saved_total_comments = int(sum(platform_comments.values()))
        total_reported_comments = int(sum(platform_reported_comments.values()))
        comments_saved_pct: float | None = None
        if total_reported_comments > 0:
            comments_saved_pct = round(min(100.0, (saved_total_comments * 100.0) / total_reported_comments), 1)
        weekly_platform_posts.append(
            {
                "week_index": week_index,
                "label": week_entry["label"],
                "start": week_entry["start"],
                "end": week_entry["end"],
                "week_type": week_entry.get("week_type"),
                "episode_number": week_entry.get("episode_number"),
                "posts": _platform_int_payload(platform_posts),
                "comments": _platform_int_payload(platform_comments),
                "reported_comments": _platform_int_payload(platform_reported_comments),
                "total_posts": int(sum(platform_posts.values())),
                "total_comments": saved_total_comments,
                "total_reported_comments": total_reported_comments,
                "comments_saved_pct": comments_saved_pct,
            }
        )

    weekly_platform_engagement: list[dict[str, Any]] = []
    for week_entry in weekly:
        week_index = int(week_entry["week_index"])
        platform_engagement = weekly_platform_engagement_map.get(
            week_index,
            dict.fromkeys(SUPPORTED_PLATFORMS, 0),
        )
        engagement_payload = _platform_int_payload(platform_engagement)
        total_engagement = int(sum(engagement_payload.values()))
        weekly_platform_engagement.append(
            {
                "week_index": week_index,
                "label": week_entry["label"],
                "start": week_entry["start"],
                "end": week_entry["end"],
                "week_type": week_entry.get("week_type"),
                "episode_number": week_entry.get("episode_number"),
                "engagement": engagement_payload,
                "total_engagement": total_engagement,
                "has_data": total_engagement > 0,
            }
        )

    weekly_daily_activity: list[dict[str, Any]] = []
    for week_entry in weekly:
        week_index = int(week_entry["week_index"])
        day_entries = (weekly_daily_activity_map.get(week_index) or {}).get("days") or []
        days_payload: list[dict[str, Any]] = []
        for day_entry in day_entries:
            posts_payload = day_entry.get("posts") or {}
            comments_payload = day_entry.get("comments") or {}
            reported_comments_payload = day_entry.get("reported_comments") or {}
            days_payload.append(
                {
                    "day_index": int(day_entry.get("day_index", 0)),
                    "date_local": str(day_entry.get("date_local") or ""),
                    "posts": _platform_int_payload(posts_payload),
                    "comments": _platform_int_payload(comments_payload),
                    "reported_comments": _platform_int_payload(reported_comments_payload),
                    "total_posts": int(day_entry.get("total_posts", 0)),
                    "total_comments": int(day_entry.get("total_comments", 0)),
                    "total_reported_comments": int(day_entry.get("total_reported_comments", 0)),
                }
            )

        weekly_daily_activity.append(
            {
                "week_index": week_index,
                "label": week_entry["label"],
                "start": week_entry["start"],
                "end": week_entry["end"],
                "week_type": week_entry.get("week_type"),
                "episode_number": week_entry.get("episode_number"),
                "days": days_payload,
            }
        )

    comments_saved_by_platform = dict.fromkeys(SUPPORTED_PLATFORMS, 0)
    reported_comments_by_platform = dict.fromkeys(SUPPORTED_PLATFORMS, 0)
    for week_row in weekly_platform_posts:
        comments_payload = week_row.get("comments") if isinstance(week_row.get("comments"), dict) else {}
        reported_payload = (
            week_row.get("reported_comments") if isinstance(week_row.get("reported_comments"), dict) else {}
        )
        for platform in SUPPORTED_PLATFORMS:
            comments_saved_by_platform[platform] += int(comments_payload.get(platform, 0))
            reported_comments_by_platform[platform] += int(reported_payload.get(platform, 0))

    platform_comments_saved_pct = {
        platform: (
            _safe_percent(
                comments_saved_by_platform.get(platform, 0),
                reported_comments_by_platform.get(platform, 0),
            )
            if platform in available_platforms
            else None
        )
        for platform in SUPPORTED_PLATFORMS
    }
    total_saved_comments = sum(comments_saved_by_platform.values())
    total_reported_comments = sum(reported_comments_by_platform.values())
    comments_saved_pct_overall = _safe_percent(total_saved_comments, total_reported_comments)
    youtube_posts = [row for row in posts if str(row.get("platform") or "") == "youtube"]
    youtube_reels_count = sum(
        1 for row in youtube_posts if bool(row.get("is_short")) or "/shorts/" in str(row.get("url") or "")
    )
    youtube_videos_count = max(0, len(youtube_posts) - youtube_reels_count)
    youtube_content_breakdown = {
        "videos_count": youtube_videos_count,
        "reels_count": youtube_reels_count,
        "total_count": len(youtube_posts),
    }

    last_post_dt = max((row["ts"] for row in posts), default=None)
    last_comment_dt = max((row["ts"] for row in comments), default=None)
    freshness_anchor = max(
        [value for value in [last_post_dt, last_comment_dt] if isinstance(value, datetime)],
        default=None,
    )
    data_freshness_minutes: int | None = None
    if isinstance(freshness_anchor, datetime):
        data_freshness_minutes = max(0, int((now - freshness_anchor).total_seconds() // 60))

    weekly_flags: list[dict[str, Any]] = []
    weekly_by_index = sorted(weekly, key=lambda item: int(item.get("week_index", 0)))
    trend_weeks = [item for item in weekly_by_index if str(item.get("week_type") or "") != "bye"]
    weekly_posts_by_index = {
        int(item.get("week_index", 0)): item
        for item in weekly_platform_posts
        if isinstance(item.get("week_index"), int)
    }
    for idx, week_entry in enumerate(trend_weeks):
        week_index = int(week_entry.get("week_index", 0))
        post_volume = int(week_entry.get("post_volume") or 0)
        if post_volume == 0:
            weekly_flags.append(
                {
                    "week_index": week_index,
                    "code": "zero_activity",
                    "severity": "info",
                    "message": "No posts captured in this week window.",
                }
            )

        trailing_values = [int(item.get("post_volume") or 0) for item in trend_weeks[max(0, idx - 2) : idx]]
        trailing_avg = (sum(trailing_values) / len(trailing_values)) if trailing_values else 0.0
        if trailing_avg > 0:
            if post_volume >= 6 and post_volume >= (2.0 * trailing_avg):
                weekly_flags.append(
                    {
                        "week_index": week_index,
                        "code": "spike",
                        "severity": "warn",
                        "message": f"Post volume spike vs trailing 2-week average ({trailing_avg:.1f}).",
                    }
                )
            if trailing_avg >= 4 and post_volume <= (0.4 * trailing_avg):
                weekly_flags.append(
                    {
                        "week_index": week_index,
                        "code": "drop",
                        "severity": "warn",
                        "message": f"Post volume drop vs trailing 2-week average ({trailing_avg:.1f}).",
                    }
                )

        weekly_post_row = weekly_posts_by_index.get(week_index) or {}
        week_reported_comments = int(weekly_post_row.get("total_reported_comments") or 0)
        week_saved_pct = weekly_post_row.get("comments_saved_pct")
        if week_reported_comments > 0 and isinstance(week_saved_pct, (int, float)) and float(week_saved_pct) < 60.0:
            weekly_flags.append(
                {
                    "week_index": week_index,
                    "code": "comment_gap",
                    "severity": "warn",
                    "message": f"Only {float(week_saved_pct):.1f}% of expected comments are saved.",
                }
            )

    schedule_profile: dict[str, Any] | None = None
    if include_schedule:
        schedule_platforms: list[dict[str, Any]] = []
        for platform in [item for item in SUPPORTED_PLATFORMS if item in available_platforms]:
            day_values: list[int] = []
            for week_row in weekly_daily_activity:
                for day_row in week_row.get("days") or []:
                    posts_payload = day_row.get("posts") or {}
                    day_values.append(int(posts_payload.get(platform, 0)))
            zero_days = sum(1 for value in day_values if value <= 0)
            active_days = sum(1 for value in day_values if value > 0)
            schedule_platforms.append(
                {
                    "platform": platform,
                    "zero_days": zero_days,
                    "peak_day_posts": max(day_values) if day_values else 0,
                    "median_day_posts": _median_int(day_values),
                    "active_days": active_days,
                }
            )
        schedule_profile = {
            "timezone": timezone,
            "platforms": schedule_platforms,
        }

    benchmark: dict[str, Any] | None = None
    if include_benchmark:
        benchmark_weeks = sorted(weekly, key=lambda item: int(item.get("week_index", 0)))
        current_week_entry: dict[str, Any] | None = None
        if week is not None:
            current_week_entry = next(
                (item for item in benchmark_weeks if int(item.get("week_index", -1)) == week),
                None,
            )
        if current_week_entry is None and benchmark_weeks:
            current_week_entry = benchmark_weeks[-1]

        def _metrics_payload(item: dict[str, Any] | None) -> dict[str, int]:
            return {
                "posts": int((item or {}).get("post_volume") or 0),
                "comments": int((item or {}).get("comment_volume") or 0),
                "engagement": int((item or {}).get("engagement") or 0),
            }

        def _delta_pct(current_value: int, baseline_value: int) -> float | None:
            if baseline_value <= 0:
                return None
            return round(((current_value - baseline_value) * 100.0) / float(baseline_value), 1)

        current_index = int((current_week_entry or {}).get("week_index", -1))
        previous_week_entry = next(
            (item for item in benchmark_weeks if int(item.get("week_index", -1)) == current_index - 1),
            None,
        )
        trailing_prev_weeks = [item for item in benchmark_weeks if int(item.get("week_index", -1)) < current_index][-3:]
        trailing_avg_metrics = {
            "posts": 0.0,
            "comments": 0.0,
            "engagement": 0.0,
        }
        if trailing_prev_weeks:
            trailing_avg_metrics = {
                "posts": (
                    sum(int(item.get("post_volume") or 0) for item in trailing_prev_weeks) / len(trailing_prev_weeks)
                ),
                "comments": sum(int(item.get("comment_volume") or 0) for item in trailing_prev_weeks)
                / len(trailing_prev_weeks),
                "engagement": sum(int(item.get("engagement") or 0) for item in trailing_prev_weeks)
                / len(trailing_prev_weeks),
            }

        consistency_score: dict[str, float | None] = {}
        for platform in [item for item in SUPPORTED_PLATFORMS if item in available_platforms]:
            total_days = 0
            active_days = 0
            for week_row in weekly_daily_activity:
                for day_row in week_row.get("days") or []:
                    total_days += 1
                    posts_payload = day_row.get("posts") or {}
                    if int(posts_payload.get(platform, 0)) > 0:
                        active_days += 1
            consistency_score[platform] = _safe_percent(active_days, total_days)

        current_metrics = _metrics_payload(current_week_entry)
        previous_metrics = _metrics_payload(previous_week_entry)
        benchmark = {
            "week_index": int((current_week_entry or {}).get("week_index", -1)),
            "current": current_metrics,
            "previous_week": {
                "week_index": int((previous_week_entry or {}).get("week_index", -1)) if previous_week_entry else None,
                "metrics": previous_metrics,
                "delta_pct": {
                    "posts": _delta_pct(current_metrics["posts"], previous_metrics["posts"]),
                    "comments": _delta_pct(current_metrics["comments"], previous_metrics["comments"]),
                    "engagement": _delta_pct(current_metrics["engagement"], previous_metrics["engagement"]),
                },
            },
            "trailing_3_week_avg": {
                "window_size": len(trailing_prev_weeks),
                "metrics": {
                    "posts": round(trailing_avg_metrics["posts"], 1),
                    "comments": round(trailing_avg_metrics["comments"], 1),
                    "engagement": round(trailing_avg_metrics["engagement"], 1),
                },
                "delta_pct": {
                    "posts": _delta_pct(current_metrics["posts"], int(round(trailing_avg_metrics["posts"]))),
                    "comments": _delta_pct(current_metrics["comments"], int(round(trailing_avg_metrics["comments"]))),
                    "engagement": _delta_pct(
                        current_metrics["engagement"],
                        int(round(trailing_avg_metrics["engagement"])),
                    ),
                },
            },
            "consistency_score_pct": consistency_score,
        }

    platform_breakdown = []
    for platform in available_platforms:
        platform_rows = [row for row in rows if row["platform"] == platform]
        platform_comments = [row for row in platform_rows if row["kind"] == "comment"]
        platform_breakdown.append(
            {
                "platform": platform,
                "posts": sum(1 for row in platform_rows if row["kind"] == "post"),
                "comments": len(platform_comments),
                "engagement": sum(int(row["engagement"]) for row in platform_rows),
                "sentiment": {
                    "positive": sum(1 for row in platform_comments if row["sentiment"] == "positive"),
                    "neutral": sum(1 for row in platform_comments if row["sentiment"] == "neutral"),
                    "negative": sum(1 for row in platform_comments if row["sentiment"] == "negative"),
                },
            }
        )

    leaderboards = {
        "bravo_content": [
            {
                "platform": row["platform"],
                "source_id": row["source_id"],
                "text": row["text"][:240],
                "engagement": row["engagement"],
                "url": row["url"],
                "timestamp": _iso(row["ts"]),
                "thumbnail_url": row.get("thumbnail_url"),
            }
            for row in sorted(posts, key=lambda item: item["engagement"], reverse=True)[:15]
        ],
        "viewer_discussion": [
            {
                "platform": row["platform"],
                "source_id": row["source_id"],
                "text": row["text"][:240],
                "engagement": row["engagement"],
                "url": row["url"],
                "timestamp": _iso(row["ts"]),
                "sentiment": row["sentiment"],
                "thumbnail_url": row.get("thumbnail_url"),
            }
            for row in sorted(comments, key=lambda item: item["engagement"], reverse=True)[:20]
        ],
    }

    jobs = list_jobs(season_id, limit=25) if include_jobs else []

    response: dict[str, Any] = {
        "window": {
            "start": _iso(start_dt),
            "end": _iso(end_dt),
            "timezone": timezone,
            "week_anchor": str(context.anchor_date),
            "week_zero_start": _iso(week_zero_start_local.astimezone(UTC)),
            "week": week,
            "source_scope": source_scope,
        },
        "summary": {
            "show_id": context.show_id,
            "season_id": context.season_id,
            "season_number": context.season_number,
            "show_name": context.show_name,
            "total_posts": len(posts),
            "total_comments": len(comments),
            "total_engagement": sum(int(row["engagement"]) for row in rows),
            "sentiment_mix": sentiment_mix,
            "deltas": {
                "posts": None,
                "comments": None,
                "engagement": None,
            },
            "data_quality": {
                "comments_saved_pct_overall": comments_saved_pct_overall,
                "platform_comments_saved_pct": platform_comments_saved_pct,
                "last_post_at": _iso(last_post_dt),
                "last_comment_at": _iso(last_comment_dt),
                "data_freshness_minutes": data_freshness_minutes,
                "youtube_content_breakdown": youtube_content_breakdown,
                "post_metadata": post_metadata,
            },
        },
        "weekly": weekly,
        "weekly_platform_posts": weekly_platform_posts,
        "weekly_platform_engagement": weekly_platform_engagement,
        "weekly_daily_activity": weekly_daily_activity,
        "platform_breakdown": platform_breakdown,
        "themes": _build_drivers(comments, analyzer_context=sentiment_context),
        "leaderboards": leaderboards,
        "jobs": jobs,
    }
    if include_flags:
        response["weekly_flags"] = weekly_flags
    if include_schedule and schedule_profile is not None:
        response["schedule_profile"] = schedule_profile
    if include_benchmark and benchmark is not None:
        response["benchmark"] = benchmark

    if include_rows:
        lookup_windows = visible_windows
        rows_payload: list[dict[str, Any]] = []
        for row in rows:
            bucket = _week_for_timestamp(row["ts"], windows=lookup_windows, timezone=timezone)
            rows_payload.append(
                {
                    "week_index": bucket.week_index if bucket else None,
                    "platform": row["platform"],
                    "kind": row["kind"],
                    "source_id": row["source_id"],
                    "timestamp": _iso(row["ts"]),
                    "author": row["author"],
                    "url": row["url"],
                    "engagement": row["engagement"],
                    "sentiment": row["sentiment"],
                    "text": row["text"],
                    "thumbnail_url": row.get("thumbnail_url"),
                }
            )
        response["rows"] = rows_payload

    _set_cached_analytics(cache_key, response)
    return response


# ---------------------------------------------------------------------------
# Comment coverage (saved vs platform-reported)
# ---------------------------------------------------------------------------


def _comments_coverage_for_platform(
    season_id: str,
    *,
    platform: str,
    start_dt: datetime,
    end_dt: datetime,
    source_scope: str,
    target_accounts_by_platform: dict[str, set[str]],
    season_context: SeasonContext | None = None,
) -> dict[str, int]:
    requires_target_accounts = source_scope in {"bravo", "creator"}
    platform_accounts = set(target_accounts_by_platform.get(platform, set()))
    if requires_target_accounts and not platform_accounts:
        return {
            "posts_scanned": 0,
            "stale_posts_count": 0,
            "saved_comments": 0,
            "reported_comments": 0,
            "saved_replies": 0,
            "reported_replies": 0,
            "saved_quotes": 0,
            "reported_quotes": 0,
        }

    apply_account_filter = source_scope != "community" and bool(platform_accounts)
    account_handles_list = sorted(platform_accounts)
    instagram_active_filter = "and c.is_missing = false" if _comment_lifecycle_supported("instagram_comments") else ""
    tiktok_active_filter = "and c.is_missing = false" if _comment_lifecycle_supported("tiktok_comments") else ""
    youtube_active_filter = "and c.is_missing = false" if _comment_lifecycle_supported("youtube_comments") else ""
    facebook_active_filter = "and c.is_missing = false" if _comment_lifecycle_supported("facebook_comments") else ""
    twitter_reply_active_filter_r = "and r.is_missing = false" if _comment_lifecycle_supported("twitter_tweets") else ""
    twitter_reply_active_filter_child = (
        "and child.is_missing = false" if _comment_lifecycle_supported("twitter_tweets") else ""
    )
    twitter_reply_active_filter_t = "and t.is_missing = false" if _comment_lifecycle_supported("twitter_tweets") else ""
    twitter_quote_active_filter_q = "and q.is_missing = false" if _comment_lifecycle_supported("twitter_tweets") else ""

    if platform == "instagram":
        account_filter = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params: list[Any] = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(account_handles_list)
        row = (
            pg.fetch_one(
                f"""
            with posts as (
              select
                p.id,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.instagram_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter}
            ), comment_counts as (
              select c.post_id, count(*)::bigint as saved_comments
              from social.instagram_comments c
              join posts p on p.id = c.post_id
              where true
                {instagram_active_filter}
              group by c.post_id
            )
            select
              count(*)::bigint as posts_scanned,
              coalesce(
                sum(case when coalesce(cc.saved_comments, 0) < p.reported_comments then 1 else 0 end),
                0
              )::bigint as stale_posts_count,
              coalesce(sum(coalesce(cc.saved_comments, 0)), 0)::bigint as saved_comments,
              coalesce(sum(p.reported_comments), 0)::bigint as reported_comments
            from posts p
            left join comment_counts cc on cc.post_id = p.id
            """,
                params,
            )
            or {}
        )
    elif platform == "tiktok":
        account_filter = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(account_handles_list)
        row = (
            pg.fetch_one(
                f"""
            with posts as (
              select
                p.id,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.tiktok_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter}
            ), comment_counts as (
              select c.post_id, count(*)::bigint as saved_comments
              from social.tiktok_comments c
              join posts p on p.id = c.post_id
              where true
                {tiktok_active_filter}
              group by c.post_id
            )
            select
              count(*)::bigint as posts_scanned,
              coalesce(
                sum(case when coalesce(cc.saved_comments, 0) < p.reported_comments then 1 else 0 end),
                0
              )::bigint as stale_posts_count,
              coalesce(sum(coalesce(cc.saved_comments, 0)), 0)::bigint as saved_comments,
              coalesce(sum(p.reported_comments), 0)::bigint as reported_comments
            from posts p
            left join comment_counts cc on cc.post_id = p.id
            """,
                params,
            )
            or {}
        )
    elif platform == "youtube":
        account_filter = (
            "and ltrim(lower(coalesce(nullif(v.channel_title, ''), nullif(v.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(account_handles_list)
        row = (
            pg.fetch_one(
                f"""
            with posts as (
              select
                v.id,
                greatest(0, coalesce(v.comments_count, 0))::bigint as reported_comments
              from social.youtube_videos v
              where v.season_id = %s
                and v.published_at >= %s
                and v.published_at <= %s
                {account_filter}
            ), comment_counts as (
              select c.video_id as post_id, count(*)::bigint as saved_comments
              from social.youtube_comments c
              join posts p on p.id = c.video_id
              where true
                {youtube_active_filter}
              group by c.video_id
            )
            select
              count(*)::bigint as posts_scanned,
              coalesce(
                sum(case when coalesce(cc.saved_comments, 0) < p.reported_comments then 1 else 0 end),
                0
              )::bigint as stale_posts_count,
              coalesce(sum(coalesce(cc.saved_comments, 0)), 0)::bigint as saved_comments,
              coalesce(sum(p.reported_comments), 0)::bigint as reported_comments
            from posts p
            left join comment_counts cc on cc.post_id = p.id
            """,
                params,
            )
            or {}
        )
    elif platform == "twitter":
        if apply_account_filter:
            row = (
                pg.fetch_one(
                    f"""
                with recursive posts as (
                  select
                    t.tweet_id,
                    greatest(0, coalesce(t.replies_count, 0))::bigint as reported_replies,
                    greatest(0, coalesce(t.quotes, 0))::bigint as reported_quotes,
                    greatest(0, coalesce(t.replies_count, 0) + coalesce(t.quotes, 0))::bigint as reported_comments
                  from social.twitter_tweets t
                  where t.season_id = %s
                    and t.is_reply = false
                    and t.created_at >= %s
                    and t.created_at <= %s
                    and ltrim(lower(coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '')), '@') = any(%s)
                ), thread_replies as (
                  select
                    r.tweet_id,
                    r.reply_to_tweet_id as root_tweet_id
                  from social.twitter_tweets r
                  where r.season_id = %s
                    and r.is_reply = true
                    {twitter_reply_active_filter_r}
                    and r.reply_to_tweet_id in (select tweet_id from posts)
                  union
                  select
                    child.tweet_id,
                    parent.root_tweet_id
                  from social.twitter_tweets child
                  join thread_replies parent on child.reply_to_tweet_id = parent.tweet_id
                  where child.season_id = %s
                    and child.is_reply = true
                    {twitter_reply_active_filter_child}
                ), reply_counts as (
                  select root_tweet_id, count(*)::bigint as saved_comments
                  from thread_replies
                  group by root_tweet_id
                ), quote_counts as (
                  select
                    q.quoted_tweet_id as root_tweet_id,
                    count(*)::bigint as saved_quotes
                  from social.twitter_tweets q
                  where q.season_id = %s
                    and q.is_quote = true
                    {twitter_quote_active_filter_q}
                    and q.quoted_tweet_id in (select tweet_id from posts)
                  group by q.quoted_tweet_id
                ), combined_counts as (
                  select
                    p.tweet_id,
                    coalesce(rc.saved_comments, 0)::bigint as saved_replies,
                    coalesce(qc.saved_quotes, 0)::bigint as saved_quotes,
                    (coalesce(rc.saved_comments, 0) + coalesce(qc.saved_quotes, 0))::bigint as saved_interactions
                  from posts p
                  left join reply_counts rc on rc.root_tweet_id = p.tweet_id
                  left join quote_counts qc on qc.root_tweet_id = p.tweet_id
                )
                select
                  count(*)::bigint as posts_scanned,
                  coalesce(
                    sum(case when coalesce(cc.saved_interactions, 0) < p.reported_comments then 1 else 0 end),
                    0
                  )::bigint as stale_posts_count,
                  coalesce(sum(coalesce(cc.saved_interactions, 0)), 0)::bigint as saved_comments,
                  coalesce(sum(p.reported_comments), 0)::bigint as reported_comments,
                  coalesce(sum(p.reported_replies), 0)::bigint as reported_replies,
                  coalesce(sum(p.reported_quotes), 0)::bigint as reported_quotes,
                  coalesce(sum(coalesce(cc.saved_replies, 0)), 0)::bigint as saved_replies,
                  coalesce(sum(coalesce(cc.saved_quotes, 0)), 0)::bigint as saved_quotes
                from posts p
                left join combined_counts cc on cc.tweet_id = p.tweet_id
                """,
                    [season_id, start_dt, end_dt, account_handles_list, season_id, season_id, season_id],
                )
                or {}
            )
        else:
            row = (
                pg.fetch_one(
                    f"""
                with posts as (
                  select
                    t.tweet_id,
                    greatest(0, coalesce(t.replies_count, 0))::bigint as reported_replies,
                    greatest(0, coalesce(t.quotes, 0))::bigint as reported_quotes,
                    greatest(0, coalesce(t.replies_count, 0) + coalesce(t.quotes, 0))::bigint as reported_comments
                  from social.twitter_tweets t
                  where t.season_id = %s
                    and t.is_reply = false
                    and t.created_at >= %s
                    and t.created_at <= %s
                ), reply_counts as (
                  select t.reply_to_tweet_id as root_tweet_id, count(*)::bigint as saved_comments
                  from social.twitter_tweets t
                  where t.season_id = %s
                    and t.is_reply = true
                    {twitter_reply_active_filter_t}
                    and t.reply_to_tweet_id in (select tweet_id from posts)
                  group by t.reply_to_tweet_id
                ), quote_counts as (
                  select q.quoted_tweet_id as root_tweet_id, count(*)::bigint as saved_quotes
                  from social.twitter_tweets q
                  where q.season_id = %s
                    and q.is_quote = true
                    {twitter_quote_active_filter_q}
                    and q.quoted_tweet_id in (select tweet_id from posts)
                  group by q.quoted_tweet_id
                ), combined_counts as (
                  select
                    p.tweet_id,
                    coalesce(rc.saved_comments, 0)::bigint as saved_replies,
                    coalesce(qc.saved_quotes, 0)::bigint as saved_quotes,
                    (coalesce(rc.saved_comments, 0) + coalesce(qc.saved_quotes, 0))::bigint as saved_interactions
                  from posts p
                  left join reply_counts rc on rc.root_tweet_id = p.tweet_id
                  left join quote_counts qc on qc.root_tweet_id = p.tweet_id
                )
                select
                  count(*)::bigint as posts_scanned,
                  coalesce(
                    sum(case when coalesce(cc.saved_interactions, 0) < p.reported_comments then 1 else 0 end),
                    0
                  )::bigint as stale_posts_count,
                  coalesce(sum(coalesce(cc.saved_interactions, 0)), 0)::bigint as saved_comments,
                  coalesce(sum(p.reported_comments), 0)::bigint as reported_comments,
                  coalesce(sum(p.reported_replies), 0)::bigint as reported_replies,
                  coalesce(sum(p.reported_quotes), 0)::bigint as reported_quotes,
                  coalesce(sum(coalesce(cc.saved_replies, 0)), 0)::bigint as saved_replies,
                  coalesce(sum(coalesce(cc.saved_quotes, 0)), 0)::bigint as saved_quotes
                from posts p
                left join combined_counts cc on cc.tweet_id = p.tweet_id
                """,
                    [season_id, start_dt, end_dt, season_id, season_id],
                )
                or {}
            )
    elif platform == "facebook":
        account_filter = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(account_handles_list)
        row = (
            pg.fetch_one(
                f"""
            with posts as (
              select
                p.id,
                greatest(0, coalesce(p.comments_count, 0))::bigint as reported_comments
              from social.facebook_posts p
              where p.season_id = %s
                and p.posted_at >= %s
                and p.posted_at <= %s
                {account_filter}
            ), comment_counts as (
              select c.post_id, count(*)::bigint as saved_comments
              from social.facebook_comments c
              join posts p on p.id = c.post_id
              where true
                {facebook_active_filter}
              group by c.post_id
            )
            select
              count(*)::bigint as posts_scanned,
              coalesce(
                sum(case when coalesce(cc.saved_comments, 0) < p.reported_comments then 1 else 0 end),
                0
              )::bigint as stale_posts_count,
              coalesce(sum(coalesce(cc.saved_comments, 0)), 0)::bigint as saved_comments,
              coalesce(sum(p.reported_comments), 0)::bigint as reported_comments
            from posts p
            left join comment_counts cc on cc.post_id = p.id
            """,
                params,
            )
            or {}
        )
    elif platform == "threads":
        account_filter = (
            "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
            if apply_account_filter
            else ""
        )
        params = [season_id, start_dt, end_dt]
        if apply_account_filter:
            params.append(account_handles_list)
        posts = pg.fetch_all(
            f"""
            select
              p.id::text as id,
              greatest(0, coalesce(p.replies_count, 0))::bigint as reported_replies,
              greatest(0, coalesce(p.quotes, 0))::bigint as reported_quotes,
              greatest(0, coalesce(p.replies_count, 0) + coalesce(p.quotes, 0))::bigint as reported_comments,
              p.text,
              coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data
            from social.meta_threads_posts p
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
              {account_filter}
            """,
            params,
        )
        context = season_context
        if _threads_should_enforce_rhoslc_relevance(context=context):
            hashtags, keywords = _threads_build_relevance_terms(
                season_id,
                source_scope=source_scope,
                context=context,
            )
            posts = [
                post
                for post in posts
                if _threads_text_topic_match(
                    text=post.get("text"),
                    raw_data=post.get("raw_data"),
                    hashtags=hashtags,
                    keywords=keywords,
                )
            ]
        post_ids = [str(post.get("id") or "").strip() for post in posts if str(post.get("id") or "").strip()]
        interaction_counts = _count_stored_threads_interactions(post_ids) if post_ids else {}
        posts_scanned = len(post_ids)
        reported_comments = 0
        saved_comments = 0
        reported_replies = 0
        saved_replies = 0
        reported_quotes = 0
        saved_quotes = 0
        stale_posts_count = 0
        for post in posts:
            post_id = str(post.get("id") or "").strip()
            if not post_id:
                continue
            reported = int(post.get("reported_comments") or 0)
            reported_reply_count = int(post.get("reported_replies") or 0)
            reported_quote_count = int(post.get("reported_quotes") or 0)
            interaction_payload = interaction_counts.get(post_id) or {}
            saved = int(interaction_payload.get("total") or 0)
            saved_reply_count = int(interaction_payload.get("replies") or 0)
            saved_quote_count = int(interaction_payload.get("quotes") or 0)
            reported_comments += reported
            saved_comments += saved
            reported_replies += reported_reply_count
            saved_replies += saved_reply_count
            reported_quotes += reported_quote_count
            saved_quotes += saved_quote_count
            if saved < reported:
                stale_posts_count += 1
        row = {
            "posts_scanned": posts_scanned,
            "stale_posts_count": stale_posts_count,
            "saved_comments": saved_comments,
            "reported_comments": reported_comments,
            "saved_replies": saved_replies,
            "reported_replies": reported_replies,
            "saved_quotes": saved_quotes,
            "reported_quotes": reported_quotes,
        }
    else:
        row = {}

    return {
        "posts_scanned": int(row.get("posts_scanned") or 0),
        "stale_posts_count": int(row.get("stale_posts_count") or 0),
        "saved_comments": int(row.get("saved_comments") or 0),
        "reported_comments": int(row.get("reported_comments") or 0),
        "saved_replies": int(row.get("saved_replies") or 0),
        "reported_replies": int(row.get("reported_replies") or 0),
        "saved_quotes": int(row.get("saved_quotes") or 0),
        "reported_quotes": int(row.get("reported_quotes") or 0),
    }


def get_comments_coverage(
    season_id: str,
    *,
    platforms: list[str] | None,
    timezone: str,
    source_scope: str,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> dict[str, Any]:
    context = get_season_context(season_id)
    available_platforms = _resolve_requested_platforms(platforms)

    start_dt, end_dt, now_utc = _resolve_coverage_window(
        context=context,
        timezone=timezone,
        source_scope=source_scope,
        date_start=date_start,
        date_end=date_end,
    )

    target_accounts_by_platform = _target_accounts_by_platform(
        season_id,
        source_scope=source_scope,
        context=context,
    )
    active_job_status_by_platform = _active_job_status_by_platform_for_coverage_window(
        context=context,
        timezone=timezone,
        source_scope=source_scope,
        start_dt=start_dt,
        end_dt=end_dt,
        now_utc=now_utc,
        platforms=available_platforms,
    )

    by_platform: dict[str, dict[str, Any]] = {}
    total_saved = 0
    total_reported = 0
    total_stale_posts = 0
    total_posts = 0
    for platform in available_platforms:
        stats = _comments_coverage_for_platform(
            season_id,
            platform=platform,
            start_dt=start_dt,
            end_dt=end_dt,
            source_scope=source_scope,
            target_accounts_by_platform=target_accounts_by_platform,
            season_context=context,
        )
        saved = int(stats.get("saved_comments") or 0)
        reported = int(stats.get("reported_comments") or 0)
        stale_posts = int(stats.get("stale_posts_count") or 0)
        posts_scanned = int(stats.get("posts_scanned") or 0)
        total_saved += saved
        total_reported += reported
        total_stale_posts += stale_posts
        total_posts += posts_scanned
        comment_sync_status = _build_comment_sync_status(
            expected_count=reported,
            fetched_count=saved,
            upserted_count=saved,
            stale_posts_count=stale_posts,
            failure_reason=_platform_failure_reason(platform, "comment_gap")
            if stale_posts > 0 or saved < reported
            else None,
            attempted=posts_scanned > 0,
        )
        media_mirror_status = _build_media_mirror_status(
            source_count=0,
            mirrored_count=0,
            not_needed=True,
        )
        by_platform[platform] = {
            "saved_comments": saved,
            "reported_comments": reported,
            "coverage_pct": _safe_percent(saved, reported),
            "up_to_date": saved >= reported,
            "stale_posts_count": stale_posts,
            "posts_scanned": posts_scanned,
            "saved_replies": int(stats.get("saved_replies") or 0),
            "reported_replies": int(stats.get("reported_replies") or 0),
            "reply_coverage_pct": _safe_percent(
                int(stats.get("saved_replies") or 0),
                int(stats.get("reported_replies") or 0),
            ),
            "saved_quotes": int(stats.get("saved_quotes") or 0),
            "reported_quotes": int(stats.get("reported_quotes") or 0),
            "quote_coverage_pct": _safe_percent(
                int(stats.get("saved_quotes") or 0),
                int(stats.get("reported_quotes") or 0),
            ),
            **_overlay_platform_status_with_active_jobs(
                _build_platform_status_payload(
                    posts_scanned=posts_scanned,
                    comment_sync_status=comment_sync_status,
                    media_mirror_status=media_mirror_status,
                    last_refresh_at=None,
                    last_refresh_reason=None,
                    active_job_summary=active_job_status_by_platform.get(platform),
                ),
                active_job_status=active_job_status_by_platform.get(platform),
            ),
        }

    total_comment_sync_status = _build_comment_sync_status(
        expected_count=total_reported,
        fetched_count=total_saved,
        upserted_count=total_saved,
        stale_posts_count=total_stale_posts,
        failure_reason="comment_gap" if total_stale_posts > 0 or total_saved < total_reported else None,
        attempted=total_posts > 0,
    )
    total_media_status = _build_media_mirror_status(
        source_count=0,
        mirrored_count=0,
        not_needed=True,
    )
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "platforms": available_platforms,
        "window": {
            "start": _iso(start_dt),
            "end": _iso(end_dt),
            "timezone": timezone,
        },
        "total_saved_comments": total_saved,
        "total_reported_comments": total_reported,
        "coverage_pct": _safe_percent(total_saved, total_reported),
        "up_to_date": total_saved >= total_reported,
        "stale_posts_count": total_stale_posts,
        "posts_scanned": total_posts,
        "by_platform": by_platform,
        "evaluated_at": _iso(now_utc),
        **_build_platform_status_payload(
            posts_scanned=total_posts,
            comment_sync_status=total_comment_sync_status,
            media_mirror_status=total_media_status,
            last_refresh_at=None,
            last_refresh_reason=None,
        ),
    }


def _resolve_coverage_window(
    *,
    context: SeasonContext,
    timezone: str,
    source_scope: str,
    date_start: datetime | None,
    date_end: datetime | None,
) -> tuple[datetime, datetime, datetime]:
    now_utc = _now_utc()
    if date_start is None and date_end is None:
        _, week_zero_start_local = _resolve_week_windows(
            context,
            timezone=timezone,
            source_scope=source_scope,
            now_utc=now_utc,
        )
        start_dt = week_zero_start_local.astimezone(UTC)
        end_dt = now_utc
    else:
        start_dt = _coerce_dt(date_start)
        if start_dt is None:
            start_dt = datetime.combine(context.anchor_date, time.min, tzinfo=UTC)
        end_dt = _coerce_dt(date_end) or now_utc
    if end_dt < start_dt:
        end_dt = start_dt
    return start_dt, end_dt, now_utc


def _normalize_sync_status_label(value: str | None) -> str:
    normalized = str(value or "").strip().lower()
    return normalized or "idle"


def _is_active_sync_status(value: Any) -> bool:
    return _normalize_sync_status_label(str(value or "")) in {"queued", "running"}


def _platform_failure_reason(platform: str, reason: str | None) -> str | None:
    normalized_platform = str(platform or "").strip().lower()
    normalized_reason = str(reason or "").strip().lower()
    if not normalized_platform or not normalized_reason:
        return None
    if normalized_reason.startswith(f"{normalized_platform}_"):
        return normalized_reason
    return f"{normalized_platform}_{normalized_reason}"


def _derive_media_failure_reason(
    platform: str,
    *,
    post_failed_count: int = 0,
    post_partial_count: int = 0,
    post_pending_count: int = 0,
    comment_failed_count: int = 0,
    comment_pending_count: int = 0,
) -> str | None:
    normalized_platform = str(platform or "").strip().lower()
    if not normalized_platform:
        return None
    if post_failed_count > 0 and comment_failed_count > 0:
        return f"{normalized_platform}_post_and_comment_media_mirror_failed"
    if post_failed_count > 0:
        return f"{normalized_platform}_post_media_mirror_failed"
    if comment_failed_count > 0:
        return f"{normalized_platform}_comment_media_mirror_failed"
    if post_partial_count > 0 and comment_pending_count > 0:
        return f"{normalized_platform}_post_and_comment_media_mirror_gap"
    if post_partial_count > 0 or post_pending_count > 0:
        return f"{normalized_platform}_post_media_mirror_gap"
    if comment_pending_count > 0:
        return f"{normalized_platform}_comment_media_mirror_gap"
    return None


def _build_comment_sync_status(
    *,
    expected_count: int,
    fetched_count: int,
    upserted_count: int,
    stale_posts_count: int = 0,
    failure_reason: str | None = None,
    attempted: bool | None = None,
    active_status: str | None = None,
) -> dict[str, Any]:
    normalized_failure_reason = str(failure_reason or "").strip() or None
    normalized_active_status = _normalize_sync_status_label(active_status)
    if normalized_active_status in {"queued", "running"}:
        status = normalized_active_status
    elif expected_count <= 0 and upserted_count <= 0 and fetched_count <= 0:
        if attempted is False:
            status = "not_attempted"
        elif attempted is True:
            status = "unknown"
        else:
            status = "idle"
    elif normalized_failure_reason and upserted_count <= 0:
        status = "failed"
    elif normalized_failure_reason or stale_posts_count > 0 or upserted_count < max(expected_count, fetched_count):
        status = "partial"
    else:
        status = "complete"
    return {
        "status": status,
        "expected_count": max(0, int(expected_count)),
        "fetched_count": max(0, int(fetched_count)),
        "upserted_count": max(0, int(upserted_count)),
        "failure_reason": normalized_failure_reason,
    }


def _build_media_mirror_status(
    *,
    source_count: int,
    mirrored_count: int,
    failed_count: int = 0,
    pending_count: int = 0,
    partial_count: int = 0,
    last_job_id: str | None = None,
    not_needed: bool = False,
    attempted: bool | None = None,
    active_status: str | None = None,
    failure_reason: str | None = None,
) -> dict[str, Any]:
    normalized_last_job_id = str(last_job_id or "").strip() or None
    normalized_source_count = max(0, int(source_count))
    normalized_mirrored_count = max(0, int(mirrored_count))
    normalized_failed_count = max(0, int(failed_count))
    normalized_pending_count = max(0, int(pending_count))
    normalized_partial_count = max(0, int(partial_count))
    normalized_active_status = _normalize_sync_status_label(active_status)
    normalized_failure_reason = str(failure_reason or "").strip() or None
    unresolved_count = max(
        normalized_source_count - normalized_mirrored_count,
        normalized_failed_count + normalized_pending_count + normalized_partial_count,
    )
    if normalized_active_status in {"queued", "running"} and not not_needed:
        status = normalized_active_status
    elif not_needed or normalized_source_count <= 0:
        status = "not_needed"
    elif normalized_failed_count > 0 and normalized_mirrored_count <= 0 and unresolved_count >= normalized_source_count:
        status = "failed"
    elif normalized_pending_count > 0 and normalized_mirrored_count <= 0 and normalized_failed_count <= 0:
        status = "pending"
    elif unresolved_count > 0 or normalized_partial_count > 0 or normalized_failed_count > 0:
        status = "partial"
    elif normalized_mirrored_count >= normalized_source_count:
        status = "complete"
    elif attempted is False:
        status = "not_attempted"
    else:
        status = "unknown"
    return {
        "status": status,
        "source_count": normalized_source_count,
        "mirrored_count": normalized_mirrored_count,
        "failed_count": normalized_failed_count,
        "pending_count": normalized_pending_count,
        "partial_count": normalized_partial_count,
        "last_job_id": normalized_last_job_id,
        "failure_reason": normalized_failure_reason,
    }


def _build_platform_sync_status(
    *,
    comment_sync_status: Mapping[str, Any],
    media_mirror_status: Mapping[str, Any],
    has_rows: bool,
    stale: bool,
) -> str:
    comment_status = _normalize_sync_status_label(comment_sync_status.get("status"))
    mirror_status = _normalize_sync_status_label(media_mirror_status.get("status"))
    if comment_status == "running" or mirror_status == "running":
        return "running"
    if comment_status == "queued" or mirror_status in {"queued", "pending"}:
        return "queued"
    if (
        not has_rows
        and comment_status in {"idle", "not_attempted", "unknown"}
        and mirror_status
        in {
            "idle",
            "not_needed",
            "not_attempted",
            "unknown",
        }
    ):
        return "idle"
    if comment_status == "failed":
        return "failed"
    if mirror_status == "failed":
        return "partial" if has_rows and comment_status in {"complete", "idle"} else "failed"
    if stale:
        return "partial"
    if comment_status in {"partial", "not_attempted", "unknown"} or mirror_status in {
        "partial",
        "not_attempted",
        "unknown",
    }:
        return "partial"
    if comment_status in {"complete", "idle"} and mirror_status in {"complete", "not_needed", "idle"}:
        return "complete"
    return "partial" if has_rows else "idle"


def _normalize_optional_iso_timestamp(value: Any) -> str | None:
    return _iso(_coerce_dt(value))


def _extract_last_platform_job_id(posts: list[Mapping[str, Any]]) -> str | None:
    for post in posts:
        for key in ("media_mirror_last_job_id", "worker_run_id"):
            value = str(post.get(key) or "").strip()
            if value:
                return value
        status = post.get("status")
        if isinstance(status, Mapping):
            value = str(status.get("worker_run_id") or "").strip()
            if value:
                return value
    return None


def _extract_last_platform_refresh_at(posts: list[Mapping[str, Any]]) -> str | None:
    latest_dt: datetime | None = None
    for post in posts:
        status = post.get("status")
        if isinstance(status, Mapping):
            parsed = _coerce_dt(status.get("last_refresh_at"))
            if parsed and (latest_dt is None or parsed > latest_dt):
                latest_dt = parsed
        for key in ("media_mirror_last_attempt_at", "comment_refresh_at", "last_refresh_at"):
            parsed = _coerce_dt(post.get(key))
            if parsed and (latest_dt is None or parsed > latest_dt):
                latest_dt = parsed
    return _iso(latest_dt)


def _reason_candidates_for_platform(platform: str, *, category: str) -> set[str]:
    normalized_platform = str(platform or "").strip().lower()
    if not normalized_platform:
        return set()
    if category == "comment":
        return {
            _platform_failure_reason(normalized_platform, "comment_gap") or "",
        }
    if category == "media":
        return {
            reason
            for reason in {
                _derive_media_failure_reason(normalized_platform, post_failed_count=1),
                _derive_media_failure_reason(normalized_platform, comment_failed_count=1),
                _derive_media_failure_reason(normalized_platform, post_failed_count=1, comment_failed_count=1),
                _derive_media_failure_reason(normalized_platform, post_partial_count=1),
                _derive_media_failure_reason(normalized_platform, comment_pending_count=1),
                _derive_media_failure_reason(
                    normalized_platform,
                    post_partial_count=1,
                    comment_pending_count=1,
                ),
            }
            if reason
        }
    return set()


def _prefer_specific_failure_reason(
    current: str | None,
    candidate: str | None,
    *,
    generic_reasons: set[str],
) -> str | None:
    normalized_candidate = str(candidate or "").strip() or None
    if normalized_candidate is None:
        return current
    normalized_current = str(current or "").strip() or None
    if normalized_current is None:
        return normalized_candidate
    current_is_generic = normalized_current in generic_reasons
    candidate_is_generic = normalized_candidate in generic_reasons
    if current_is_generic and not candidate_is_generic:
        return normalized_candidate
    return normalized_current


def _extract_platform_post_failure_reasons(
    platform: str,
    posts: Sequence[Mapping[str, Any]],
) -> dict[str, str | None]:
    comment_generic_reasons = _reason_candidates_for_platform(platform, category="comment")
    media_generic_reasons = _reason_candidates_for_platform(platform, category="media")
    comment_reason: str | None = None
    media_reason: str | None = None
    last_refresh_reason: str | None = None

    for post in posts:
        status = post.get("status")
        if not isinstance(status, Mapping):
            continue
        last_refresh_reason = _prefer_specific_failure_reason(
            last_refresh_reason,
            status.get("last_refresh_reason"),
            generic_reasons=comment_generic_reasons | media_generic_reasons,
        )
        comment_payload = status.get("comment_sync_status")
        if isinstance(comment_payload, Mapping):
            comment_reason = _prefer_specific_failure_reason(
                comment_reason,
                comment_payload.get("failure_reason"),
                generic_reasons=comment_generic_reasons,
            )
        media_payload = status.get("media_mirror_status")
        if isinstance(media_payload, Mapping):
            media_reason = _prefer_specific_failure_reason(
                media_reason,
                media_payload.get("failure_reason"),
                generic_reasons=media_generic_reasons,
            )
        if comment_reason and media_reason and last_refresh_reason:
            break

    return {
        "comment_failure_reason": comment_reason,
        "media_failure_reason": media_reason,
        "last_refresh_reason": last_refresh_reason,
    }


def _build_active_job_summary(active_job_status: Mapping[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(active_job_status, Mapping):
        return None
    sync_status = _canonicalize_week_job_live_status(active_job_status.get("sync_status"))
    if not sync_status:
        return None
    stage_statuses: dict[str, dict[str, Any]] = {}
    stage_statuses_raw = active_job_status.get("stage_statuses")
    if isinstance(stage_statuses_raw, Mapping):
        for stage, payload in stage_statuses_raw.items():
            normalized_stage = _normalize_social_job_stage_for_stale(stage)
            if not normalized_stage or not isinstance(payload, Mapping):
                continue
            stage_statuses[normalized_stage] = {
                "status": _canonicalize_week_job_live_status(payload.get("status")) or sync_status,
                "job_count": max(0, int(payload.get("job_count") or 0)),
            }
    return {
        "sync_status": sync_status,
        "dominant_stage": _normalize_social_job_stage_for_stale(active_job_status.get("dominant_stage")) or None,
        "job_count": max(0, int(active_job_status.get("job_count") or 0)),
        "stage_statuses": stage_statuses,
    }


def _build_platform_status_payload(
    *,
    posts_scanned: int,
    comment_sync_status: Mapping[str, Any],
    media_mirror_status: Mapping[str, Any],
    last_refresh_at: str | None,
    last_refresh_reason: str | None,
    worker_run_id: str | None = None,
    active_job_summary: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    stale = int(comment_sync_status.get("expected_count") or 0) > int(
        comment_sync_status.get("upserted_count") or 0
    ) or int(media_mirror_status.get("source_count") or 0) > int(media_mirror_status.get("mirrored_count") or 0)
    normalized_active_job_summary = _build_active_job_summary(active_job_summary)
    if normalized_active_job_summary is not None:
        stale = False
    normalized_last_refresh_reason = (
        str(last_refresh_reason or "").strip()
        or str(comment_sync_status.get("failure_reason") or "").strip()
        or str(media_mirror_status.get("failure_reason") or "").strip()
        or None
    )
    payload = {
        "sync_status": _build_platform_sync_status(
            comment_sync_status=comment_sync_status,
            media_mirror_status=media_mirror_status,
            has_rows=posts_scanned > 0,
            stale=stale,
        ),
        "comment_sync_status": dict(comment_sync_status),
        "media_mirror_status": dict(media_mirror_status),
        "last_refresh_at": last_refresh_at,
        "last_refresh_reason": normalized_last_refresh_reason,
        "stale": stale,
        "worker_run_id": str(worker_run_id or "").strip() or None,
        "active_job_summary": normalized_active_job_summary,
    }
    if normalized_active_job_summary is not None:
        return _overlay_platform_status_with_active_jobs(payload, active_job_status=normalized_active_job_summary)
    return payload


_ACTIVE_WEEK_RUN_JOB_STATUSES = ("queued", "pending", "retrying", "running")
_ACTIVE_WEEK_RUN_STAGE_PRIORITY = {
    "posts": 0,
    "comments": 1,
    "media_mirror": 2,
    "comment_media_mirror": 3,
}


def _resolve_week_run_row(season_id: str, *, source_scope: str, week_index: int) -> dict[str, Any] | None:
    if not _relation_exists("social.scrape_runs"):
        return None
    return pg.fetch_one(
        """
        select
          id::text as run_id,
          status
        from social.scrape_runs
        where season_id = %s
          and source_scope = %s
          and (
            (
              coalesce(config->>'week_index', '') ~ '^[0-9]+$'
              and (config->>'week_index')::int = %s
            )
            or (
              coalesce(config->>'orchestration_week_index', '') ~ '^[0-9]+$'
              and (config->>'orchestration_week_index')::int = %s
            )
          )
        order by
          case
            when status in ('queued', 'pending', 'retrying', 'running') then 0
            when status = 'completed' then 1
            else 2
          end,
          created_at desc
        limit 1
        """,
        [season_id, source_scope, week_index, week_index],
    )


def _resolve_week_run_rows_by_platform(
    season_id: str,
    *,
    source_scope: str,
    week_index: int,
    platforms: Sequence[str] | None = None,
) -> dict[str, dict[str, Any]]:
    normalized_platforms = sorted(
        {str(platform or "").strip().lower() for platform in (platforms or []) if str(platform or "").strip()}
    )
    if not _relation_exists("social.scrape_runs"):
        return {}
    if not _relation_exists("social.scrape_jobs"):
        fallback = _resolve_week_run_row(season_id, source_scope=source_scope, week_index=week_index)
        if not fallback or not normalized_platforms:
            return {}
        return {platform: dict(fallback) for platform in normalized_platforms}

    platform_filter = "and lower(coalesce(j.platform, '')) = any(%s)" if normalized_platforms else ""
    params: list[Any] = [season_id, source_scope]
    if normalized_platforms:
        params.append(normalized_platforms)
    params.extend([week_index, week_index, week_index, week_index])
    rows = pg.fetch_all(
        f"""
        with candidate_runs as (
          select distinct
            lower(coalesce(j.platform, '')) as platform,
            r.id::text as run_id,
            lower(coalesce(r.status, '')) as status,
            r.created_at
          from social.scrape_runs r
          join social.scrape_jobs j on j.run_id = r.id
          where r.season_id = %s
            and r.source_scope = %s
            and lower(coalesce(j.platform, '')) <> ''
            {platform_filter}
            and (
              (
                coalesce(r.config->>'week_index', '') ~ '^[0-9]+$'
                and (r.config->>'week_index')::int = %s
              )
              or (
                coalesce(r.config->>'orchestration_week_index', '') ~ '^[0-9]+$'
                and (r.config->>'orchestration_week_index')::int = %s
              )
              or (
                coalesce(j.config->>'week_index', '') ~ '^[0-9]+$'
                and (j.config->>'week_index')::int = %s
              )
              or (
                coalesce(j.config->>'orchestration_week_index', '') ~ '^[0-9]+$'
                and (j.config->>'orchestration_week_index')::int = %s
              )
            )
        )
        select
          platform,
          run_id,
          status
        from (
          select
            platform,
            run_id,
            status,
            row_number() over (
              partition by platform
              order by
                case
                  when status in ('queued', 'pending', 'retrying', 'running') then 0
                  when status = 'completed' then 1
                  else 2
                end,
                created_at desc,
                run_id desc
            ) as rn
          from candidate_runs
        ) ranked
        where rn = 1
        """,
        params,
    )
    resolved: dict[str, dict[str, Any]] = {}
    for row in rows:
        platform = str(row.get("platform") or "").strip().lower()
        run_id = str(row.get("run_id") or "").strip()
        if not platform or not run_id:
            continue
        resolved[platform] = {
            "run_id": run_id,
            "status": str(row.get("status") or "").strip().lower() or None,
        }
    return resolved


def _canonicalize_week_job_live_status(value: Any) -> str:
    normalized = str(value or "").strip().lower()
    if normalized == "running":
        return "running"
    if normalized in {"queued", "pending", "retrying"}:
        return "queued"
    return ""


def _active_week_job_status_by_platform(
    run_id: str | None,
    *,
    source_scope: str,
    week_index: int,
    platforms: Sequence[str],
    run_rows_by_platform: Mapping[str, Mapping[str, Any]] | None = None,
) -> dict[str, dict[str, Any]]:
    normalized_platforms = sorted(
        {str(platform or "").strip().lower() for platform in platforms if str(platform or "").strip()}
    )
    if not normalized_platforms or not _relation_exists("social.scrape_jobs"):
        return {}
    run_ids_by_platform: dict[str, str] = {}
    if isinstance(run_rows_by_platform, Mapping):
        for platform, row in run_rows_by_platform.items():
            normalized_platform = str(platform or "").strip().lower()
            normalized_run_id = str((row or {}).get("run_id") or "").strip()
            if normalized_platform and normalized_run_id:
                run_ids_by_platform[normalized_platform] = normalized_run_id
    normalized_run_id = str(run_id or "").strip()
    if normalized_run_id:
        for platform in normalized_platforms:
            run_ids_by_platform.setdefault(platform, normalized_run_id)
    if not run_ids_by_platform:
        return {}
    normalized_run_ids = sorted({value for value in run_ids_by_platform.values() if value})

    rows = pg.fetch_all(
        """
        select
          lower(coalesce(j.platform, '')) as platform,
          lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) as stage,
          lower(coalesce(j.status, '')) as status,
          count(*)::int as job_count
        from social.scrape_jobs j
        where j.run_id = any(%s::uuid[])
          and j.source_scope = %s
          and lower(coalesce(j.platform, '')) = any(%s)
          and j.status = any(%s)
          and (
            (
              coalesce(j.config->>'week_index', '') ~ '^[0-9]+$'
              and (j.config->>'week_index')::int = %s
            )
            or (
              coalesce(j.config->>'orchestration_week_index', '') ~ '^[0-9]+$'
              and (j.config->>'orchestration_week_index')::int = %s
            )
          )
        group by 1, 2, 3
        """,
        [
            normalized_run_ids,
            source_scope,
            normalized_platforms,
            list(_ACTIVE_WEEK_RUN_JOB_STATUSES),
            week_index,
            week_index,
        ],
    )
    by_platform: dict[str, dict[str, Any]] = {}
    for row in rows:
        platform = str(row.get("platform") or "").strip().lower()
        stage = _normalize_social_job_stage_for_stale(row.get("stage"))
        live_status = _canonicalize_week_job_live_status(row.get("status"))
        job_count = max(0, int(row.get("job_count") or 0))
        if not platform or not stage or not live_status or job_count <= 0:
            continue
        platform_entry = by_platform.setdefault(
            platform,
            {
                "sync_status": "queued",
                "job_count": 0,
                "dominant_stage": None,
                "stage_statuses": {},
            },
        )
        platform_entry["job_count"] = int(platform_entry.get("job_count") or 0) + job_count
        platform_is_running = str(platform_entry.get("sync_status") or "").strip().lower() == "running"
        if live_status == "running":
            platform_entry["sync_status"] = "running"
        stage_statuses = platform_entry["stage_statuses"]
        stage_entry = stage_statuses.setdefault(stage, {"status": live_status, "job_count": 0})
        stage_entry["job_count"] = int(stage_entry.get("job_count") or 0) + job_count
        if live_status == "running":
            stage_entry["status"] = "running"
        dominant_stage = str(platform_entry.get("dominant_stage") or "").strip().lower() or None
        candidate_priority = _ACTIVE_WEEK_RUN_STAGE_PRIORITY.get(stage, 99)
        current_priority = _ACTIVE_WEEK_RUN_STAGE_PRIORITY.get(dominant_stage or "", 99)
        if dominant_stage is None:
            platform_entry["dominant_stage"] = stage
        elif live_status == "running":
            if (not platform_is_running) or candidate_priority < current_priority:
                platform_entry["dominant_stage"] = stage
        elif platform_entry["sync_status"] != "running" and candidate_priority < current_priority:
            platform_entry["dominant_stage"] = stage

    for _platform, entry in by_platform.items():
        stage = str(entry.get("dominant_stage") or "").strip().lower()
        sync_status = str(entry.get("sync_status") or "queued").strip().lower() or "queued"
        entry["last_refresh_reason"] = f"{stage}_{sync_status}" if stage else f"sync_{sync_status}"
        entry["worker_run_id"] = run_ids_by_platform.get(_platform) or normalized_run_id
    return by_platform


def _primary_week_run_id(run_rows_by_platform: Mapping[str, Mapping[str, Any]]) -> str | None:
    active_candidates: list[str] = []
    fallback_candidates: list[str] = []
    for platform in sorted(run_rows_by_platform):
        row = run_rows_by_platform.get(platform) or {}
        run_id = str(row.get("run_id") or "").strip()
        if not run_id:
            continue
        if str(row.get("status") or "").strip().lower() in _ACTIVE_WEEK_RUN_JOB_STATUSES:
            active_candidates.append(run_id)
        else:
            fallback_candidates.append(run_id)
    if active_candidates:
        return active_candidates[0]
    if fallback_candidates:
        return fallback_candidates[0]
    return None


def _overlay_platform_status_with_active_jobs(
    status_payload: Mapping[str, Any],
    *,
    active_job_status: Mapping[str, Any] | None,
) -> dict[str, Any]:
    payload = dict(status_payload)
    active_job_summary = _build_active_job_summary(active_job_status)
    if active_job_summary is None:
        return payload

    sync_status = _canonicalize_week_job_live_status(active_job_summary.get("sync_status"))
    if not sync_status:
        return payload

    payload["sync_status"] = sync_status
    payload["stale"] = False
    payload["active_job_summary"] = active_job_summary
    payload["last_refresh_reason"] = str(active_job_status.get("last_refresh_reason") or "").strip() or payload.get(
        "last_refresh_reason"
    )
    payload["worker_run_id"] = str(active_job_status.get("worker_run_id") or "").strip() or payload.get("worker_run_id")

    stage_statuses = active_job_summary.get("stage_statuses")
    if isinstance(stage_statuses, Mapping):
        comments_stage = stage_statuses.get("comments")
        if isinstance(comments_stage, Mapping) and isinstance(payload.get("comment_sync_status"), Mapping):
            comment_sync = dict(payload["comment_sync_status"])
            if _normalize_sync_status_label(comment_sync.get("status")) != "complete":
                comment_sync["status"] = _canonicalize_week_job_live_status(comments_stage.get("status")) or sync_status
                payload["comment_sync_status"] = comment_sync
        mirror_stage = stage_statuses.get("media_mirror") or stage_statuses.get("comment_media_mirror")
        if isinstance(mirror_stage, Mapping) and isinstance(payload.get("media_mirror_status"), Mapping):
            mirror_status = dict(payload["media_mirror_status"])
            if _normalize_sync_status_label(mirror_status.get("status")) != "complete":
                mirror_status["status"] = _canonicalize_week_job_live_status(mirror_stage.get("status")) or sync_status
                payload["media_mirror_status"] = mirror_status
    return payload


def _active_job_status_by_platform_for_coverage_window(
    *,
    context: SeasonContext,
    timezone: str,
    source_scope: str,
    start_dt: datetime,
    end_dt: datetime,
    now_utc: datetime,
    platforms: Sequence[str],
) -> dict[str, dict[str, Any]]:
    try:
        coverage_week_index = _week_index_for_coverage_window(
            context=context,
            timezone=timezone,
            source_scope=source_scope,
            start_dt=start_dt,
            end_dt=end_dt,
            now_utc=now_utc,
        )
    except Exception:
        logger.debug(
            "Unable to resolve coverage week window for season=%s source_scope=%s",
            context.season_id,
            source_scope,
            exc_info=True,
        )
        return {}
    if coverage_week_index is None:
        return {}
    try:
        active_week_runs = _resolve_week_run_rows_by_platform(
            context.season_id,
            source_scope=source_scope,
            week_index=coverage_week_index,
            platforms=platforms,
        )
        return _active_week_job_status_by_platform(
            None,
            source_scope=source_scope,
            week_index=coverage_week_index,
            platforms=platforms,
            run_rows_by_platform=active_week_runs,
        )
    except Exception:
        logger.debug(
            "Unable to resolve active coverage jobs for season=%s source_scope=%s week_index=%s",
            context.season_id,
            source_scope,
            coverage_week_index,
            exc_info=True,
        )
        return {}


def _week_index_for_coverage_window(
    *,
    context: SeasonContext,
    timezone: str,
    source_scope: str,
    start_dt: datetime,
    end_dt: datetime,
    now_utc: datetime,
) -> int | None:
    week_windows, _ = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now_utc,
    )
    for window in week_windows:
        candidate_start = window.start_local.astimezone(UTC)
        candidate_end = (window.end_local - timedelta(microseconds=1)).astimezone(UTC)
        if candidate_start == start_dt and candidate_end == end_dt:
            return window.week_index
    return None


def _count_post_source_assets(
    *,
    source_media_urls: list[str] | None,
    hosted_media_urls: list[str] | None,
    source_thumbnail_url: str | None,
    hosted_thumbnail_url: str | None,
) -> tuple[int, int]:
    source_media_count = len(_as_text_list(source_media_urls or []))
    hosted_media_count = min(len(_as_text_list(hosted_media_urls or [])), source_media_count)
    source_count = source_media_count + (1 if str(source_thumbnail_url or "").strip() else 0)
    mirrored_count = hosted_media_count + (1 if str(hosted_thumbnail_url or "").strip() else 0)
    return source_count, mirrored_count


def _infer_post_media_mirror_status(
    *,
    source_media_urls: list[str] | None,
    hosted_media_urls: list[str] | None,
    source_thumbnail_url: str | None,
    hosted_thumbnail_url: str | None,
    stored_status: str | None,
) -> str | None:
    normalized_stored_status = str(stored_status or "").strip() or None
    if normalized_stored_status is not None:
        return normalized_stored_status
    source_count, mirrored_count = _count_post_source_assets(
        source_media_urls=source_media_urls,
        hosted_media_urls=hosted_media_urls,
        source_thumbnail_url=source_thumbnail_url,
        hosted_thumbnail_url=hosted_thumbnail_url,
    )
    if source_count <= 0:
        return "not_needed"
    if mirrored_count >= source_count:
        return "complete"
    if mirrored_count > 0:
        return "partial"
    return None


def _build_post_status_payload(
    *,
    expected_comments: int,
    saved_comments: int,
    source_media_urls: list[str] | None,
    hosted_media_urls: list[str] | None,
    source_thumbnail_url: str | None,
    hosted_thumbnail_url: str | None,
    media_mirror_status: str | None,
    media_mirror_last_job_id: str | None = None,
    last_refresh_at: Any = None,
    last_refresh_reason: str | None = None,
) -> dict[str, Any]:
    source_count, mirrored_count = _count_post_source_assets(
        source_media_urls=source_media_urls,
        hosted_media_urls=hosted_media_urls,
        source_thumbnail_url=source_thumbnail_url,
        hosted_thumbnail_url=hosted_thumbnail_url,
    )
    normalized_media_status = _normalize_sync_status_label(media_mirror_status)
    unresolved_media_count = max(source_count - mirrored_count, 0)
    mirror_failed_count = unresolved_media_count if normalized_media_status == "failed" else 0
    mirror_pending_count = unresolved_media_count if normalized_media_status in {"pending", "queued", "running"} else 0
    mirror_partial_count = unresolved_media_count if normalized_media_status == "partial" else 0
    normalized_last_refresh_reason = str(last_refresh_reason or "").strip() or None
    comment_sync_status = _build_comment_sync_status(
        expected_count=expected_comments,
        fetched_count=saved_comments,
        upserted_count=saved_comments,
        stale_posts_count=1 if saved_comments < expected_comments else 0,
        failure_reason=normalized_last_refresh_reason if saved_comments < expected_comments else None,
        attempted=saved_comments > 0 or expected_comments > 0,
    )
    media_status = _build_media_mirror_status(
        source_count=source_count,
        mirrored_count=mirrored_count,
        failed_count=mirror_failed_count,
        pending_count=mirror_pending_count,
        partial_count=mirror_partial_count,
        last_job_id=media_mirror_last_job_id,
        not_needed=source_count <= 0,
        attempted=source_count > 0,
        failure_reason=normalized_last_refresh_reason if unresolved_media_count > 0 else None,
    )
    return _build_platform_status_payload(
        posts_scanned=1,
        comment_sync_status=comment_sync_status,
        media_mirror_status=media_status,
        last_refresh_at=_normalize_optional_iso_timestamp(last_refresh_at),
        last_refresh_reason=normalized_last_refresh_reason,
        worker_run_id=media_mirror_last_job_id,
    )


def _mirror_coverage_for_platform(
    season_id: str,
    *,
    platform: str,
    start_dt: datetime,
    end_dt: datetime,
    source_scope: str,
    target_accounts_by_platform: dict[str, set[str]] | None = None,
    season_context: SeasonContext | None = None,
) -> dict[str, int]:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    source_id_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    posted_at_column = PLATFORM_POSTED_AT_COLUMN.get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        return {
            "posts_scanned": 0,
            "needs_mirror_count": 0,
            "mirrored_count": 0,
            "failed_count": 0,
            "partial_count": 0,
            "pending_count": 0,
        }

    requires_target_accounts = source_scope in {"bravo", "creator"}
    account_handles = set((target_accounts_by_platform or {}).get(normalized_platform, set()))
    if requires_target_accounts and not account_handles:
        return {
            "posts_scanned": 0,
            "needs_mirror_count": 0,
            "mirrored_count": 0,
            "failed_count": 0,
            "partial_count": 0,
            "pending_count": 0,
        }

    account_handles_list = sorted(account_handles)
    account_expr = (
        "coalesce(nullif(p.source_account, ''), nullif(p.channel_title, ''), '')"
        if normalized_platform == "youtube"
        else "coalesce(nullif(p.source_account, ''), nullif(p.username, ''), '')"
    )
    account_filter = f"and ltrim(lower({account_expr}), '@') = any(%s)" if account_handles_list else ""
    media_urls_expr = "p.media_urls" if _platform_posts_has_column(normalized_platform, "media_urls") else "'[]'::jsonb"
    thumbnail_expr = (
        "coalesce(nullif(p.media_urls ->> 0, ''), '')"
        if normalized_platform == "twitter"
        else "coalesce(nullif(p.thumbnail_url, ''), '')"
    )
    threads_text_expr = "coalesce(p.text, '')" if normalized_platform == "threads" else "''::text"
    threads_raw_data_expr = (
        "coalesce(to_jsonb(p) -> 'raw_data', '{}'::jsonb)" if normalized_platform == "threads" else "'{}'::jsonb"
    )
    twitter_root_filter = "and p.is_reply = false" if normalized_platform == "twitter" else ""
    params: list[Any] = [season_id, start_dt, end_dt]
    if account_handles_list:
        params.append(account_handles_list)
    rows = pg.fetch_all(
        f"""
        select
          p.id::text as id,
          p.{source_id_column} as source_id,
          p.{posted_at_column} as posted_at,
          {thumbnail_expr} as thumbnail_url,
          {media_urls_expr} as media_urls,
          {threads_text_expr} as text,
          {threads_raw_data_expr} as raw_data,
          coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', '') as hosted_thumbnail_url,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(p) ->> 'media_mirror_status', '') as media_mirror_status
        from social.{table} p
        where p.season_id = %s
          and p.{posted_at_column} >= %s
          and p.{posted_at_column} <= %s
          {twitter_root_filter}
          {account_filter}
        """,
        params,
    )
    if normalized_platform == "threads":
        context = season_context
        if _threads_should_enforce_rhoslc_relevance(context=context):
            hashtags, keywords = _threads_build_relevance_terms(
                season_id,
                source_scope=source_scope,
                context=context,
            )
            rows = [
                row
                for row in rows
                if _threads_text_topic_match(
                    text=row.get("text"),
                    raw_data=row.get("raw_data"),
                    hashtags=hashtags,
                    keywords=keywords,
                )
            ]

    posts_scanned = 0
    needs_mirror_count = 0
    mirrored_count = 0
    failed_count = 0
    partial_count = 0
    pending_count = 0
    for row in rows:
        posts_scanned += 1
        mirror_status = str(row.get("media_mirror_status") or "").strip().lower()
        if mirror_status == "failed":
            failed_count += 1
        elif mirror_status == "partial":
            partial_count += 1
        elif mirror_status == "pending":
            pending_count += 1

        if _platform_post_needs_media_mirror(normalized_platform, row):
            needs_mirror_count += 1
        else:
            mirrored_count += 1

    return {
        "posts_scanned": posts_scanned,
        "needs_mirror_count": needs_mirror_count,
        "mirrored_count": mirrored_count,
        "failed_count": failed_count,
        "partial_count": partial_count,
        "pending_count": pending_count,
    }


def _comment_media_coverage_for_platform(
    season_id: str,
    *,
    platform: str,
    start_dt: datetime,
    end_dt: datetime,
    source_scope: str,
    target_accounts_by_platform: dict[str, set[str]] | None = None,
) -> dict[str, int]:
    normalized_platform = (platform or "").strip().lower()
    empty_payload = {
        "items_scanned": 0,
        "needs_mirror_count": 0,
        "mirrored_count": 0,
        "failed_count": 0,
        "pending_count": 0,
    }
    if normalized_platform not in {"instagram", "tiktok", "twitter", "facebook", "threads"}:
        return empty_payload
    if normalized_platform == "instagram" and not _column_exists("social", "instagram_comments", "media_urls"):
        return empty_payload
    if normalized_platform == "tiktok" and not _tiktok_comments_has_column("media_urls"):
        return empty_payload
    if normalized_platform == "twitter" and not _platform_posts_has_column("twitter", "media_urls"):
        return empty_payload
    if normalized_platform == "facebook" and not _column_exists("social", "facebook_comments", "media_urls"):
        return empty_payload
    if normalized_platform == "threads" and not _column_exists("social", "meta_threads_comments", "media_urls"):
        return empty_payload
    requires_target_accounts = source_scope in {"bravo", "creator"}
    account_handles = set((target_accounts_by_platform or {}).get(normalized_platform, set()))
    if requires_target_accounts and not account_handles:
        return empty_payload

    account_filter = (
        "and ltrim(lower(coalesce(nullif(p.source_account, ''), nullif(p.username, ''), '')), '@') = any(%s)"
        if account_handles
        else ""
    )
    params: list[Any] = [season_id, start_dt, end_dt]
    if account_handles:
        params.append(sorted(account_handles))
    if normalized_platform == "instagram":
        instagram_comment_active_filter = (
            "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("instagram_comments") else ""
        )
        rows = pg.fetch_all(
            f"""
            select
              coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status
            from social.instagram_comments c
            join social.instagram_posts p on p.id = c.post_id
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
              {instagram_comment_active_filter}
              {account_filter}
            """,
            params,
        )
    elif normalized_platform == "tiktok":
        tiktok_comment_active_filter = (
            "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("tiktok_comments") else ""
        )
        rows = pg.fetch_all(
            f"""
            select
              coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status
            from social.tiktok_comments c
            join social.tiktok_posts p on p.id = c.post_id
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
              {tiktok_comment_active_filter}
              {account_filter}
            """,
            params,
        )
    elif normalized_platform == "facebook":
        facebook_comment_active_filter = (
            "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("facebook_comments") else ""
        )
        rows = pg.fetch_all(
            f"""
            select
              coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status
            from social.facebook_comments c
            join social.facebook_posts p on p.id = c.post_id
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
              {facebook_comment_active_filter}
              {account_filter}
            """,
            params,
        )
    elif normalized_platform == "threads":
        threads_comment_active_filter = (
            "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("meta_threads_comments") else ""
        )
        rows = pg.fetch_all(
            f"""
            select
              coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status
            from social.meta_threads_comments c
            join social.meta_threads_posts p on p.id = c.post_id
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
              {threads_comment_active_filter}
              {account_filter}
            """,
            params,
        )
    else:
        twitter_comment_active_filter = (
            "and coalesce(t.is_missing, false) = false" if _comment_lifecycle_supported("twitter_tweets") else ""
        )
        rows = pg.fetch_all(
            f"""
            select
              coalesce(t.media_urls, '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(t) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(t) ->> 'media_mirror_status', '') as media_mirror_status
            from social.twitter_tweets t
            join social.twitter_tweets p on p.tweet_id = t.reply_to_tweet_id and p.season_id = t.season_id
            where p.season_id = %s
              and p.created_at >= %s
              and p.created_at <= %s
              and t.is_reply = true
              {twitter_comment_active_filter}
              {account_filter}
            union all
            select
              coalesce(t.media_urls, '[]'::jsonb) as media_urls,
              coalesce(to_jsonb(t) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
              coalesce(to_jsonb(t) ->> 'media_mirror_status', '') as media_mirror_status
            from social.twitter_tweets t
            join social.twitter_tweets p on p.tweet_id = t.quoted_tweet_id and p.season_id = t.season_id
            where p.season_id = %s
              and p.created_at >= %s
              and p.created_at <= %s
              and t.is_quote = true
              {twitter_comment_active_filter}
              {account_filter}
            """,
            params + params,
        )

    items_scanned = 0
    needs_mirror_count = 0
    mirrored_count = 0
    failed_count = 0
    pending_count = 0
    for row in rows:
        source_urls = _as_text_list(row.get("media_urls"))
        if not source_urls:
            continue
        hosted_urls = _as_text_list(row.get("hosted_media_urls"))
        source_count = len(source_urls)
        hosted_count = min(len(hosted_urls), source_count)
        missing_count = max(source_count - hosted_count, 0)
        status = str(row.get("media_mirror_status") or "").strip().lower()

        items_scanned += source_count
        mirrored_count += hosted_count
        needs_mirror_count += missing_count
        if missing_count <= 0:
            continue
        if status == "failed":
            failed_count += missing_count
        else:
            pending_count += missing_count

    return {
        "items_scanned": items_scanned,
        "needs_mirror_count": needs_mirror_count,
        "mirrored_count": mirrored_count,
        "failed_count": failed_count,
        "pending_count": pending_count,
    }


def get_mirror_coverage(
    season_id: str,
    *,
    platforms: list[str] | None,
    timezone: str,
    source_scope: str,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> dict[str, Any]:
    context = get_season_context(season_id)
    available_platforms = _resolve_requested_platforms(platforms)

    start_dt, end_dt, now_utc = _resolve_coverage_window(
        context=context,
        timezone=timezone,
        source_scope=source_scope,
        date_start=date_start,
        date_end=date_end,
    )

    target_accounts_by_platform = _target_accounts_by_platform(
        season_id,
        source_scope=source_scope,
        context=context,
    )
    active_job_status_by_platform = _active_job_status_by_platform_for_coverage_window(
        context=context,
        timezone=timezone,
        source_scope=source_scope,
        start_dt=start_dt,
        end_dt=end_dt,
        now_utc=now_utc,
        platforms=available_platforms,
    )

    by_platform: dict[str, dict[str, Any]] = {}
    total_posts = 0
    total_needs_mirror = 0
    total_mirrored = 0
    total_failed = 0
    total_partial = 0
    total_pending = 0
    total_comment_media_items_scanned = 0
    total_comment_media_needs_mirror = 0
    total_comment_media_mirrored = 0
    total_comment_media_failed = 0
    total_comment_media_pending = 0
    last_job_ids: list[str] = []
    for platform in available_platforms:
        stats = _mirror_coverage_for_platform(
            season_id,
            platform=platform,
            start_dt=start_dt,
            end_dt=end_dt,
            source_scope=source_scope,
            target_accounts_by_platform=target_accounts_by_platform,
            season_context=context,
        )
        posts_scanned = int(stats.get("posts_scanned") or 0)
        needs_mirror_count = int(stats.get("needs_mirror_count") or 0)
        mirrored_count = int(stats.get("mirrored_count") or 0)
        failed_count = int(stats.get("failed_count") or 0)
        partial_count = int(stats.get("partial_count") or 0)
        pending_count = int(stats.get("pending_count") or 0)
        total_posts += posts_scanned
        total_needs_mirror += needs_mirror_count
        total_mirrored += mirrored_count
        total_failed += failed_count
        total_partial += partial_count
        total_pending += pending_count
        try:
            comment_media_stats = _comment_media_coverage_for_platform(
                season_id,
                platform=platform,
                start_dt=start_dt,
                end_dt=end_dt,
                source_scope=source_scope,
                target_accounts_by_platform=target_accounts_by_platform,
            )
        except Exception:
            logger.debug(
                "Unable to resolve comment-media coverage for season=%s platform=%s source_scope=%s",
                season_id,
                platform,
                source_scope,
                exc_info=True,
            )
            comment_media_stats = {
                "items_scanned": 0,
                "needs_mirror_count": 0,
                "mirrored_count": 0,
                "failed_count": 0,
                "pending_count": 0,
            }
        comment_media_items_scanned = int(comment_media_stats.get("items_scanned") or 0)
        comment_media_needs_mirror_count = int(comment_media_stats.get("needs_mirror_count") or 0)
        comment_media_mirrored_count = int(comment_media_stats.get("mirrored_count") or 0)
        comment_media_failed_count = int(comment_media_stats.get("failed_count") or 0)
        comment_media_pending_count = int(comment_media_stats.get("pending_count") or 0)
        total_comment_media_items_scanned += comment_media_items_scanned
        total_comment_media_needs_mirror += comment_media_needs_mirror_count
        total_comment_media_mirrored += comment_media_mirrored_count
        total_comment_media_failed += comment_media_failed_count
        total_comment_media_pending += comment_media_pending_count
        media_mirror_status = _build_media_mirror_status(
            source_count=posts_scanned + comment_media_items_scanned,
            mirrored_count=mirrored_count + comment_media_mirrored_count,
            failed_count=failed_count + comment_media_failed_count,
            pending_count=pending_count + comment_media_pending_count,
            partial_count=partial_count,
            attempted=(posts_scanned + comment_media_items_scanned) > 0,
            failure_reason=_derive_media_failure_reason(
                platform,
                post_failed_count=failed_count,
                post_partial_count=partial_count,
                post_pending_count=pending_count,
                comment_failed_count=comment_media_failed_count,
                comment_pending_count=comment_media_pending_count,
            ),
        )
        comment_sync_status = _build_comment_sync_status(
            expected_count=0,
            fetched_count=0,
            upserted_count=0,
            attempted=False,
        )
        if media_mirror_status.get("last_job_id"):
            last_job_ids.append(str(media_mirror_status["last_job_id"]))
        by_platform[platform] = {
            "posts_scanned": posts_scanned,
            "needs_mirror_count": needs_mirror_count,
            "mirrored_count": mirrored_count,
            "failed_count": failed_count,
            "partial_count": partial_count,
            "pending_count": pending_count,
            "comment_media_items_scanned": comment_media_items_scanned,
            "comment_media_needs_mirror_count": comment_media_needs_mirror_count,
            "comment_media_mirrored_count": comment_media_mirrored_count,
            "comment_media_failed_count": comment_media_failed_count,
            "comment_media_pending_count": comment_media_pending_count,
            "up_to_date": needs_mirror_count == 0 and comment_media_needs_mirror_count == 0,
            **_overlay_platform_status_with_active_jobs(
                _build_platform_status_payload(
                    posts_scanned=posts_scanned,
                    comment_sync_status=comment_sync_status,
                    media_mirror_status=media_mirror_status,
                    last_refresh_at=None,
                    last_refresh_reason=None,
                    worker_run_id=media_mirror_status.get("last_job_id"),
                    active_job_summary=active_job_status_by_platform.get(platform),
                ),
                active_job_status=active_job_status_by_platform.get(platform),
            ),
        }

    total_comment_sync_status = _build_comment_sync_status(
        expected_count=0,
        fetched_count=0,
        upserted_count=0,
        attempted=False,
    )
    total_media_status = _build_media_mirror_status(
        source_count=total_posts + total_comment_media_items_scanned,
        mirrored_count=total_mirrored + total_comment_media_mirrored,
        failed_count=total_failed + total_comment_media_failed,
        pending_count=total_pending + total_comment_media_pending,
        partial_count=total_partial,
        attempted=(total_posts + total_comment_media_items_scanned) > 0,
        failure_reason=(
            "coverage_post_and_comment_media_mirror_failed"
            if (total_failed + total_comment_media_failed) > 0
            else "coverage_post_and_comment_media_mirror_gap"
            if (total_needs_mirror + total_comment_media_needs_mirror) > 0
            else None
        ),
    )
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "platforms": available_platforms,
        "window": {
            "start": _iso(start_dt),
            "end": _iso(end_dt),
            "timezone": timezone,
        },
        "up_to_date": total_needs_mirror == 0 and total_comment_media_needs_mirror == 0,
        "needs_mirror_count": total_needs_mirror,
        "mirrored_count": total_mirrored,
        "failed_count": total_failed,
        "partial_count": total_partial,
        "pending_count": total_pending,
        "posts_scanned": total_posts,
        "comment_media_items_scanned": total_comment_media_items_scanned,
        "comment_media_needs_mirror_count": total_comment_media_needs_mirror,
        "comment_media_mirrored_count": total_comment_media_mirrored,
        "comment_media_failed_count": total_comment_media_failed,
        "comment_media_pending_count": total_comment_media_pending,
        "by_platform": by_platform,
        "evaluated_at": _iso(now_utc),
        **_build_platform_status_payload(
            posts_scanned=total_posts,
            comment_sync_status=total_comment_sync_status,
            media_mirror_status=total_media_status,
            last_refresh_at=None,
            last_refresh_reason=None,
            worker_run_id=last_job_ids[0] if last_job_ids else None,
        ),
    }


# ---------------------------------------------------------------------------
# Week detail (drill-down into individual posts + comments for one week)
# ---------------------------------------------------------------------------

_MENTION_RE = re.compile(r"@([\w.]+)")
_HASHTAG_RE = re.compile(r"(?<![\w.])#([A-Za-z0-9_]+)")
WeekDetailSortField = Literal["engagement", "likes", "views", "comments_count", "shares", "retweets", "posted_at"]
WeekDetailSortDir = Literal["asc", "desc"]
WEEK_DETAIL_SORT_FIELDS: set[str] = {
    "engagement",
    "likes",
    "views",
    "comments_count",
    "shares",
    "retweets",
    "posted_at",
}
WEEK_DETAIL_SORT_DIRS: set[str] = {"asc", "desc"}


def _json_text_list(value: Any, *, prefix: str = "", strip_prefix: str | None = None) -> list[str]:
    return _as_text_list(value, prefix=prefix, strip_prefix=strip_prefix)


def _normalize_week_detail_sort(sort_field: str, sort_dir: str) -> tuple[WeekDetailSortField, WeekDetailSortDir]:
    normalized_field = str(sort_field or "posted_at").strip().lower()
    if normalized_field not in WEEK_DETAIL_SORT_FIELDS:
        normalized_field = "posted_at"
    normalized_dir = str(sort_dir or "desc").strip().lower()
    if normalized_dir not in WEEK_DETAIL_SORT_DIRS:
        normalized_dir = "desc"
    return normalized_field, normalized_dir


def _week_detail_order_by_clause(
    *,
    timestamp_expr: str,
    field_expr_by_sort: Mapping[str, str],
    engagement_expr: str,
    sort_field: str,
    sort_dir: str,
) -> str:
    normalized_field, normalized_dir = _normalize_week_detail_sort(sort_field, sort_dir)
    if normalized_field == "posted_at":
        return f"{timestamp_expr} {normalized_dir} nulls last"
    metric_expr = engagement_expr if normalized_field == "engagement" else field_expr_by_sort.get(normalized_field, "0")
    return f"coalesce({metric_expr}, 0) {normalized_dir}, {timestamp_expr} desc nulls last"


def _coerce_week_detail_sort_metric(value: Any) -> float:
    if isinstance(value, bool):
        return float(int(value))
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _parse_mentions(text: str | None) -> list[str]:
    """Extract @mentions from text."""
    if not text:
        return []
    return [f"@{m}" for m in _MENTION_RE.findall(text)]


def _parse_hashtags(text: str | None) -> list[str]:
    if not text:
        return []
    return _normalize_unique_terms([tag.lstrip("#") for tag in _HASHTAG_RE.findall(text)])


_INSTAGRAM_CUSTOM_COVER_HINT_KEYS = {
    "has_custom_thumbnail",
    "is_custom_thumbnail",
    "custom_thumbnail_url",
    "custom_thumbnail_src",
    "has_custom_cover",
    "is_custom_cover",
    "custom_cover_url",
    "custom_cover_photo_url",
    "custom_cover_media",
}


def _instagram_has_custom_cover_hint(node: Any) -> bool:
    if isinstance(node, dict):
        for key, value in node.items():
            normalized_key = str(key or "").strip().lower()
            if normalized_key in _INSTAGRAM_CUSTOM_COVER_HINT_KEYS:
                if isinstance(value, bool):
                    if value:
                        return True
                elif isinstance(value, (int, float)):
                    if value != 0:
                        return True
                elif isinstance(value, str):
                    candidate = value.strip().lower()
                    if candidate and candidate not in {"0", "false", "none", "null"}:
                        return True
                elif value:
                    return True
            if _instagram_has_custom_cover_hint(value):
                return True
        return False
    if isinstance(node, list):
        return any(_instagram_has_custom_cover_hint(item) for item in node)
    return False


def _normalize_media_url_for_compare(url: str | None) -> str:
    value = str(url or "").strip()
    if not value:
        return ""
    parsed = urlparse(value)
    host = parsed.netloc.lower().strip()
    path = str(parsed.path or "").strip().rstrip("/")
    return f"{host}{path}".lower()


def _instagram_cover_source_from_post_row(post_row: dict[str, Any]) -> tuple[str | None, str | None]:
    media_type = str(post_row.get("media_type") or "").strip().lower()
    post_format = str(post_row.get("post_format") or "").strip().lower()
    is_video_like = media_type in {"video", "reel"} or post_format in {"video", "reel"}
    if not is_video_like:
        return None, None

    raw_data = post_row.get("raw_data") if isinstance(post_row.get("raw_data"), dict) else {}
    if _instagram_has_custom_cover_hint(raw_data):
        return "custom_cover", "high"

    thumbnail_url = str(post_row.get("thumbnail_url") or "").strip()
    if not thumbnail_url:
        return "unknown", "none"

    source_media_urls = _as_text_list(post_row.get("source_media_urls"))
    if not source_media_urls:
        source_media_urls = _as_text_list(post_row.get("media_urls"))
    video_urls = [url for url in source_media_urls if _is_video_like_media_url(url)]
    if not video_urls:
        return "unknown", "none"

    normalized_thumb = _normalize_media_url_for_compare(thumbnail_url)
    normalized_video_urls = {
        normalized for normalized in (_normalize_media_url_for_compare(url) for url in video_urls) if normalized
    }
    if normalized_thumb and normalized_thumb in normalized_video_urls:
        return "still_frame_or_default", "low"

    return ("still_frame_or_default", "low") if len(video_urls) >= 1 else ("unknown", "none")


def _week_detail_instagram(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    thumbnail_expr = _instagram_posts_thumbnail_expr("p")
    hosted_media_urls_expr = _instagram_posts_json_array_expr("p", "hosted_media_urls")
    post_format_expr = _instagram_posts_json_text_expr("p", "post_format")
    profile_tags_expr = _instagram_posts_json_array_expr("p", "profile_tags")
    collaborators_expr = _instagram_posts_json_array_expr("p", "collaborators")
    hashtags_expr = _instagram_posts_json_array_expr("p", "hashtags")
    mentions_expr = _instagram_posts_json_array_expr("p", "mentions")
    duration_expr = _instagram_posts_duration_expr("p")
    mirror_attempt_count_expr = _instagram_posts_json_int_expr("p", "media_mirror_attempt_count")
    mirror_last_attempt_at_expr = _instagram_posts_json_timestamptz_expr("p", "media_mirror_last_attempt_at")
    mirror_last_job_id_expr = _instagram_posts_json_text_expr("p", "media_mirror_last_job_id")

    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    query_params = [season_id, start_dt, end_dt]
    if account_handles_list:
        query_params.append(account_handles_list)

    count_rows = pg.fetch_all(
        f"""
        select count(*)::int as post_count
        from social.instagram_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
        {account_filter}
        """,
        query_params,
    )
    total_post_count = int((count_rows[0] if count_rows else {}).get("post_count") or 0)

    effective_post_limit = max(0, post_limit + post_offset)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="p.posted_at",
        field_expr_by_sort={
            "likes": "p.likes",
            "views": "p.views",
            "comments_count": "p.comments_count",
            "shares": "0",
            "retweets": "0",
        },
        engagement_expr="coalesce(p.likes, 0) + coalesce(p.comments_count, 0) + coalesce(p.views, 0)",
        sort_field=sort_field,
        sort_dir=sort_dir,
    )
    posts_params = query_params
    posts = pg.fetch_all(
        f"""
        select
          p.id,
          p.shortcode as source_id,
          p.username as author,
          p.caption as text,
          coalesce(p.likes, 0) as likes,
          coalesce(p.comments_count, 0) as comments_count,
          coalesce(p.views, 0) as views,
          p.media_type,
          coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
          {hosted_media_urls_expr} as hosted_media_urls,
          coalesce(nullif(p.thumbnail_url, ''), '') as source_thumbnail_url,
          coalesce(nullif(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          {thumbnail_expr} as thumbnail_url,
          {post_format_expr} as post_format,
          {profile_tags_expr} as profile_tags,
          {collaborators_expr} as collaborators,
          {hashtags_expr} as hashtags,
          {mentions_expr} as mentions,
          {duration_expr} as duration_seconds,
          nullif(coalesce(to_jsonb(p) ->> 'owner_profile_pic_url', ''), '') as owner_profile_pic_url,
          nullif(coalesce(to_jsonb(p) ->> 'hosted_owner_profile_pic_url', ''), '') as hosted_owner_profile_pic_url,
          nullif(coalesce(to_jsonb(p) ->> 'owner_full_name', ''), '') as owner_full_name,
          coalesce(to_jsonb(p) -> 'hosted_tagged_profile_pics', '{{}}'::jsonb) as hosted_tagged_profile_pics,
          coalesce(to_jsonb(p) -> 'tagged_users_detail', '[]'::jsonb) as tagged_users_detail,
          coalesce(to_jsonb(p) -> 'collaborators_detail', '[]'::jsonb) as collaborators_detail,
          coalesce(to_jsonb(p) -> 'child_posts_data', '[]'::jsonb) as child_posts_data,
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          {mirror_attempt_count_expr} as media_mirror_attempt_count,
          {mirror_last_attempt_at_expr} as media_mirror_last_attempt_at,
          {mirror_last_job_id_expr} as media_mirror_last_job_id,
          nullif(coalesce(to_jsonb(p) ->> 'metadata_error', ''), '') as metadata_error,
          p.posted_at as ts
        from social.instagram_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
          {account_filter}
        order by {order_by_clause}
        limit {effective_post_limit}
        """,
        posts_params,
    )

    post_ids = [p["id"] for p in posts]
    comments_by_post: dict[Any, list[dict]] = defaultdict(list)
    comment_counts_by_post: dict[Any, int] = defaultdict(int)
    instagram_comment_active_filter = (
        "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("instagram_comments") else ""
    )

    if post_ids:
        # Get total comment counts per post
        count_rows = pg.fetch_all(
            f"""
            select c.post_id, count(*)::int as cnt
            from social.instagram_comments c
            where c.post_id = any(%s::uuid[])
              {instagram_comment_active_filter}
            group by c.post_id
            """,
            [post_ids],
        )
        for row in count_rows:
            comment_counts_by_post[row["post_id"]] = row["cnt"]

        # Get top N comments per post using lateral join (0 = no cap)
        limit_clause = f"limit {max_comments}" if max_comments > 0 else "limit all"
        comment_rows = pg.fetch_all(
            f"""
            select sub.*
            from unnest(%s::uuid[]) as pid(id)
            cross join lateral (
              select
                c.comment_id,
                c.post_id,
                c.username as author,
                c.text,
                coalesce(c.likes, 0) as likes,
                coalesce(c.is_reply, false) as is_reply,
                coalesce(c.reply_count, 0) as reply_count,
                c.created_at
              from social.instagram_comments c
              where c.post_id = pid.id
                {instagram_comment_active_filter}
              order by c.likes desc nulls last, c.created_at asc
              {limit_clause}
            ) sub
            """,
            [post_ids],
        )
        for row in comment_rows:
            comments_by_post[row["post_id"]].append(row)

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    saved_comments_count = 0
    for p in posts:
        engagement = p["likes"] + p["comments_count"] + p["views"]
        total_engagement += engagement
        db_comment_count = comment_counts_by_post.get(p["id"], 0)
        saved_comments_count += db_comment_count
        total_comments_count += p["comments_count"]
        post_comments = comments_by_post.get(p["id"], [])

        source_media_urls = _json_text_list(p.get("source_media_urls"))
        hosted_media_urls = _json_text_list(p.get("hosted_media_urls"))
        media_urls = hosted_media_urls or source_media_urls
        source_thumbnail_url = str(p.get("source_thumbnail_url") or "").strip() or None
        hosted_thumbnail_url = str(p.get("hosted_thumbnail_url") or "").strip() or None
        thumbnail_url = str(p.get("thumbnail_url") or "").strip() or source_thumbnail_url
        cover_source, cover_source_confidence = _instagram_cover_source_from_post_row(
            {
                "media_type": p.get("media_type"),
                "post_format": p.get("post_format"),
                "raw_data": p.get("raw_data"),
                "thumbnail_url": thumbnail_url,
                "source_media_urls": source_media_urls,
                "media_urls": source_media_urls,
            }
        )
        hashtags = _json_text_list(p.get("hashtags"), strip_prefix="#")
        mentions = _json_text_list(p.get("mentions"), prefix="@", strip_prefix="@")
        if not hashtags:
            hashtags = _parse_hashtags(p.get("text"))
        if not mentions:
            mentions = _parse_mentions(p.get("text"))
        profile_tags = _json_text_list(p.get("profile_tags"), prefix="@", strip_prefix="@")
        collaborators = _json_text_list(p.get("collaborators"), prefix="@", strip_prefix="@")
        owner_profile_pic_url = _resolve_post_avatar_url(
            hosted_avatar_url=None,
            direct_avatar_url=p.get("owner_profile_pic_url"),
            raw_data=p.get("raw_data"),
        )
        hosted_owner_profile_pic_url = _first_non_empty_str(p.get("hosted_owner_profile_pic_url"))
        hosted_tagged_profile_pics = _as_json_string_map(p.get("hosted_tagged_profile_pics"))
        hosted_avatar_by_handle = {
            normalized_key: value
            for key, value in hosted_tagged_profile_pics.items()
            if (normalized_key := _normalize_account_handle(key))
        }
        tagged_users_detail = _enrich_handle_details(
            "instagram",
            _as_json_object_list(p.get("tagged_users_detail")),
            hosted_avatar_by_handle=hosted_avatar_by_handle,
        )
        collaborators_detail = _enrich_handle_details(
            "instagram",
            _as_json_object_list(p.get("collaborators_detail")),
            hosted_avatar_by_handle=hosted_avatar_by_handle,
        )
        child_posts_data_raw = _as_json_object_list(p.get("child_posts_data"))
        child_posts_data: list[dict[str, Any]] = []
        for child in child_posts_data_raw:
            payload = dict(child)
            tagged_child = _enrich_handle_details(
                "instagram",
                _as_json_object_list(payload.get("tagged_users_detail")),
                hosted_avatar_by_handle=hosted_avatar_by_handle,
            )
            payload["tagged_users_detail"] = tagged_child
            payload["profile_tags_detail"] = tagged_child
            payload["mentions_detail"] = tagged_child
            child_posts_data.append(payload)
        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=hosted_owner_profile_pic_url,
            direct_avatar_url=owner_profile_pic_url,
            raw_data=p.get("raw_data"),
        )
        user_url = _resolve_platform_profile_url("instagram", handle=p.get("author"))

        result_posts.append(
            {
                **{
                    "source_id": p["source_id"],
                    "author": p["author"] or "",
                    "text": p.get("text") or "",
                    "url": f"https://www.instagram.com/p/{p['source_id']}/" if p["source_id"] else "",
                    "posted_at": _iso(p["ts"]),
                    "likes": p["likes"],
                    "comments_count": p["comments_count"],
                    "views": p["views"],
                    "media_type": p.get("media_type"),
                    "media_urls": media_urls,
                    "source_media_urls": source_media_urls,
                    "hosted_media_urls": hosted_media_urls,
                    "thumbnail_url": thumbnail_url,
                    "source_thumbnail_url": source_thumbnail_url,
                    "hosted_thumbnail_url": hosted_thumbnail_url,
                    "cover_source": cover_source,
                    "cover_source_confidence": cover_source_confidence,
                    "post_format": p.get("post_format"),
                    "profile_tags": profile_tags,
                    "collaborators": collaborators,
                    "hashtags": hashtags,
                    "mentions": mentions,
                    "user": {
                        "username": p["author"] or "",
                        "display_name": _first_non_empty_str(p.get("owner_full_name")),
                        "url": user_url,
                        "avatar_url": user_avatar_url,
                    },
                    "owner_full_name": _first_non_empty_str(p.get("owner_full_name")),
                    "owner_profile_pic_url": owner_profile_pic_url,
                    "hosted_owner_profile_pic_url": hosted_owner_profile_pic_url,
                    "hosted_tagged_profile_pics": hosted_tagged_profile_pics,
                    "tagged_users_detail": tagged_users_detail,
                    "profile_tags_detail": tagged_users_detail,
                    "mentions_detail": _enrich_handle_details(
                        "instagram",
                        [*tagged_users_detail, *_build_handle_details_from_tokens("instagram", mentions)],
                        hosted_avatar_by_handle=hosted_avatar_by_handle,
                    ),
                    "collaborators_detail": collaborators_detail,
                    "child_posts_data": child_posts_data,
                    "duration_seconds": p.get("duration_seconds"),
                    "media_mirror_attempt_count": p.get("media_mirror_attempt_count"),
                    "media_mirror_last_attempt_at": _iso(_coerce_dt(p.get("media_mirror_last_attempt_at"))),
                    "media_mirror_last_job_id": str(p.get("media_mirror_last_job_id") or "") or None,
                    "metadata_error": _first_non_empty_str(p.get("metadata_error")),
                    "engagement": engagement,
                    "total_comments_available": db_comment_count,
                    "comments": [
                        {
                            "comment_id": c["comment_id"],
                            "author": c["author"] or "",
                            "text": c["text"] or "",
                            "likes": c["likes"],
                            "is_reply": c["is_reply"],
                            "reply_count": c["reply_count"],
                            "created_at": _iso(c["created_at"]),
                        }
                        for c in post_comments
                    ],
                },
                "status": _build_post_status_payload(
                    expected_comments=int(p["comments_count"] or 0),
                    saved_comments=db_comment_count,
                    source_media_urls=source_media_urls,
                    hosted_media_urls=hosted_media_urls,
                    source_thumbnail_url=source_thumbnail_url,
                    hosted_thumbnail_url=hosted_thumbnail_url,
                    media_mirror_status="partial" if len(hosted_media_urls) < len(source_media_urls) else "complete",
                    media_mirror_last_job_id=str(p.get("media_mirror_last_job_id") or "") or None,
                    last_refresh_at=p.get("media_mirror_last_attempt_at"),
                    last_refresh_reason=_first_non_empty_str(p.get("metadata_error")),
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": total_comments_count,
            "saved_comments_total": saved_comments_count,
            "comments_saved_pct": _safe_percent(saved_comments_count, total_comments_count),
        },
    }


def _week_detail_tiktok(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    thumbnail_expr = _platform_thumbnail_expr("p", "tiktok")
    saves_expr = "coalesce(p.saves, 0)" if _platform_posts_has_column("tiktok", "saves") else "0"
    mentions_expr = (
        "coalesce(p.mentions, '[]'::jsonb)" if _platform_posts_has_column("tiktok", "mentions") else "'[]'::jsonb"
    )
    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    params = [season_id, start_dt, end_dt]
    if account_handles_list:
        params.append(account_handles_list)
    count_rows = pg.fetch_all(
        f"""
        select count(*)::int as post_count
        from social.tiktok_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
        {account_filter}
        """,
        params,
    )
    total_post_count = int((count_rows[0] if count_rows else {}).get("post_count") or 0)
    effective_post_limit = max(0, post_limit + post_offset)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="p.posted_at",
        field_expr_by_sort={
            "likes": "p.likes",
            "views": "p.views",
            "comments_count": "p.comments_count",
            "shares": "p.shares",
            "retweets": "0",
        },
        engagement_expr=(
            "coalesce(p.likes, 0) + coalesce(p.comments_count, 0) + coalesce(p.shares, 0) + coalesce(p.views, 0)"
        ),
        sort_field=sort_field,
        sort_dir=sort_dir,
    )
    posts = pg.fetch_all(
        f"""
        select
          p.id,
          p.video_id as source_id,
          p.username as author,
          p.nickname,
          p.description as text,
          coalesce(p.likes, 0) as likes,
          coalesce(p.comments_count, 0) as comments_count,
          coalesce(p.shares, 0) as shares,
          {saves_expr} as saves,
          coalesce(p.views, 0) as views,
          coalesce(p.hashtags, '[]'::jsonb) as hashtags,
          {mentions_expr} as mentions,
          {thumbnail_expr} as thumbnail_url,
          coalesce(nullif(p.thumbnail_url, ''), '') as source_thumbnail_url,
          coalesce(nullif(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
          {_platform_hosted_media_expr("p")} as hosted_media_urls,
          p.duration_seconds,
          nullif(coalesce(to_jsonb(p) ->> 'user_avatar_url', ''), '') as user_avatar_url,
          nullif(coalesce(to_jsonb(p) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          p.posted_at as ts
        from social.tiktok_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
          {account_filter}
        order by {order_by_clause}
        limit {effective_post_limit}
        """,
        params,
    )

    post_ids = [p["id"] for p in posts]
    comments_by_post: dict[Any, list[dict]] = defaultdict(list)
    comment_counts_by_post: dict[Any, int] = defaultdict(int)
    tiktok_comment_active_filter = (
        "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("tiktok_comments") else ""
    )

    if post_ids:
        count_rows = pg.fetch_all(
            f"""
            select c.post_id, count(*)::int as cnt
            from social.tiktok_comments c
            where c.post_id = any(%s::uuid[])
              {tiktok_comment_active_filter}
            group by c.post_id
            """,
            [post_ids],
        )
        for row in count_rows:
            comment_counts_by_post[row["post_id"]] = row["cnt"]

        limit_clause = f"limit {max_comments}" if max_comments > 0 else "limit all"
        comment_rows = pg.fetch_all(
            f"""
            select sub.*
            from unnest(%s::uuid[]) as pid(id)
            cross join lateral (
              select
                c.comment_id,
                c.post_id,
                c.username as author,
                c.text,
                coalesce(c.likes, 0) as likes,
                coalesce(c.is_reply, false) as is_reply,
                coalesce(c.reply_count, 0) as reply_count,
                c.created_at,
                coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
                coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
                nullif(coalesce(to_jsonb(c) ->> 'media_mirror_status', ''), '') as media_mirror_status
              from social.tiktok_comments c
              where c.post_id = pid.id
                {tiktok_comment_active_filter}
              order by c.likes desc nulls last, c.created_at asc
              {limit_clause}
            ) sub
            """,
            [post_ids],
        )
        for row in comment_rows:
            comments_by_post[row["post_id"]].append(row)

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    saved_comments_count = 0
    for p in posts:
        engagement = p["likes"] + p["comments_count"] + p["shares"] + p["views"]
        total_engagement += engagement
        total_comments_count += p["comments_count"]
        db_comment_count = comment_counts_by_post.get(p["id"], 0)
        saved_comments_count += db_comment_count
        post_comments = comments_by_post.get(p["id"], [])

        hashtags = _json_text_list(p.get("hashtags"), strip_prefix="#")
        if not hashtags:
            hashtags = _parse_hashtags(p.get("text"))
        mentions = _json_text_list(p.get("mentions"), prefix="@", strip_prefix="@")
        if not mentions:
            mentions = _parse_mentions(p.get("text"))

        author = p["author"] or ""
        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=p.get("hosted_user_avatar_url"),
            direct_avatar_url=p.get("user_avatar_url"),
            raw_data=p.get("raw_data"),
        )
        user_url = _resolve_platform_profile_url("tiktok", handle=author)
        mentions_detail = _build_handle_details_from_tokens("tiktok", mentions)
        result_posts.append(
            {
                "source_id": p["source_id"],
                "author": author,
                "nickname": p.get("nickname") or "",
                "text": p.get("text") or "",
                "url": f"https://www.tiktok.com/@{author}/video/{p['source_id']}" if p["source_id"] and author else "",
                "posted_at": _iso(p["ts"]),
                "likes": p["likes"],
                "comments_count": p["comments_count"],
                "shares": p["shares"],
                "saves": int(p.get("saves") or 0),
                "views": p["views"],
                "hashtags": hashtags,
                "thumbnail_url": p.get("thumbnail_url"),
                "source_thumbnail_url": str(p.get("source_thumbnail_url") or "").strip() or None,
                "hosted_thumbnail_url": str(p.get("hosted_thumbnail_url") or "").strip() or None,
                "media_urls": _as_text_list(p.get("source_media_urls")),
                "source_media_urls": _as_text_list(p.get("source_media_urls")),
                "hosted_media_urls": _as_text_list(p.get("hosted_media_urls")),
                "duration_seconds": p.get("duration_seconds"),
                "mentions": mentions,
                "user": {
                    "username": author,
                    "display_name": p.get("nickname") or "",
                    "url": user_url,
                    "avatar_url": user_avatar_url,
                },
                "mentions_detail": mentions_detail,
                "engagement": engagement,
                "total_comments_available": db_comment_count,
                "comments": [
                    {
                        "comment_id": c["comment_id"],
                        "author": c["author"] or "",
                        "text": c["text"] or "",
                        "likes": c["likes"],
                        "is_reply": c["is_reply"],
                        "reply_count": c["reply_count"],
                        "created_at": _iso(c["created_at"]),
                        "media_urls": _as_text_list(c.get("media_urls")),
                        "hosted_media_urls": _as_text_list(c.get("hosted_media_urls")),
                        "media_mirror_status": c.get("media_mirror_status"),
                    }
                    for c in post_comments
                ],
                "status": _build_post_status_payload(
                    expected_comments=int(p["comments_count"] or 0),
                    saved_comments=db_comment_count,
                    source_media_urls=_as_text_list(p.get("source_media_urls")),
                    hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                    source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                    hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                    media_mirror_status=(
                        "partial"
                        if len(_as_text_list(p.get("hosted_media_urls")))
                        < len(_as_text_list(p.get("source_media_urls")))
                        else "complete"
                    ),
                    last_refresh_at=None,
                    last_refresh_reason="tiktok_metadata_unavailable"
                    if not _as_text_list(p.get("source_media_urls")) and int(p.get("views") or 0) <= 0
                    else None,
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": total_comments_count,
            "saved_comments_total": saved_comments_count,
            "comments_saved_pct": _safe_percent(saved_comments_count, total_comments_count),
        },
    }


def _week_detail_youtube(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    try:
        context = get_season_context(season_id)
    except Exception:
        logger.debug("Unable to resolve season context for YouTube week detail: season=%s", season_id, exc_info=True)
        context = None
    thumbnail_expr = _platform_thumbnail_expr("v", "youtube")
    youtube_is_short_expr = _youtube_is_short_expr("v")
    youtube_media_urls_expr = (
        "coalesce(v.media_urls, '[]'::jsonb)" if _platform_posts_has_column("youtube", "media_urls") else "'[]'::jsonb"
    )
    hashtags_expr = (
        "coalesce(v.hashtags, '[]'::jsonb)" if _platform_posts_has_column("youtube", "hashtags") else "'[]'::jsonb"
    )
    mentions_expr = (
        "coalesce(v.mentions, '[]'::jsonb)" if _platform_posts_has_column("youtube", "mentions") else "'[]'::jsonb"
    )
    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(v.channel_title, ''), nullif(v.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    youtube_comment_active_filter = (
        " and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("youtube_comments") else ""
    )
    params = [season_id, start_dt, end_dt]
    if account_handles_list:
        params.append(account_handles_list)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="v.published_at",
        field_expr_by_sort={
            "likes": "v.likes",
            "views": "v.views",
            "comments_count": "v.comments_count",
            "shares": "0",
            "retweets": "0",
        },
        engagement_expr="coalesce(v.views, 0) + coalesce(v.likes, 0) + coalesce(v.comments_count, 0)",
        sort_field=sort_field,
        sort_dir=sort_dir,
    )
    candidate_posts = pg.fetch_all(
        f"""
        select
          v.id,
          v.video_id as source_id,
          v.channel_title as author,
          v.title,
          v.description as text,
          coalesce(v.views, 0) as views,
          coalesce(v.likes, 0) as likes,
          coalesce(v.comments_count, 0) as comments_count,
          {youtube_is_short_expr} as is_short,
          {hashtags_expr} as hashtags,
          {mentions_expr} as mentions,
          {thumbnail_expr} as thumbnail_url,
          coalesce(nullif(v.thumbnail_url, ''), '') as source_thumbnail_url,
          coalesce(to_jsonb(v) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(nullif(to_jsonb(v) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          {youtube_media_urls_expr} as source_media_urls,
          nullif(coalesce(to_jsonb(v) ->> 'media_mirror_status', ''), '') as media_mirror_status,
          {_instagram_posts_json_timestamptz_expr("v", "media_mirror_last_attempt_at")} as media_mirror_last_attempt_at,
          {_instagram_posts_json_text_expr("v", "media_mirror_last_job_id")} as media_mirror_last_job_id,
          v.duration_seconds,
          nullif(coalesce(to_jsonb(v) ->> 'user_avatar_url', ''), '') as user_avatar_url,
          nullif(coalesce(to_jsonb(v) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
          coalesce(to_jsonb(v) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          v.published_at as ts
        from social.youtube_videos v
        where v.season_id = %s
          and v.published_at >= %s
          and v.published_at <= %s
          {account_filter}
        order by {order_by_clause}
        """,
        params,
    )
    filtered_posts = [
        post
        for post in candidate_posts
        if _youtube_post_matches_show_terms(
            context=context,
            title=post.get("title"),
            description=post.get("text"),
            post_hashtags=_json_text_list(post.get("hashtags"), strip_prefix="#"),
        )
    ]
    total_post_count = len(filtered_posts)
    if post_offset > 0:
        filtered_posts = filtered_posts[post_offset:]
    posts = filtered_posts[:post_limit] if post_limit > 0 else filtered_posts

    post_ids = [p["id"] for p in posts]
    comments_by_post: dict[Any, list[dict]] = defaultdict(list)
    comment_counts_by_post: dict[Any, int] = defaultdict(int)

    if post_ids:
        count_rows = pg.fetch_all(
            f"""
            select c.video_id, count(*)::int as cnt
            from social.youtube_comments c
            where c.video_id = any(%s::uuid[])
              {youtube_comment_active_filter}
            group by c.video_id
            """,
            [post_ids],
        )
        for row in count_rows:
            comment_counts_by_post[row["video_id"]] = row["cnt"]

        limit_clause = f"limit {max_comments}" if max_comments > 0 else "limit all"
        comment_rows = pg.fetch_all(
            f"""
            select sub.*
            from unnest(%s::uuid[]) as pid(id)
            cross join lateral (
              select
                c.comment_id,
                c.video_id,
                c.author,
                c.text,
                coalesce(c.likes, 0) as likes,
                coalesce(c.is_reply, false) as is_reply,
                coalesce(c.reply_count, 0) as reply_count,
                c.created_at
              from social.youtube_comments c
              where c.video_id = pid.id
                {youtube_comment_active_filter}
              order by c.likes desc nulls last, c.created_at asc
              {limit_clause}
            ) sub
            """,
            [post_ids],
        )
        for row in comment_rows:
            comments_by_post[row["video_id"]].append(row)

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    expected_comments_count = 0
    saved_comments_count = 0
    for p in posts:
        db_comment_count = comment_counts_by_post.get(p["id"], 0)
        expected_comments_count += int(p["comments_count"] or 0)
        saved_comments_count += db_comment_count
        effective_comments_count = _youtube_effective_comment_count(
            reported_count=p["comments_count"],
            saved_count=db_comment_count,
        )
        engagement = p["views"] + p["likes"] + effective_comments_count
        total_engagement += engagement
        total_comments_count += effective_comments_count
        post_comments = comments_by_post.get(p["id"], [])
        normalized_title, normalized_text = _normalize_youtube_title_description(
            p.get("title"),
            p.get("text"),
            is_short=bool(p.get("is_short")),
        )
        token_text = f"{normalized_title}\n{normalized_text}"
        hashtags = _json_text_list(p.get("hashtags"), strip_prefix="#")
        if not hashtags:
            hashtags = _parse_hashtags(token_text)
        mentions = _json_text_list(p.get("mentions"), prefix="@", strip_prefix="@")
        if not mentions:
            mentions = _parse_mentions(token_text)
        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=p.get("hosted_user_avatar_url"),
            direct_avatar_url=p.get("user_avatar_url"),
            raw_data=p.get("raw_data"),
        )
        author_handle = _normalize_account_handle(p.get("author"))
        user_url = _resolve_platform_profile_url("youtube", handle=author_handle or p.get("author"))
        mentions_detail = _build_handle_details_from_tokens("youtube", mentions)

        result_posts.append(
            {
                "source_id": p["source_id"],
                "author": p["author"] or "",
                "title": normalized_title,
                "text": normalized_text,
                "url": (
                    f"https://www.youtube.com/shorts/{p['source_id']}"
                    if p.get("is_short")
                    else f"https://www.youtube.com/watch?v={p['source_id']}"
                )
                if p["source_id"]
                else "",
                "is_short": bool(p.get("is_short")),
                "posted_at": _iso(p["ts"]),
                "views": p["views"],
                "likes": p["likes"],
                "comments_count": effective_comments_count,
                "hashtags": hashtags,
                "mentions": mentions,
                "thumbnail_url": p.get("thumbnail_url"),
                "source_thumbnail_url": str(p.get("source_thumbnail_url") or "").strip() or None,
                "hosted_thumbnail_url": str(p.get("hosted_thumbnail_url") or "").strip() or None,
                "media_urls": _as_text_list(p.get("source_media_urls")),
                "source_media_urls": _as_text_list(p.get("source_media_urls")),
                "hosted_media_urls": _as_text_list(p.get("hosted_media_urls")),
                "duration_seconds": p.get("duration_seconds"),
                "user": {
                    "username": p["author"] or "",
                    "display_name": p.get("author") or "",
                    "url": user_url,
                    "avatar_url": user_avatar_url,
                },
                "mentions_detail": mentions_detail,
                "engagement": engagement,
                "total_comments_available": db_comment_count,
                "comments": [
                    {
                        "comment_id": c["comment_id"],
                        "author": c["author"] or "",
                        "text": c["text"] or "",
                        "likes": c["likes"],
                        "is_reply": c["is_reply"],
                        "reply_count": c["reply_count"],
                        "created_at": _iso(c["created_at"]),
                    }
                    for c in post_comments
                ],
                "status": _build_post_status_payload(
                    expected_comments=int(p["comments_count"] or 0),
                    saved_comments=db_comment_count,
                    source_media_urls=_as_text_list(p.get("source_media_urls")),
                    hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                    source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                    hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                    media_mirror_status=_infer_post_media_mirror_status(
                        source_media_urls=_as_text_list(p.get("source_media_urls")),
                        hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                        source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                        hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                        stored_status=str(p.get("media_mirror_status") or "").strip() or None,
                    ),
                    media_mirror_last_job_id=str(p.get("media_mirror_last_job_id") or "").strip() or None,
                    last_refresh_at=p.get("media_mirror_last_attempt_at"),
                    last_refresh_reason=(
                        "youtube_comment_gap" if db_comment_count < int(p["comments_count"] or 0) else None
                    ),
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": expected_comments_count,
            "saved_comments_total": saved_comments_count,
            "comments_saved_pct": _safe_percent(saved_comments_count, expected_comments_count),
        },
    }


def _week_detail_twitter(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    """Twitter week detail with optional recursive reply chains for scoped accounts."""
    thumbnail_expr = _platform_thumbnail_expr("t", "twitter")

    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    posts_params = [season_id, start_dt, end_dt]
    if account_handles_list:
        posts_params.append(account_handles_list)
    count_rows = pg.fetch_all(
        f"""
        select count(*)::int as post_count
        from social.twitter_tweets t
        where t.season_id = %s
          and t.is_reply = false
          and t.created_at >= %s
          and t.created_at <= %s
        {account_filter}
        """,
        posts_params,
    )
    total_post_count = int((count_rows[0] if count_rows else {}).get("post_count") or 0)
    effective_post_limit = max(0, post_limit + post_offset)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="t.created_at",
        field_expr_by_sort={
            "likes": "t.likes",
            "views": "t.views",
            "comments_count": "0",
            "shares": "0",
            "retweets": "t.retweets",
        },
        engagement_expr=(
            "coalesce(t.likes, 0) + coalesce(t.retweets, 0) + coalesce(t.replies_count, 0) + "
            "coalesce(t.quotes, 0) + coalesce(t.views, 0)"
        ),
        sort_field=sort_field,
        sort_dir=sort_dir,
    )

    posts = pg.fetch_all(
        f"""
        select
          t.tweet_id as source_id,
          coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
          t.display_name,
          t.text,
          coalesce(t.likes, 0) as likes,
          coalesce(t.retweets, 0) as retweets,
          coalesce(t.replies_count, 0) as replies_count,
          coalesce(t.quotes, 0) as quotes,
          coalesce(t.views, 0) as views,
          nullif(coalesce(to_jsonb(t) ->> 'user_id', ''), '') as user_id,
          nullif(coalesce(to_jsonb(t) ->> 'user_profile_url', ''), '') as user_profile_url,
          nullif(coalesce(to_jsonb(t) ->> 'user_avatar_url', ''), '') as user_avatar_url,
          nullif(coalesce(to_jsonb(t) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
          coalesce(to_jsonb(t) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(nullif(to_jsonb(t) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          nullif(coalesce(to_jsonb(t) ->> 'media_mirror_status', ''), '') as media_mirror_status,
          {_instagram_posts_json_timestamptz_expr("t", "media_mirror_last_attempt_at")} as media_mirror_last_attempt_at,
          {_instagram_posts_json_text_expr("t", "media_mirror_last_job_id")} as media_mirror_last_job_id,
          coalesce(to_jsonb(t) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          t.hashtags,
          t.mentions,
          t.media_urls,
          {thumbnail_expr} as thumbnail_url,
          t.created_at as ts
        from social.twitter_tweets t
        where t.season_id = %s
          and t.is_reply = false
          and t.created_at >= %s
          and t.created_at <= %s
          {account_filter}
        order by {order_by_clause}
        limit {effective_post_limit}
        """,
        posts_params,
    )

    # For account-scoped runs: get full recursive reply chains for each post.
    # For unscoped runs: get direct replies only.
    post_tweet_ids = [p["source_id"] for p in posts if p["source_id"]]
    comments_by_root: dict[str, list[dict]] = defaultdict(list)
    comment_counts_by_root: dict[str, int] = defaultdict(int)

    if post_tweet_ids:
        twitter_reply_active_filter = (
            " and coalesce(r.is_missing, false) = false" if _comment_lifecycle_supported("twitter_tweets") else ""
        )
        twitter_child_reply_active_filter = (
            " and coalesce(child.is_missing, false) = false" if _comment_lifecycle_supported("twitter_tweets") else ""
        )
        twitter_reply_row_active_filter = (
            " and coalesce(t.is_missing, false) = false" if _comment_lifecycle_supported("twitter_tweets") else ""
        )
        if account_handles_list:
            # Full recursive reply chain (matches existing analytics CTE pattern)
            reply_rows = pg.fetch_all(
                f"""
                with recursive root_posts as (
                  select tweet_id from unnest(%s::text[]) as t(tweet_id)
                ), thread_replies as (
                  select r.tweet_id, r.reply_to_tweet_id,
                         r.reply_to_tweet_id as root_tweet_id
                  from social.twitter_tweets r
                  where r.season_id = %s
                    and r.is_reply = true
                    and r.reply_to_tweet_id in (select tweet_id from root_posts)
                    {twitter_reply_active_filter}
                  union
                  select child.tweet_id, child.reply_to_tweet_id,
                         parent.root_tweet_id
                  from social.twitter_tweets child
                  join thread_replies parent on child.reply_to_tweet_id = parent.tweet_id
                  where child.season_id = %s
                    and child.is_reply = true
                    {twitter_child_reply_active_filter}
                )
                select
                  tr.root_tweet_id,
                  t.tweet_id as comment_id,
                  coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                  coalesce(t.display_name, '') as display_name,
                  nullif(coalesce(to_jsonb(t) ->> 'user_id', ''), '') as user_id,
                  nullif(coalesce(to_jsonb(t) ->> 'user_profile_url', ''), '') as user_url,
                  nullif(coalesce(to_jsonb(t) ->> 'user_avatar_url', ''), '') as user_avatar_url,
                  nullif(coalesce(to_jsonb(t) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
                  t.text,
                  coalesce(t.likes, 0) as likes,
                  true as is_reply,
                  coalesce(t.replies_count, 0) as reply_count,
                  t.created_at
                from thread_replies tr
                join social.twitter_tweets t on t.tweet_id = tr.tweet_id
                where t.season_id = %s
                  {twitter_reply_row_active_filter}
                order by tr.root_tweet_id, t.likes desc nulls last, t.created_at asc
                """,
                [post_tweet_ids, season_id, season_id, season_id],
            )
        else:
            # Non-bravo: direct replies only
            reply_rows = pg.fetch_all(
                f"""
                select
                  t.reply_to_tweet_id as root_tweet_id,
                  t.tweet_id as comment_id,
                  coalesce(nullif(t.username, ''), nullif(t.source_account, ''), '') as author,
                  coalesce(t.display_name, '') as display_name,
                  nullif(coalesce(to_jsonb(t) ->> 'user_id', ''), '') as user_id,
                  nullif(coalesce(to_jsonb(t) ->> 'user_profile_url', ''), '') as user_url,
                  nullif(coalesce(to_jsonb(t) ->> 'user_avatar_url', ''), '') as user_avatar_url,
                  nullif(coalesce(to_jsonb(t) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
                  t.text,
                  coalesce(t.likes, 0) as likes,
                  true as is_reply,
                  coalesce(t.replies_count, 0) as reply_count,
                  t.created_at
                from social.twitter_tweets t
                where t.season_id = %s
                  and t.is_reply = true
                  and t.reply_to_tweet_id = any(%s)
                  {twitter_reply_row_active_filter}
                order by t.reply_to_tweet_id, t.likes desc nulls last, t.created_at asc
                """,
                [season_id, post_tweet_ids],
            )

        # Group and count (max_comments=0 means no cap)
        for row in reply_rows:
            root_id = row["root_tweet_id"]
            comment_counts_by_root[root_id] = comment_counts_by_root.get(root_id, 0) + 1
            if max_comments == 0 or len(comments_by_root[root_id]) < max_comments:
                comments_by_root[root_id].append(row)

    quote_counts_by_root = _count_stored_quotes(post_tweet_ids) if post_tweet_ids else {}

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    expected_comments_count = 0
    total_quotes_saved = 0
    for p in posts:
        reposts = max(0, int(p.get("reposts") or p["retweets"] or 0))
        engagement = p["likes"] + p["retweets"] + p["replies_count"] + p["quotes"] + p["views"]
        total_engagement += engagement
        expected_comments_count += int(p["replies_count"] or 0) + int(p["quotes"] or 0)
        total_comments_count += comment_counts_by_root.get(p["source_id"], 0)
        total_quotes_saved += int(quote_counts_by_root.get(p["source_id"], 0))

        hashtags = p.get("hashtags")
        if isinstance(hashtags, str):
            try:
                hashtags = json.loads(hashtags)
            except (json.JSONDecodeError, TypeError):
                hashtags = None

        mentions = p.get("mentions")
        if isinstance(mentions, str):
            try:
                mentions = json.loads(mentions)
            except (json.JSONDecodeError, TypeError):
                mentions = None
        if isinstance(mentions, list):
            mentions = [f"@{m}" if not str(m).startswith("@") else str(m) for m in mentions]

        media_urls = p.get("media_urls")
        if isinstance(media_urls, str):
            try:
                media_urls = json.loads(media_urls)
            except (json.JSONDecodeError, TypeError):
                media_urls = None

        author = p["author"] or ""
        post_comments = comments_by_root.get(p["source_id"], [])
        user_url = _resolve_platform_profile_url("twitter", handle=author, explicit_url=p.get("user_profile_url"))

        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=p.get("hosted_user_avatar_url"),
            direct_avatar_url=p.get("user_avatar_url"),
            raw_data=p.get("raw_data"),
        )

        result_posts.append(
            {
                "source_id": p["source_id"],
                "author": p["author"] or "",
                "display_name": p.get("display_name") or "",
                "text": p.get("text") or "",
                "url": f"https://x.com/{author}/status/{p['source_id']}" if p["source_id"] and author else "",
                "posted_at": _iso(p["ts"]),
                "likes": p["likes"],
                "retweets": p["retweets"],
                "reposts": reposts,
                "replies_count": p["replies_count"],
                "quotes": p["quotes"],
                "views": p["views"],
                "hashtags": hashtags or [],
                "mentions": mentions or [],
                "media_urls": media_urls,
                "source_media_urls": _as_text_list(media_urls or []),
                "hosted_media_urls": _as_text_list(p.get("hosted_media_urls")),
                "thumbnail_url": p.get("thumbnail_url"),
                "source_thumbnail_url": str(p.get("thumbnail_url") or "").strip() or None,
                "hosted_thumbnail_url": str(p.get("hosted_thumbnail_url") or "").strip() or None,
                "user": {
                    "id": p.get("user_id"),
                    "username": p["author"] or "",
                    "display_name": p.get("display_name") or "",
                    "url": user_url,
                    "avatar_url": user_avatar_url,
                },
                "engagement": engagement,
                "total_comments_available": comment_counts_by_root.get(p["source_id"], 0),
                "total_quotes_in_db": int(quote_counts_by_root.get(p["source_id"], 0)),
                "comments": [
                    {
                        "comment_id": c["comment_id"],
                        "author": c["author"] or "",
                        "text": c["text"] or "",
                        "likes": c["likes"],
                        "is_reply": c["is_reply"],
                        "reply_count": c["reply_count"],
                        "created_at": _iso(c["created_at"]),
                        "user": {
                            "id": c.get("user_id"),
                            "username": c["author"] or "",
                            "display_name": c.get("display_name") or "",
                            "url": _resolve_platform_profile_url(
                                "twitter",
                                handle=c.get("author"),
                                explicit_url=c.get("user_url"),
                            ),
                            "avatar_url": _first_non_empty_str(
                                c.get("hosted_user_avatar_url"), c.get("user_avatar_url")
                            ),
                        },
                    }
                    for c in post_comments
                ],
                "status": _build_post_status_payload(
                    expected_comments=int(p["replies_count"] or 0) + int(p["quotes"] or 0),
                    saved_comments=int(comment_counts_by_root.get(p["source_id"], 0) or 0)
                    + int(quote_counts_by_root.get(p["source_id"], 0) or 0),
                    source_media_urls=_as_text_list(media_urls or []),
                    hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                    source_thumbnail_url=str(p.get("thumbnail_url") or "").strip() or None,
                    hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                    media_mirror_status=_infer_post_media_mirror_status(
                        source_media_urls=_as_text_list(media_urls or []),
                        hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                        source_thumbnail_url=str(p.get("thumbnail_url") or "").strip() or None,
                        hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                        stored_status=str(p.get("media_mirror_status") or "").strip() or None,
                    ),
                    media_mirror_last_job_id=str(p.get("media_mirror_last_job_id") or "").strip() or None,
                    last_refresh_at=p.get("media_mirror_last_attempt_at"),
                    last_refresh_reason=None
                    if (
                        int(comment_counts_by_root.get(p["source_id"], 0) or 0)
                        + int(quote_counts_by_root.get(p["source_id"], 0) or 0)
                    )
                    >= (int(p["replies_count"] or 0) + int(p["quotes"] or 0))
                    else "twitter_incomplete_or_capped",
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": expected_comments_count,
            "saved_comments_total": total_comments_count + total_quotes_saved,
            "comments_saved_pct": _safe_percent(total_comments_count + total_quotes_saved, expected_comments_count),
        },
    }


def _week_detail_facebook(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    thumbnail_expr = _platform_thumbnail_expr("p", "facebook")
    hashtags_expr = (
        "coalesce(p.hashtags, '[]'::jsonb)" if _platform_posts_has_column("facebook", "hashtags") else "'[]'::jsonb"
    )
    mentions_expr = (
        "coalesce(p.mentions, '[]'::jsonb)" if _platform_posts_has_column("facebook", "mentions") else "'[]'::jsonb"
    )
    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    params = [season_id, start_dt, end_dt]
    if account_handles_list:
        params.append(account_handles_list)
    count_rows = pg.fetch_all(
        f"""
        select count(*)::int as post_count
        from social.facebook_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
        {account_filter}
        """,
        params,
    )
    total_post_count = int((count_rows[0] if count_rows else {}).get("post_count") or 0)
    effective_post_limit = max(0, post_limit + post_offset)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="p.posted_at",
        field_expr_by_sort={
            "likes": "p.likes",
            "views": "p.views",
            "comments_count": "p.comments_count",
            "shares": "p.shares",
            "retweets": "0",
        },
        engagement_expr=(
            "coalesce(p.likes, 0) + coalesce(p.comments_count, 0) + coalesce(p.shares, 0) + coalesce(p.views, 0)"
        ),
        sort_field=sort_field,
        sort_dir=sort_dir,
    )
    posts = pg.fetch_all(
        f"""
        select
          p.id,
          p.post_id as source_id,
          coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '') as author,
          p.caption as text,
          coalesce(p.post_type, 'feed') as post_type,
          coalesce(p.likes, 0) as likes,
          coalesce(p.comments_count, 0) as comments_count,
          coalesce(p.shares, 0) as shares,
          coalesce(p.views, 0) as views,
          {hashtags_expr} as hashtags,
          {mentions_expr} as mentions,
          {thumbnail_expr} as thumbnail_url,
          coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(nullif(p.thumbnail_url, ''), '') as source_thumbnail_url,
          coalesce(nullif(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          nullif(coalesce(to_jsonb(p) ->> 'media_mirror_status', ''), '') as media_mirror_status,
          {_instagram_posts_json_timestamptz_expr("p", "media_mirror_last_attempt_at")} as media_mirror_last_attempt_at,
          {_instagram_posts_json_text_expr("p", "media_mirror_last_job_id")} as media_mirror_last_job_id,
          nullif(coalesce(to_jsonb(p) ->> 'user_avatar_url', ''), '') as user_avatar_url,
          nullif(coalesce(to_jsonb(p) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          p.posted_at as ts
        from social.facebook_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
          {account_filter}
        order by {order_by_clause}
        limit {effective_post_limit}
        """,
        params,
    )
    post_ids = [p["id"] for p in posts]
    comments_by_post: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    comment_counts_by_post: dict[Any, int] = defaultdict(int)
    facebook_comment_active_filter = (
        "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("facebook_comments") else ""
    )
    if post_ids:
        count_rows = pg.fetch_all(
            f"""
            select c.post_id, count(*)::int as cnt
            from social.facebook_comments c
            where c.post_id = any(%s::uuid[])
              {facebook_comment_active_filter}
            group by c.post_id
            """,
            [post_ids],
        )
        for row in count_rows:
            comment_counts_by_post[row["post_id"]] = row["cnt"]
        limit_clause = f"limit {max_comments}" if max_comments > 0 else "limit all"
        comment_rows = pg.fetch_all(
            f"""
            select sub.*
            from unnest(%s::uuid[]) as pid(id)
            cross join lateral (
              select
                c.comment_id,
                c.post_id,
                c.username as author,
                c.text,
                coalesce(c.likes, 0) as likes,
                coalesce(c.is_reply, false) as is_reply,
                coalesce(c.reply_count, 0) as reply_count,
                c.created_at
              from social.facebook_comments c
              where c.post_id = pid.id
                {facebook_comment_active_filter}
              order by c.likes desc nulls last, c.created_at asc
              {limit_clause}
            ) sub
            """,
            [post_ids],
        )
        for row in comment_rows:
            comments_by_post[row["post_id"]].append(row)

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    saved_comments_count = 0
    for p in posts:
        engagement = p["likes"] + p["comments_count"] + p["shares"] + p["views"]
        total_engagement += engagement
        total_comments_count += int(p["comments_count"] or 0)
        db_comment_count = int(comment_counts_by_post.get(p["id"], 0) or 0)
        saved_comments_count += db_comment_count
        post_comments = comments_by_post.get(p["id"], [])
        hashtags = _json_text_list(p.get("hashtags"), strip_prefix="#")
        if not hashtags:
            hashtags = _parse_hashtags(p.get("text"))
        mentions = _json_text_list(p.get("mentions"), prefix="@", strip_prefix="@")
        if not mentions:
            mentions = _parse_mentions(p.get("text"))
        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=p.get("hosted_user_avatar_url"),
            direct_avatar_url=p.get("user_avatar_url"),
            raw_data=p.get("raw_data"),
        )
        user_url = _resolve_platform_profile_url("facebook", handle=p.get("author"))
        mentions_detail = _build_handle_details_from_tokens("facebook", mentions)
        url = (
            f"https://www.facebook.com/reel/{p['source_id']}"
            if str(p.get("post_type") or "").lower() == "reel"
            else f"https://www.facebook.com/{p['author'] or ''}/posts/{p['source_id']}"
        )
        result_posts.append(
            {
                "source_id": p["source_id"],
                "author": p["author"] or "",
                "text": p.get("text") or "",
                "url": url if p["source_id"] else "",
                "posted_at": _iso(p["ts"]),
                "likes": p["likes"],
                "comments_count": p["comments_count"],
                "shares": p["shares"],
                "views": p["views"],
                "hashtags": hashtags,
                "mentions": mentions,
                "post_type": p.get("post_type") or "feed",
                "thumbnail_url": p.get("thumbnail_url"),
                "source_thumbnail_url": str(p.get("source_thumbnail_url") or "").strip() or None,
                "hosted_thumbnail_url": str(p.get("hosted_thumbnail_url") or "").strip() or None,
                "media_urls": _as_text_list(p.get("source_media_urls")),
                "source_media_urls": _as_text_list(p.get("source_media_urls")),
                "hosted_media_urls": _as_text_list(p.get("hosted_media_urls")),
                "user": {
                    "username": p["author"] or "",
                    "display_name": p.get("author") or "",
                    "url": user_url,
                    "avatar_url": user_avatar_url,
                },
                "mentions_detail": mentions_detail,
                "engagement": engagement,
                "total_comments_available": db_comment_count,
                "comments": [
                    {
                        "comment_id": c["comment_id"],
                        "author": c["author"] or "",
                        "text": c["text"] or "",
                        "likes": c["likes"],
                        "is_reply": c["is_reply"],
                        "reply_count": c["reply_count"],
                        "created_at": _iso(c["created_at"]),
                    }
                    for c in post_comments
                ],
                "status": _build_post_status_payload(
                    expected_comments=int(p["comments_count"] or 0),
                    saved_comments=db_comment_count,
                    source_media_urls=_as_text_list(p.get("source_media_urls")),
                    hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                    source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                    hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                    media_mirror_status=_infer_post_media_mirror_status(
                        source_media_urls=_as_text_list(p.get("source_media_urls")),
                        hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                        source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                        hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                        stored_status=str(p.get("media_mirror_status") or "").strip() or None,
                    ),
                    media_mirror_last_job_id=str(p.get("media_mirror_last_job_id") or "").strip() or None,
                    last_refresh_at=p.get("media_mirror_last_attempt_at"),
                    last_refresh_reason=None
                    if db_comment_count >= int(p["comments_count"] or 0)
                    else "facebook_comment_gap",
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": total_comments_count,
            "saved_comments_total": saved_comments_count,
            "comments_saved_pct": _safe_percent(saved_comments_count, total_comments_count),
        },
    }


def _week_detail_threads(
    season_id: str,
    *,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    max_comments: int,
    source_scope: str = "bravo",
    season_context: SeasonContext | None = None,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    thumbnail_expr = _platform_thumbnail_expr("p", "threads")
    hashtags_expr = (
        "coalesce(p.hashtags, '[]'::jsonb)" if _platform_posts_has_column("threads", "hashtags") else "'[]'::jsonb"
    )
    mentions_expr = (
        "coalesce(p.mentions, '[]'::jsonb)" if _platform_posts_has_column("threads", "mentions") else "'[]'::jsonb"
    )
    account_handles_list = sorted(account_handles)
    account_filter = (
        "and ltrim(lower(coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '')), '@') = any(%s)"
        if account_handles_list
        else ""
    )
    params = [season_id, start_dt, end_dt]
    if account_handles_list:
        params.append(account_handles_list)
    effective_post_limit = max(0, post_limit + post_offset)
    threads_comment_active_filter = (
        "and coalesce(c.is_missing, false) = false" if _comment_lifecycle_supported("meta_threads_comments") else ""
    )
    context = season_context
    enforce_rhoslc_relevance = _threads_should_enforce_rhoslc_relevance(context=context)
    relevance_hashtags: list[str] = []
    relevance_keywords: list[str] = []
    total_post_count = 0
    if enforce_rhoslc_relevance and context is not None:
        relevance_hashtags, relevance_keywords = _threads_build_relevance_terms(
            season_id,
            source_scope=source_scope,
            context=context,
        )
    else:
        count_rows = pg.fetch_all(
            f"""
            select count(*)::int as post_count
            from social.meta_threads_posts p
            where p.season_id = %s
              and p.posted_at >= %s
              and p.posted_at <= %s
            {account_filter}
            """,
            params,
        )
        total_post_count = int((count_rows[0] if count_rows else {}).get("post_count") or 0)
    order_by_clause = _week_detail_order_by_clause(
        timestamp_expr="p.posted_at",
        field_expr_by_sort={
            "likes": "p.likes",
            "views": "p.views",
            "comments_count": "0",
            "shares": "0",
            "retweets": "0",
        },
        engagement_expr=(
            "coalesce(p.likes, 0) + coalesce(p.replies_count, 0) + coalesce(p.reposts, 0) + "
            "coalesce(p.quotes, 0) + coalesce(p.views, 0)"
        ),
        sort_field=sort_field,
        sort_dir=sort_dir,
    )
    posts = pg.fetch_all(
        f"""
        select
          p.id,
          p.post_id as source_id,
          coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '') as author,
          p.text,
          coalesce(p.likes, 0) as likes,
          coalesce(p.replies_count, 0) as replies_count,
          coalesce(p.reposts, 0) as reposts,
          coalesce(p.quotes, 0) as quotes,
          coalesce(p.views, 0) as views,
          {hashtags_expr} as hashtags,
          {mentions_expr} as mentions,
          {thumbnail_expr} as thumbnail_url,
          coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(nullif(p.thumbnail_url, ''), '') as source_thumbnail_url,
          coalesce(nullif(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
          nullif(coalesce(to_jsonb(p) ->> 'media_mirror_status', ''), '') as media_mirror_status,
          {_instagram_posts_json_timestamptz_expr("p", "media_mirror_last_attempt_at")} as media_mirror_last_attempt_at,
          {_instagram_posts_json_text_expr("p", "media_mirror_last_job_id")} as media_mirror_last_job_id,
          nullif(coalesce(to_jsonb(p) ->> 'user_avatar_url', ''), '') as user_avatar_url,
          nullif(coalesce(to_jsonb(p) ->> 'hosted_user_avatar_url', ''), '') as hosted_user_avatar_url,
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          p.posted_at as ts
        from social.meta_threads_posts p
        where p.season_id = %s
          and p.posted_at >= %s
          and p.posted_at <= %s
          {account_filter}
        order by {order_by_clause}
        {"" if enforce_rhoslc_relevance else f"limit {effective_post_limit}"}
        """,
        params,
    )
    if enforce_rhoslc_relevance:
        filtered_posts = [
            post
            for post in posts
            if _threads_post_matches_show_terms(
                text=post.get("text"),
                raw_data=post.get("raw_data"),
                hashtags=relevance_hashtags,
                keywords=relevance_keywords,
            )
        ]
        total_post_count = len(filtered_posts)
        if effective_post_limit > 0:
            posts = filtered_posts[:effective_post_limit]
        else:
            posts = []
    post_ids = [p["id"] for p in posts]
    comments_by_post: dict[Any, list[dict[str, Any]]] = defaultdict(list)
    comment_counts_by_post: dict[Any, int] = defaultdict(int)
    if post_ids:
        count_rows = pg.fetch_all(
            f"""
            select c.post_id, count(*)::int as cnt
            from social.meta_threads_comments c
            where c.post_id = any(%s::uuid[])
              {threads_comment_active_filter}
            group by c.post_id
            """,
            [post_ids],
        )
        for row in count_rows:
            comment_counts_by_post[row["post_id"]] = row["cnt"]
        limit_clause = f"limit {max_comments}" if max_comments > 0 else "limit all"
        comment_rows = pg.fetch_all(
            f"""
            select sub.*
            from unnest(%s::uuid[]) as pid(id)
            cross join lateral (
              select
                c.comment_id,
                c.post_id,
                c.username as author,
                c.text,
                coalesce(c.likes, 0) as likes,
                coalesce(c.is_reply, true) as is_reply,
                coalesce(c.reply_count, 0) as reply_count,
                c.created_at
              from social.meta_threads_comments c
              where c.post_id = pid.id
                {threads_comment_active_filter}
              order by c.likes desc nulls last, c.created_at asc
              {limit_clause}
            ) sub
            """,
            [post_ids],
        )
        for row in comment_rows:
            comments_by_post[row["post_id"]].append(row)

    result_posts = []
    total_engagement = 0
    total_comments_count = 0
    saved_comments_count = 0
    for p in posts:
        engagement = p["likes"] + p["replies_count"] + p["reposts"] + p["quotes"] + p["views"]
        total_engagement += engagement
        total_comments_count += int(p["replies_count"] or 0) + int(p["quotes"] or 0)
        db_comment_count = int(comment_counts_by_post.get(p["id"], 0) or 0)
        saved_comments_count += db_comment_count
        post_comments = comments_by_post.get(p["id"], [])
        hashtags = _json_text_list(p.get("hashtags"), strip_prefix="#")
        if not hashtags:
            hashtags = _parse_hashtags(p.get("text"))
        mentions = _json_text_list(p.get("mentions"), prefix="@", strip_prefix="@")
        if not mentions:
            mentions = _parse_mentions(p.get("text"))
        user_avatar_url = _resolve_post_avatar_url(
            hosted_avatar_url=p.get("hosted_user_avatar_url"),
            direct_avatar_url=p.get("user_avatar_url"),
            raw_data=p.get("raw_data"),
        )
        user_url = _resolve_platform_profile_url("threads", handle=p.get("author"))
        mentions_detail = _build_handle_details_from_tokens("threads", mentions)
        result_posts.append(
            {
                "source_id": p["source_id"],
                "author": p["author"] or "",
                "text": p.get("text") or "",
                "topic": _threads_extract_topic(p.get("raw_data"), text=p.get("text")),
                "topic_path": _threads_extract_topic(p.get("raw_data"), text=p.get("text")),
                "url": f"https://www.threads.com/@{p['author'] or ''}/post/{p['source_id']}" if p["source_id"] else "",
                "posted_at": _iso(p["ts"]),
                "likes": p["likes"],
                "replies_count": p["replies_count"],
                "reposts": p["reposts"],
                "quotes": p["quotes"],
                "views": p["views"],
                "hashtags": hashtags,
                "mentions": mentions,
                "thumbnail_url": p.get("thumbnail_url"),
                "source_thumbnail_url": str(p.get("source_thumbnail_url") or "").strip() or None,
                "hosted_thumbnail_url": str(p.get("hosted_thumbnail_url") or "").strip() or None,
                "media_urls": _as_text_list(p.get("source_media_urls")),
                "source_media_urls": _as_text_list(p.get("source_media_urls")),
                "hosted_media_urls": _as_text_list(p.get("hosted_media_urls")),
                "user": {
                    "username": p["author"] or "",
                    "display_name": p.get("author") or "",
                    "url": user_url,
                    "avatar_url": user_avatar_url,
                },
                "mentions_detail": mentions_detail,
                "engagement": engagement,
                "total_comments_available": db_comment_count,
                "comments": [
                    {
                        "comment_id": c["comment_id"],
                        "author": c["author"] or "",
                        "text": c["text"] or "",
                        "likes": c["likes"],
                        "is_reply": c["is_reply"],
                        "reply_count": c["reply_count"],
                        "created_at": _iso(c["created_at"]),
                    }
                    for c in post_comments
                ],
                "status": _build_post_status_payload(
                    expected_comments=int(p["replies_count"] or 0) + int(p["quotes"] or 0),
                    saved_comments=db_comment_count,
                    source_media_urls=_as_text_list(p.get("source_media_urls")),
                    hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                    source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                    hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                    media_mirror_status=_infer_post_media_mirror_status(
                        source_media_urls=_as_text_list(p.get("source_media_urls")),
                        hosted_media_urls=_as_text_list(p.get("hosted_media_urls")),
                        source_thumbnail_url=str(p.get("source_thumbnail_url") or "").strip() or None,
                        hosted_thumbnail_url=str(p.get("hosted_thumbnail_url") or "").strip() or None,
                        stored_status=str(p.get("media_mirror_status") or "").strip() or None,
                    ),
                    media_mirror_last_job_id=str(p.get("media_mirror_last_job_id") or "").strip() or None,
                    last_refresh_at=p.get("media_mirror_last_attempt_at"),
                    last_refresh_reason=None
                    if db_comment_count >= (int(p["replies_count"] or 0) + int(p["quotes"] or 0))
                    else "threads_incomplete_or_capped",
                ),
            }
        )

    return {
        "posts": result_posts,
        "total_posts": total_post_count,
        "totals": {
            "posts": len(result_posts),
            "total_comments": total_comments_count,
            "total_engagement": total_engagement,
            "expected_comments_total": total_comments_count,
            "saved_comments_total": saved_comments_count,
            "comments_saved_pct": _safe_percent(saved_comments_count, total_comments_count),
        },
    }


_WEEK_DETAIL_HANDLERS: dict[str, Any] = {
    "instagram": _week_detail_instagram,
    "tiktok": _week_detail_tiktok,
    "youtube": _week_detail_youtube,
    "twitter": _week_detail_twitter,
    "facebook": _week_detail_facebook,
    "threads": _week_detail_threads,
}


def get_week_detail(
    season_id: str,
    *,
    week_index: int,
    platforms: list[str] | None,
    timezone: str,
    source_scope: str,
    max_comments_per_post: int = 0,
    post_limit: int = 20,
    post_offset: int = 0,
    sort_field: str = "posted_at",
    sort_dir: str = "desc",
) -> dict[str, Any]:
    """Return detailed post-level data for a single week of a season."""
    started_at = time_module.perf_counter()
    post_limit = max(0, int(post_limit))
    if post_offset < 0:
        post_offset = 0
    normalized_sort_field, normalized_sort_dir = _normalize_week_detail_sort(sort_field, sort_dir)

    context = get_season_context(season_id)
    available_platforms = _resolve_requested_platforms(platforms)

    now = _now_utc()
    week_windows, _week_zero_start_local = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now,
    )
    windows_by_index = {w.week_index: w for w in week_windows}
    window = windows_by_index.get(week_index)
    if window is None:
        raise ValueError(f"Week {week_index} is not available for this season")

    start_dt = window.start_local.astimezone(UTC)
    end_dt = (window.end_local - timedelta(microseconds=1)).astimezone(UTC)
    if end_dt < start_dt:
        end_dt = start_dt

    target_accounts_by_platform = _target_accounts_by_platform(
        season_id,
        source_scope=source_scope,
        context=context,
    )
    requires_target_accounts = source_scope in {"bravo", "creator"}

    platform_results: dict[str, Any] = {}
    status_posts_by_platform: dict[str, list[dict[str, Any]]] = {}
    merged_posts: list[tuple[str, dict[str, Any]]] = []
    grand_posts = 0
    grand_comments = 0
    grand_engagement = 0
    grand_expected_comments = 0
    grand_saved_comments = 0
    by_platform_duration_ms: dict[str, int] = {}

    def _load_platform_result(platform: str) -> tuple[str, dict[str, Any] | None, int]:
        handler = _WEEK_DETAIL_HANDLERS.get(platform)
        if not handler:
            return platform, None, 0
        account_handles = set(target_accounts_by_platform.get(platform, set()))
        if requires_target_accounts and not account_handles:
            result = {
                "posts": [],
                "total_posts": 0,
                "totals": {
                    "posts": 0,
                    "total_comments": 0,
                    "total_engagement": 0,
                },
            }
            return platform, result, 0
        handler_kwargs: dict[str, Any] = {
            "start_dt": start_dt,
            "end_dt": end_dt,
            "account_handles": account_handles,
            "max_comments": max_comments_per_post,
            "post_limit": post_limit,
            "post_offset": post_offset,
            "sort_field": normalized_sort_field,
            "sort_dir": normalized_sort_dir,
        }
        if platform == "threads":
            handler_kwargs["source_scope"] = source_scope
            handler_kwargs["season_context"] = context
        platform_started_at = time_module.perf_counter()
        result = handler(season_id, **handler_kwargs)
        duration_ms = int((time_module.perf_counter() - platform_started_at) * 1000)
        return platform, result, duration_ms

    loaded_results: dict[str, tuple[dict[str, Any], int]] = {}
    if len(available_platforms) <= 1:
        for platform in available_platforms:
            loaded_platform, result, duration_ms = _load_platform_result(platform)
            if result is not None:
                loaded_results[loaded_platform] = (result, duration_ms)
    else:
        max_workers = max(1, min(len(available_platforms), 6))
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_platform = {
                executor.submit(_load_platform_result, platform): platform for platform in available_platforms
            }
            for future in as_completed(future_to_platform):
                loaded_platform, result, duration_ms = future.result()
                if result is not None:
                    loaded_results[loaded_platform] = (result, duration_ms)

    for platform in available_platforms:
        loaded = loaded_results.get(platform)
        if loaded is None:
            continue
        result, duration_ms = loaded
        result_posts = list(result.get("posts") or [])
        by_platform_duration_ms[platform] = duration_ms
        result_total_posts = int(result.get("total_posts", len(result.get("posts") or [])) or 0)
        result_totals = _normalize_week_totals_payload(result.get("totals"), total_posts=result_total_posts)
        platform_results[platform] = {
            "posts": [],
            "total_posts": result_total_posts,
            "totals": result_totals,
        }
        status_posts_by_platform[platform] = result_posts
        for post in result_posts:
            merged_posts.append((platform, post))
        totals = result_totals
        grand_posts += int(totals.get("posts", 0))
        grand_comments += totals.get("total_comments", 0)
        grand_engagement += totals.get("total_engagement", 0)
        grand_expected_comments += int(totals.get("expected_comments_total") or 0)
        grand_saved_comments += int(totals.get("saved_comments_total") or 0)

    active_week_runs = _resolve_week_run_rows_by_platform(
        context.season_id,
        source_scope=source_scope,
        week_index=week_index,
        platforms=available_platforms,
    )
    active_job_status_by_platform = _active_week_job_status_by_platform(
        None,
        source_scope=source_scope,
        week_index=week_index,
        platforms=available_platforms,
        run_rows_by_platform=active_week_runs,
    )
    primary_week_run_id = _primary_week_run_id(active_week_runs)

    status_by_platform: dict[str, dict[str, Any]] = {}
    for platform in available_platforms:
        platform_payload = platform_results.get(platform, {})
        platform_posts = status_posts_by_platform.get(platform, [])
        post_failure_reasons = _extract_platform_post_failure_reasons(
            platform,
            platform_posts if isinstance(platform_posts, list) else [],
        )
        comments_stats = _comments_coverage_for_platform(
            season_id,
            platform=platform,
            start_dt=start_dt,
            end_dt=end_dt,
            source_scope=source_scope,
            target_accounts_by_platform=target_accounts_by_platform,
            season_context=context,
        )
        mirror_stats = _mirror_coverage_for_platform(
            season_id,
            platform=platform,
            start_dt=start_dt,
            end_dt=end_dt,
            source_scope=source_scope,
            target_accounts_by_platform=target_accounts_by_platform,
            season_context=context,
        )
        comment_media_stats = _comment_media_coverage_for_platform(
            season_id,
            platform=platform,
            start_dt=start_dt,
            end_dt=end_dt,
            source_scope=source_scope,
            target_accounts_by_platform=target_accounts_by_platform,
        )
        comment_status = _build_comment_sync_status(
            expected_count=int(comments_stats.get("reported_comments") or 0),
            fetched_count=int(comments_stats.get("saved_comments") or 0),
            upserted_count=int(comments_stats.get("saved_comments") or 0),
            stale_posts_count=int(comments_stats.get("stale_posts_count") or 0),
            failure_reason=(
                post_failure_reasons.get("comment_failure_reason") or _platform_failure_reason(platform, "comment_gap")
                if int(comments_stats.get("stale_posts_count") or 0) > 0
                or int(comments_stats.get("saved_comments") or 0) < int(comments_stats.get("reported_comments") or 0)
                else None
            ),
            attempted=int(comments_stats.get("posts_scanned") or 0) > 0,
        )
        media_status = _build_media_mirror_status(
            source_count=int(mirror_stats.get("posts_scanned") or 0)
            + int(comment_media_stats.get("items_scanned") or 0),
            mirrored_count=int(mirror_stats.get("mirrored_count") or 0)
            + int(comment_media_stats.get("mirrored_count") or 0),
            failed_count=int(mirror_stats.get("failed_count") or 0) + int(comment_media_stats.get("failed_count") or 0),
            pending_count=int(mirror_stats.get("pending_count") or 0)
            + int(comment_media_stats.get("pending_count") or 0),
            partial_count=int(mirror_stats.get("partial_count") or 0),
            last_job_id=_extract_last_platform_job_id(platform_posts if isinstance(platform_posts, list) else []),
            attempted=(int(mirror_stats.get("posts_scanned") or 0) + int(comment_media_stats.get("items_scanned") or 0))
            > 0,
            failure_reason=post_failure_reasons.get("media_failure_reason")
            or _derive_media_failure_reason(
                platform,
                post_failed_count=int(mirror_stats.get("failed_count") or 0),
                post_partial_count=int(mirror_stats.get("partial_count") or 0),
                post_pending_count=int(mirror_stats.get("pending_count") or 0),
                comment_failed_count=int(comment_media_stats.get("failed_count") or 0),
                comment_pending_count=int(comment_media_stats.get("pending_count") or 0),
            ),
        )
        status_payload = _build_platform_status_payload(
            posts_scanned=int(comments_stats.get("posts_scanned") or 0),
            comment_sync_status=comment_status,
            media_mirror_status=media_status,
            last_refresh_at=_extract_last_platform_refresh_at(platform_posts),
            last_refresh_reason=post_failure_reasons.get("last_refresh_reason")
            or comment_status.get("failure_reason")
            or media_status.get("failure_reason"),
            worker_run_id=str((active_week_runs.get(platform) or {}).get("run_id") or "").strip()
            or media_status.get("last_job_id")
            or None,
            active_job_summary=active_job_status_by_platform.get(platform),
        )
        status_payload = _overlay_platform_status_with_active_jobs(
            status_payload,
            active_job_status=active_job_status_by_platform.get(platform),
        )
        status_by_platform[platform] = status_payload
        if isinstance(platform_payload, dict):
            platform_payload["status"] = status_payload

    reverse = normalized_sort_dir == "desc"
    if normalized_sort_field == "posted_at":
        merged_posts.sort(
            key=lambda item: str((item[1] if isinstance(item[1], dict) else {}).get("posted_at") or ""),
            reverse=reverse,
        )
    else:
        merged_posts.sort(
            key=lambda item: (
                _coerce_week_detail_sort_metric(
                    (item[1] if isinstance(item[1], dict) else {}).get(normalized_sort_field)
                ),
                str((item[1] if isinstance(item[1], dict) else {}).get("posted_at") or ""),
            ),
            reverse=reverse,
        )
    if post_limit <= 0:
        page_posts = []
        page_end = post_offset
    else:
        page_end = post_offset + post_limit
        page_posts = merged_posts[post_offset:page_end]
    paged_total_posts = len(merged_posts)

    posts_by_platform: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for platform, post in page_posts:
        posts_by_platform[platform].append(post)
    for platform in available_platforms:
        if platform in platform_results:
            platform_results[platform]["posts"] = posts_by_platform.get(platform, [])
            if not posts_by_platform.get(platform):
                platform_results[platform]["posts"] = []
    grand_posts = 0
    for platform in available_platforms:
        grand_posts += int(platform_results.get(platform, {}).get("total_posts", 0) or 0)

    week_end_inclusive = window.end_local - timedelta(microseconds=1)
    return {
        "week": {
            "week_index": week_index,
            "label": _week_window_label(window, timezone=timezone),
            "start": _iso(window.start_local.astimezone(UTC)),
            "end": _iso(week_end_inclusive.astimezone(UTC)),
            "week_type": window.week_type,
            "episode_number": window.episode_number,
        },
        "season": {
            "season_id": context.season_id,
            "show_id": context.show_id,
            "show_name": context.show_name,
            "show_slug": context.show_slug,
            "season_number": context.season_number,
        },
        "source_scope": source_scope,
        "platforms": platform_results,
        "status_by_platform": status_by_platform,
        "pagination": {
            "limit": post_limit,
            "offset": post_offset,
            "returned": len(page_posts),
            "total": paged_total_posts,
            "has_more": page_end < paged_total_posts,
        },
        "totals": {
            "posts": grand_posts,
            "total_comments": grand_comments,
            "total_engagement": grand_engagement,
            "expected_comments_total": grand_expected_comments,
            "saved_comments_total": grand_saved_comments,
            "comments_saved_pct": float(_safe_percent(grand_saved_comments, grand_expected_comments) or 0.0),
        },
        "diagnostics": {
            "run_id": primary_week_run_id,
            "run_ids_by_platform": {
                platform: str((active_week_runs.get(platform) or {}).get("run_id") or "").strip() or None
                for platform in available_platforms
            },
            "generated_at": _iso(_now_utc()),
            "source_scope": source_scope,
        },
        "meta": {
            "performance": {
                "total_duration_ms": int((time_module.perf_counter() - started_at) * 1000),
                "by_platform": by_platform_duration_ms,
                "max_comments_per_post": max(0, int(max_comments_per_post)),
            }
        },
    }


def _week_summary_account_filter(
    *,
    account_expr: str,
    account_handles: set[str],
) -> tuple[str, list[Any]]:
    account_handles_list = sorted(
        {str(handle or "").strip().lower().lstrip("@") for handle in account_handles if str(handle or "").strip()}
    )
    if not account_handles_list:
        return "", []
    return f"and ltrim(lower(coalesce(nullif({account_expr}, ''), '')), '@') = any(%s)", [account_handles_list]


def _week_summary_fast_generic(
    *,
    season_id: str,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
    post_table: str,
    timestamp_column: str,
    account_expr: str,
    comment_table: str,
    comment_fk_column: str,
    likes_expr: str,
    comments_expr: str,
    views_expr: str,
    shares_expr: str = "0",
    comments_active_filter: str = "",
) -> dict[str, Any]:
    account_filter, account_params = _week_summary_account_filter(
        account_expr=account_expr, account_handles=account_handles
    )
    params = [season_id, start_dt, end_dt, *account_params]
    aggregate = (
        pg.fetch_one(
            f"""
            select
              count(*)::int as total_posts,
              coalesce(sum(coalesce({comments_expr}, 0)), 0)::int as expected_comments_total,
              coalesce(
                sum(
                  coalesce({likes_expr}, 0)
                  + coalesce({comments_expr}, 0)
                  + coalesce({shares_expr}, 0)
                  + coalesce({views_expr}, 0)
                ),
                0
              )::bigint as total_engagement
            from social.{post_table} p
            where p.season_id = %s
              and p.{timestamp_column} >= %s
              and p.{timestamp_column} <= %s
              {account_filter}
            """,
            params,
        )
        or {}
    )
    saved_row = (
        pg.fetch_one(
            f"""
            select count(c.id)::int as saved_comments_total
            from social.{comment_table} c
            join social.{post_table} p on p.id = c.{comment_fk_column}
            where p.season_id = %s
              and p.{timestamp_column} >= %s
              and p.{timestamp_column} <= %s
              {account_filter}
              {comments_active_filter}
            """,
            params,
        )
        or {}
    )
    total_posts = int(aggregate.get("total_posts") or 0)
    expected_comments_total = int(aggregate.get("expected_comments_total") or 0)
    saved_comments_total = int(saved_row.get("saved_comments_total") or 0)
    total_engagement = int(aggregate.get("total_engagement") or 0)
    return {
        "total_posts": total_posts,
        "totals": {
            "posts": total_posts,
            "total_comments": expected_comments_total,
            "total_engagement": total_engagement,
            "expected_comments_total": expected_comments_total,
            "saved_comments_total": saved_comments_total,
            "comments_saved_pct": _safe_percent(saved_comments_total, expected_comments_total),
        },
    }


def _week_summary_fast_instagram(
    *,
    season_id: str,
    start_dt: datetime,
    end_dt: datetime,
    account_handles: set[str],
) -> dict[str, Any]:
    return _week_summary_fast_generic(
        season_id=season_id,
        start_dt=start_dt,
        end_dt=end_dt,
        account_handles=account_handles,
        post_table="instagram_posts",
        timestamp_column="posted_at",
        account_expr="coalesce(nullif(p.username, ''), nullif(p.source_account, ''))",
        comment_table="instagram_comments",
        comment_fk_column="post_id",
        likes_expr="p.likes",
        comments_expr="p.comments_count",
        views_expr="p.views",
    )


